import './website-review.css';

export const dynamic = 'force-dynamic';
export const metadata = { robots: { index: false, follow: false } };
export default async function ClinicalReviewLayout({ children }: { children: ReactNode }) {
  try { await authorizeClinicalReview(); }
  catch (error) {
    const known = error instanceof ClinicalReviewAccessError;
    return <main className="inner-page"><h1>Clinical Review</h1>
      <p role="alert">{known ? error.message : 'Clinical Review is temporarily unavailable.'}</p>
      {known && error.status === 401 && <a href={chatGPTSignInPath('/workspace/atlas-review')} target="_top">Sign in with ChatGPT</a>}
      <p><a href="/workspace">Return to workspace</a></p></main>;
  }
  return <section className="website-clinical-review">
    <p className="review-account-scope">Personal reviews within your authorized institution. Saved decisions do not publish content or grant institution sign-off.</p>
    {children}
  </section>;
}

import { notFound } from 'next/navigation';
import { dissectionProfiles } from '@/atlas-review/app/dissection-data';
import { clinicalReviewReturn } from '../../../../lib/clinical-review-return';
import './review-model-embedded.css';

/** Both presentations share the existing exact query validation and private
 * parent layout. Embedded presentation removes navigation, never access checks. */
export async function renderReviewModel(params: Record<string, string | string[] | undefined>, embedded = false) {
  const kind = params.kind ?? 'body';
  const region = params.region ?? 'whole-body';
  if (typeof kind !== 'string' || !['body','shoulder','kidneys','female-pelvis','back-layers','abdominal-wall','lower-limb'].includes(kind)
    || typeof region !== 'string' || !Object.hasOwn(dissectionProfiles, region)) notFound();
  const query = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) {
    if (!/^(kind|region|study|structure|side|source|focus|detail|part|partSource|ref|refSpecimen|refFrame|refStructure|refSource|refRevision|refStudy|refView|specimen|specimenScope|specimenPart|specimenSource|specimenRevision|specimenStudy|specimenView|specimenTopic)$/.test(key)
      || typeof value !== 'string' || value.length > 256) notFound();
    query.set(key, value);
  }
  query.set('kind', kind); query.set('region', region);
  const back = await clinicalReviewReturn(Object.fromEntries(query));
  const frame = <iframe className="review-model-frame" title="Clinical Review anatomy model" src={'/atlas-review-viewer/index.html?' + query.toString()} allowFullScreen />;
  if (embedded) return <div className="review-model-embedded"><p>Private anatomy inspection · education only · no decision is recorded here</p>{frame}</div>;
  return <><nav className="review-model-bar" aria-label="Review model navigation"><a data-review-return href={back.href} title={back.name ? `Return to ${back.name} review` : undefined}>{back.name ? '← Back to worksheet' : '← Clinical Review'}</a><span>Review-linked model</span></nav>{frame}</>;
}

.website-clinical-review:has(> .review-model-embedded) > .review-account-scope { display:none; }
.review-model-embedded { height:100dvh; min-height:0; display:flex; flex-direction:column; background:var(--vm-midnight); color:var(--vm-ivory); }
.review-model-embedded > p { flex:none; margin:0; padding:.45rem .7rem; font-size:.75rem; line-height:1.4; }
.review-model-embedded > .review-model-frame { flex:1; height:0; min-height:0; }

