'use client';

import { labelDepthSurface } from '@/atlas-review/lib/label-depth';

import {
  Component,
  Suspense,
  useEffect,
  useLayoutEffect,
  useMemo,
  type ReactNode,
  type RefObject,
} from 'react';
import { useThree, type ThreeEvent } from '@react-three/fiber';
import { AnatomyCanvas as Canvas } from './anatomy-canvas';
import { Html, Line, useGLTF } from '@react-three/drei';
import * as THREE from 'three';
import type { AnatomyStructure, SystemKey } from './anatomy-data';
import { FittedCamera } from './fitted-camera';
import {
  shoulderArrangementItems,
  shoulderPresentationOffsets,
} from '@/atlas-review/lib/shoulder-arrangement';
import { arrangementBounds, type BodyLayout } from '@/atlas-review/lib/body-arrangement';
import manifest from '@/atlas-review/public/models/bodyparts3d/manifest.json';
import {
  applyMaterialInspection,
  clippedMeshRaycast,
  sectionPlanes,
  pointRetained,
} from '@/atlas-review/lib/inspection-geometry';
import { type InspectionState, systemOpacity } from '@/atlas-review/lib/inspection-state';
import type { StudyCamera } from '@/atlas-review/lib/study-views';
import { Button } from '@/atlas-review/components/ui/button';
import { SceneRecovery, RendererMonitor } from './scene-recovery';
import type { RendererHealth } from '@/atlas-review/lib/renderer-health';
import { SceneLabel, SceneLabelLayer } from './scene-label-layer';
import { modelLoadAccessNotice, modelLoadFailure } from '@/atlas-review/lib/model-load-failure';

const noPlanes: THREE.Plane[] = [];
const sectionFrame = new THREE.Box3();
for (const part of manifest.parts) {
  const box = new THREE.Box3(
    new THREE.Vector3().fromArray(part.bounds.min),
    new THREE.Vector3().fromArray(part.bounds.max),
  );
  box.min.y = Math.max(box.min.y, -3.15);
  if (!box.isEmpty()) sectionFrame.union(box);
}

export type CameraView = 'posterior' | 'anterior' | 'lateral';
export type AnatomyLayer = 'cuff' | 'surface' | 'bones';
type SceneProps = {
  modelUrl?: string;
  structures: AnatomyStructure[];
  selectedId: string;
  visibleSystems: Record<SystemKey, boolean>;
  isolated: boolean;
  explode: number;
  layout: BodyLayout;
  showLabels: boolean;
  syncPlane: boolean;
  resetNonce: number;
  view: CameraView;
  layer: AnatomyLayer;
  zoom: number;
  zoomStep?: number;
  exam: boolean;
  anchorSkeleton: boolean;
  showOrigins: boolean;
  plate: boolean;
  inspection: InspectionState;
  cameraCapture?: RefObject<StudyCamera | null>;
  cameraRestore?: RefObject<StudyCamera | null>;
  tourLocked?: boolean;
  transitionMs?: number;
  transitionPaused?: boolean;
  onSelect: (id: string) => void;
  onRendererHealth: (health: RendererHealth) => void;
  onModelReady: (ready: boolean) => void;
};
const views: Record<CameraView, [number, number, number]> = {
  posterior: [2.5, 1.2, -12],
  anterior: [-1.5, 1, 12],
  lateral: [-14, 1.5, -1.3],
};
// Source-registered surface anchors. Anatomy meshes retain their common registration.
const anchors: Record<string, [number, number, number]> = {
  scapula: [0.34, -1.05, -1.55],
  humerus: [-2.9, -2.5, 0.12],
  clavicle: [0.7, 1.58, 1.46],
  supraspinatus: [-0.6, 1.56, -1.12],
  infraspinatus: [-0.35, 0.02, -1.6],
  subscapularis: [-0.35, -0.35, -0.48],
  'teres-minor': [-1.6, -0.6, -1.08],
  deltoid: [-3.12, 0.22, 0.1],
  'biceps-long-head': [-2.5, -1.5, 0.83],
};
// Preserve the existing landmark choices, but not their old fixed positions.
const labelPresets: Record<CameraView, string[]> = {
  posterior: [
    'scapula',
    'humerus',
    'clavicle',
    'supraspinatus',
    'infraspinatus',
    'teres-minor',
    'deltoid',
  ],
  anterior: [
    'scapula',
    'humerus',
    'clavicle',
    'subscapularis',
    'deltoid',
    'biceps-long-head',
  ],
  lateral: [
    'humerus',
    'clavicle',
    'supraspinatus',
    'infraspinatus',
    'teres-minor',
    'subscapularis',
    'deltoid',
    'biceps-long-head',
  ],
};

function isVisible(structure: AnatomyStructure, props: SceneProps) {
  if (!props.visibleSystems[structure.system]) return false;
  const slug = structure.id.split(':').at(-1)!;
  const selected = props.selectedId === structure.id && !props.exam;
  return (
    selected ||
    !(
      (props.layer === 'bones' && structure.category !== 'bone') ||
      (props.layer === 'cuff' && ['deltoid', 'biceps-long-head'].includes(slug))
    )
  );
}

function Tissue({
  geometry,
  bone,
  selected,
  faded,
  slug,
  shiftY = 0,
  cuts = noPlanes,
  opacity = 1,
}: {
  geometry: THREE.BufferGeometry;
  bone: boolean;
  selected: boolean;
  faded: boolean;
  slug: string;
  shiftY?: number;
  cuts?: THREE.Plane[];
  opacity?: number;
}) {
  const invalidate = useThree((s) => s.invalidate);
  // Crop in original anatomical coordinates even when the entire structure moves.
  const clippingPlane = useMemo(
    () => new THREE.Plane(new THREE.Vector3(0, 1, 0), 3.15 - shiftY),
    [shiftY],
  );
  const material = useMemo(() => {
    const colors: Record<string, string> = {
      supraspinatus: '#c96959',
      infraspinatus: '#b9544d',
      subscapularis: '#c26557',
      'teres-minor': '#a94b48',
      deltoid: '#c56b60',
      'biceps-long-head': '#b55b55',
    };
    const result = new THREE.MeshStandardMaterial({
      color: bone ? '#e5d3ae' : (colors[slug] ?? '#bb5b50'),
      roughness: 0.91,
      metalness: 0,
      transparent: faded,
      opacity: faded ? 0.085 : 1,
      depthWrite: !faded,
      side: THREE.DoubleSide,
      clippingPlanes: [clippingPlane],
      clipShadows: true,
      emissive: selected ? '#513016' : '#000000',
      emissiveIntensity: selected ? 0.1 : 0,
    });
    // Fine tonal hatching describes form; these are NOT measured muscle fascicles.
    if (!bone)
      result.onBeforeCompile = (shader) => {
        shader.vertexShader =
          'varying vec3 vAnatomyPosition;\n' + shader.vertexShader;
        shader.vertexShader = shader.vertexShader.replace(
          '#include <begin_vertex>',
          '#include <begin_vertex>\nvAnatomyPosition = position;',
        );
        shader.fragmentShader =
          'varying vec3 vAnatomyPosition;\n' + shader.fragmentShader;
        const fan = [
          'infraspinatus',
          'subscapularis',
          'supraspinatus',
          'teres-minor',
        ].includes(slug);
        shader.fragmentShader = shader.fragmentShader.replace(
          '#include <color_fragment>',
          `#include <color_fragment>
        float fiber = ${fan ? 'atan(vAnatomyPosition.y - 1.3, vAnatomyPosition.x + 2.6) * 95.0' : 'atan(vAnatomyPosition.x + 3.0, vAnatomyPosition.y + 3.7) * 150.0'};
        float stroke = pow(0.5 + 0.5 * sin(fiber + sin(vAnatomyPosition.y * 7.0) * 0.22), 10.0);
        diffuseColor.rgb *= 0.92 + 0.14 * stroke;
      `,
        );
      };
    result.customProgramCacheKey = () => `${slug}-${bone}`;
    return result;
  }, [bone, selected, faded, slug, clippingPlane]);
  useEffect(() => () => material.dispose(), [material]);
  const outline = useMemo(() => {
    const result = new THREE.MeshBasicMaterial({
      color: selected ? '#836337' : bone ? '#75674e' : '#733e37',
      side: THREE.BackSide,
      clippingPlanes: [clippingPlane],
    });
    result.onBeforeCompile = (shader) => {
      shader.vertexShader = shader.vertexShader.replace(
        '#include <begin_vertex>',
        '#include <begin_vertex>\ntransformed += normal * 0.009;',
      );
    };
    return result;
  }, [bone, selected, clippingPlane]);
  useEffect(() => () => outline.dispose(), [outline]);
  useLayoutEffect(() => {
    const planes = [clippingPlane, ...cuts],
      alpha = faded ? 0.085 : opacity;
    applyMaterialInspection(material, planes, alpha);
    applyMaterialInspection(outline, planes, 1);
    invalidate();
  }, [material, outline, clippingPlane, cuts, faded, opacity, invalidate]);
  return (
    <>
      <mesh
        userData={labelDepthSurface}
        geometry={geometry}
        material={material}
        castShadow={!faded && opacity >= 0.95}
        receiveShadow
        raycast={faded ? () => null : clippedMeshRaycast}
      />
      {!faded && opacity >= 0.95 && (
        <mesh geometry={geometry} material={outline} raycast={() => null} />
      )}
    </>
  );
}

function Model(props: SceneProps & { offsets: Map<string, THREE.Vector3> }) {
  const { scene } = useGLTF(props.modelUrl ?? '/models/bodyparts3d/shoulder-right.glb', false, true);
  const onModelReady = props.onModelReady;
  useEffect(() => {
    onModelReady(true);
  }, [onModelReady]);
  const meshes = useMemo(() => {
    const result: Record<string, THREE.Mesh[]> = {};
    scene.traverse((object) => {
      if (object instanceof THREE.Mesh) {
        const slug = object.name
          .split('__')[0]
          .replace('biceps-long-head-muscle', 'biceps-long-head');
        (result[slug] ??= []).push(object);
      }
    });
    return result;
  }, [scene]);
  const surfaceAnchors = useMemo(() => {
    const result: Record<string, [number, number, number]> = {};
    for (const [slug, target] of Object.entries(anchors)) {
      let distance = Infinity;
      const desired = new THREE.Vector3(...target),
        candidate = new THREE.Vector3();
      for (const mesh of meshes[slug] ?? []) {
        const positions = mesh.geometry.getAttribute('position');
        for (let i = 0; i < positions.count; i++) {
          candidate.fromBufferAttribute(positions, i);
          const next = candidate.distanceToSquared(desired);
          if (next < distance) {
            distance = next;
            result[slug] = candidate.toArray() as [number, number, number];
          }
        }
      }
    }
    return result;
  }, [meshes]);
  return (
    <group dispose={null}>
      {props.structures.map((structure) => {
        const slug = structure.id.split(':').at(-1)!;
        const selected = props.selectedId === structure.id && !props.exam;
        if (!isVisible(structure, props)) return null;
        const displacement =
          props.offsets.get(structure.id) ?? new THREE.Vector3();
        const faded = props.isolated && !selected;
        const cuts = sectionPlanes(
          sectionFrame,
          props.inspection,
          displacement,
          selected,
        );
        const opacity = systemOpacity(
          props.inspection,
          structure.system,
          selected,
        );
        const anchor = surfaceAnchors[slug],
          labelled = labelPresets[props.view].includes(slug) || selected;
        const select = (event: ThreeEvent<MouseEvent>) => {
          event.stopPropagation();
          props.onSelect(structure.id);
        };
        return (
          <group key={structure.id}>
            {props.showOrigins &&
              !props.exam &&
              props.layout !== 'tray' &&
              displacement.lengthSq() > 0 && (
                <group raycast={() => null}>
                  {meshes[slug]?.map((mesh) => (
                    <Tissue
                      key={mesh.name}
                      geometry={mesh.geometry}
                      bone={structure.category === 'bone'}
                      selected={false}
                      faded
                      slug={slug}
                      cuts={sectionPlanes(sectionFrame, props.inspection)}
                    />
                  ))}
                </group>
              )}
            <group position={displacement}>
              <group
                onClick={select}
                onPointerOver={(event) => {
                  event.stopPropagation();
                  document.body.style.cursor = 'pointer';
                }}
                onPointerOut={() => {
                  document.body.style.cursor = '';
                }}
              >
                {meshes[slug]?.map((mesh) => (
                  <Tissue
                    key={mesh.name}
                    geometry={mesh.geometry}
                    bone={structure.category === 'bone'}
                    selected={selected}
                    faded={faded}
                    slug={slug}
                    shiftY={displacement.y}
                    cuts={cuts}
                    opacity={opacity}
                  />
                ))}
              </group>
              {props.showLabels &&
                !props.exam &&
                !faded &&
                opacity >= 0.2 &&
                anchor &&
                labelled &&
                pointRetained(
                  new THREE.Vector3(...anchor).add(displacement),
                  cuts,
                ) && (
                  <SceneLabel
                    id={structure.id}
                    name={structure.name}
                    selected={selected}
                    position={anchor}
                    priority={labelPresets[props.view].indexOf(slug)}
                    onSelect={props.onSelect}
                  />
                )}
            </group>
          </group>
        );
      })}
    </group>
  );
}

class ModelBoundary extends Component<
  { children: ReactNode; onModelReady: (ready: boolean) => void; modelUrl?: string },
  { failed: boolean; error: unknown }
> {
  state = { failed: false, error: null as unknown };
  static getDerivedStateFromError(error: unknown) {
    return { failed: true, error };
  }
  componentDidCatch() {
    this.props.onModelReady(false);
  }
  render() {
    const modelUrl = this.props.modelUrl ?? '/models/bodyparts3d/shoulder-right.glb';
    let requested = modelUrl;
    try {
      if (typeof window !== 'undefined') requested = new URL(modelUrl, window.location.href).href;
    } catch { /* Unverified URLs retain the generic failure message. */ }
    const accessNotice = this.state.failed
      ? modelLoadAccessNotice([modelLoadFailure(this.state.error, requested)]) : null;
    return this.state.failed ? (
      <Html center>
        <div className="model-loading">
          <p role="status">
            {accessNotice?.message ?? 'The anatomy model could not load. Your view settings are retained.'}
          </p>
          <Button
            size="sm"
            variant="outline"
            onClick={() => {
              useGLTF.clear(modelUrl);
              this.setState({ failed: false, error: null });
            }}
          >
            {accessNotice?.retryLabel ?? 'Retry shoulder anatomy'}
          </Button>
        </div>
      </Html>
    ) : (
      this.props.children
    );
  }
}

export function AnatomyScene(props: SceneProps) {
  const layout = props.exam ? 'spatial' : props.layout;
  const arrangementView = props.view === 'lateral' ? 'right' : props.view;
  const items = useMemo(
    () =>
      shoulderArrangementItems(
        props.structures.filter((s) => isVisible(s, props)),
      ),
    [props],
  );
  const offsets = useMemo(
    () =>
      shoulderPresentationOffsets(
        items,
        arrangementView,
        props.exam ? 0 : props.explode,
        layout,
        props.selectedId,
        props.anchorSkeleton,
      ),
    [
      items,
      arrangementView,
      props.exam,
      props.explode,
      layout,
      props.selectedId,
      props.anchorSkeleton,
    ],
  );
  const bounds = useMemo(() => {
    const box = arrangementBounds(items, offsets);
    if (props.showOrigins && !props.exam && layout !== 'tray')
      box.union(arrangementBounds(items, new Map()));
    if (box.isEmpty())
      box.set(new THREE.Vector3(-4, -3.15, -2), new THREE.Vector3(2, 2.5, 2));
    return box;
  }, [items, offsets, props.showOrigins, props.exam, layout]);
  const orthographic = props.plate || layout === 'tray';
  return (
    <SceneRecovery
      className="shoulder-scene"
      cameraKey={[
        props.view,
        props.zoom,
        props.zoomStep,
        props.resetNonce,
        orthographic,
        layout,
      ].join('/')}
      key={orthographic ? 'plate' : 'perspective'}
      onHealth={props.onRendererHealth}
      cameraCapture={props.cameraCapture}
      cameraRestore={props.cameraRestore}
    >
      {(onHealth, autoRecoveryCamera, cameraTransitionActive) => (
        <Canvas
          onFailure={() => onHealth('failed')}
          orthographic={orthographic}
          shadows
          camera={{
            position: [1.85, 0.88, -12],
            fov: 39,
            near: 0.01,
            far: 150,
          }}
          dpr={[1, 1.8]}
          frameloop="demand"
          gl={{ antialias: true, alpha: true, localClippingEnabled: true }}
        >
          <RendererMonitor onHealth={onHealth} />
          <ambientLight intensity={1.25} />
          <hemisphereLight args={['#ffffff', '#aa8d70', 1.3]} />
          <directionalLight
            position={[-4, 8, -6]}
            intensity={2.4}
            color="#fffaf1"
            castShadow
            shadow-mapSize={[1024, 1024]}
            shadow-bias={-0.0005}
            shadow-normalBias={0.025}
            shadow-camera-left={-6}
            shadow-camera-right={6}
            shadow-camera-top={5}
            shadow-camera-bottom={-5}
          />
          <directionalLight
            position={[3, 4, 6]}
            intensity={1.7}
            color="#fffef9"
          />
          <directionalLight
            position={[5, -1, -3]}
            intensity={0.5}
            color="#eef5ff"
          />
          <SceneLabelLayer>
            <ModelBoundary key={props.modelUrl ?? '/models/bodyparts3d/shoulder-right.glb'} onModelReady={props.onModelReady} modelUrl={props.modelUrl}>
              <Suspense
                fallback={
                  <Html center>
                    <div className="model-loading">
                      Loading anatomical surfaces…
                    </div>
                  </Html>
                }
              >
                <Model {...props} offsets={offsets} />
              </Suspense>
            </ModelBoundary>
          </SceneLabelLayer>
          {props.syncPlane && (
            <group position={[-0.6, 0.2, 0]}>
              <mesh rotation={[-Math.PI / 2, 0, 0]}>
                <planeGeometry args={[7, 5]} />
                <meshBasicMaterial
                  color="#298879"
                  transparent
                  opacity={0.1}
                  side={THREE.DoubleSide}
                  depthWrite={false}
                />
              </mesh>
              <Line
                points={[
                  [-3.5, 0, 0],
                  [3.5, 0, 0],
                ]}
                color="#298879"
                lineWidth={1}
              />
            </group>
          )}
          <FittedCamera
            bounds={bounds}
            fitOccupancy={[0.7, 0.9]}
            direction={
              orthographic
                ? props.view === 'posterior'
                  ? [0, 0, -1]
                  : props.view === 'anterior'
                    ? [0, 0, 1]
                    : [-1, 0, 0]
                : views[props.view]
            }
            viewKey={props.view}
            zoom={props.zoom}
            zoomStep={props.zoomStep}
            reset={props.resetNonce}
            locked={props.tourLocked || (props.plate && layout !== 'tray')}
            transitionMs={props.transitionMs}
            transitionPaused={props.transitionPaused}
            planar={layout === 'tray'}
            cameraCapture={props.cameraCapture}
            cameraRestore={props.cameraRestore}
            autoRecoveryCamera={autoRecoveryCamera}
            cameraTransitionActive={cameraTransitionActive}
            guidedRecovery={!!props.tourLocked}
          />
        </Canvas>
      )}
    </SceneRecovery>
  );
}

'use client';
import { useEffect, useLayoutEffect, useMemo } from 'react';
import { useThree } from '@react-three/fiber';
import * as THREE from 'three';
import { labelDepthSurface } from '@/atlas-review/lib/label-depth';
import { tissuePicking } from '@/atlas-review/lib/tissue-picking';
import {
  applyMaterialInspection,
  clippedMeshRaycast,
} from '@/atlas-review/lib/inspection-geometry';

const noPlanes: THREE.Plane[] = [];

/** Authored diagrammatic surface treatment. Hatching is NOT muscle-fibre data. */
export function AnatomyTissue({
  geometry,
  color,
  selected,
  ghost,
  muscle,
  illustrated,
  outline,
  opacity = 1,
  clippingPlanes = noPlanes,
}: {
  geometry: THREE.BufferGeometry;
  color: string;
  selected: boolean;
  ghost: boolean;
  muscle: boolean;
  illustrated: boolean;
  outline: boolean;
  opacity?: number;
  clippingPlanes?: THREE.Plane[];
}) {
  const invalidate = useThree((s) => s.invalidate);
  // Reserve the bounded cache for the measured dense-muscle picking bottleneck.
  useEffect(() => ghost || !muscle ? undefined : tissuePicking.retain(geometry), [geometry, ghost, muscle]);
  const { material, contour } = useMemo(() => {
    geometry.computeBoundingBox();
    const size = geometry.boundingBox!.getSize(new THREE.Vector3()),
      center = geometry.boundingBox!.getCenter(new THREE.Vector3());
    const axis =
      size.x > size.y && size.x > size.z ? 0 : size.z > size.y ? 2 : 1;
    const scale = Math.max(size.getComponent(axis), 0.01),
      width = Math.max(size.getComponent(axis === 0 ? 1 : 0), 0.01);
    const m = new THREE.MeshStandardMaterial({
      color: selected ? '#e3bb78' : color,
      roughness: 0.92,
      metalness: 0,
      side: THREE.DoubleSide,
      transparent: ghost,
      opacity: ghost ? 0.055 : 1,
      depthWrite: !ghost,
      emissive: selected ? '#503112' : '#000000',
      emissiveIntensity: 0.13,
    });
    if (illustrated && muscle && !ghost)
      m.onBeforeCompile = (shader) => {
        shader.uniforms.diagramCenter = { value: center };
        shader.uniforms.diagramAlong = {
          value: new THREE.Vector3().setComponent(axis, 1),
        };
        shader.uniforms.diagramAcross = {
          value: new THREE.Vector3().setComponent(axis === 0 ? 1 : 0, 1),
        };
        shader.uniforms.diagramScale = {
          value: new THREE.Vector2(width, scale),
        };
        shader.vertexShader =
          'varying vec3 vDiagramPosition;\n' + shader.vertexShader;
        shader.vertexShader = shader.vertexShader.replace(
          '#include <begin_vertex>',
          '#include <begin_vertex>\nvDiagramPosition = position;',
        );
        shader.fragmentShader =
          'varying vec3 vDiagramPosition; uniform vec3 diagramCenter; uniform vec3 diagramAlong; uniform vec3 diagramAcross; uniform vec2 diagramScale;\n' +
          shader.fragmentShader;
        shader.fragmentShader = shader.fragmentShader.replace(
          '#include <color_fragment>',
          `#include <color_fragment>
        float crossSurface=dot(vDiagramPosition-diagramCenter,diagramAcross)/diagramScale.x;
        float alongSurface=dot(vDiagramPosition-diagramCenter,diagramAlong)/diagramScale.y;
        float stripe=crossSurface*110.0+sin(alongSurface*4.0)*1.8;
        float ink=1.0-smoothstep(0.12,0.12+max(fwidth(stripe)*0.7,0.1),abs(sin(stripe)));
        diffuseColor.rgb*=1.0-ink*0.13;
      `,
        );
      };
    m.customProgramCacheKey = () =>
      `diagram-v1-${illustrated}-${muscle}-${ghost}`;
    const c = new THREE.MeshBasicMaterial({
      color: selected ? '#8a6330' : muscle ? '#713f37' : '#746b54',
      side: THREE.BackSide,
    });
    const thickness = Math.min(0.008, Math.max(0.0005, size.length() * 0.001));
    c.onBeforeCompile = (shader) => {
      shader.uniforms.diagramThickness = { value: thickness };
      shader.vertexShader =
        'uniform float diagramThickness;\n' + shader.vertexShader;
      shader.vertexShader = shader.vertexShader.replace(
        '#include <begin_vertex>',
        '#include <begin_vertex>\ntransformed += normal * diagramThickness;',
      );
    };
    c.customProgramCacheKey = () => 'diagram-contour-v1';
    return { material: m, contour: c };
  }, [geometry, color, selected, ghost, muscle, illustrated]);
  useEffect(
    () => () => {
      material.dispose();
      contour.dispose();
    },
    [material, contour],
  );
  useLayoutEffect(() => {
    applyMaterialInspection(material, clippingPlanes, ghost ? 0.055 : opacity);
    applyMaterialInspection(contour, clippingPlanes, 1);
    invalidate();
  }, [material, contour, clippingPlanes, opacity, ghost, invalidate]);
  return (
    <>
      <mesh
        userData={labelDepthSurface}
        geometry={geometry}
        material={material}
        raycast={ghost ? () => null : clippedMeshRaycast}
      />
      {illustrated && outline && !ghost && opacity >= 0.95 && (
        <mesh geometry={geometry} material={contour} raycast={() => null} />
      )}
    </>
  );
}

