    setFocus(false);
    setZoom(1);
    // Refit also clears live wheel zoom/pan when React zoom is already one.
    cameraRestore.current = null;
    setReset((n) => n + 1);
  }
  function restoreStructures(ids: string[]) {
    if (exam) return;
    const requested = new Set(ids);
    const allowed = resolved.removed.filter((item) => requested.has(item.id));
    if (!allowed.length) return;
    dispatch({ type: 'restore-many', ids: allowed.map((item) => item.id) });
    setSystems((prev) => {
      const next = { ...prev };
      for (const item of allowed) next[item.system] = true;
      return next;
    });
    setIsolated(false);
    setFocus(false);
    setZoom(1);
    cameraRestore.current = null;
    setReset((n) => n + 1);
  }
  function changeVesselVisibility(kind: VesselKind, show: boolean) {
    const action = vesselVisibilityAction(
      regionStructures,
      resolved.visible.map((s) => s.id),
      kind,
      show,
      exam || !systems.vessels,
    );
    if (!action) return;
    dispatch(action);
    // Retain camera, selection, source identity and other tissue visibility.
    // A local visibility change emits no imaging or entitlement event.
  }
  function onSceneSelect(id: string) {
    if (!displayReady) return;
    if (coronaryScene.contextIds.includes(id)) return;
    if (exam) {
      if (practice.mode === 'find' || practice.mode === 'reason')
        submitPractice(id);
    } else select(id);
  }
  function submitPractice(chosen: string | null) {
    if (practicePaused) return;
    practiceDispatch({
      type: 'answer',
      sessionId: practice.id,
      index: question,
      chosen,
    });
  }
  function preset(id: string) {
    const next = bodyPresetSystems(id);
    if (exam || !next) return;
    setInspection(initialInspection);
    dispatch({ type: 'free' });
    setSystems(next);
    setSelectedId(null);
    setIsolated(false);
    setFocus(false);
    setZoom(1);
    setReset((n) => n + 1);
  }
  function changeLayout(next: BodyLayout) {
    if (exam || next === layout) return;
    setLayout(next);
    setPlate(next === 'tray');
    setExplode(next === 'spatial' ? 0 : 100);
    // A deliberately framed selection should stay inspectable when the dense
    // catalogue opens; changing presentation must not silently hide entries.
    if (!(next === 'tray' && focus && selectedId && enabledIds.has(selectedId)))
      setFocus(false);
    setIsolated(false);
    setZoom(1);
    setReset((n) => n + 1);
  }
  function startExam(retry = false) {
    if (exam || practiceBlocked || (retry && !retryCount)) return;
    const session = createPracticeSession(
      available,
      practiceLoadStatus.loaded,
      {
        id: ++practiceSerial.current,
        mode: practiceMode,
        count: retry ? retryCount : practiceCount,
        sampling: practiceSampling,
        focusIds: focusTargetIds,
        retryIds: retry ? retryIds : undefined,
      },
    );
    if (!session) return;
    // Practice temporarily changes presentation, not the learner's study view.
    practiceReturnView.current = {
      selectedId, isolated, focus, explode, layout, plate, zoom, view,
      camera: copyRecoveryCamera(cameraCapture.current),
    };
    cameraRestore.current = null;
    if (layout === 'tray') setPlate(false);
    setLayout('spatial');
    practiceDispatch({ type: 'start', session });
    setSelectedId(null);
    setIsolated(false);
    setFocus(false);
    setExplode(0);
    setZoom(1);
    setReset((n) => n + 1);
  }
  function restorePracticeView() {
    const state = practiceReturnView.current;
    practiceReturnView.current = null;
