          name: string;
          title: string;
          description: string;
          inputSchema: object;
          annotations: object;
          execute: (input: unknown) => unknown;
        },
        options: { signal: AbortSignal },
      ) => unknown;
    };
    const context = (document as Document & { modelContext?: Context })
      .modelContext;
    if (!context || !catalog) return;
    const lifecycle = new AbortController();
    Promise.resolve(
      context.registerTool(
        {
          name: 'select_body_structure',
          title: 'Select body structure',
          description:
            'Select a source-mapped structure in the current body region.',
          inputSchema: {
            type: 'object',
            properties: {
              structureId: {
                type: 'string',
                enum: regionStructures.map((s) => s.id),
              },
            },
            required: ['structureId'],
            additionalProperties: false,
          },
          annotations: { readOnlyHint: false, untrustedContentHint: false },
          execute(input) {
            if (exam || guidedLearning) throw new Error('Selection tools disabled during exam or guided learning');
            const id = (input as { structureId?: unknown }).structureId;
            if (
              typeof id !== 'string' ||
              !regionStructures.some((s) => s.id === id)
            )
              throw new Error('Structure not in this region');
            select(id);
            return { selectedId: id };
          },
        },
        { signal: lifecycle.signal },
      ),
    ).catch(() => undefined);
