                    !focus && !isolated && !ghostRemoved && !showOrigins &&
                    explode === 0 && layout === 'spatial' && inspection.plane === 'off'
                    ? {
                      label: regionalCloseUp ? 'Fit all sources' : `Frame ${framingRegion}`,
