          <group key={structure.id}>
            {props.originStyle !== 'selected-guide' &&
              props.showOrigins &&
              props.layout !== 'tray' &&
              props.explode > 0 &&
              position.lengthSq() > 0 &&
              !removed &&
              (selected || props.structures.length < 150) && (
                <mesh geometry={geometry} raycast={() => null}>
                  <meshBasicMaterial
                    color="#16c6b2"
                    wireframe
                    transparent
                    opacity={0.025}
                    depthWrite={false}
                    clippingPlanes={sectionPlanes(frame, props.inspection)}
                  />
                </mesh>
              )}
            {originGuide?.id === structure.id && (
              <group>
                <mesh geometry={geometry} raycast={() => null}>
                  <meshBasicMaterial
                    color="#16c6b2"
                    wireframe
                    transparent
                    opacity={0.12}
                    depthWrite={false}
                  />
                </mesh>
                <Line
                  points={[originGuide.start, originGuide.end]}
                  color="#16c6b2"
                  lineWidth={1}
                  transparent
                  opacity={0.6}
                  depthWrite={false}
                  raycast={() => null}
                />
              </group>
            )}
            <group position={position}>
              {props.csfMotion && !props.exam && !removed && props.explode === 0 &&
                props.inspection.plane === 'off' && props.systems[structure.system] &&
                <CsfMotion structure={structure} bundleHash={bundle.sha256}/>}
              <group
                onClick={select}
                onPointerOver={(e) => {
                  if (!interactive) return;
                  e.stopPropagation();
                  document.body.style.cursor = 'pointer';
                }}
                onPointerOut={() => {
                  if (props.contextIds?.includes(structure.id)) return;
                  document.body.style.cursor = '';
                }}
              >
                {!batchedIds.has(structure.id) && <AnatomyTissue
                  geometry={geometry}
                  color={
                    props.appearance?.[structure.id]?.color ??
                    colorFor(structure)
                  }
                  selected={selected}
                  ghost={faded}
                  muscle={structure.system === 'muscles'}
                  illustrated={props.illustrated}
                  outline={renderedCount < 150 || selected}
                  opacity={opacity}
                  clippingPlanes={clippingPlanes}
                />}
              </group>
              {props.labels &&
                labelAnchor &&
                !props.exam &&
                !faded &&
                (opacity >= 0.2 || (props.csfMotion && opacity >= 0.15)) &&
                pointRetained(
                  new THREE.Vector3(...labelAnchor).add(position),
                  clippingPlanes,
                ) &&
                labelIndex >= 0 && (
                  <SceneLabel
                    id={structure.id}
                    name={structure.name}
                    selected={selected}
                    position={labelAnchor}
                    priority={labelIndex}
                    onSelect={props.onSelect}
                  />
                )}
            </group>
          </group>
        );
      })}
    </group>
  );
}
/** Fetch and validate a hidden tour source without creating any scene geometry. */
function BundlePreload({ bundle, props }: { bundle: BodyCatalog['bundles'][number]; props: Props }) {
  const { scene } = useGLTF(modelDeliveryUrl(bundle.url, props.assetBase), false, true);
  const geometries = useMemo(() => bodyBundleGeometries(scene, props.catalog.structures, bundle.id),
