  // anatomy or causing structures to jump when another entry is hidden.
  const spreadScale = useMemo(
    () => props.adaptiveSpread ? bodySpreadScale(frame) : new THREE.Vector3(1, 1, 1),
    [props.adaptiveSpread, frame],
  );
  const offsets = useMemo(
    () =>
      new Map(
        rendered.map((item) => [
          item.id,
          layout === 'spatial' && props.adaptiveSpread
            ? bodySpreadOffset(
                item.center,
                center,
                props.exam ? 0 : props.explode,
                props.anchorSkeleton && item.system === 'skeleton',
                spreadScale,
              )
            : bodyPresentationOffset(
                item,
                center,
                props.exam ? (practiceTray ? 100 : 0) : props.explode,
                layout,
                props.anchorSkeleton,
                tray,
              ),
        ]),
      ),
    [
      rendered,
      center,
      props.exam,
      practiceTray,
      props.explode,
      layout,
      props.anchorSkeleton,
      tray,
      props.adaptiveSpread,
      spreadScale,
    ],
  );
  const originGuide = useMemo(
    () => selectedOriginGuide({
      enabled: props.originStyle === 'selected-guide' && props.showOrigins,
      exam: props.exam,
      layout,
      explode: props.explode,
      selectedId: props.selectedId,
      structures: rendered,
      hiddenIds: props.hiddenIds,
      contextIds: props.contextIds,
      inspection: props.inspection,
      offsets,
      appearance: props.appearance,
    }),
    [
      props.originStyle, props.showOrigins, props.exam, layout, props.explode,
      props.selectedId, rendered, props.hiddenIds, props.contextIds,
      props.inspection, offsets, props.appearance,
    ],
  );
  const bounds = useMemo(() => {
    if (props.cameraBounds && !focusId && !props.exam)
      return new THREE.Box3(
        new THREE.Vector3().fromArray(props.cameraBounds.min),
        new THREE.Vector3().fromArray(props.cameraBounds.max),
      );
    let list = rendered.length ? rendered : props.structures;
    if (focusId) {
      const selected = list.find((s) => s.id === focusId);
      if (selected) list = [selected];
    }
    const result = new THREE.Box3();
    for (const s of list)
      result.union(translatedBox(s.bounds, offsets.get(s.id)));
    if (result.isEmpty())
      result.set(new THREE.Vector3(-2, -8, -1), new THREE.Vector3(2, 8, 1));
    if (originGuide) result.union(translatedBox(originGuide.bounds));
    if (
      props.originStyle !== 'selected-guide' && props.showOrigins &&
      layout !== 'tray' && !focusId
    ) result.union(frame);
    return result;
  }, [
    props.structures,
    rendered,
    focusId,
    offsets,
    layout,
    props.showOrigins,
    props.originStyle,
    originGuide,
    frame,
    props.cameraBounds,
    props.exam,
  ]);
  const bundles = requestedBodySceneBundles(props.catalog, rendered, props.structures, props.loadBundleIds);
  const cameraPreset = useMemo(() => props.presetBounds
    ? new THREE.Box3(
      new THREE.Vector3().fromArray(props.presetBounds.min),
      new THREE.Vector3().fromArray(props.presetBounds.max),
    ) : null, [props.presetBounds]);
  const labelIds = sceneLabelIds(
    props.selectedId,
    props.landmarks,
    rendered.filter((s) => !props.hiddenIds.includes(s.id)).map((s) => s.id),
    props.focus,
  );
  const orthographic = props.plate || layout === 'tray';
  const orientationOutput = useMemo(() => createRef<HTMLSpanElement>(), []);
  const keyboardOrientationOutput = useMemo(() => createRef<HTMLOutputElement>(), []);
  const keyboardCameraFrom = useMemo(() => createRef<THREE.Vector3>(), []);
  const orientationAxes = useMemo(
    () => orientationBasis(props.catalog.coordinateSystem),
    [props.catalog.coordinateSystem],
  );
  const onKeyboardRotate = (cameraFrom: THREE.Vector3, azimuth: number, polar: number) => {
    const node = keyboardOrientationOutput.current;
    if (!node || props.exam) return;
    const direction = orientationText(cameraOrientation(cameraFrom, orientationAxes));
    const degrees = (angle: number) => Math.round(angle * 180 / Math.PI);
    keyboardCameraFrom.current = cameraFrom.clone();
    // oxlint-disable-next-line react/react-compiler -- This read-only live status is an imperative DOM sink for Three camera input.
    node.textContent = `View from: ${direction}. Orbit angle: ${degrees(azimuth)}° around, ${degrees(polar)}° from above.`;
  };
  return (
    <SceneRecovery
      className="body-scene"
      cameraKey={[
        props.view,
        props.zoom,
        props.zoomStep,
        props.reset,
        focusId,
        orthographic,
        layout,
      ].join('/')}
      key={orthographic ? 'plate' : 'perspective'}
      onHealth={props.onRendererHealth}
      cameraCapture={props.cameraCapture}
      cameraRestore={props.cameraRestore}
    >
      {(onHealth, autoRecoveryCamera, cameraTransitionActive) => (
        <div className="anatomy-oriented-scene" data-orientation={!props.exam}>
          {!props.exam && (
            <p className="anatomy-live-orientation" aria-live="off">
              View from: <span ref={orientationOutput}>unavailable</span>
            </p>
          )}
          {!props.exam && (
            <output ref={keyboardOrientationOutput} className="sr-only" aria-live="polite" aria-atomic="true" />
          )}
        <Canvas
          onFailure={() => onHealth('failed')}
          orthographic={orthographic}
          camera={{ position: [0, 0, 28], fov: 38, near: 0.01, far: 150 }}
          dpr={[1, 1.6]}
          frameloop="demand"
          gl={{ antialias: true, alpha: true, localClippingEnabled: true }}
        >
          <RendererMonitor onHealth={onHealth} />
          <SceneOrientation
            output={orientationOutput}
            statusOutput={keyboardOrientationOutput}
            keyboardCameraFrom={keyboardCameraFrom}
            coordinates={props.catalog.coordinateSystem}
            enabled={!props.exam}
          />
          <ambientLight intensity={1.4} />
          <hemisphereLight args={['#fffef8', '#a38b70', 1.1]} />
          <directionalLight position={[8, 15, 10]} intensity={2.3} />
          <directionalLight position={[-8, 6, -8]} intensity={1.8} />
          <SceneLabelLayer>
            {bundles.map((bundle) => (
              <AssetBoundary
                key={`${bundle.id}:${props.retries?.[bundle.id] ?? 0}`}
                id={bundle.id}
                url={modelDeliveryUrl(bundle.url, props.assetBase)}
                onFailure={props.onFailure}
              >
                <Suspense fallback={null}>
                  {rendered.some(s => s.bundle === bundle.id) ? <Bundle
                    bundle={bundle}
                    items={rendered.filter((s) => s.bundle === bundle.id)}
                    props={props}
                    offsets={offsets}
                    frame={cutFrame}
                    labelIds={labelIds}
                    renderedCount={rendered.length}
                    originGuide={originGuide}
                  /> : <BundlePreload bundle={bundle} props={props} />}
                </Suspense>
              </AssetBoundary>
            ))}
          </SceneLabelLayer>
          <FittedCamera
            bounds={bounds}
            presetBounds={cameraPreset}
            direction={
              orthographic && !['inferior', 'superior'].includes(props.view)
                ? [vectors[props.view][0], 0, vectors[props.view][2]]
                : vectors[props.view]
            }
            up={
              props.view === 'superior'
                ? [0, 0, -1]
                : props.view === 'inferior'
                  ? [0, 0, 1]
                  : [0, 1, 0]
            }
            viewKey={props.view}
            zoom={props.zoom}
            zoomStep={props.zoomStep}
            fitOccupancy={props.fitOccupancy ?? [0.7, 0.9]}
            reset={props.reset}
            locked={props.tourLocked || (props.plate && layout !== 'tray')}
            transitionMs={props.transitionMs}
            transitionPaused={props.transitionPaused}
            planar={layout === 'tray'}
            recenterKey={focusId ?? props.presetKey ?? ''}
            cameraCapture={props.cameraCapture}
            cameraRestore={props.cameraRestore}
            autoRecoveryCamera={autoRecoveryCamera}
            cameraTransitionActive={cameraTransitionActive}
            guidedRecovery={!!props.tourLocked || !!props.guidedRecovery}
            onKeyboardRotate={onKeyboardRotate}
          />
        </Canvas>
        </div>
      )}
    </SceneRecovery>
  );
}

export function retryBodyAssets(urls: string[], assetBase?: string) {
  for (const url of urls) useGLTF.clear(modelDeliveryUrl(url, assetBase));
}

