'use client';
import { useMemo, useState } from 'react';
import type { BodyCatalog } from './body-types';
import type { NestedImagingTopic } from '@/atlas-review/content/nested-teaching';
import type { NestedRequest } from '@/atlas-review/lib/nested-anatomy';
import {
  componentImagingTargets,
  isComponentImagingTopic,
} from '@/atlas-review/lib/component-imaging-navigation';
import { Button } from '@/atlas-review/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/atlas-review/components/ui/select';
import './component-imaging-notes.css';

export function ComponentImagingNotes({
  catalog,
  parentId,
  topic,
  side,
  disabled,
  onOpen,
}: {
  catalog: BodyCatalog;
  parentId: string;
  topic: string;
  side: string;
  disabled: boolean;
  onOpen: (
    request: NestedRequest,
    launcher: HTMLButtonElement,
    topic: NestedImagingTopic,
  ) => void;
}) {
  const targets = useMemo(
    () =>
      disabled ? [] : componentImagingTargets(catalog, parentId, topic, side),
    [catalog, parentId, topic, side, disabled],
  );
  const [choice, setChoice] = useState('');
  const keyOf = (target: NestedRequest) =>
    `${target.study}:${target.structureId}`;
  const target = targets.find((entry) => keyOf(entry) === choice) ?? targets[0];
  if (!target || disabled || !isComponentImagingTopic(topic)) return null;
  const label =
    topic === 'ultrasound'
      ? 'Ultrasound'
      : topic === 'xray'
        ? 'X-ray'
        : topic.toUpperCase();
  return (
    <details className="component-imaging-notes">
      <summary>
        {label} component notes · {targets.length}
      </summary>
      <p>
        Draft notes for individual parts, not a whole-organ lesson or scan
        access.
      </p>
      <Select
        value={keyOf(target)}
        onValueChange={(value) => {
          if (targets.some((entry) => keyOf(entry) === value))
            setChoice(value!);
        }}
      >
        <SelectTrigger aria-label={`${label} component lesson`}>
          <SelectValue>
            {target.structure.name} · {target.title}
          </SelectValue>
        </SelectTrigger>
        <SelectContent>
          {targets.map((entry) => (
            <SelectItem key={keyOf(entry)} value={keyOf(entry)}>
              {entry.structure.name} · {entry.title}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <Button
        size="sm"
        variant="outline"
        onClick={(event) => {
          if (!disabled) onOpen(target, event.currentTarget, topic);
        }}
      >
        Open {label} notes in dissection
      </Button>
    </details>
  );
}

'use client';
import {useEffect,useMemo,useRef} from 'react';
import {useFrame,useThree} from '@react-three/fiber';
import * as THREE from 'three';
import {csfMarkerY,csfTracksFor} from '@/atlas-review/lib/csf-motion';
import type {BodyStructure} from './body-types';

/** Non-selectable teaching overlay; never modifies anatomy or owns a timer. */
export function CsfMotion({structure,bundleHash}:{structure:BodyStructure;bundleHash:string}){
  const tracks=useMemo(()=>csfTracksFor(structure,bundleHash),[structure,bundleHash]);
  const elapsed=useRef(0),invalidate=useThree(s=>s.invalidate);
  const geometry=useMemo(()=>{
    const g=new THREE.BufferGeometry();
    const positions=new Float32Array(tracks.length*3);
    tracks.forEach((t,i)=>{positions.set([t.center[0],csfMarkerY(t.center[1],t.amplitude,t.phase,0),t.center[2]],i*3);});
    g.setAttribute('position',new THREE.BufferAttribute(positions,3));return g;
  },[tracks]);
  useEffect(()=>{invalidate();return()=>geometry.dispose();},[geometry,invalidate]);
  useFrame((_state,delta)=>{
    // Hidden tabs/context loss cannot produce a catch-up jump on return.
    if(typeof document!=='undefined'&&document.hidden)return;
    elapsed.current+=Math.min(Math.max(delta,0),0.05);
    const p=geometry.getAttribute('position');
    tracks.forEach((t,i)=>p.setY(i,csfMarkerY(t.center[1],t.amplitude,t.phase,elapsed.current)));
    p.needsUpdate=true;invalidate();
  });
  if(!tracks.length)return null;
  return <points name={`csf-schematic:${structure.id}`} geometry={geometry} raycast={()=>null} frustumCulled={false}>
    <shaderMaterial transparent depthWrite={false} depthTest vertexShader={`
      void main(){gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);gl_PointSize=5.0;}`}
      fragmentShader={`void main(){float r=length(gl_PointCoord-vec2(0.5));if(r>0.5)discard;
        gl_FragColor=vec4(0.10,0.95,0.90,0.95*(1.0-smoothstep(0.25,0.5,r)));}`}/>
  </points>;
}

'use client';
import { Button } from '@/atlas-review/components/ui/button';
import { Slider } from '@/atlas-review/components/ui/slider';
import {
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem,
} from '@/atlas-review/components/ui/select';
import {
  initialInspection,
  sectionAxes,
  type InspectionState,
  type SectionPlane,
} from '@/atlas-review/lib/inspection-state';

export const cutPlanes: Record<SectionPlane, string> = {
  off: 'Off · whole components',
  axial: 'Axial · horizontal',
  coronal: 'Coronal · front–back',
  sagittal: 'Sagittal · right–left',
};

export function CutawayControls({
  value,
  onChange,
  subject = 'Eye',
  positionId = 'eye-layer-cut-position',
}: {
  value: InspectionState;
  onChange: (next: InspectionState) => void;
  subject?: string;
  positionId?: string;
}) {
  const axis = value.plane === 'off' ? null : sectionAxes[value.plane];
  return (
    <details className="eye-layer-cutaway">
      <summary>
        Cutaway · {value.plane === 'off' ? 'Off' : cutPlanes[value.plane]}
      </summary>
      <Select
        value={value.plane}
        onValueChange={(plane) => {
          if (plane && Object.hasOwn(cutPlanes, plane))
            onChange({ ...initialInspection, plane: plane as SectionPlane });
        }}
      >
        <SelectTrigger aria-label={`${subject} cutaway plane`}>
          <SelectValue>{cutPlanes[value.plane]}</SelectValue>
        </SelectTrigger>
        <SelectContent>
          {Object.entries(cutPlanes).map(([plane, label]) => (
            <SelectItem key={plane} value={plane}>
              {label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      {axis && (
        <>
          <label htmlFor={positionId}>Cut position · {value.position}%</label>
          <Slider
            id={positionId}
            aria-label={`${subject} cutaway position`}
            aria-valuetext={`${value.position}% from ${axis.low.toLowerCase()} to ${axis.high.toLowerCase()}`}
            min={0}
            max={100}
            step={1}
            value={[value.position]}
            onValueChange={(values) => {
              const position = Array.isArray(values) ? values[0] : values;
              if (Number.isFinite(position))
                onChange({
                  ...value,
                  position: Math.max(0, Math.min(100, position)),
                });
            }}
          />
          <div className="eye-layer-cut-axis" aria-hidden="true">
            <span>{axis.low}</span>
            <span>{axis.high}</span>
          </div>
          <Button
            size="sm"
            variant="outline"
            aria-label={`Reverse ${subject.toLowerCase()} cutaway side`}
            onClick={() => onChange({ ...value, flipped: !value.flipped })}
          >
            Keep {value.flipped ? axis.low : axis.high} · reverse
          </Button>
          <p>
            Artificial open-surface cut, not a scan or reconstructed tissue. It
            also cuts the selected component and follows separated parts.
          </p>
        </>
      )}
    </details>
  );
}

'use client';
import { useLayoutEffect, useMemo, useRef, useState } from 'react';
import {
  ArrowLeft,
  ArrowRight,
  RotateCcw,
  Undo2,
  Redo2,
  Layers3,
} from 'lucide-react';
import { Button } from '@/atlas-review/components/ui/button';
import { Switch } from '@/atlas-review/components/ui/switch';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/atlas-review/components/ui/select';
import type {
  DissectionProfile,
  DissectionState,
  DissectionStage,
  DissectionFocus,
} from './dissection-data';
import { bodySystems, type BodyStructure, type BodySystem } from './body-types';
import {
  dissectionSections,
  dissectionTransition,
  filterRemovedStructures,
} from '@/atlas-review/lib/dissection-workbench';
import { stageStructures } from './dissection-data';
import { StudyLibrary } from './study-library';
import { DissectionOrientation } from './dissection-orientation';
import type { DissectionGuidance } from '@/atlas-review/lib/dissection-guidance';
import type { DissectionView } from './dissection-data';

export function DissectionControls({
  profile,
  state,
  onStage,
  onFocus,
  onUndo,
  onRedo,
  onReset,
  ghost,
  onGhost,
  visibleCount,
  structures,
  visibleIds,
  loaded,
  failed,
  disabled,
}: {
  profile: DissectionProfile;
  state: DissectionState;
  onStage: (id: string) => void;
  onFocus: (id: string) => void;
  onUndo: () => void;
  onRedo: () => void;
  onReset: () => void;
  ghost: boolean;
  onGhost: (value: boolean) => void;
  visibleCount: number;
  structures: BodyStructure[];
  visibleIds: string[];
  loaded: string[];
  failed: string[];
  disabled: boolean;
}) {
  const { layers, windows } = useMemo(
    () => dissectionSections(profile),
    [profile],
  );
  const stage = profile.stages.find((s) => s.id === state.stageId);
  const [libraryOpen, setLibraryOpen] = useState(false);
  const [libraryOpened, setLibraryOpened] = useState(false);
  const libraryTrigger = useRef<HTMLButtonElement>(null);
  const deck = useRef<HTMLElement>(null);
  const undoButton = useRef<HTMLButtonElement>(null);
  const redoButton = useRef<HTMLButtonElement>(null);
  const resetButton = useRef<HTMLButtonElement>(null);
  const focusHandover = useRef<{ kind: 'undo' | 'redo'; source: HTMLButtonElement } | null>(null);
  const rememberHistoryAction = (kind: 'undo' | 'redo') => {
    const source = kind === 'undo' ? undoButton.current : redoButton.current;
    if (!source || disabled || source.disabled || source.ownerDocument.activeElement !== source) {
      focusHandover.current = null;
      return;
    }
    const pending = { kind, source };
    focusHandover.current = pending;
    // A no-op action must not leave a future, unrelated history update armed.
    setTimeout(() => { if (focusHandover.current === pending) focusHandover.current = null; }, 0);
  };
  useLayoutEffect(() => {
    const pending = focusHandover.current;
    focusHandover.current = null;
    if (!pending || disabled) return;
    const root = deck.current, source = pending.source, doc = source.ownerDocument;
    if (!root?.isConnected || !source.isConnected || !source.disabled ||
        source.closest('.dissection-deck') !== root ||
        root.closest('[hidden], [inert], [aria-hidden="true"]') ||
        source.closest('[hidden], [inert], [aria-hidden="true"]') ||
        !root.getClientRects().length || !source.getClientRects().length ||
        (doc.activeElement !== source && doc.activeElement !== doc.body)) return;
    const alternate = pending.kind === 'undo' ? redoButton.current : undoButton.current;
    const target = alternate && !alternate.disabled ? alternate : resetButton.current;
    if (target?.isConnected && !target.disabled && target.ownerDocument === doc &&
        root.contains(target) &&
        !target.closest('[hidden], [inert], [aria-hidden="true"]') &&
        target.getClientRects().length) target.focus({ preventScroll: true });
  }, [state.history.length, state.future.length, disabled]);
  const layerMode =
    layers.length > 0 && stage?.kind !== 'window' && !state.focusId;
  const choices = layerMode ? layers : windows;
  const showLayers = layerMode && !libraryOpen;
  const index = choices.findIndex((s) => s.id === state.stageId);
  const next = layerMode ? choices[index + 1] : undefined;
  const transition = useMemo(
    () =>
      next
        ? dissectionTransition(structures, profile, visibleIds, next.id)
        : null,
    [structures, profile, visibleIds, next],
  );
  const counts = useMemo(
    () =>
      new Map(
        layers.map((item) => [
          item.id,
          stageStructures(structures, profile, item.id).length,
        ]),
      ),
    [structures, profile, layers],
  );
  const title = state.focusId
    ? profile.focuses.find((f) => f.id === state.focusId)?.title
    : (stage?.title ?? 'Free exploration');
  return (
    <section
      ref={deck}
      className="dissection-deck"
      aria-label="Guided dissection controls"
    >
      <div className="dissection-deck-heading">
        <Layers3 />
        <strong>Dissection workspace</strong>
        <span title="Enabled by the current layers and system filters; models may still be loading or unavailable.">
          {visibleCount} enabled
        </span>
        <Button
          ref={undoButton}
          size="sm"
          variant="ghost"
          onClick={onUndo}
          onClickCapture={() => rememberHistoryAction('undo')}
          disabled={disabled || !state.history.length}
          aria-label="Undo last dissection change"
          aria-keyshortcuts="Control+Z Meta+Z"
          title="Undo a dissection step or removal (Ctrl/Cmd+Z); camera and display settings are separate"
        >
          <Undo2 />
          Undo
        </Button>
        <Button
          ref={redoButton}
          size="sm"
          variant="ghost"
          onClick={onRedo}
          onClickCapture={() => rememberHistoryAction('redo')}
          disabled={disabled || !state.future.length}
          aria-label="Redo last undone dissection change"
          aria-keyshortcuts="Control+Shift+Z Meta+Shift+Z Control+Y"
          title="Reapply the last undone dissection change (Ctrl/Cmd+Shift+Z or Ctrl+Y)"
        >
          <Redo2 />
          Redo
        </Button>
        <Button ref={resetButton} size="sm" variant="ghost" onClick={onReset} disabled={disabled}>
          <RotateCcw />
          Reassemble
        </Button>
      </div>
      <div className="dissection-modes" aria-label="Dissection mode">
        {layers.length > 0 && (
          <button
            type="button"
            aria-pressed={showLayers}
            disabled={disabled}
            onClick={() => {
              setLibraryOpen(false);
              onStage(layers[0].id);
            }}
          >
            Layer by layer <small>{layers.length} steps</small>
          </button>
        )}
        <button
          type="button"
          ref={libraryTrigger}
          aria-pressed={libraryOpen}
          disabled={disabled || (!windows.length && !profile.focuses.length)}
          onClick={() => {
            setLibraryOpened(true);
            setLibraryOpen((value) => !value);
          }}
        >
          Study windows & focuses <small>Search & preview</small>
        </button>
      </div>
      <p className="dissection-mode-note">
        {showLayers
          ? 'Remove available layers step by step. Missing skin, fascia or other tissues are not simulated.'
          : 'Independent views of selected structures—not successive dissection layers.'}
      </p>
      <p className="dissection-current-view">
        Current recipe: <strong>{title}</strong>
      </p>
      <div hidden={!libraryOpen}>
        {libraryOpened && (
          <StudyLibrary
            profile={profile}
            state={state}
            structures={structures}
            visibleIds={visibleIds}
            loaded={loaded}
            failed={failed}
            disabled={disabled}
            onStage={(id) => {
              onStage(id);
              setLibraryOpen(false);
              libraryTrigger.current?.focus();
            }}
            onFocus={(id) => {
              onFocus(id);
              setLibraryOpen(false);
              libraryTrigger.current?.focus();
            }}
          />
        )}
      </div>
      {showLayers && (
        <div className="dissection-step-row">
          {layerMode && (
            <Button
              size="icon"
              variant="outline"
              disabled={disabled || index <= 0}
              onClick={() => onStage(choices[index - 1].id)}
              aria-label="Previous dissection stage"
            >
              <ArrowLeft />
            </Button>
          )}
          <Select
            value={index < 0 ? 'free' : state.stageId}
            onValueChange={(id) => {
              if (id) onStage(id);
            }}
          >
            <SelectTrigger
              disabled={disabled}
              aria-label="Choose dissection stage"
            >
              <SelectValue>
                {index >= 0 && layerMode
                  ? `${index + 1} / ${choices.length} · `
                  : ''}
                {title}
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="free">Free exploration</SelectItem>
              {choices.map((s, i) => (
                <SelectItem key={s.id} value={s.id}>
                  {layerMode ? `${i + 1}. ` : ''}
                  {s.title}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          {layerMode && (
            <Button
              size="icon"
              variant="outline"
              disabled={disabled || !next}
              onClick={() => next && onStage(next.id)}
              aria-label="Next dissection stage"
            >
              <ArrowRight />
            </Button>
          )}
        </div>
      )}
      {showLayers && !disabled && (
        <ol
          className="dissection-layer-track"
          aria-label="Available layer sequence"
        >
          {layers.map((s, i) => (
            <li key={s.id}>
              <button
                type="button"
                title={s.title}
                aria-label={`Stage ${i + 1}: ${s.title}`}
                aria-current={s.id === state.stageId ? 'step' : undefined}
                disabled={disabled}
                onClick={() => onStage(s.id)}
                className={i === index ? 'current' : ''}
              >
                <span>{i + 1}</span>
                <strong>{s.title}</strong>
                <small>{counts.get(s.id)} retained</small>
              </button>
            </li>
          ))}
        </ol>
      )}
      {showLayers && transition && !disabled && (
        <details className="dissection-preview" key={next?.id}>
          <summary>
            Next: {transition.stage.title}
            <span>
              {transition.removed.length} to hide · {transition.restored.length}{' '}
              to restore
            </span>
          </summary>
          <p>{transition.stage.description}</p>
          <p>
            Starts a clean stage: manual changes, system filters and separation
            reset. Counts refer to catalogue visibility, including anatomy still
            loading.
          </p>
          {(
            [
              ['To hide', transition.removed],
              ['To restore', transition.restored],
            ] as const
          ).map(
            ([heading, items]) =>
              items.length > 0 && (
                <div key={heading}>
                  <strong>
                    {heading} ({items.length})
                  </strong>
                  <ul>
                    {items.map((item) => (
                      <li key={item.id}>{item.name}</li>
                    ))}
                  </ul>
                </div>
              ),
          )}
          <Button
            size="sm"
            disabled={disabled}
            onClick={() => onStage(transition.stage.id)}
          >
            Apply next step <ArrowRight />
          </Button>
        </details>
      )}
      {showLayers && !next && (
        <output className="dissection-mode-note">
          Layer sequence complete. Step back to restore layers, reassemble, or
          choose a study window.
        </output>
      )}
      <div className="dissection-options">
        <label htmlFor="ghost-tissues">
          <Switch
            id="ghost-tissues"
            checked={ghost}
            onCheckedChange={onGhost}
            disabled={disabled}
            aria-label="Ghost removed tissues"
          />
          <span>Ghost removed tissues</span>
        </label>
        <Button
          size="sm"
          variant="outline"
          disabled={disabled}
          onClick={() => {
            onStage('free');
            setLibraryOpen(false);
          }}
        >
          Free exploration
        </Button>
      </div>
    </section>
  );
}

export function DissectionGuide({
  guidance,
  side,
  view,
  onOrient,
  onRecipe,
  profile,
  stage,
  focus,
  removed,
  onRestore,
  onRestoreMany,
  onSelect,
  customized,
}: {
  guidance: DissectionGuidance;
  side: string;
  view: DissectionView;
  onOrient: () => void;
  onRecipe: (kind: 'recipe' | 'next') => void;
  profile: DissectionProfile;
  stage: DissectionStage | undefined;
  focus?: DissectionFocus;
  removed: BodyStructure[];
  onRestore: (id: string) => void;
  onRestoreMany: (ids: string[]) => void;
  onSelect: (id: string) => void;
  customized: boolean;
}) {
  const [removedSearch, setRemovedSearch] = useState('');
  const [removedSystem, setRemovedSystem] = useState<BodySystem | 'all'>('all');
  const matches = useMemo(
    () => filterRemovedStructures(removed, removedSearch, removedSystem),
    [removed, removedSearch, removedSystem],
  );
  return (
    <section className="dissection-guide" aria-label="Dissection study guide">
      <div className="eyebrow">
        {focus
          ? 'FOCUSED STUDY'
          : stage?.kind === 'window'
            ? 'EXPOSURE WINDOW'
            : 'REGIONAL DISSECTION'}
        {customized ? ' · CUSTOMISED' : ''}
      </div>
      <h2>{focus?.title ?? stage?.title ?? profile.title}</h2>
      <p>
        {focus
          ? (focus.description ??
            'This focused view retains the selected muscle or organ group with available skeletal context.')
          : (stage?.description ?? profile.orientation)}
      </p>
      <div className="dissection-inspect">
        <strong>Look for</strong>
        <p>
          {focus?.inspect ??
            stage?.inspect ??
            'Rotate, select a structure and use Remove to create your own view. Undo and Reassemble restore your changes.'}
        </p>
      </div>
      <DissectionOrientation
        guide={guidance}
        side={side}
        view={view}
        onOrient={onOrient}
        onSelect={onSelect}
        onRecipe={onRecipe}
      />
      <details className="dissection-removed">
        <summary>Removed from this view ({removed.length})</summary>
        {removed.length ? (
          <>
            <div className="dissection-tray-filters">
              <input
                type="search"
                value={removedSearch}
                onChange={(e) => setRemovedSearch(e.target.value)}
                aria-label="Search removed structures"
                placeholder="Find a removed structure…"
              />
              <select
                value={removedSystem}
                onChange={(e) =>
                  setRemovedSystem(e.target.value as BodySystem | 'all')
                }
                aria-label="Filter removed structures by system"
              >
                <option value="all">All systems</option>
                {(Object.keys(bodySystems) as BodySystem[]).map((system) => (
                  <option key={system} value={system}>
                    {bodySystems[system].name} (
                    {removed.filter((item) => item.system === system).length})
                  </option>
                ))}
              </select>
              <button
                type="button"
                disabled={!matches.length}
                onClick={() => onRestoreMany(matches.map((item) => item.id))}
              >
                Restore these {matches.length} structures
              </button>
              <output>
                {matches.length} of {removed.length} removed structures match.
                Group restoration can be undone in one step.
              </output>
            </div>
            <div className="dissection-tray-list">
              {matches.map((s) => (
                <button
                  type="button"
                  key={s.id}
                  onClick={() => onRestore(s.id)}
                >
                  <span>{s.name}</span>
                  <small>Restore</small>
                </button>
              ))}
              {!matches.length && (
                <p>
                  No removed structures match. Clear the search or choose
                  another system.
                </p>
              )}
            </div>
          </>
        ) : (
          <p>
            No structures removed. System switches are separate from dissection
            removal.
          </p>
        )}
      </details>
      <details className="dissection-limits">
        <summary>Coverage & review limits</summary>
        <p>{profile.orientation}</p>
        <ul>
          {profile.limitations.map((text) => (
            <li key={text}>{text}</li>
          ))}
        </ul>
        <p>
          Educational visibility stages · Not tissue cutting or an operative
          sequence. Independent anatomical review is pending.
        </p>
        {[...new Set(profile.references)].map((url) => (
          <a key={url} href={url} target="_blank" rel="noreferrer">
            Anatomical reference ↗
          </a>
        ))}
      </details>
    </section>
  );
}

'use client';
import { useState } from 'react';
import { Button } from '@/atlas-review/components/ui/button';
import { ArrowRight, Compass } from 'lucide-react';
import type { DissectionView } from './dissection-data';
import { filterRemovedStructures } from '@/atlas-review/lib/dissection-workbench';
import {
  dissectionOrientation,
  guideAvailabilityText,
  guidanceRecipeAction,
  type DissectionGuidance,
} from '@/atlas-review/lib/dissection-guidance';

export function DissectionOrientation({
  guide,
  side,
  view,
  onOrient,
  onSelect,
  onRecipe,
  disabled = false,
}: {
  guide: DissectionGuidance;
  side: string;
  view: DissectionView;
  onOrient: () => void;
  onSelect: (id: string) => void;
  onRecipe: (kind: 'recipe' | 'next') => void;
  disabled?: boolean;
}) {
  const [query, setQuery] = useState('');
  if (disabled) return null;
  const matchedIds = new Set(
    filterRemovedStructures(guide.expected, query).map((s) => s.id),
  );
  const matches = guide.members.filter(({ structure }) =>
    matchedIds.has(structure.id),
  );
  const recipeAction = guidanceRecipeAction(guide, 'recipe', disabled);
  const changed = guide.missing.length > 0 || guide.added.length > 0;
  return (
    <div className="dissection-orientation">
      <div className="dissection-orientation-heading">
        <Compass aria-hidden="true" />
        <strong>Orient this dissection</strong>
      </div>
      <p>
        {side === 'both'
          ? 'Both sides'
          : side === 'left'
            ? 'Left-side scope'
            : 'Right-side scope'}{' '}
        · midline, unpaired and source-unspecified entries remain included.
      </p>
      <dl>
        <div>
          <dt>Camera preset</dt>
          <dd>{dissectionOrientation[view]}</dd>
        </div>
        {guide.recipe && (
          <div>
            <dt>Recipe orientation</dt>
            <dd>{dissectionOrientation[guide.recipe.view]}</dd>
          </div>
        )}
      </dl>
      <p className="dissection-guidance-note">
        Free rotation can differ from the preset. Reorient resets pan, zoom and
        selected-only framing; tissue visibility and separation amount stay
        unchanged.
      </p>
      <Button variant="outline" size="sm" onClick={onOrient}>
        <Compass />
        Reorient {guide.recipe ? 'to recipe' : 'to preset'}
      </Button>
      <details className="dissection-view-inventory">
        <summary>
          What is in this view?{' '}
          <span>{guide.visible.length} enabled entries</span>
        </summary>
        <p>
          {guide.counts.ready} ready · {guide.counts.pending} loading ·{' '}
          {guide.counts.failed} unavailable. {guide.counts.removed} removed ·{' '}
          {guide.counts.systemOff} system off.
        </p>
        <p className="dissection-guidance-note">
          Counts are catalogue entries, not visible pixels. Ghosting, fading,
          clipping and separation do not change these counts.
        </p>
        {guide.recipe ? (
          <>
            <p>
              {changed
                ? `${guide.missing.length} recipe entries omitted · ${guide.added.length} extra entries enabled.`
                : 'Enabled entries match the recipe.'}
            </p>
            {guide.targets && (
              <p>
                {guide.targets.length} recipe targets ·{' '}
                {guide.context?.length ?? 0} context entries in the clean
                recipe. Context is a study grouping, not a validated anatomical
                relationship.
              </p>
            )}
            {changed && (
              <>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => onRecipe('recipe')}
                  disabled={!recipeAction}
                >
                  Reopen clean recipe
                </Button>
                <p className="dissection-guidance-note">
                  Restores the recipe, enables systems and resets manual edits,
                  cutaways and separation. Failed downloads may still need Retry
                  missing anatomy.
                </p>
              </>
            )}
            <label className="dissection-member-search">
              <span>Find a recipe member</span>
              <input
                type="search"
                value={query}
                maxLength={256}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Name or FMA ID"
              />
            </label>
            <output aria-live="polite">
              {matches.length} of {guide.members.length} recipe entries match.
            </output>
            <ul className="dissection-member-list">
              {matches.map(({ structure: s, status, role }) => (
                <li key={s.id}>
                  <button type="button" onClick={() => onSelect(s.id)}>
                    <span>{s.name}</span>
                    <small>
                      {role === 'member'
                        ? 'Recipe member'
                        : role === 'target'
                          ? 'Target'
                          : 'Context'}{' '}
                      · {guideAvailabilityText[status]}
                    </small>
                    <small>{s.fmaId}</small>
                  </button>
                </li>
              ))}
            </ul>
            {!matches.length && (
              <p>
                No recipe members match. Clear the search or choose another
                view.
              </p>
            )}
          </>
        ) : (
          <p>
            Free exploration has no fixed recipe. Reassemble to restart the
            region, or choose a study window.
          </p>
        )}
      </details>
      {guide.next && (
        <div className="dissection-next-guidance">
          <strong>Next layer: {guide.next.stage.title}</strong>
          <p>
            {guide.next.removed.length} to hide · {guide.next.restored.length}{' '}
            to restore · {guide.next.retained.length} retained.
          </p>
          <Button
            size="sm"
            variant="outline"
            onClick={() => onRecipe('next')}
            disabled={!guidanceRecipeAction(guide, 'next', disabled)}
          >
            Open next layer
            <ArrowRight />
          </Button>
          <p className="dissection-guidance-note">
            Starts a clean recipe; manual edits, system filters, cutaways and
            separation reset. This is a visibility sequence, not an operative
            order.
          </p>
        </div>
      )}
      {guide.finalLayer && (
        <p>
          Final layer reached. Step back, reassemble or choose an independent
          study window.
        </p>
      )}
      {guide.landmarks.length > 0 && (
        <div className="dissection-landmarks" aria-label="Stage landmarks">
          {guide.landmarks.map(({ structure: s, status }) => (
            <button type="button" key={s.id} onClick={() => onSelect(s.id)}>
              <span>{s.name}</span>
              <small>{guideAvailabilityText[status]}</small>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

'use client';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/atlas-review/components/ui/select';
import type { BodyLayout } from '@/atlas-review/lib/body-arrangement';
import './explode-style-select.css';

const styles = [
  { value: 'spatial', label: 'Spread' },
  { value: 'extract', label: 'Extract selected' },
  { value: 'tray', label: 'Tray' },
] as const;

export function ExplodeStyleSelect({
  value,
  disabled,
  onChange,
}: {
  value: BodyLayout;
  disabled: boolean;
  onChange: (value: BodyLayout) => void;
}) {
  return (
    <Select
      value={value}
      items={styles}
      disabled={disabled}
      onValueChange={(next) => {
        if (!disabled && styles.some((style) => style.value === next))
          onChange(next as BodyLayout);
      }}
    >
      <SelectTrigger
        className="vm-explode-style"
        aria-label="Explode style"
        title="Choose how structures separate"
      >
        <SelectValue />
      </SelectTrigger>
      <SelectContent className="vm-explode-menu" alignItemWithTrigger={false}>
        {styles.map((style) => (
          <SelectItem key={style.value} value={style.value}>
            {style.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

'use client';
import { useCallback, useEffect, useLayoutEffect, useMemo, useReducer, useRef, useState } from 'react';
import { NestedTeaching } from './nested-teaching';
import { ImagingLink } from './imaging-link';
import { useNestedEducationLink } from './nested-education-link';
import {useHeadNestedSelection} from './head-selection-channel';
import type { NestedImagingTopic } from '@/atlas-review/content/nested-teaching';
import { guidedPlaybackDuration, guidedSweepDuration, isGuidedPlaybackRate, type GuidedPlaybackRate } from '@/atlas-review/lib/guided-playback';
import { TourSpeedControl } from './tour-speed-control';
import { ArrowLeft, RotateCcw, Eye, Focus, Tags } from 'lucide-react';
import { Button } from '@/atlas-review/components/ui/button';
import { Switch } from '@/atlas-review/components/ui/switch';
import { Slider } from '@/atlas-review/components/ui/slider';
import {
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem,
} from '@/atlas-review/components/ui/select';
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogDescription,
} from './study-surface';
import { BodyScene, retryBodyAssets } from './body-scene';
import { allBodySystems, type BodyCatalog, type BodyStructure } from './body-types';
import { initialInspection } from '@/atlas-review/lib/inspection-state';
import {
  CutawayControls as EyeCutawayControls,
  cutPlanes as eyeCutPlanes,
} from './cutaway-controls';
export { CutawayControls as EyeCutawayControls } from './cutaway-controls';
import {
  selectionBounds,
  selectionVisibility,
} from '@/atlas-review/lib/selection-visibility';
import {
  eyeCatalog,
  eyeLayersFor,
  eyeNotes,
  eyeReferences,
  type EyePreset,
} from '@/atlas-review/lib/eye-layers';
import {
  initialEyeLayers,
  reduceEyeLayers,
  type EyeAction,
  type EyeLayerState,
} from '@/atlas-review/lib/eye-layer-state';
import type { DissectionView } from './dissection-data';
import type { BodyLayout } from '@/atlas-review/lib/body-arrangement';
import type { RendererHealth } from '@/atlas-review/lib/renderer-health';
import { modelLoadAccessNotice, type ModelLoadFailure } from '@/atlas-review/lib/model-load-failure';
import type { StudyCamera } from '@/atlas-review/lib/study-views';
import { eyeLayerGuide } from '@/atlas-review/lib/eye-layer-guide';
import './eye-layers.css';

export function EyeLayerView({
  parent,
  initialSelectedId,
  initialTeachingTopic,
  educationCatalog,
  assetBase = '',
  initialGuidedLearningExpanded = false,
}: {
  parent: BodyStructure;
  initialSelectedId?: string;
  initialTeachingTopic?: NestedImagingTopic;
  educationCatalog?: BodyCatalog;
  assetBase?: string;
  initialGuidedLearningExpanded?: boolean;
}) {
  const layers = useMemo(() => eyeLayersFor(parent), [parent]);
  const initialSelection = layers.find((s) => s.id === initialSelectedId)?.id;
  const frame = useMemo(() => selectionBounds(layers), [layers]);
  const [manualInspection, setInspection] = useState(initialInspection);
  const [
    { selectedId: manualSelectedId, hidden: manualHidden, history, future, preset: manualPreset },
    dispatch,
  ] = useReducer(
    (state: EyeLayerState, action: EyeAction) =>
      reduceEyeLayers(layers, state, action),
    layers,
    (items) =>
      initialSelection
        ? {
            selectedId: initialSelection,
            hidden: [],
            history: [],
            future: [],
            preset: 'all' as const,
          }
        : initialEyeLayers(items),
  );
  const [manualExplode, setExplode] = useState(0),
    [manualLayout, setLayout] = useState<BodyLayout>('extract');
  const [manualOrigins, setShowOrigins] = useState(false);
  const [manualView, setView] = useState<DissectionView>('anterior'),
    [manualLabels, setLabels] = useState(true);
  const [manualIsolated, setIsolated] = useState(!!initialSelection),
    [manualFocus, setFocus] = useState(false),
    [reset, setReset] = useState(0);
  const [health, setHealth] = useState<RendererHealth>('starting');
  const [loaded, setLoaded] = useState(false),
    [failed, setFailed] = useState(false),
    [retry, setRetry] = useState(0);
  const [failureReason, setFailureReason] = useState<ModelLoadFailure>('unavailable');
  const accessNotice = failed ? modelLoadAccessNotice([failureReason]) : null;
  const guide = useMemo(() => eyeLayerGuide(parent), [parent]);
  const cameraCapture = useRef<StudyCamera | null>(null), cameraRestore = useRef<StudyCamera | null>(null);
  const guideLauncher = useRef<HTMLButtonElement | null>(null), restoreGuideFocus = useRef(false);
  const [guideExpanded, setGuideExpanded] = useState(initialGuidedLearningExpanded);
  const [reducedMotion, setReducedMotion] = useState(true), [pageHidden, setPageHidden] = useState(false);
  const [guidance, setGuidance] = useState<{id: string; index: number; camera: StudyCamera | null} | null>(null);
  const [fullTour, setFullTour] = useState(false), [tourPlaying, setTourPlaying] = useState(false);
  const [tourRate, setTourRate] = useState<GuidedPlaybackRate>(1);
  const [motionPaused, setMotionPaused] = useState(false);
  const playbackEpoch = useRef(0);
  const playbackOwner = useRef<{guide: typeof guide; guidance: typeof guidance; parent: typeof parent;
    ready: boolean; hidden: boolean; fullTour: boolean; playing: boolean} | null>(null);
  const step = guidance?.id === guide?.id ? guide?.steps[guidance!.index] : undefined;
  // Guidance is a reversible presentation overlay: manual state/history never changes.
  const selectedId = step?.selectedId ?? manualSelectedId;
  const hidden = step ? layers.filter(s => !step.ids.includes(s.id)).map(s => s.id) : manualHidden;
  const currentPreset = step?.preset ?? manualPreset;
  const inspection = step ? initialInspection : manualInspection;
  const explode = step ? 0 : manualExplode, layout = step ? 'spatial' : manualLayout;
  const showOrigins = step ? false : manualOrigins, view = step?.view ?? manualView;
  const labels = step ? true : manualLabels, isolated = step ? guide!.fadeOthers : manualIsolated;
  const focus = step ? false : manualFocus;
  const ready = health === 'ready' && loaded && !failed;
  const pauseTour = useCallback(() => { playbackEpoch.current++; setTourPlaying(false); setMotionPaused(true); }, []);
  useLayoutEffect(() => { playbackOwner.current = {guide, guidance, parent, ready, hidden: pageHidden,
    fullTour, playing: tourPlaying}; });
  useEffect(() => {
    if (!fullTour || !tourPlaying || !guidance || guidance.id !== guide?.id || !ready || pageHidden) return;
    let active = true;
    const epoch = playbackEpoch.current, index = guidance.index;
    const timer = window.setTimeout(() => {
      const owner = playbackOwner.current;
      if (!active || epoch !== playbackEpoch.current || document.hidden || !owner ||
        owner.guide !== guide || owner.guidance !== guidance || owner.parent !== parent ||
        !owner.ready || owner.hidden || !owner.fullTour || !owner.playing) return;
      if (index + 1 < guide.steps.length) guideStep(index + 1);
      else pauseTour();
    }, guidedPlaybackDuration(guide.steps[index].caption, 0, tourRate));
    return () => { active = false; window.clearTimeout(timer); };
  }, [fullTour, tourPlaying, guidance, guide, parent, ready, pageHidden, tourRate, pauseTour]);
  useEffect(() => { if (fullTour && (!ready || pageHidden || guidance?.id !== guide?.id)) pauseTour(); },
    [fullTour, ready, pageHidden, guidance?.id, guide?.id, pauseTour]);
  const changeTourRate = (rate: GuidedPlaybackRate) => {
    if (!isGuidedPlaybackRate(rate) || rate === tourRate) return;
    playbackEpoch.current++;
    setTourRate(rate);
  };
  useEffect(() => {
    const leave = () => pauseTour();
    window.addEventListener('pagehide', leave);
    return () => { window.removeEventListener('pagehide', leave); playbackOwner.current = null; playbackEpoch.current++; };
  }, [pauseTour]);
  useEffect(() => {
    if (!guide) return;
    const preference = window.matchMedia('(prefers-reduced-motion: reduce)');
    const motion = () => { setReducedMotion(preference.matches); pauseTour(); };
    const visibility = () => { setPageHidden(document.hidden); if (document.hidden) pauseTour(); };
    motion(); visibility();
    preference.addEventListener('change', motion); document.addEventListener('visibilitychange', visibility);
    return () => { preference.removeEventListener('change', motion); document.removeEventListener('visibilitychange', visibility); };
  }, [guide, pauseTour]);
  useLayoutEffect(() => {
    if (!guidance && restoreGuideFocus.current) {
      guideLauncher.current?.focus(); restoreGuideFocus.current = false;
    }
  }, [guidance]);
  const onLoaded = useCallback(() => {
    setLoaded(true);
    setFailed(false);
    setFailureReason('unavailable');
  }, []);
  const onFailure = useCallback((_id: string, reason: ModelLoadFailure = 'unavailable') => {
    pauseTour();
    setFailed(true);
    setLoaded(false);
    setFailureReason(reason);
  }, [pauseTour]);
  const selected = layers.find((s) => s.id === selectedId);
  useHeadNestedSelection({catalog:educationCatalog,parent,study:'eye',selected,
    blocked:step?{status:'blocked',reason:'guided'}:!ready|| (!!initialSelectedId&&!initialSelection)?{status:'blocked',reason:'unavailable'}:null});
  const cutSelection = selected
    ? selectionVisibility({
        system: selected.system,
        enabled: true,
        bounds: selected.bounds,
        frame,
        inspection,
      })
    : null;
  const appearance = useMemo(
    () =>
      Object.fromEntries(
        layers.map((s) => [
          s.id,
          {
            color: eyeNotes[s.kind].color,
            opacity:
              s.id === selectedId
                ? Math.max(0.55, eyeNotes[s.kind].opacity)
                : eyeNotes[s.kind].opacity,
          },
        ]),
      ),
    [layers, selectedId],
  );
  function applySelection(id: string) {
    if (step) return;
    dispatch({ type: 'select', id });
    setFocus(false);
  }
  const educationAllowedIds = useMemo(
    () => loaded && !failed
      ? layers.filter((s) => !hidden.includes(s.id)).map((s) => s.id)
      : [],
    [layers, hidden, loaded, failed],
  );
  const educationLink = useNestedEducationLink({
    catalog: educationCatalog,
    parent,
    study: 'eye',
    layers,
    allowedIds: educationAllowedIds,
    disabled: !layers.length || (!!initialSelectedId && !initialSelection) ||
      health !== 'ready' || !loaded || failed ||
      !!step || isolated || inspection.plane !== 'off',
    onSelect: applySelection,
  });
  function select(id: string) {
    if (step) return;
    applySelection(id);
    educationLink.publish(id);
  }
  function preset(value: EyePreset) {
    if (step) return;
    dispatch({ type: 'preset', value });
    setExplode(0);
    setIsolated(false);
    setFocus(false);
    setInspection(initialInspection);
  }
  function guideStep(index: number) {
    if (!guide || !ready || pageHidden || !Number.isInteger(index) || !guide.steps[index] ||
      (!!initialSelectedId && !initialSelection)) return;
    playbackEpoch.current++;
    setMotionPaused(false);
    setGuidance(previous => ({id: guide.id, index,
      camera: previous?.id === guide.id ? previous.camera : structuredClone(cameraCapture.current)}));
    setReset(n => n + 1); setGuideExpanded(true);
  }
  function exitGuide() {
    if (!guidance) return;
    pauseTour(); setFullTour(false);
    cameraRestore.current = structuredClone(guidance.camera);
    restoreGuideFocus.current = true; setGuidance(null); setReset(n => n + 1);
  }
  const unavailable = eyeCatalog.excluded.filter(
    (s) => s.parentId === parent.id,
  );
  if (!layers.length)
    return (
      <p role="alert">
        This eye’s source binding has changed. Layer dissection is unavailable
        pending review.
      </p>
    );
  return (
    <div className="eye-layer-workbench">
      <div className="eye-layer-viewport">
        <BodyScene
          assetBase={assetBase}
          catalog={eyeCatalog}
          structures={layers}
          selectedId={selectedId}
          systems={allBodySystems}
          isolated={isolated && !!selected}
          hiddenIds={hidden}
          ghostRemoved={false}
          illustrated
          labels={labels}
          landmarks={layers.map((s) => s.id)}
          explode={explode}
          layout={layout}
          anchorSkeleton={false}
          showOrigins={showOrigins}
          originStyle="selected-guide"
          view={view}
          zoom={1}
          reset={reset}
          focus={focus}
          exam={false}
          inspection={inspection}
          plate={false}
          appearance={appearance}
          retries={{ 'eye-layers': retry }}
          cameraBounds={step ? selectionBounds(layers.filter(s => step.ids.includes(s.id))) : undefined}
          cameraCapture={cameraCapture} cameraRestore={cameraRestore}
          tourLocked={!!step}
          transitionMs={step && !reducedMotion ? fullTour ? guidedSweepDuration(tourRate) : guide!.transitionMs : 0}
          transitionPaused={!!step && (!ready || pageHidden || (fullTour && motionPaused))}
          onSelect={select}
          onLoaded={onLoaded}
          onFailure={onFailure}
          onRendererHealth={next => { if (next !== 'ready') pauseTour(); setHealth(next); }}
        />
        {!loaded && !failed && (
          <output className="eye-layer-status">Loading eye layers…</output>
        )}
        {failed && (
          <div className="eye-layer-status" role="alert">
            {accessNotice?.message ?? 'Eye layers could not load.'}{' '}
            <Button
              size="sm"
              onClick={() => {
                retryBodyAssets(eyeCatalog.bundles.map((b) => b.url), assetBase);
                setFailed(false);
                setFailureReason('unavailable');
                setLoaded(false);
                setRetry((r) => r + 1);
              }}
            >
              {accessNotice?.retryLabel ?? 'Retry'}
            </Button>
          </div>
        )}
        {hidden.length === layers.length && (
          <p className="eye-layer-status">
            All components are hidden.{' '}
            <Button size="sm" onClick={() => preset('all')}>
              Show all
            </Button>
          </p>
        )}
        <div className="eye-layer-scene-tools">
          <Select
            disabled={!!step}
            value={view}
            onValueChange={(v) => {
              if (step) return;
              if (
                v &&
                [
                  'anterior',
                  'posterior',
                  'left',
                  'right',
                  'superior',
                  'inferior',
                ].includes(v)
              )
                setView(v as DissectionView);
            }}
          >
            <SelectTrigger aria-label="Eye camera view">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {(
                [
                  'anterior',
                  'posterior',
                  'left',
                  'right',
                  'superior',
                  'inferior',
                ] as const
              ).map((v) => (
                <SelectItem key={v} value={v}>
                  {v[0].toUpperCase() + v.slice(1)}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Button
            size="sm"
            variant={labels ? 'default' : 'outline'}
            disabled={!!step}
            aria-pressed={labels}
            onClick={() => { if (!step) setLabels((v) => !v); }}
          >
            <Tags /> Labels
          </Button>
          <Button
            size="sm"
            variant="outline"
            disabled={!!step}
            onClick={() => {
              if (step) return;
              setReset((r) => r + 1);
              setFocus(false);
            }}
          >
            <RotateCcw /> Frame eye
          </Button>
        </div>
        {(explode > 0 || inspection.plane !== 'off') && (
          <p className="eye-layer-layout-note">
            <span>
              {explode > 0 &&
                'Separated teaching layout · not anatomical positions'}
              {explode > 0 && inspection.plane !== 'off' && ' · '}
              {inspection.plane !== 'off' &&
                `${eyeCutPlanes[inspection.plane]} cut · ${inspection.position}% · not a scan`}
            </span>
            {inspection.plane !== 'off' && (
              <Button
                size="sm"
                variant="outline"
                disabled={!!step}
                onClick={() => { if (!step) setInspection(initialInspection); }}
              >
                Restore whole view
              </Button>
            )}
          </p>
        )}
      </div>
      <aside
        className="eye-layer-controls"
        aria-label="Eye dissection controls"
      >
        {guide && <details className="eye-layer-guided-learning" open={guideExpanded}
          onToggle={event => {
            if (event.target !== event.currentTarget) return;
             if (step && !event.currentTarget.open) pauseTour();
             if (!step) setGuideExpanded(event.currentTarget.open);
          }}>
          <summary>Guided learning</summary>
          <TourSpeedControl rate={tourRate} onRateChange={changeTourRate} />
          {step ? <section aria-label="Eye-layer walkthrough" aria-live="polite">
            <p>Step {guidance!.index + 1} of {guide.steps.length} · Draft</p>
            <h3>{step.title}</h3><p tabIndex={0} onFocus={pauseTour}>{step.caption}</p>
            {fullTour && <Button size="sm" variant="outline" disabled={!ready || pageHidden}
              aria-pressed={tourPlaying} onClick={() => { if (!ready || pageHidden) return;
                if (tourPlaying) pauseTour(); else { setMotionPaused(false); setTourPlaying(true); } }}>
              {tourPlaying ? 'Pause full tour' : 'Resume full tour'}</Button>}
            {!ready || pageHidden ? <p role="status">Walkthrough paused until the model is ready and this page is visible.</p> : null}
            <div className="eye-layer-actions">
              <Button size="sm" variant="outline" disabled={!ready || pageHidden || guidance!.index === 0}
                onClick={() => guideStep(guidance!.index - 1)}>Previous step</Button>
              <Button size="sm" variant="outline" disabled={!ready || pageHidden || guidance!.index === guide.steps.length - 1}
                onClick={() => guideStep(guidance!.index + 1)}>Next step</Button>
              <Button size="sm" variant="outline" onClick={exitGuide}>End walkthrough</Button>
            </div>
            <div onFocusCapture={pauseTour} onPointerDownCapture={pauseTour}>
              {step.references.map(url => <a key={url} href={url} target="_blank" rel="noreferrer">{eyeReferences.find(r => r.url === url)?.label ?? 'Source reference'}</a>)}
            </div>
          </section> : <><p>{guide.title} · Four source-bound steps · Draft</p>
            <Button size="sm" disabled={!ready || pageHidden || (!!initialSelectedId && !initialSelection)}
              onClick={() => { if (!ready || pageHidden || (!!initialSelectedId && !initialSelection)) return;
                setFullTour(true); setTourPlaying(!reducedMotion); guideStep(0);
                if (reducedMotion) setMotionPaused(true); }}>Play full tour</Button>
            <p>Step by step</p>
            <Button ref={guideLauncher} size="sm" variant="outline"
              disabled={!ready || pageHidden || (!!initialSelectedId && !initialSelection)}
              onClick={() => guideStep(0)}>Start eye walkthrough</Button></>}
          <p data-testid="eye-tour-source-scope">Draft source-component teaching · not clinical approval or scan registration.</p>
           <details data-testid="eye-tour-limitations" onToggle={event => { if (event.currentTarget.open) pauseTour(); }}>
            <summary>Tour scope &amp; limitations</summary>
            <p>{guide.limitation}</p>
          </details>
        </details>}
        <fieldset className="eye-layer-manual-controls" disabled={!!step} inert={!!step} hidden={!!step}>
        <legend className="sr-only">Manual eye dissection controls</legend>
        {educationLink.adapter && <ImagingLink link={educationLink} />}
        <div className="eye-layer-presets">
          <label htmlFor="eye-layer-preset">Study view</label>
          <Select
            value={currentPreset}
            disabled={!!step}
            onValueChange={(v) => {
              if (v && v !== 'custom') preset(v as EyePreset);
            }}
          >
            <SelectTrigger id="eye-layer-preset">
              <SelectValue>
                {
                  {
                    all: 'All available components',
                    anterior: 'Anterior structures',
                    lens: 'Lens and support',
                    wall: 'Wall layers',
                    custom: 'Custom selection',
                  }[currentPreset]
                }
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All available components</SelectItem>
              <SelectItem value="anterior">Anterior structures</SelectItem>
              <SelectItem value="lens">Lens and support</SelectItem>
              <SelectItem
                value="wall"
                disabled={!layers.some((s) => s.kind === 'sclera')}
              >
                Wall layers
              </SelectItem>
              <SelectItem value="custom" disabled>
                Custom selection
              </SelectItem>
            </SelectContent>
          </Select>
        </div>
        <ul className="eye-layer-list">
          {layers.map((s) => (
            <li key={s.id}>
              <Button
                size="sm"
                variant={selectedId === s.id ? 'secondary' : 'ghost'}
                aria-pressed={selectedId === s.id}
                disabled={!!step}
                onClick={() => select(s.id)}
              >
                {eyeNotes[s.kind].label}
              </Button>
              <Switch
                checked={!hidden.includes(s.id)}
                disabled={!!step}
                onCheckedChange={(visible) => {
                  if (step) return;
                  dispatch({ type: 'visibility', id: s.id, visible });
                  setFocus(false);
                  if (!visible && selectedId === s.id) setIsolated(false);
                }}
                aria-label={`Show ${s.name.toLowerCase()}`}
              />
            </li>
          ))}
        </ul>
        <div className="eye-layer-actions">
          <Button
            size="sm"
            variant="outline"
            disabled={!!step || !history.length}
            onClick={() => {
              if (step) return;
              dispatch({ type: 'undo' });
              setFocus(false);
              setIsolated(false);
            }}
          >
            Undo layers
          </Button>
          <Button
            size="sm"
            variant="outline"
            disabled={!!step || !future.length}
            title="Reapply the last undone layer or selection change"
            onClick={() => {
              if (step) return;
              dispatch({ type: 'redo' });
              setFocus(false);
              setIsolated(false);
            }}
          >
            Redo layers
          </Button>
          <Button
            size="sm"
            variant="outline"
            disabled={!!step}
            onClick={() => {
              if (step) return;
              preset('all');
              setReset((r) => r + 1);
            }}
          >
            Reassemble
          </Button>
        </div>
        <EyeCutawayControls
          value={inspection}
          onChange={(next) => {
            if (step) return;
            setInspection(next);
            setFocus(false);
          }}
        />
        <details className="eye-layer-separation">
          <summary>Separate components</summary>
          <Select
            value={layout}
            disabled={!!step}
            onValueChange={(v) => {
              if (step) return;
              if (v === 'extract' || v === 'tray') {
                setLayout(v);
                setExplode(0);
              }
            }}
          >
            <SelectTrigger aria-label="Eye separation mechanism">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="extract">Lift selected component</SelectItem>
              <SelectItem value="tray">Spread all (flat plate)</SelectItem>
            </SelectContent>
          </Select>
          <label htmlFor="eye-layer-explode">Separation · {explode}%</label>
          <Slider
            id="eye-layer-explode"
            aria-label="Eye component separation"
            aria-valuetext={`${explode}%`}
            min={0}
            max={100}
            step={1}
            value={[explode]}
            disabled={!!step || (layout === 'extract' && !selected)}
            onValueChange={(v) => { if (!step) setExplode(Array.isArray(v) ? v[0] : v); }}
          />
          <p>
            Drag to rotate in lift mode; spread mode uses a flat teaching
            plate.
          </p>
          <label className="origin-guide-toggle" htmlFor="eye-origin-guide">
            Show original position
            <Switch
              id="eye-origin-guide"
              checked={showOrigins}
              disabled={!!step}
              onCheckedChange={(visible) => { if (!step) setShowOrigins(visible); }}
              aria-label="Show original position"
              aria-describedby="eye-origin-guide-note"
            />
          </label>
          <p id="eye-origin-guide-note">
            Selected part only: a faint outline and line back to its source
            position, not a tissue connection. Hidden at 0%, in flat-plate or
            cutaway views, or when the part is hidden or not moving.
          </p>
        </details>
        </fieldset>
        {selected && (
          <section className="eye-layer-teaching" aria-live="polite">
            <h3>{selected.name}</h3>
            <span className="eye-layer-source-id">
              {selected.fmaId} · Draft
            </span>
            {cutSelection?.clipped && (
              <output className="eye-layer-cut-warning">
                {cutSelection.reasons.includes('Selection clipped by cutaway')
                  ? 'This component is fully cut away. Use Restore whole view to see it.'
                  : 'The cutaway may hide part of this component.'}
              </output>
            )}
            <p>{eyeNotes[selected.kind].anatomy}</p>
            <p>{eyeNotes[selected.kind].function}</p>
            <div className="eye-layer-actions">
              <Button
                size="sm"
                 variant={isolated ? 'default' : 'outline'}
                 aria-pressed={isolated}
                 disabled={!!step}
                 onClick={() => { if (!step) setIsolated((v) => !v); }}
              >
                <Eye /> Fade others
              </Button>
              <Button
                 size="sm"
                 variant="outline"
                 disabled={!!step || health !== 'ready' || !loaded}
                 onClick={() => { if (!step) setFocus((v) => !v); }}
              >
                <Focus /> Frame
              </Button>
            </div>
            <NestedTeaching
              parent={parent}
              study="eye"
              selected={selected}
              reviewAvailable={!assetBase}
              initialTopic={
                selected.id === initialSelection
                  ? initialTeachingTopic
                  : undefined
              }
            />
          </section>
        )}
        {unavailable.length > 0 && (
          <details className="eye-layer-limits">
            <summary>
              {unavailable.length} right-eye components unavailable
            </summary>
            <p>
              Opposite-side source fragments require review. No mirrored
              substitutes are shown.
            </p>
            <ul>
              {unavailable.map((s) => (
                <li key={s.fmaId}>{s.name}</li>
              ))}
            </ul>
          </details>
        )}
        <details className="eye-layer-limits">
          <summary>Source and limitations</summary>
          {parent.laterality === 'right' && (
            <p>
              Four components use source-cleaned surfaces: 36 tiny
              disconnected triangles on the opposite side were removed.
              Retained surfaces were not moved or mirrored. Anatomical review
              remains pending.
            </p>
          )}
          <p>
            Colours and transparency aid viewing, not optical simulation.
            Retina and finer tissue layers are not separately segmented.
            CT/MRI/US links and clinical validation are pending.
          </p>
          <p>{eyeCatalog.credit}</p>
          <p>
            Components separated from the source aggregate, transformed,
            recoloured and normal-smoothed for this viewer. Pinned
            opposite-side fragments are suppressed on the right; retained
            surfaces are not moved or mirrored.
          </p>
          <a
            href="https://creativecommons.org/licenses/by/4.0/"
            target="_blank"
            rel="noreferrer"
          >
            CC BY 4.0 licence
          </a>
          {eyeReferences.map((r) => (
            <a key={r.url} href={r.url} target="_blank" rel="noreferrer">
              {r.label}
            </a>
          ))}
        </details>
      </aside>
    </div>
  );
}

