'use client';
import { useCallback, useMemo, useReducer, useState } from 'react';
import {
  cranialArteryComponentsFor,
  cranialArteryComponentViewCatalog,
} from '@/atlas-review/lib/cranial-artery-components';
import { ArrowLeft, Focus, RotateCcw, Tags } from 'lucide-react';
import { Button } from '@/atlas-review/components/ui/button';
import { Switch } from '@/atlas-review/components/ui/switch';
import { Slider } from '@/atlas-review/components/ui/slider';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/atlas-review/components/ui/select';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from './study-surface';
import { BodyScene, retryBodyAssets } from './body-scene';
import { allBodySystems, type BodyCatalog, type BodyStructure } from './body-types';
import { ImagingLink } from './imaging-link';
import { useNestedEducationLink } from './nested-education-link';
import { NestedTeaching } from './nested-teaching';
import { nestedReviewHref } from '@/atlas-review/lib/nested-review-links';
import { CutawayControls, cutPlanes } from './cutaway-controls';
import { initialInspection } from '@/atlas-review/lib/inspection-state';
import {
  selectionBounds,
  selectionVisibility,
} from '@/atlas-review/lib/selection-visibility';
import {
  initialVentricles,
  reduceVentricles,
  type VentricularState,
  type VentricularAction,
} from '@/atlas-review/lib/ventricles';
import {
  femoralComponentsFor,
  femoralComponentViewCatalog,
  femoralComponentPresets,
  femoralComponentLabel,
  femoralComponentColour,
} from '@/atlas-review/lib/femoral-components';
import type { BodyLayout } from '@/atlas-review/lib/body-arrangement';
import type { RendererHealth } from '@/atlas-review/lib/renderer-health';
import { modelLoadAccessNotice, type ModelLoadFailure } from '@/atlas-review/lib/model-load-failure';
import type { DissectionView } from './dissection-data';
import type { NestedImagingTopic } from '@/atlas-review/content/nested-teaching';
import './eye-layers.css';

type Props = {
  parent: BodyStructure;
  educationCatalog?: BodyCatalog;
  study?: 'femoral-components' | 'cranial-artery-components';
  initialSelectedId?: string;
  initialTeachingTopic?: NestedImagingTopic;
  assetBase?: string;
};
const views = [
  'anterior',
  'posterior',
  'left',
  'right',
  'superior',
  'inferior',
] as const;
const layouts = {
  extract: 'Lift selected',
  spatial: 'Spread in 3D',
  tray: 'Flat teaching plate',
};
const femoralPresetNames = {
  all: 'Both source components',
  lateral: 'Lateral circumflex',
  remainder: 'Source remainder',
};

export function FemoralComponentView({
  parent,
  educationCatalog,
  study = 'femoral-components',
  initialSelectedId,
  initialTeachingTopic,
  assetBase = '',
}: Props) {
  const catalog = useMemo(
    () =>
      study === 'cranial-artery-components'
        ? cranialArteryComponentViewCatalog(parent)
        : femoralComponentViewCatalog(parent),
    [parent, study],
  );
  const parts = useMemo(
    () =>
      study === 'cranial-artery-components'
        ? cranialArteryComponentsFor(parent)
        : femoralComponentsFor(parent),
    [parent, study],
  );
  const presets: Record<string, string[]> = useMemo(
    () =>
      study === 'cranial-artery-components'
        ? { all: parts.map((s) => s.id) }
        : femoralComponentPresets(femoralComponentsFor(parent)),
    [parts, parent, study],
  );
  const presetNames: Record<string, string> =
    study === 'cranial-artery-components'
      ? { all: `All ${parts.length} source parts` }
      : femoralPresetNames;
  // All supplied components set the clipping frame, even after hiding a part.
  const frame = useMemo(() => selectionBounds(parts), [parts]);
  const initialSelection = parts.find((s) => s.id === initialSelectedId)?.id;
  const [{ selectedId, hidden, history, future }, dispatch] = useReducer(
    (s: VentricularState, a: VentricularAction) =>
      reduceVentricles(parts, s, a, presets),
    parts,
    (items) => ({
      ...initialVentricles(items),
      selectedId:
        initialSelection ??
        items.find((s) => s.role === 'lateral-circumflex')?.id ??
        (study === 'cranial-artery-components' ? items[0]?.id : null) ??
        null,
    }),
  );
  const [inspection, setInspection] = useState(initialInspection);
  const [layout, setLayout] = useState<BodyLayout>('extract');
  const [explode, setExplode] = useState(0),
    [showOrigins, setShowOrigins] = useState(false);
  const [view, setView] = useState<DissectionView>('anterior'),
    [labels, setLabels] = useState(true);
  const [isolated, setIsolated] = useState(!!initialSelection),
    [focus, setFocus] = useState(false),
    [reset, setReset] = useState(0);
  const [loaded, setLoaded] = useState(false),
    [failed, setFailed] = useState(false),
    [retry, setRetry] = useState(0);
  const [health, setHealth] = useState<RendererHealth>('starting');
  const [failureReason, setFailureReason] = useState<ModelLoadFailure>('unavailable');
  const accessNotice = failed ? modelLoadAccessNotice([failureReason]) : null;
  const onLoaded = useCallback(() => {
    setLoaded(true);
    setFailed(false);
    setFailureReason('unavailable');
  }, []);
  const onFailure = useCallback((_id: string, reason: ModelLoadFailure = 'unavailable') => {
    setFailed(true);
    setLoaded(false);
    setFailureReason(reason);
  }, []);
  const selected = parts.find((s) => s.id === selectedId);
  const appearance = useMemo(
    () =>
      Object.fromEntries(
        parts.map((s) => [
          s.id,
          {
            color:
              s.role === 'source-part'
                ? s.sourceOrder % 2
                  ? '#be6157'
                  : '#975349'
                : femoralComponentColour(s),
            opacity: 1,
          },
        ]),
      ),
    [parts],
  );
  const preset =
    Object.entries(presets).find(([, ids]) =>
      parts.every((s) => ids.includes(s.id) === !hidden.includes(s.id)),
    )?.[0] ?? 'custom';
  const visibility = selected
    ? selectionVisibility({
        system: selected.system,
        enabled: true,
        bounds: selected.bounds,
        frame,
        inspection,
      })
    : null;
  function change(action: VentricularAction) {
    dispatch(action);
    setFocus(false);
    setIsolated(false);
  }
  const educationAllowedIds = useMemo(
    () => loaded && !failed ? parts.filter(s => !hidden.includes(s.id)).map(s => s.id) : [],
    [parts, hidden, loaded, failed],
  );
  function applySelection(id: string) {
    if (parts.some(s => s.id === id)) change({ type: 'select', id });
  }
  const educationLink = useNestedEducationLink({
    catalog: educationCatalog, parent, study, layers: parts,
    allowedIds: educationAllowedIds,
    disabled: !loaded || failed || health !== 'ready' || isolated ||
      inspection.plane !== 'off' || (initialSelectedId !== undefined && !initialSelection),
    onSelect: applySelection,
  });
  function select(id: string) {
    if (!parts.some(s => s.id === id)) return;
    applySelection(id);
    educationLink.publish(id);
  }
  function showPreset(value: string) {
    if (!Object.hasOwn(presets, value)) return;
    change({ type: 'preset', value });
    setExplode(0);
    setInspection(initialInspection);
  }
  if (!parts.length || (initialSelectedId !== undefined && !initialSelection))
    return (
      <p role="alert">
        This source binding is unavailable. Return to the atlas and select the
        current artery source.
      </p>
    );
  return (
    <div className="eye-layer-workbench">
      <div className="eye-layer-viewport">
        <BodyScene
          assetBase={assetBase}
          catalog={catalog}
          structures={parts}
          selectedId={selectedId}
          systems={allBodySystems}
          isolated={isolated && !!selected}
          hiddenIds={hidden}
          ghostRemoved={false}
          illustrated
          labels={labels}
          landmarks={parts.map((s) => s.id)}
          explode={explode}
          layout={layout}
          anchorSkeleton={false}
          showOrigins={showOrigins}
          originStyle="selected-guide"
          view={view}
          zoom={1}
          reset={reset}
          focus={focus}
          exam={false}
          inspection={inspection}
          inspectionBounds={frame}
          plate={false}
          appearance={appearance}
          retries={{ [study]: retry }}
          onSelect={select}
          onLoaded={onLoaded}
          onFailure={onFailure}
          onRendererHealth={setHealth}
        />
        {!loaded && !failed && (
          <output className="eye-layer-status">
            Loading artery components…
          </output>
        )}
        {failed && (
          <div className="eye-layer-status" role="alert">
            {accessNotice?.message ?? 'Components could not load.'}{' '}
            <Button
              size="sm"
              onClick={() => {
                retryBodyAssets(catalog.bundles.map((b) => b.url), assetBase);
                setLoaded(false);
                setFailed(false);
                setFailureReason('unavailable');
                // Retrying this asset does not restart the existing canvas.
                setRetry((r) => r + 1);
              }}
            >
              {accessNotice?.retryLabel ?? 'Retry'}
            </Button>
          </div>
        )}
        {hidden.length === parts.length && (
          <p className="eye-layer-status">
            {study === 'cranial-artery-components'
              ? 'All source parts are hidden.'
              : 'Both components are hidden.'}{' '}
            <Button size="sm" onClick={() => showPreset('all')}>
              Show all
            </Button>
          </p>
        )}
        <div className="eye-layer-scene-tools">
          <Select
            value={view}
            onValueChange={(v) => {
              if (views.includes(v as DissectionView))
                setView(v as DissectionView);
            }}
          >
            <SelectTrigger aria-label="Artery camera view">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {views.map((v) => (
                <SelectItem key={v} value={v}>
                  {v[0].toUpperCase() + v.slice(1)}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Button
            size="sm"
            variant={labels ? 'default' : 'outline'}
            aria-pressed={labels}
            onClick={() => setLabels((v) => !v)}
          >
            <Tags /> Labels
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => {
              setFocus(false);
              setReset((r) => r + 1);
            }}
          >
            <RotateCcw /> Frame all
          </Button>
        </div>
        {(explode > 0 || inspection.plane !== 'off') && (
          <p className="eye-layer-layout-note">
            <span>
              {explode > 0 && 'Separated layout · not anatomical positions'}
              {explode > 0 && inspection.plane !== 'off' && ' · '}
              {inspection.plane !== 'off' &&
                `${cutPlanes[inspection.plane]} cut · not a scan`}
            </span>
            <Button
              size="sm"
              variant="outline"
              onClick={() => {
                setExplode(0);
                setInspection(initialInspection);
                setFocus(false);
              }}
            >
              Restore source position
            </Button>
          </p>
        )}
      </div>
      <aside
        className="eye-layer-controls"
        aria-label="Artery component controls"
      >
        {educationLink.adapter && <ImagingLink link={educationLink} />}
        {study === 'femoral-components' && (
          <div className="eye-layer-presets">
            <label htmlFor="femoral-component-preset">Study view</label>
            <Select
              value={preset}
              onValueChange={(v) => {
                if (v) showPreset(v);
              }}
            >
              <SelectTrigger id="femoral-component-preset">
                <SelectValue>
                  {presetNames[preset as keyof typeof presetNames] ??
                    'Custom selection'}
                </SelectValue>
              </SelectTrigger>
              <SelectContent>
                {Object.entries(presetNames).map(([value, label]) => (
                  <SelectItem key={value} value={value}>
                    {label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        )}
        <ul
          className={`eye-layer-list${study === 'cranial-artery-components' ? ' artery-source-part-list' : ''}`}
          aria-label="Artery source parts"
          tabIndex={study === 'cranial-artery-components' ? 0 : undefined}
        >
          {parts.map((s) => (
            <li key={s.id}>
              <Button
                size="sm"
                variant={s.id === selectedId ? 'secondary' : 'ghost'}
                aria-pressed={s.id === selectedId}
                onClick={() => select(s.id)}
              >
                {s.role === 'source-part' ? s.name : femoralComponentLabel(s)}
              </Button>
              <Switch
                checked={!hidden.includes(s.id)}
                aria-label={`Show ${s.name.toLowerCase()}`}
                onCheckedChange={(visible) =>
                  change({ type: 'visibility', id: s.id, visible })
                }
              />
            </li>
          ))}
        </ul>
        <div className="eye-layer-actions">
          <Button
            size="sm"
            variant="outline"
            disabled={!history.length}
            onClick={() => change({ type: 'undo' })}
          >
            Undo
          </Button>
          <Button
            size="sm"
            variant="outline"
            disabled={!future.length}
            onClick={() => change({ type: 'redo' })}
          >
            Redo
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => {
              showPreset('all');
              setReset((r) => r + 1);
            }}
          >
            Reassemble
          </Button>
        </div>
        <CutawayControls
          subject="Artery"
          positionId="femoral-component-cut-position"
          value={inspection}
          onChange={(next) => {
            setInspection(next);
            setFocus(false);
          }}
        />
        <details className="eye-layer-separation">
          <summary>Separate components</summary>
          <Select
            value={layout}
            onValueChange={(v) => {
              if (v && Object.hasOwn(layouts, v)) {
                setLayout(v as BodyLayout);
                setExplode(0);
                setFocus(false);
              }
            }}
          >
            <SelectTrigger aria-label="Artery separation mechanism">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {Object.entries(layouts).map(([value, label]) => (
                <SelectItem key={value} value={value}>
                  {label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <label htmlFor="femoral-component-separation">
            Separation · {explode}%
          </label>
          <Slider
            id="femoral-component-separation"
            aria-label="Artery component separation"
            aria-valuetext={`${explode}%`}
            min={0}
            max={100}
            step={1}
            value={[explode]}
            disabled={layout === 'extract' && !selected}
            onValueChange={(v) => {
              const amount = Array.isArray(v) ? v[0] : v;
              if (Number.isFinite(amount)) {
                setExplode(Math.max(0, Math.min(100, amount)));
                setFocus(false);
              }
            }}
          />
          <label
            className="origin-guide-toggle"
            htmlFor="femoral-component-origin"
          >
            Show original position
            <Switch
              id="femoral-component-origin"
              checked={showOrigins}
              onCheckedChange={setShowOrigins}
            />
          </label>
          <p>
            The selected-part guide marks its source position, not a vessel
            connection. Hidden in cutaway and flat-plate views.
          </p>
        </details>
        {selected && (
          <section className="eye-layer-teaching" aria-live="polite">
            <h3>{selected.name}</h3>
            <span className="eye-layer-source-id">
              {selected.sources[0].file} · Source component · Draft
            </span>
            <p>{selected.coverageNote}</p>
            {visibility?.clipped && (
              <output className="eye-layer-cut-warning">
                The cutaway hides some or all of this component. Restore source
                position to remove the cut.
              </output>
            )}
            <div className="eye-layer-actions">
              <Button
                size="sm"
                variant={isolated ? 'default' : 'outline'}
                aria-pressed={isolated}
                onClick={() => setIsolated((v) => !v)}
              >
                Fade others
              </Button>
              <Button
                size="sm"
                variant="outline"
                disabled={!loaded || health !== 'ready'}
                onClick={() => setFocus((v) => !v)}
              >
                <Focus /> Frame selected
              </Button>
            </div>
            {study === 'femoral-components' ? (
              <NestedTeaching
                parent={parent}
                study="femoral-components"
                selected={selected}
                reviewAvailable={!assetBase}
                initialTopic={
                  selected.id === initialSelection
                    ? initialTeachingTopic
                    : undefined
                }
              />
            ) : (
              <p className="eye-layer-source-id">
                Parent concept: {parent.fmaId}. Unnamed source part; no
                independent clinical lesson, imaging registration or
                branch-order claim.
                {!assetBase && nestedReviewHref(parent, study, selected) && <><br/><a href={nestedReviewHref(parent, study, selected)!} target="_blank" rel="noreferrer">Review this structure</a></>}
              </p>
            )}
          </section>
        )}
        <details className="eye-layer-limits">
          <summary>Source and limitations</summary>
          {study === 'femoral-components' ? (
            <p>
              These two components partition the existing aggregate without
              adding tissue. The remainder is not a complete artery or a
              separately named perforator. Vessel junctions and anatomical
              extent need review.
            </p>
          ) : (
            <p>
              These {parts.length} source-file parts partition the existing
              artery selection exactly. All original triangle corners and vertex
              normals are retained. A source file can contain several
              disconnected pieces. Numbering identifies archive parts, not named
              branches or clinical segments. No additional root anatomy is
              created.
            </p>
          )}
          <p>{catalog.credit}</p>
          <p>
            Source surfaces separated and recoloured; established coordinate
            transform retained
            {study === 'femoral-components'
              ? ' and normals recomputed'
              : ' with original rendered normals'}
            . No fitting, mirroring or invented connections.
          </p>
          <a
            href="https://creativecommons.org/licenses/by/4.0/"
            target="_blank"
            rel="noreferrer"
          >
            CC BY 4.0 licence
          </a>
        </details>
      </aside>
    </div>
  );
}

export default function FemoralComponents({
  onClose,
  ...props
}: Props & { onClose: () => void }) {
  return (
    <Dialog
      open
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
    >
      <DialogContent className="eye-layers-dialog" showCloseButton={false}>
        <header className="eye-layer-heading">
          <div>
            <DialogTitle>{props.parent.name} · source dissection</DialogTitle>
            <DialogDescription>
              {props.study === 'cranial-artery-components'
                ? `${cranialArteryComponentsFor(props.parent).length} original source parts.`
                : 'Two supplied components.'}{' '}
              Anatomical validation pending.
            </DialogDescription>
          </div>
          <Button variant="outline" onClick={onClose}>
            <ArrowLeft /> Back to atlas
          </Button>
        </header>
        <FemoralComponentView
          key={`${props.parent.id}:${props.study ?? 'femoral-components'}`}
          {...props}
        />
      </DialogContent>
    </Dialog>
  );
}

'use client';
/* oxlint-disable react/react-compiler -- Three.js camera is an imperative external renderer, not React state. */
import { useCallback, useEffect, useRef, type RefObject } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import type { OrbitControls as Controls } from 'three-stdlib';
import { Box3, Vector3, PerspectiveCamera, OrthographicCamera } from 'three';
import { fitBounds } from '@/atlas-review/lib/explode-layout.mjs';
import {
  captureStudyCamera,
  restoreStudyCamera,
  planarStudyCamera,
  relativeStudyScale,
} from '@/atlas-review/lib/study-camera';
import type { StudyCamera } from '@/atlas-review/lib/study-views';
import { steppedCameraScale } from '@/atlas-review/lib/camera-zoom';
import { bindCameraKeyboard, bindCameraPanKeyboard } from '@/atlas-review/lib/camera-keyboard';
import { interpolateTourCamera, type TourCameraPose } from '@/atlas-review/lib/tour-camera';

export function FittedCamera({
  bounds,
  direction,
  up = [0, 1, 0],
  viewKey,
  zoom,
  zoomStep = 0,
  fitOccupancy = [0.7, 0.7],
  presetBounds = null,
  reset,
  locked = false,
  planar = false,
  recenterKey = '',
  cameraCapture,
  cameraRestore,
  autoRecoveryCamera,
  cameraTransitionActive,
  guidedRecovery = false,
  onKeyboardRotate,
  transitionMs = 0,
  transitionPaused = false,
}: {
  bounds: Box3;
  direction: number[];
  up?: number[];
  viewKey: string;
  zoom: number;
  zoomStep?: number;
  fitOccupancy?: [number, number];
  /** Initial/reset/recenter target only; saves stay relative to full bounds. */
  presetBounds?: Box3 | null;
  reset: number;
  locked?: boolean;
  planar?: boolean;
  recenterKey?: string;
  cameraCapture?: RefObject<StudyCamera | null>;
  cameraRestore?: RefObject<StudyCamera | null>;
  /** Private SceneRecovery marker; only its own queued camera may resume a guide. */
  autoRecoveryCamera?: RefObject<StudyCamera | null>;
  /** Last captured pose belongs to an actively moving guide. */
  cameraTransitionActive?: RefObject<boolean>;
  guidedRecovery?: boolean;
  onKeyboardRotate?: (cameraFrom: Vector3, azimuth: number, polar: number) => void;
  /** Opt-in guided tours only. Ordinary atlas camera behaviour stays immediate. */
  transitionMs?: number;
  transitionPaused?: boolean;
}) {
  const { camera, size, invalidate, gl } = useThree();
  const controls = useRef<Controls>(null);
  const transition = useRef<{ from: TourCameraPose; to: TourCameraPose; elapsed: number; duration: number } | null>(null);
  const skipTransitionDelta = useRef(true);
  const previous = useRef<{
    key: string;
    bounds: Box3;
    aspect: number;
    fov: number;
    occupancy: [number, number];
    recenterKey: string;
    zoom: number;
    zoomStep: number;
    center: Vector3;
  } | null>(null);
  const key = `${viewKey}/${reset}/${locked}/${planar}`;
  const dx = direction[0],
    dy = direction[1],
    dz = direction[2];
  const ux = up[0],
    uy = up[1],
    uz = up[2];
  const aspect = size.width / Math.max(1, size.height);
  const [horizontalFill, verticalFill] = fitOccupancy;
  const fov = camera instanceof PerspectiveCamera ? camera.fov : 39;
  const capture = useCallback(() => {
    if (
      cameraCapture &&
      controls.current &&
      (camera instanceof PerspectiveCamera ||
        camera instanceof OrthographicCamera)
    )
      cameraCapture.current = captureStudyCamera(
        camera,
        controls.current.target,
        bounds,
        size.width / Math.max(1, size.height),
      );
    if (cameraTransitionActive)
      cameraTransitionActive.current = transition.current !== null;
  }, [cameraCapture, cameraTransitionActive, camera, bounds, size.width, size.height]);
  useFrame((_state, delta) => {
    const motion = transition.current;
    if (!motion || transitionPaused) return;
    // Demand rendering can report the entire time since its previous frame on
    // the first frame of a tour or after a pause. Subsequent valid deltas are
    // real active time, even on a slow device.
    const activeDelta = skipTransitionDelta.current || !Number.isFinite(delta) || delta <= 0
      ? 0 : delta;
    skipTransitionDelta.current = false;
    motion.elapsed += activeDelta * 1000;
    const progress = Math.min(1, motion.elapsed / motion.duration);
    const pose = interpolateTourCamera(motion.from, motion.to, progress);
    camera.position.copy(pose.position);
    camera.up.copy(pose.up);
    camera.lookAt(pose.target);
    controls.current?.target.copy(pose.target);
    controls.current?.update();
    if (progress === 1) transition.current = null;
    capture();
    if (progress !== 1) invalidate();
  });
  useEffect(() => {
    if (transitionPaused) skipTransitionDelta.current = true;
    else invalidate();
  }, [transitionPaused, invalidate]);
  useEffect(() => {
    const interruptedTransition = transition.current !== null;
    transition.current = null;
    let from = controls.current && previous.current ? {
      position: camera.position.clone(), target: controls.current.target.clone(), up: camera.up.clone(),
    } : null;
    // This component owns the orthographic frustum. Fiber's automatic resize
    // otherwise replaces its world-space extent with canvas pixels before this
    // effect, which is then mistaken for a user zoom and shrinks the anatomy.
    // Perspective cameras still use Fiber's automatic aspect-ratio updates.
    if (camera instanceof OrthographicCamera)
      (camera as OrthographicCamera & { manual: boolean }).manual = true;
    if (
      cameraRestore?.current &&
      (camera instanceof PerspectiveCamera ||
        camera instanceof OrthographicCamera)
    ) {
      const resumeGuide = guidedRecovery && camera instanceof PerspectiveCamera &&
        autoRecoveryCamera?.current === cameraRestore.current;
      const restored = restoreStudyCamera(
        camera,
        bounds,
        size.width / Math.max(1, size.height),
        planar
          ? planarStudyCamera(cameraRestore.current, [dx, dy, dz], [ux, uy, uz])
          : cameraRestore.current,
      );
      cameraRestore.current = null;
      if (autoRecoveryCamera) autoRecoveryCamera.current = null;
      controls.current?.target.copy(restored.target);
      controls.current?.update();
      if (resumeGuide) {
        // The captured pose is the new start; the selected preset remains the
        // destination. Reduced motion takes the same path with zero duration.
        from = {
          position: camera.position.clone(), target: restored.target.clone(), up: camera.up.clone(),
        };
      } else {
        previous.current = {
          key,
          bounds: bounds.clone(),
          aspect,
          fov,
          occupancy: [horizontalFill, verticalFill],
          recenterKey,
          zoom,
          zoomStep,
          center: bounds.getCenter(new Vector3()),
        };
        capture();
        invalidate();
        return;
      }
    }
    // Resize or reduced-motion changes must still arrive at the selected preset,
    // not accidentally adopt an intermediate animated orbit as the new view.
    const isPreset = previous.current?.key !== key || interruptedTransition;
    const isRecenter = previous.current?.recenterKey !== recenterKey;
    const orbit =
      !isPreset && controls.current
        ? camera.position.clone().sub(controls.current.target).normalize()
        : new Vector3(dx, dy, dz).normalize();
    if (isPreset) camera.up.set(ux, uy, uz);
    const fit = fitBounds(
      bounds,
      orbit,
      camera.up,
      aspect,
      fov,
      [horizontalFill, verticalFill],
    );
    const presetFit = (isPreset || isRecenter) && presetBounds
      ? fitBounds(presetBounds, orbit, camera.up, aspect, fov, [horizontalFill, verticalFill])
      : fit;
    const retainZoom =
      !isPreset &&
      !isRecenter &&
      previous.current &&
      controls.current &&
      zoom === previous.current.zoom
        ? previous.current
        : null;
    // Wheel/orbit gestures change the live camera between React effects.
    // Re-evaluate the PREVIOUS geometry/viewport in the CURRENT orbit so an
    // orientation change is not mistaken for zoom. Only genuine bounds or
    // viewport changes should adapt the framing on the next effect.
    const priorFit = retainZoom
      ? fitBounds(retainZoom.bounds, orbit, camera.up, retainZoom.aspect, retainZoom.fov, retainZoom.occupancy)
      : null;
    const retainedScale =
      priorFit && controls.current
        ? relativeStudyScale(
            camera as PerspectiveCamera | OrthographicCamera,
            controls.current.target,
            priorFit.distance,
            priorFit.halfHeight,
          )
        : zoom * (camera instanceof OrthographicCamera
          ? presetFit.halfHeight / fit.halfHeight
          : presetFit.distance / fit.distance);
    const stepDelta = !isPreset && !isRecenter && previous.current
      ? zoomStep - previous.current.zoomStep : 0;
    const userZoom = steppedCameraScale(retainedScale, stepDelta);
    const distance =
      camera instanceof OrthographicCamera
        ? priorFit && controls.current
          ? camera.position.distanceTo(controls.current.target) * fit.distance / priorFit.distance
          : fit.distance
        : fit.distance * userZoom;
    const target = presetFit.center.clone();
    if (!isPreset && !isRecenter && previous.current && controls.current)
      target.add(controls.current.target.clone().sub(previous.current.center));
    camera.position.copy(target).addScaledVector(orbit, distance);
    camera.lookAt(target);
    if (camera instanceof OrthographicCamera) {
      const aspect = size.width / Math.max(1, size.height),
        height = fit.halfHeight * userZoom;
      camera.zoom = 1;
      camera.left = -height * aspect;
      camera.right = height * aspect;
      camera.top = height;
      camera.bottom = -height;
    }
    if (
      camera instanceof PerspectiveCamera ||
      camera instanceof OrthographicCamera
    ) {
      camera.near = 0.01;
      camera.far = Math.max(
        150,
        distance + bounds.getSize(new Vector3()).length() * 4,
      );
      camera.updateProjectionMatrix();
    }
    controls.current?.target.copy(target);
    controls.current?.update();
    previous.current = {
      key,
      bounds: bounds.clone(),
      aspect,
      fov,
      occupancy: [horizontalFill, verticalFill],
      recenterKey,
      zoom,
      zoomStep,
      // Keep the full-frame reference even when the preset targeted a smaller
      // region. Later orbit/zoom/resize and legacy saves retain that pan/scale.
      center: fit.center,
    };
    if (from && transitionMs > 0 && camera instanceof PerspectiveCamera && isPreset) {
      transition.current = {
        from,
        to: { position: camera.position.clone(), target: target.clone(), up: camera.up.clone() },
        elapsed: 0,
        duration: transitionMs,
      };
      skipTransitionDelta.current = true;
      camera.position.copy(from.position);
      camera.up.copy(from.up);
      camera.lookAt(from.target);
      controls.current?.target.copy(from.target);
      controls.current?.update();
    }
    capture();
    invalidate();
  }, [
    bounds,
    camera,
    size.width,
    size.height,
    key,
    zoom,
    zoomStep,
    dx,
    dy,
    dz,
    ux,
    uy,
    uz,
    invalidate,
    cameraRestore,
    autoRecoveryCamera,
    cameraTransitionActive,
    guidedRecovery,
    capture,
    planar,
    recenterKey,
    aspect,
    fov,
    horizontalFill,
    verticalFill,
    presetBounds,
    transitionMs,
  ]);
  useEffect(() => {
    if (!gl?.domElement || locked) return;
    if (planar) {
      if (!(camera instanceof OrthographicCamera)) return;
      return bindCameraPanKeyboard(gl.domElement, camera, () => controls.current, () => {
        capture();
        invalidate();
      });
    }
    return bindCameraKeyboard(gl.domElement, () => controls.current, () => {
      // A consumed keyboard rotation is manual inspection, just like an orbit
      // gesture. Do not overwrite its live pose on the next guided-tour frame.
      transition.current = null;
      capture();
      invalidate();
      if (onKeyboardRotate && controls.current) {
        onKeyboardRotate(
          camera.getWorldDirection(new Vector3()).negate(),
          controls.current.getAzimuthalAngle(),
          controls.current.getPolarAngle(),
        );
      }
    });
  }, [gl, locked, planar, capture, invalidate, camera, onKeyboardRotate]);
  return (
    <OrbitControls
      ref={controls}
      makeDefault
      enableRotate={!locked && !planar}
      enablePan={!locked}
      enableZoom={!locked}
      minDistance={0.1}
      maxDistance={Math.max(500, bounds.getSize(new Vector3()).length() * 20)}
      onStart={() => { transition.current = null; capture(); }}
      onChange={capture}
    />
  );
}

@import 'tailwindcss';
@import 'tw-animate-css';
@import '../../components/review-ui-variants.css';

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background); --color-foreground: var(--foreground);
  --color-card: var(--card); --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover); --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary); --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary); --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted); --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent); --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive); --color-border: var(--border);
  --color-input: var(--input); --color-ring: var(--ring);
  --color-sidebar: var(--sidebar); --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary); --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent); --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border); --color-sidebar-ring: var(--sidebar-ring);
  --radius-sm: .25rem; --radius-md: .4rem; --radius-lg: .65rem; --radius-xl: .85rem; --radius-2xl: 1.1rem;
  --font-sans: "Segoe UI Variable", "Segoe UI", Arial, sans-serif;
  --font-mono: "Cascadia Mono", Consolas, monospace;
}

:root {
  /* Locked palette from the approved Visible Medicine course identity. */
  --vm-midnight: #041a23; --vm-ink: #002631; --vm-teal: #16c6b2;
  --vm-lime: #d2dc16; --vm-ivory: #f8f7f2; --vm-muted: #5d7477;
  --background: var(--vm-ivory); --foreground: var(--vm-ink); --card: #ffffff; --card-foreground: var(--vm-ink);
  --popover: #ffffff; --popover-foreground: var(--vm-ink); --primary: var(--vm-ink); --primary-foreground: var(--vm-ivory);
  --secondary: #e8eeeb; --secondary-foreground: #18332e; --muted: #edf1ef; --muted-foreground: #62706d;
  --accent: #ddebe8; --accent-foreground: var(--vm-ink); --destructive: #bc3e38; --border: #d5dfdc;
  --input: #d5dfdc; --ring: var(--vm-teal); --radius: .55rem;
  --sidebar: #fbfdfc; --sidebar-foreground: #15211f; --sidebar-primary: #143d35; --sidebar-primary-foreground: #fff;
  --sidebar-accent: #e4f4ef; --sidebar-accent-foreground: #143d35; --sidebar-border: #dbe3df; --sidebar-ring: #2d7b6d;
}

.dark {
  --background:var(--vm-midnight); --foreground:var(--vm-ivory); --card:var(--vm-ink); --card-foreground:var(--vm-ivory);
  --popover:var(--vm-ink); --popover-foreground:var(--vm-ivory); --primary:var(--vm-teal); --primary-foreground:var(--vm-midnight);
  --secondary:#22302d; --secondary-foreground:#edf7f4; --muted:#22302d; --muted-foreground:#9aafaa;
  --accent:#25473f; --accent-foreground:#eafff8; --destructive:#ee6c63; --border:#2a3a37;
  --input:#344642; --ring:#78d7bd; --sidebar:#17201f; --sidebar-foreground:#edf7f4;
  --sidebar-primary:#78d7bd; --sidebar-primary-foreground:#10221d; --sidebar-accent:#25473f;
  --sidebar-accent-foreground:#eafff8; --sidebar-border:#2a3a37; --sidebar-ring:#78d7bd;
}

* { box-sizing: border-box; }
html, body { margin: 0; min-height: 100%; font-family: "Segoe UI Variable", "Segoe UI", Arial, sans-serif; background: var(--background); color: var(--foreground); }
button, input { font: inherit; }
button { cursor: pointer; }

.app-shell { min-height: 100vh; background: #eef2f0; }
.topbar {
  height: 64px; display: grid; grid-template-columns: auto auto 1fr auto; align-items: center; gap: 12px;
  padding: 0 20px; border-bottom: 1px solid #d5dfdb; background: rgba(255,255,255,.96); position: relative; z-index: 20;
}
.brand-mark {
  width: 34px; height: 34px; display: grid; place-items: center; background: #143b34; color: #bff4e4;
  font-weight: 800; border-radius: 8px 8px 8px 2px; box-shadow: inset 0 0 0 1px #ffffff12;
}
.brand-lockup { line-height: .85; letter-spacing: .14em; font-size: 12px; }
.brand-lockup span { display: block; font-size: 9px; color: #71807c; margin-top: 5px; }
.workspace-name { justify-self: center; display: flex; gap: 7px; align-items: center; font-size: 14px; font-weight: 670; }
.workspace-name svg { width: 17px; color: #3f7467; }
.workspace-name span { color: #788480; font-weight: 400; }
.top-actions { display: flex; gap: 8px; align-items: center; }
.prototype-badge { color: #736749; background: #fff9e9; border-color: #eadcad; font-size: 11px; font-weight: 650; }
.mode-button { min-width: 110px; height: 34px; }

.workspace-grid { height: calc(100vh - 64px); display: grid; grid-template-columns: 260px minmax(420px, 1fr) 390px; overflow: hidden; }
.control-rail, .info-panel { background: #fbfdfc; overflow: auto; scrollbar-width: thin; scrollbar-color: #bdcac6 transparent; }
.control-rail { border-right: 1px solid #d7e0dc; padding: 22px 18px 18px; }
.info-panel { border-left: 1px solid #d7e0dc; padding: 28px 28px 24px; }
.eyebrow, .info-kicker { font-size: 11px; font-weight: 760; letter-spacing: .115em; text-transform: uppercase; color: #71817c; }

.anatomy-search { width: 100%; height: 40px; margin: 10px 0 22px; background: #fff; border-color: #cfdbd7; box-shadow: 0 1px 0 #13211e08; }
.anatomy-search input { font-size: 14px; }
.anatomy-search-menu { width: 240px; }
.rail-section-heading { display: flex; align-items: center; justify-content: space-between; margin: 0 2px 9px; font-size: 12px; font-weight: 750; color: #34443f; }
.rail-section-heading small { font-size: 11px; color: #84918d; font-weight: 500; }
.structure-heading { border-top: 1px solid #e0e7e4; margin-top: 20px; padding-top: 19px; }

.system-card {
  display: grid; grid-template-columns: 36px 1fr auto; align-items: center; gap: 9px; padding: 9px 10px; margin: 7px 0;
  border: 1px solid #dbe4e0; background: #fff; border-radius: 8px; transition: border-color .18s, background .18s;
}
.system-card.active { border-color: #aed0c6; background: #eff8f5; }
.system-card > span:not(.system-icon) { display: flex; flex-direction: column; font-size: 14px; }
.system-card small { color: #7d8986; margin-top: 1px; font-size: 11px; }
.system-icon { width: 34px; height: 34px; display: grid; place-items: center; background: #f0ece2; border-radius: 6px; color: #8a7452; }
.system-icon svg { width: 17px; }
.system-icon.muscles { background: #f9e4e0; color: #b34e45; }
.system-icon.soft-tissue { background: #dcf3ec; color: #397d6d; }

.structure-list { display: flex; flex-direction: column; gap: 2px; }
.structure-row {
  width: 100%; display: grid; grid-template-columns: 8px 1fr 15px; align-items: center; gap: 9px; border: 0;
  background: transparent; padding: 9px 8px; border-radius: 6px; text-align: left; color: #46534f; font-size: 13px; transition: background .15s;
}
.structure-row:hover { background: #edf3f0; }
.structure-row svg { width: 14px; color: #8a9793; }
.structure-row.selected { background: #dff2eb; color: #174b40; font-weight: 700; }
.structure-row.selected svg { color: #367e6e; }
.dot { width: 8px; height: 8px; border-radius: 99px; box-shadow: inset 0 0 0 1px #00000012; }

.viewer-panel {
  position: relative; min-width: 0; overflow: hidden;
  background: radial-gradient(circle at 48% 38%, #354944 0, #21312e 43%, #111918 100%);
}
.viewer-panel:before { content: ""; position: absolute; inset: 0; pointer-events: none; background: linear-gradient(115deg, #8cddc812, transparent 30%, transparent 72%, #03060640); z-index: 1; }
.viewer-panel canvas { touch-action: none; }
.viewer-panel.atlas-mode { background: #dfe5e1; }
.viewer-panel.atlas-mode:before { background: radial-gradient(circle at 50% 45%, #ffffffc7 0, transparent 58%), linear-gradient(115deg, #7ca89813, transparent 34%, transparent 75%, #44605716); }
.viewer-meta { position: absolute; z-index: 4; top: 20px; left: 22px; right: 22px; display: flex; justify-content: space-between; color: #a4b7b2; font-size: 10px; font-weight: 700; letter-spacing: .12em; }
.atlas-mode .viewer-meta { color: #60726c; }
.live-dot { color: #bce9dc; }
.atlas-mode .live-dot { color: #1f6757; }
.live-dot:before { content: ""; display: inline-block; width: 6px; height: 6px; border-radius: 99px; background: #67ceb0; margin-right: 7px; box-shadow: 0 0 0 4px #67ceb018; }
.viewer-mode-switch { position: absolute; z-index: 7; top: 42px; left: 50%; transform: translateX(-50%); display: flex; gap: 3px; margin: 0; padding: 3px; border: 1px solid #ffffff1d; border-radius: 8px; background: #172522e8; box-shadow: 0 8px 24px #07100d26; }
.viewer-mode-switch button { display: flex; align-items: center; gap: 6px; min-height: 30px; padding: 0 10px; border: 0; border-radius: 5px; background: transparent; color: #aebeba; font-size: 11px; font-weight: 680; }
.viewer-mode-switch button svg { width: 14px; height: 14px; }
.viewer-mode-switch button.active { background: #f5fbf8; color: #174d41; box-shadow: 0 1px 3px #0002; }
.anatomy-atlas { position: absolute; z-index: 2; inset: 0; display: grid; place-items: center; padding: 82px 28px 112px; }
.atlas-frame { height: 100%; max-width: 100%; display: flex; flex-direction: column; align-items: center; }
.atlas-plate-heading { width: 100%; display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; margin-bottom: 8px; color: #2d423c; }
.atlas-plate-heading > div { display: flex; flex-direction: column; }
.atlas-plate-heading strong { font-family: Georgia, "Times New Roman", serif; font-size: 18px; letter-spacing: -.01em; }
.atlas-plate-heading span { color: #71817c; font-size: 9px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
.atlas-plate-heading > span { white-space: nowrap; }
.atlas-stage { position: relative; height: calc(100% - 42px); max-width: 100%; overflow: hidden; border: 1px solid #c9d3cf; background: #fff; box-shadow: 0 16px 50px #1b312928, 0 2px 7px #1b312914; }
.atlas-image, .atlas-focus-image { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: fill; user-select: none; transition: opacity .2s, filter .2s; }
.atlas-image.dimmed { opacity: .17; filter: grayscale(.65); }
.atlas-focus-image { z-index: 1; pointer-events: none; }
.atlas-hotspots, .atlas-labels { position: absolute; z-index: 2; inset: 0; pointer-events: none; }
.atlas-hotspot { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; background: transparent; pointer-events: auto; transition: background .16s; }
.atlas-hotspot:hover, .atlas-hotspot:focus-visible { background: color-mix(in srgb, var(--hotspot-color) 24%, transparent); outline: none; }
.atlas-hotspot.selected { background: color-mix(in srgb, var(--hotspot-color) 30%, #54c3a833); filter: saturate(1.25); }
.atlas-hotspot.selected:focus-visible { background: color-mix(in srgb, var(--hotspot-color) 42%, transparent); }
.atlas-label { position: absolute; display: inline-flex; align-items: center; gap: 5px; max-width: 132px; transform: translate(-6px, -50%); padding: 4px 7px; border: 1px solid #c7d3cf; border-radius: 3px; background: #fffffff0; color: #40524d; box-shadow: 0 3px 10px #1b30291c; font-size: 10px; line-height: 1.15; font-weight: 700; }
.atlas-label:before { content: ""; width: 5px; height: 5px; flex: none; border-radius: 99px; background: #4d9b87; }
.atlas-label.align-right { transform: translate(calc(-100% + 6px), -50%); }
.atlas-label.selected { z-index: 3; border-color: #225f51; background: #153f36; color: #fff; box-shadow: 0 4px 14px #102b2452; }
.atlas-label.selected:before { background: #87dec6; }
.atlas-provenance { margin-top: 7px; align-self: flex-end; color: #63736e; font-size: 9px; text-decoration: none; }
.atlas-provenance:hover { color: #1d5b4d; text-decoration: underline; }
.scene-label { border: 1px solid #ffffff28; background: #14221fe8; color: #dceae6; border-radius: 5px; font-size: 11px; white-space: nowrap; padding: 5px 8px; box-shadow: 0 7px 18px #05090835; }
.scene-label:before { content: ""; display: inline-block; width: 5px; height: 5px; background: #80d4bd; border-radius: 50%; margin-right: 6px; vertical-align: 1px; }
.scene-label.selected { color: #18211e; background: #fff4be; border-color: #fff4be; font-weight: 750; }
.scene-label.selected:before { background: #9b7927; }

.viewer-toolbar {
  position: absolute; z-index: 5; left: 50%; bottom: 48px; transform: translateX(-50%); display: flex; align-items: center; gap: 4px;
  width: min(560px, calc(100% - 30px)); min-height: 48px; padding: 6px; border: 1px solid #ffffff1d; border-radius: 10px;
  background: #14201eea; color: #d7e6e1; box-shadow: 0 16px 35px #0509084a; backdrop-filter: blur(14px);
}
.viewer-toolbar button { color: #d3e1dd; }
