/* Anatomical illustration: actual 3D surfaces against a quiet paper-like ground. */
.illustration-mode { background: radial-gradient(ellipse at 48% 45%, #fffefb 0%, #f3f1ea 60%, #e7e9e4 100%); }
.illustration-mode:before { background: none; }
.illustration-mode .viewer-meta { color: #64716b; letter-spacing: .08em; }
.illustration-mode .live-dot { color: #416958; }
.dissection-controls { position: absolute; z-index: 6; top: 49px; left: 16px; right: 16px; display: flex; justify-content: center; gap: 10px; flex-wrap: wrap; }
.dissection-controls fieldset { display: flex; gap: 2px; padding: 4px; border: 1px solid #cdd5cc; border-radius: 7px; background: #fffffff0; box-shadow: 0 3px 10px #34463a0a; }
.dissection-controls legend { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
.dissection-controls button { min-height: 32px; padding: 4px 9px; border-radius: 4px; font-size: 12px; color: #667169; text-transform: capitalize; }
.dissection-controls button.active { color: #f9fcfa; background: #2d5c4e; }
.illustration-mode .scene-label { border: 0; border-bottom: 1px solid #a5aea0; background: #fffffff0; color: #4d554c; border-radius: 1px; padding: 4px 7px; font-size: 12px; box-shadow: none; }
.illustration-mode .scene-label:before { display: none; }
.illustration-mode .scene-label.selected { color: #634e2f; background: #fbf3df; border-bottom: 2px solid #9a7d4c; }
.illustration-mode .viewer-hint { bottom: 28px; color: #6c786f; }
.illustration-mode .viewer-toolbar { bottom: 58px; }
.model-credit { position: absolute; bottom: 8px; left: 50%; transform: translateX(-50%); font-size: 10px; color: #748177; white-space: nowrap; }
.model-credit:hover { text-decoration: underline; }
.zoom-controls { position: absolute; right: 16px; bottom: 128px; z-index: 5; display: flex; flex-direction: column; gap: 4px; }
.zoom-controls button { background: #ffffffd9; color: #466152; }
.model-loading { padding: 14px 20px; width: 230px; background: white; border: 1px solid #cdd5cc; color: #526451; font-size: 14px; text-align: center; border-radius: 6px; }
.illustration-mode .exam-prompt { top: 108px; color: #354c3c; }
