.imaging-empty button { color: #2e7762; font-size: 12px; text-decoration: underline; }
/* Visible Medicine schematic system: ivory drawing surface, midnight chrome,
   teal navigation and restrained lime selection. Tissue colours remain semantic. */
.vm-brand { display: flex; flex: 0 0 auto; align-items: center; width: 270px; min-width: 0; }
.vm-brand img { display: block; width: 100%; height: auto; }
.topbar { grid-template-columns: auto 1fr auto; height: 72px; background: var(--vm-midnight); color: var(--vm-ivory); border-bottom: 3px solid var(--vm-teal); }
.topbar .workspace-name svg, .topbar .workspace-name span { color: var(--vm-teal); }
.topbar .body-return-link { color: var(--vm-ivory); }
.topbar button { background: var(--vm-ink); color: var(--vm-ivory); border-color: #426169; }
.workspace-grid { height: calc(100dvh - 72px); }
.app-shell, .illustration-mode { background: var(--vm-ivory); }
.control-rail, .info-panel { color: var(--vm-ink); background: #fff; }
.info-panel h1, .info-panel h2 { color: var(--vm-ink); }
.eyebrow, .info-kicker, .rail-section-heading, .illustration-mode .viewer-meta { color: var(--vm-muted); }
.system-card.active { background: #f0faf7; border-color: #81bcb3; }
