.illustration-mode .viewer-toolbar { background: var(--vm-midnight); }
.vm-scene-options { position: absolute; z-index: 6; left: 12px; right: 12px; bottom: 112px; display: flex; justify-content: center; flex-wrap: wrap; gap: 5px; }
.vm-scene-options button { min-height: 32px; padding: 4px 9px; border: 1px solid #b4c9c8; border-radius: 5px; background: #fffffff0; color: var(--vm-ink); font-size: 12px; }
.vm-scene-options button[aria-pressed='true'] { background: var(--vm-ink); color: var(--vm-ivory); border-color: var(--vm-teal); }
.vm-review-status { margin: 12px 0 20px; padding: 10px 12px; border: 1px solid #d5dfdc; border-left: 3px solid var(--vm-teal); border-radius: 4px; color: var(--vm-ink); background: var(--vm-ivory); font-size: 14px; line-height: 1.5; }
