const serverSnapshot = () => null;
export const comparisonMessages = {
  disconnected: 'The comparison viewer is disconnected.',
  paused: 'Live viewer selection is paused. Enable it in Didanix live link to compare.',
  'select-structure': 'Select a structure in the anatomy viewer.',
  'source-mismatch':
    'The mapped anatomy revision has changed. This image is withheld until the mapping is reviewed.',
  loading: 'Loading the selected teaching image…',
  unmapped:
    'No teaching image is mapped to this selection. No image has been substituted.',
  'access-denied':
    'This imaging resource is not included in your current access. Your atlas remains available.',
  error:
    'The imaging viewer could not display this frame. Your anatomy view is unchanged.',
};
function ImageSurface({ snapshot }: { snapshot: ComparisonSnapshot }) {
  const host = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const element = host.current;
    if (!element) return;
    const dispose = comparisonBridge.mount(element, snapshot);
    return () => {
      dispose();
      element.replaceChildren();
    };
  }, [snapshot]);
  return (
    <div
      className="vm-comparison-surface"
      ref={host}
      aria-label={`${snapshot.modality} ${snapshot.frame.plane} teaching image`}
    />
  );
}
export function ComparisonPanel({
  snapshot,
  status,
}: {
  snapshot: ComparisonSnapshot;
  status: ReturnType<typeof comparisonAvailability>;
}) {
  const frame = snapshot.frame;
  return (
    <>
      <p className="vm-comparison-boundary">
        Teaching comparison · not spatially registered
      </p>
      {status !== 'ready' ? (
        <p className="vm-comparison-message" role="status">
          {comparisonMessages[status]}
        </p>
      ) : (
        <>
          <div className="vm-comparison-plane">
            <Select
              value={frame.plane}
              onValueChange={(value) => {
                if (imagePlanes.includes(value as ImagePlane))
                  comparisonBridge.request(snapshot, {
                    plane: value as ImagePlane,
                  });
              }}
            >
              <SelectTrigger aria-label="Imaging plane">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {imagePlanes.map((plane) => (
                  <SelectItem key={plane} value={plane}>
                    {plane[0].toUpperCase() + plane.slice(1)}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <span>
              {snapshot.modality} · {frame.slice + 1} / {frame.sliceCount}
            </span>
          </div>
          <ImageSurface snapshot={snapshot} />
          <div className="vm-comparison-slices">
            <Button
              variant="outline"
              aria-label="Previous image slice"
              disabled={frame.slice === 0}
              onClick={() =>
                comparisonBridge.request(snapshot, { slice: frame.slice - 1 })
              }
            >
              −
            </Button>
            <Slider
              aria-label="Image slice"
              aria-valuetext={`${frame.slice + 1} of ${frame.sliceCount}`}
              min={0}
              max={Math.max(1, frame.sliceCount - 1)}
              step={1}
              value={[frame.slice]}
              disabled={frame.sliceCount === 1}
              onValueChange={(value) =>
                comparisonBridge.request(snapshot, {
                  slice: Array.isArray(value) ? value[0] : value,
                })
              }
            />
            <Button
              variant="outline"
              aria-label="Next image slice"
              disabled={frame.slice === frame.sliceCount - 1}
              onClick={() =>
                comparisonBridge.request(snapshot, { slice: frame.slice + 1 })
              }
            >
              +
            </Button>
          </div>
        </>
      )}
    </>
  );
}
/** The model subtree never unmounts when comparison is opened or closed. */
export function ImagingComparisonWorkspace({
  children,
  selected,
  link,
}: {
  children: ReactNode;
  selected: AnatomyLinkEntry | null;
  link: ReturnType<typeof useImagingLink>;
}) {
  const snapshot = useSyncExternalStore(
    comparisonBridge.subscribe,
    comparisonBridge.getSnapshot,
    serverSnapshot,
  );
  const [opened, setOpened] = useState(false);
  const [mobilePane, setMobilePane] = useState('model');
  const toggle = useRef<HTMLButtonElement>(null);
  const panelId = useId();
  const connected = !!snapshot && snapshot.adapterId === link.adapter?.id;
  const open = opened && connected && !link.disabled;
  const status = comparisonAvailability(
    snapshot,
    selected,
    link.adapter?.id ?? null,
    link.enabled,
    link.disabled,
  );
  useEffect(() => {
    if (!connected || link.disabled) {
      setOpened(false);
      setMobilePane('model');
    }
  }, [connected, link.disabled]);
  return (
    <div
      className="vm-comparison"
      data-open={open}
      data-mobile-pane={mobilePane}
    >
      {connected && !link.disabled && (
        <div className="vm-comparison-toolbar">
          <Button
            ref={toggle}
            variant="outline"
            aria-expanded={open}
            aria-controls={panelId}
            onClick={() => {
              setOpened(!open);
              setMobilePane('model');
            }}
          >
            {open ? 'Close comparison' : `Compare ${snapshot.modality}`}
          </Button>
          {open && (
            <>
              <span className="vm-comparison-label">{snapshot.label}</span>
              <RadioGroup
                className="vm-comparison-mobile-choice"
                aria-label="Visible comparison pane"
                value={mobilePane}
                onValueChange={setMobilePane}
              >
                {['model', 'image'].map((pane) => (
                  <label key={pane}>
                    <RadioGroupItem value={pane} />
                    {pane === 'model' ? 'Anatomy' : snapshot.modality}
                  </label>
                ))}
              </RadioGroup>
            </>
          )}
        </div>
      )}
      <div className="vm-comparison-model">{children}</div>
      <section
        id={panelId}
        className="vm-comparison-image"
        aria-label="Imaging comparison"
        hidden={!open}
        onKeyDown={(event) => {
          if (event.key === 'Escape') {
            event.stopPropagation();
            setOpened(false);
            toggle.current?.focus();
          }
        }}
      >
        {open && snapshot && (
          <ComparisonPanel snapshot={snapshot} status={status} />
        )}
      </section>
    </div>
  );
}

'use client';
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from 'react';
import {
  createAtlasReceiver,
  imagingBridge,
  type AdapterInfo,
  type createImagingBridge,
} from '@/atlas-review/lib/imaging-sync';
import {
  type AnatomyLinkEntry,
  type SelectionResolution,
} from '@/atlas-review/lib/anatomy-link-registry';
import './imaging-link.css';

export function useImagingLink({
  entries,
  allowedIds,
  disabled,
  onSelect,
  bridge = imagingBridge,
}: {
  entries: AnatomyLinkEntry[];
  allowedIds: string[];
  disabled: boolean;
  onSelect: (id: string) => void;
  bridge?: ReturnType<typeof createImagingBridge>;
}) {
  const [enabled, setEnabled] = useState(false);
  const [adapter, setAdapter] = useState<AdapterInfo | null>(null);
  const [notice, setNotice] = useState('');
  const [choice, setChoice] = useState<SelectionResolution | null>(null);
  const current = useRef({ entries, allowedIds, disabled, onSelect, enabled });
  useLayoutEffect(() => {
    current.current = { entries, allowedIds, disabled, onSelect, enabled };
  });
  useEffect(() => {
    const update = () => {
      setAdapter(bridge.getAdapter());
      setEnabled(false);
      current.current.enabled = false;
      setChoice(null);
      setNotice('');
    };
    update();
    const unsubscribe = bridge.subscribe(update);
    const detach = bridge.attachAtlas(
      createAtlasReceiver(
        () => current.current,
        (resolution) => {
          setChoice(
            resolution.status === 'choice-required' ? resolution : null,
          );
          if (resolution.status === 'selected') {
            setNotice(
              `Selected ${resolution.candidates[0].name} from the linked viewer.`,
            );
          } else
            setNotice(
              resolution.status === 'out-of-scope'
                ? 'This structure is outside the current region or side. Change the atlas scope and send the selection again.'
                : resolution.status === 'unknown-structure'
                  ? 'This identity is not available in this atlas view. No anatomy was substituted.'
                  : resolution.mapping === 'aggregate'
                    ? 'This view represents that component within a larger structure. Choose whether to show the group.'
                    : 'This structure has separately selectable parts here. Choose a part; none has been selected automatically.',
            );
        },
      ),
    );
    return () => {
      unsubscribe();
      detach();
    };
  }, [bridge]);
  const publish = useCallback((id: string) => {
    if (!current.current.enabled || current.current.disabled) return;
    if (!current.current.allowedIds.includes(id)) return;
    setChoice(null);
    const entry = current.current.entries.find((entry) => entry.id === id);
    if (entry && bridge.publish(entry))
      setNotice(
        `Sent ${entry.name} to the linked viewer. Selection only; no patient alignment.`,
      );
  }, [bridge]);
  function choose(id: string) {
    if (
      !enabled ||
      disabled ||
      !adapter ||
      !choice?.candidates.some((c) => c.id === id) ||
      !allowedIds.includes(id)
    )
      return;
    onSelect(id);
    setChoice(null);
    publish(id);
  }
  return {
    enabled,
    adapter,
    notice,
    choice,
    disabled,
    publish,
    choose,
    setEnabled(value: boolean) {
      current.current.enabled = value;
      setEnabled(value);
      setChoice(null);
      setNotice('');
    },
    clearChoice() {
      setChoice(null);
    },
    allowedIds,
  };
}
export function ImagingLink({
  link,
}: {
  link: ReturnType<typeof useImagingLink>;
}) {
  const candidates =
    link.choice?.candidates.filter((c) => link.allowedIds.includes(c.id)) ?? [];
  const active = !!link.adapter && link.enabled && !link.disabled;
  return (
    <details className="vm-imaging-link">
      <summary>
        Didanix live link{' '}
        <span>
          {!link.adapter
            ? 'No live viewer'
            : active
              ? 'Selection linked'
              : 'Selection paused'}
        </span>
      </summary>
      <div className="vm-imaging-content">
        <p>
          Website CT/MRI anatomy comparisons use separate links. This status
          applies only to the live Didanix viewer connection.
        </p>
        <p>
          Link Didanix Education to select corresponding CT, MRI, X-ray or
          ultrasound anatomy in either direction.
        </p>
        {link.adapter ? (
          <p>
            <strong>{link.adapter.label}</strong> · {link.adapter.modality}{' '}
            adapter registered. This status does not verify that a study is
            loaded.
          </p>
        ) : (
          <p>
            No live Didanix viewer is connected. This does not disable the
            website’s CT/MRI anatomy comparison links or the 3D Atlas.
          </p>
        )}
        <label>
          <input
            type="checkbox"
            checked={link.enabled}
            disabled={!link.adapter || link.disabled}
            onChange={(event) => link.setEnabled(event.target.checked)}
          />{' '}
          Allow linked structure selection
        </label>
        <p className="vm-imaging-boundary">
          Selection only · no patient registration. Reference points are
          assembled source-model millimetres, not patient coordinates or
          measured landmarks. No scans are included.
        </p>
        {link.disabled && <p>Linked selection is paused in this view. Return to a loaded, unfiltered exploration view to reconnect.</p>}
        <output aria-live="polite">{!link.disabled && link.notice}</output>
        {active && candidates.length > 0 && (
          <div className="vm-imaging-choices">
            {candidates.map((candidate) => (
              <button
                type="button"
                key={candidate.id}
                onClick={() => link.choose(candidate.id)}
              >
                {candidate.name}
              </button>
            ))}
            <button type="button" onClick={() => link.clearChoice()}>
              Dismiss choice
            </button>
          </div>
        )}
      </div>
    </details>
  );
}

'use client';
import { useEffect, useState } from 'react';
import { Button } from '@/atlas-review/components/ui/button';
import {
  makeIndependentStudyLink,
  resolveIndependentStudyLink,
  noIndependentStudyLink,
  type IndependentStudyLink,
} from '@/atlas-review/lib/independent-study-links';
import type { SpecimenDefinition } from '@/atlas-review/lib/independent-specimen';
import type { DissectionView } from './dissection-data';
import { CopySpecimenLink } from './specimen-study-link';
import { KneeSpecimenView, type SpecimenSupplement } from './um-knee-study';
import { independentStudyDeliveryUrl } from '@/atlas-review/lib/model-delivery';

export function IndependentStudyView({
  definition,
  supplement,
  link = noIndependentStudyLink,
  assetBase = '',
}: {
  definition: SpecimenDefinition;
  supplement: SpecimenSupplement;
  link?: IndependentStudyLink;
  assetBase?: string;
}) {
  return (
    <ResolvedIndependentStudy
      key={definition.key + JSON.stringify(link)}
      definition={definition}
      supplement={supplement}
      link={link}
      assetBase={assetBase}
    />
  );
}
function ResolvedIndependentStudy({
  definition,
  supplement,
  link,
  assetBase,
}: {
  definition: SpecimenDefinition;
  supplement: SpecimenSupplement;
  link: IndependentStudyLink;
  assetBase: string;
}) {
  const [result, setResult] = useState<{
    definition: SpecimenDefinition;
    link: IndependentStudyLink;
    value: Awaited<ReturnType<typeof resolveIndependentStudyLink>>;
  } | null>(
    link.status === 'none'
      ? { definition, link, value: { status: 'none' } }
      : null,
  );
  const resolved =
    result?.definition === definition && result.link === link
      ? result.value
      : null;
  const [ignore, setIgnore] = useState(false);
  useEffect(() => {
    let current = true;
    resolveIndependentStudyLink(link, definition)
      .then((value) => {
        if (current) setResult({ definition, link, value });
      })
      .catch(() => {
        if (current)
          setResult({
            definition,
            link,
            value: {
              status: 'rejected',
              reason: 'Source verification could not be completed.',
            },
          });
      });
    return () => {
      current = false;
    };
  }, [link, definition]);
  if (!ignore && !resolved)
    return <p role="status">Checking the exact source selection…</p>;
  if (!ignore && resolved?.status === 'rejected')
    return (
      <section className="um-specimen-link-warning" role="alert">
        <h2>This study link cannot be opened</h2>
        <p>{resolved.reason} No alternative structure has been selected.</p>
        <Button variant="outline" onClick={() => setIgnore(true)}>
          Open current source view
        </Button>
      </section>
    );
  return (
    <KneeSpecimenView
      assetBase={assetBase}
      specimen={definition}
      supplement={supplement}
      initialNavigation={
        !ignore && resolved?.status === 'ready' ? resolved : undefined
      }
    />
  );
}
export function IndependentStudyLinkControl({
  definition,
  selectedId,
  studyId,
  view,
  assetBase = '',
}: {
  definition: SpecimenDefinition;
  selectedId: string;
  studyId: string | null;
  view: DissectionView;
  assetBase?: string;
}) {
  const identity = JSON.stringify([definition.key, selectedId, studyId, view, assetBase]);
  const [result, setResult] = useState<{
    identity: string;
    href: string | null;
  } | null>(null);
  useEffect(() => {
    let current = true;
    makeIndependentStudyLink(definition, { selectedId, studyId, view })
      .then((href) => {
        if (current) setResult({ identity, href: href ? independentStudyDeliveryUrl(href, assetBase) : null });
      })
      .catch(() => {
        if (current) setResult({ identity, href: null });
      });
    return () => {
      current = false;
    };
  }, [definition, selectedId, studyId, view, identity, assetBase]);
  return (
    <details className="um-knee-details">
      <summary>{assetBase ? 'Link to this structure' : 'Link & review this structure'}</summary>
      {result?.identity === identity ? (
        result.href ? (
          <CopySpecimenLink key={result.href} href={result.href} />
        ) : (
          <p>This exact source link is unavailable.</p>
        )
      ) : (
        <p role="status">Preparing source-checked link…</p>
      )}
      {!assetBase && <p>
        <a
          href={`/workspace/atlas-review/specimens?specimen=${encodeURIComponent(definition.key)}&structure=${encodeURIComponent(selectedId)}`}
          target="_blank"
          rel="noreferrer"
        >
          Review this structure
        </a>
      </p>}
      <p>
        {studyId
          ? 'Opens this selection with the chosen source study.'
          : 'Custom dissection: opens this selection with others faded.'}{' '}
        Original positions and camera direction are restored; separation and
        hidden-tissue edits are not shared. No scan registration or paid access
        is granted.
      </p>
    </details>
  );
}

'use client';
import { useId } from 'react';
import { Button } from '@/atlas-review/components/ui/button';
import { Slider } from '@/atlas-review/components/ui/slider';
import { Switch } from '@/atlas-review/components/ui/switch';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/atlas-review/components/ui/select';
import {
  initialInspection,
  sectionAxes,
  type InspectionState,
  type SectionPlane,
} from '@/atlas-review/lib/inspection-state';
import './inspection.css';

export function InspectionControls({
  value,
  onChange,
  systems,
  plate,
  onPlate,
  disabled = false,
}: {
  value: InspectionState;
  onChange: (value: InspectionState) => void;
  systems: { id: string; name: string; enabled: boolean }[];
  plate: boolean;
  onPlate: (value: boolean) => void;
  disabled?: boolean;
}) {
  const axis = value.plane === 'off' ? null : sectionAxes[value.plane];
  const id = useId();
  return (
    <details className="vm-inspection">
      <summary>
        Inspect deeper{' '}
        <span>
          {axis
            ? `${value.plane} cutaway`
            : 'Cutaway · transparency · illustration view'}
        </span>
      </summary>
      <fieldset disabled={disabled}>
        <legend className="sr-only">Anatomy inspection controls</legend>
        <div className="vm-inspection-grid">
          <div>
            <h3>Cutaway plane</h3>
            <Select
              disabled={disabled}
              value={value.plane}
              onValueChange={(plane) =>
                plane && onChange({ ...value, plane: plane as SectionPlane })
              }
            >
              <SelectTrigger aria-label="Cutaway plane">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="off">No cutaway</SelectItem>
                <SelectItem value="axial">Axial — horizontal</SelectItem>
                <SelectItem value="coronal">Coronal — front / back</SelectItem>
                <SelectItem value="sagittal">
                  Sagittal — right / left
                </SelectItem>
              </SelectContent>
            </Select>
            {axis && (
              <>
                <div className="vm-inspection-scale">
                  <span>{axis.low}</span>
                  <output>{value.position}%</output>
                  <span>{axis.high}</span>
                </div>
                <Slider
                  disabled={disabled}
                  value={[value.position]}
                  min={0}
                  max={100}
                  step={1}
                  aria-label={`${value.plane} cutaway position`}
                  aria-valuetext={`${value.position}% from ${axis.low.toLowerCase()} to ${axis.high.toLowerCase()}`}
                  onValueChange={(v) =>
                    onChange({
                      ...value,
                      position: Array.isArray(v) ? v[0] : v,
                    })
                  }
                />
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() =>
                    onChange({ ...value, flipped: !value.flipped })
                  }
                >
                  Keep{' '}
                  {value.flipped
                    ? axis.low.toLowerCase()
                    : axis.high.toLowerCase()}{' '}
                  side · reverse
                </Button>
                <p>
                  Open surface cutaway, not a scan or a reconstruction of
                  internal tissue. Cuts follow each structure during explode.
                </p>
              </>
            )}
          </div>
          <div>
            <h3>Tissue opacity</h3>
            {systems.map((system) => (
              <div className="vm-opacity" key={system.id}>
                <div>
                  <span>
                    {system.name}
                    {!system.enabled && ' · hidden'}
                  </span>
                  <output>{value.opacity[system.id] ?? 100}%</output>
                </div>
                <Slider
                  min={5}
                  max={100}
                  step={5}
                  value={[value.opacity[system.id] ?? 100]}
                  disabled={!system.enabled || disabled}
                  aria-label={`${system.name} opacity`}
                  aria-valuetext={`${value.opacity[system.id] ?? 100}%`}
                  onValueChange={(v) =>
                    onChange({
                      ...value,
                      opacity: {
                        ...value.opacity,
                        [system.id]: Array.isArray(v) ? v[0] : v,
                      },
                    })
                  }
                />
              </div>
            ))}
            <p>
              Below 20%, clicks pass through to deeper surfaces. Search can
              still select these tissues.
            </p>
          </div>
        </div>
        <div className="vm-inspection-options">
          <label htmlFor={`${id}-solid`}>
            <Switch
              id={`${id}-solid`}
              disabled={disabled}
              checked={value.keepSelectedSolid}
              onCheckedChange={(checked) =>
                onChange({ ...value, keepSelectedSolid: checked })
              }
              aria-label="Keep selected structure opaque"
            />
            Keep selection solid
          </label>
          <label htmlFor={`${id}-uncut`}>
            <Switch
              id={`${id}-uncut`}
              disabled={disabled}
              checked={value.keepSelectedUncut === true}
              onCheckedChange={(checked) =>
                onChange({ ...value, keepSelectedUncut: checked })
              }
              aria-label="Keep selected structure uncut"
            />
            Keep selection uncut
          </label>
          <label htmlFor={`${id}-plate`}>
            <Switch
              id={`${id}-plate`}
              disabled={disabled}
              checked={plate}
              onCheckedChange={onPlate}
              aria-label="Orthographic illustration view"
            />
            Orthographic illustration
          </label>
          <Button
            size="sm"
            variant="ghost"
            onClick={() => {
              onChange(initialInspection);
              onPlate(false);
            }}
          >
            Reset inspection
          </Button>
        </div>
      </fieldset>
      {disabled && (
        <p>Inspection settings are suspended during identification practice.</p>
      )}
    </details>
  );
}

'use client';

import { useCallback, useLayoutEffect, useMemo, useReducer, useRef, useState } from 'react';
import { Button } from '@/atlas-review/components/ui/button';
import {
  createPracticeSession,
  initialPractice,
  missedPracticeIds,
  practiceReducer,
  practiceRenderIds,
  practiceScore,
  type PracticeMode,
} from '@/atlas-review/lib/anatomy-practice';
import { nestedPracticeKind, nestedPracticeReady } from '@/atlas-review/lib/nested-practice';
import type { NestedStudy } from '@/atlas-review/lib/nested-anatomy';
import type { RendererHealth } from '@/atlas-review/lib/renderer-health';
import { initialInspection } from '@/atlas-review/lib/inspection-state';
import { BodyScene, retryBodyAssets } from './body-scene';
import { allBodySystems, type BodyCatalog, type BodyStructure } from './body-types';
import type { DissectionView } from './dissection-data';
import './nested-practice.css';

export function NestedPractice({
  catalog,
  structures,
  study,
  mode,
  view,
  assetBase = '',
  onClose,
}: {
  catalog: BodyCatalog;
  structures: BodyStructure[];
  study: NestedStudy;
  mode: PracticeMode;
  view: DissectionView;
  assetBase?: string;
  onClose: () => void;
}) {
  const kind = nestedPracticeKind(study) ?? 'structure';
  const [practice, dispatch] = useReducer(
    practiceReducer,
    undefined,
    () =>
      createPracticeSession(
        structures,
        [...new Set(structures.map((s) => s.bundle))],
        {
          id: 1,
          mode,
          count: Math.min(5, structures.length),
          sampling: 'all',
        },
      ) ?? initialPractice,
  );
  const [health, setHealth] = useState<RendererHealth>('starting');
  const [loaded, setLoaded] = useState<string[]>([]);
  const [failed, setFailed] = useState<string[]>([]);
  const [retry, setRetry] = useState(0);
  const [separated, setSeparated] = useState(false);
  const heading = useRef<HTMLHeadingElement>(null);
  const feedback = useRef<HTMLOutputElement>(null);
  useLayoutEffect(() => {
    heading.current?.focus();
  }, [practice.id, practice.index, practice.status]);

  const rendered = useMemo(() => {
    if (practice.status === 'complete') return structures;
    const ids = new Set(practiceRenderIds(practice));
    return structures.filter((structure) => ids.has(structure.id));
  }, [practice, structures]);
  const required = useMemo(
    () => [...new Set(rendered.map((structure) => structure.bundle))],
    [rendered],
  );
  const ready = nestedPracticeReady(health, required, loaded, failed);
  const question = practice.questions[practice.index];
  const target = structures.find((structure) => structure.id === question?.target);
  const answered = practice.responses.length > practice.index;
  const currentResponse = practice.responses[practice.index];
  useLayoutEffect(() => {
    if (answered && practice.status !== 'complete') feedback.current?.focus();
  }, [answered, practice.id, practice.index, practice.status]);
  const appearance = useMemo(
    () =>
      Object.fromEntries(
        structures.map((structure) => [
          structure.id,
          { color: '#a7adb2', opacity: 1 },
        ]),
      ),
    [structures],
  );
  const onLoaded = useCallback((id: string) => {
    setLoaded((value) => (value.includes(id) ? value : [...value, id]));
    setFailed((value) => value.filter((failedId) => failedId !== id));
  }, []);
  const onFailure = useCallback((id: string) => {
    setFailed((value) => (value.includes(id) ? value : [...value, id]));
  }, []);

  function answer(chosen: string | null) {
    if (!ready || !question || answered) return;
    dispatch({
      type: 'answer',
      sessionId: practice.id,
      index: practice.index,
      chosen,
    });
  }
  function next() {
    if (!ready || !answered) return;
    dispatch({ type: 'next', sessionId: practice.id, index: practice.index });
  }
  function retryMissed() {
    const session = createPracticeSession(
      structures,
      [...new Set(structures.map((s) => s.bundle))],
      {
        id: practice.id + 1,
        mode,
        count: Math.min(5, structures.length),
        sampling: 'all',
        retryIds: missedPracticeIds(practice.responses),
      },
    );
    if (session) {
      setHealth('starting');
      setLoaded([]);
      setFailed([]);
      dispatch({ type: 'start', session });
    }
  }

  const complete = practice.status === 'complete';
  return (
    <div className="nested-practice eye-layer-workbench">
      <section className="eye-layer-viewport" aria-label="Nested anatomy identification model">
        {rendered.length > 0 && (
          <BodyScene
            key={practice.id}
            assetBase={assetBase}
            catalog={catalog}
            structures={rendered}
            selectedId={null}
            systems={allBodySystems}
            isolated={false}
            hiddenIds={[]}
            ghostRemoved={false}
            illustrated
            labels={false}
            landmarks={[]}
            contextIds={[]}
            explode={0}
            layout="spatial"
            anchorSkeleton={false}
            showOrigins={false}
            view={view}
            zoom={1}
            reset={practice.id + practice.index}
            focus
            exam
            practiceTray={kind === 'structure' && practice.mode === 'find' && separated}
            inspection={initialInspection}
            plate={false}
            appearance={appearance}
            retries={Object.fromEntries(catalog.bundles.map((bundle) => [bundle.id, retry]))}
            onSelect={(id) => {
              if (practice.mode === 'find') answer(id);
            }}
            onLoaded={onLoaded}
            onFailure={onFailure}
            onRendererHealth={setHealth}
          />
        )}
        {!complete && !ready && (
          <div className="eye-layer-status" role={failed.some((id) => required.includes(id)) ? 'alert' : 'status'}>
            {failed.some((id) => required.includes(id))
              ? 'Practice is paused because required anatomy could not load.'
              : 'Preparing the identification model…'}
            {failed.some((id) => required.includes(id)) && (
              <Button
                size="sm"
                onClick={() => {
                  retryBodyAssets(
                    catalog.bundles
                      .filter((bundle) => required.includes(bundle.id) && failed.includes(bundle.id))
                      .map((bundle) => bundle.url),
                    assetBase,
                  );
                  setLoaded((value) => value.filter((id) => !failed.includes(id)));
                  setFailed([]);
                  setRetry((value) => value + 1);
                }}
              >
                Retry
              </Button>
            )}
          </div>
        )}
      </section>
      <aside className="eye-layer-controls nested-practice-controls" aria-label="Identification practice">
        <Button variant="outline" size="sm" onClick={onClose}>
          Back to dissection
        </Button>
        <h3 ref={heading} tabIndex={-1}>
          {complete
            ? 'Practice complete'
            : practice.mode === 'find'
              ? `Find ${target?.name ?? `the named ${kind}`}`
              : `Name the isolated ${kind}`}
        </h3>
        <p>{kind === 'space' ? 'Source spaces only, not chamber walls.' : 'Source-defined structures and named groups only, not complete organs or validated clinical anatomy.'} Labels, teaching and selection hints are hidden.</p>
        <p>Formative practice only; this is not a validated assessment.</p>
        {!complete && question && target && (
          <>
            <p>
              Question {practice.index + 1} of {practice.questions.length}
            </p>
            {practice.mode === 'name' ? (
              <div className="nested-practice-choices">
                {question.choices.map((id) => (
                  <Button
                    key={`${practice.id}:${practice.index}:${id}`}
                    variant="outline"
                    disabled={!ready || answered}
                    onClick={() => answer(id)}
                  >
                    {structures.find((structure) => structure.id === id)?.name}
                  </Button>
                ))}
              </div>
            ) : (
              <>
                <p>Select the named surface in the model.</p>
                {kind === 'structure' && (
                  <>
                    <Button variant="outline" aria-pressed={separated} onClick={() => setSeparated(value => !value)}>
                      {separated ? 'Restore anatomical positions' : 'Separate overlapping structures'}
                    </Button>
                    {separated && <p role="status">Separated shapes for identification, not anatomical positions.</p>}
                  </>
                )}
              </>
            )}
            <output ref={feedback} tabIndex={-1} className="block">
              {!ready
                ? 'Answering is paused until the model is ready.'
                : answered
                  ? currentResponse?.chosen === target.id
                    ? `Correct: ${target.name}.`
                    : `Answer: ${target.name}.`
                  : 'Choose once, or skip to reveal the answer.'}
            </output>
            {answered ? (
              <Button onClick={next} disabled={!ready}>
                {practice.index + 1 === practice.questions.length ? 'Finish round' : `Next ${kind}`}
              </Button>
            ) : (
              <Button variant="ghost" disabled={!ready} onClick={() => answer(null)}>
                Skip &amp; reveal
              </Button>
            )}
          </>
        )}
        {complete && (
          <section className="nested-practice-results">
            <p>
              {practiceScore(practice)} of {practice.responses.length} correct.
            </p>
            <ul>
              {practice.responses.map((response) => (
                <li key={response.target}>
                  {structures.find((structure) => structure.id === response.target)?.name} ·{' '}
                  {response.chosen === response.target ? 'Correct' : 'Review'}
                </li>
              ))}
            </ul>
            <div className="eye-layer-actions">
              <Button
                variant="outline"
                disabled={!missedPracticeIds(practice.responses).length}
                onClick={retryMissed}
              >
                Retry missed
              </Button>
              <Button onClick={onClose}>Return to dissection</Button>
            </div>
          </section>
        )}
        <p className="muted">
          Your visibility, selection and history are preserved. The camera may reframe when you return.
          {study === 'ventricles' ? ' These are ventricular spaces, not solid tissue.' : ''}
        </p>
      </aside>
    </div>
  );
}

'use client';
import type { BodyStructure } from './body-types';
import type { NestedStudy } from '@/atlas-review/lib/nested-anatomy';
import type { NestedImagingTopic } from '@/atlas-review/content/nested-teaching';
import {
  nestedTeachingFor,
  nestedTopicLesson,
  nestedTeachingReferences,
} from '@/atlas-review/lib/nested-teaching';
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from '@/atlas-review/components/ui/tabs';
import './nested-teaching.css';
import { nestedReviewHref } from '@/atlas-review/lib/nested-review-links';

// Match the main atlas's three information groups without importing its whole
// workspace/search/practice graph into these lazy-loaded child viewers.
const groups = [
  {
    id: 'anatomy',
    label: 'Anatomy',
    sections: [
      ['anatomy', 'Overview'],
      ['function', 'Function'],
    ],
  },
  {
    id: 'clinical',
    label: 'Clinical',
    sections: [
      ['clinical', 'Context'],
      ['pathology', 'Pathology'],
    ],
  },
  {
    id: 'imaging',
    label: 'Imaging',
    sections: [
      ['ct', 'CT'],
      ['mri', 'MRI'],
      ['xray', 'X-ray'],
      ['ultrasound', 'Ultrasound'],
    ],
  },
] as const;

function References({ ids }: { ids: string[] }) {
  return ids.length > 0 ? (
    <ul
      className="nested-teaching-references"
      aria-label="Teaching references"
    >
      {ids.map((id) => (
        <li key={id}>
          <a
            href={nestedTeachingReferences[id].url}
            target="_blank"
            rel="noreferrer"
          >
            {nestedTeachingReferences[id].title}
          </a>
        </li>
      ))}
    </ul>
  ) : null;
}

export function NestedTeaching({
  parent,
  study,
  selected,
  initialTopic,
  reviewAvailable = true,
}: {
  parent: BodyStructure;
  study: NestedStudy;
  selected: BodyStructure;
  initialTopic?: NestedImagingTopic;
  reviewAvailable?: boolean;
}) {
  const concept = nestedTeachingFor(parent, study, selected);
  const reviewHref = reviewAvailable
    ? nestedReviewHref(parent, study, selected)
    : null;
  if (!concept)
    return (
      <div className="nested-teaching-unavailable">
        <p>
        Teaching is unavailable for this source binding. No alternative
        structure has been substituted.
        </p>
        {reviewHref && <a href={reviewHref} target="_blank" rel="noreferrer">Review this structure</a>}
      </div>
    );
  const imagingTopic =
    initialTopic && concept.imaging?.[initialTopic]?.readiness === 'draft'
      ? initialTopic
      : undefined;
  return (
    <details
      key={imagingTopic ?? 'default'}
      className="nested-teaching"
      open={!!imagingTopic}
    >
      <summary>Learn more · anatomy, imaging, clinical &amp; quiz</summary>
      {reviewHref && <p><a href={reviewHref} target="_blank" rel="noreferrer">Review this structure</a></p>}
      <p className="nested-teaching-status">
        Teaching draft · specialist review pending. Educational use, not
        diagnosis or treatment.
      </p>
      <Tabs
        defaultValue={imagingTopic ? 'imaging' : 'anatomy'}
        className="nested-teaching-tabs"
      >
        <TabsList aria-label="Nested structure information" variant="line">
          {groups.map((group) => (
            <TabsTrigger key={group.id} value={group.id}>
              {group.label}
            </TabsTrigger>
          ))}
        </TabsList>
        {groups.map((group) => (
          <TabsContent key={group.id} value={group.id}>
            <Tabs
              defaultValue={
                group.id === 'imaging' && imagingTopic
                  ? imagingTopic
                  : group.sections[0][0]
              }
            >
              <TabsList aria-label={`${group.label} topics`}>
                {group.sections.map(([tab, label]) => (
                  <TabsTrigger key={tab} value={tab}>
                    {label}
                  </TabsTrigger>
                ))}
              </TabsList>
              {group.sections.map(([tab]) => {
                const lesson = nestedTopicLesson(concept, tab);
                const refs =
                  tab === 'anatomy' ||
                  tab === 'function' ||
                  tab === 'clinical' ||
                  tab === 'pathology'
                    ? concept.sections[tab].references
                    : (concept.imaging?.[tab]?.references ?? []);
                return (
                  <TabsContent key={tab} value={tab}>
                    <section
                      className="nested-teaching-section"
                      aria-label={lesson.title}
                    >
                      <h4>{lesson.title}</h4>
                      <p>{lesson.body}</p>
                      {lesson.note && (
                        <p className="nested-teaching-status">
                          {lesson.note}
                        </p>
                      )}
                      {lesson.readiness === 'pending' && (
                        <span className="nested-teaching-status">
                          Content pending
                        </span>
                      )}
                      <References ids={refs} />
                    </section>
                  </TabsContent>
                );
              })}
            </Tabs>
          </TabsContent>
        ))}
      </Tabs>
      <p className="nested-teaching-limit">
        <strong>Model scope:</strong> {concept.modelLimit}
      </p>
      <section
        className="nested-teaching-quiz"
        aria-label="Anatomy self-check"
      >
        <h4>Self-check</h4>
        <p>{concept.quiz.question}</p>
        <details
          key={`${study}:${selected.id}`}
          className="nested-teaching-answer"
        >
          <summary>Reveal answer</summary>
          <p>{concept.quiz.answer}</p>
          {concept.quiz.basis === 'model-scope' && (
            <p className="nested-teaching-status">
              Answer basis: current source-model scope.
            </p>
          )}
          <References ids={concept.quiz.references} />
        </details>
        <p className="nested-teaching-status">
          Unscored recall practice, not an accredited exam.
        </p>
      </section>
    </details>
  );
}

'use client';
