                before replacing or keeping edits. Keeping edits resets
                checklist confirmations and attestation, and retains all saved
                issues.
              </p>
              <Button
                variant="outline"
                disabled={busy || mustRefresh}
                onClick={() => {
                  setDrafts(bodyDraftsFromPage(page));
                  setDirty(false);
                  setReconcile(false);
                  setMessage('Loaded the displayed saved records.');
                }}
              >
                Use displayed saved records
              </Button>
              <Button
                variant="outline"
                disabled={busy || mustRefresh}
                onClick={() => {
                  setDrafts(reconcileBodyDrafts(drafts, page));
                  setReconcile(false);
                  setDirty(true);
                  setMessage(
                    'Edits retained. Repeat the checklist and attest before approval.',
                  );
                }}
              >
                Keep edits against displayed records
              </Button>
            </div>
          )}
          <p className="body-review-caution">
            {track === 'teaching'
              ? `Approval scope: available draft topics (${page.context.teachingTabs.join(', ')}), the displayed source-specific reasoning question and any displayed guided-tour sequences. Pending topics, other questions and undisplayed tours are excluded.`
              : track === 'geometry'
                ? 'Approval scope: this root-body selection and renderer only. Nested dissections and independent specimens require separate reviews.'
                : 'Planning and correction notes can be saved, but imaging cannot be approved until validated images and registration exist.'}
          </p>
          <BodyDecisionFields
            draft={draft}
            checklist={page.context.checklists[track]}
            savedIssueIds={
              page.reviews
                .find((r) => r.track === track)
                ?.issues.map((i) => i.id) ?? []
            }
            disabled={busy || reconcile}
            change={change}
          />
          <details>
            <summary>Approval requirements</summary>
            <ul>
              {bodyApprovalProblems(draft, page.context, track).map(
                (problem) => (
                  <li key={problem}>{problem}</li>
                ),
              )}
            </ul>
            {!bodyApprovalProblems(draft, page.context, track).length && (
              <p>
                Software gates met. Your personal review and accuracy remain
                your responsibility.
              </p>
            )}
          </details>
          <div className="body-review-actions">
            <Button
              disabled={busy || reconcile}
              onClick={() => {
                void save('draft');
              }}
            >
              Save draft
            </Button>
            <Button
              variant="outline"
              disabled={busy || reconcile}
              onClick={() => {
                void save('changes-required');
              }}
            >
              Save changes required
            </Button>
            <Button
              variant="outline"
              disabled={
                busy ||
                reconcile ||
                !!bodyApprovalProblems(draft, page.context, track).length
              }
              onClick={() => {
                void save('approved');
              }}
            >
              Record scoped approval
            </Button>
          </div>
          <details>
            <summary>Saved history · {titles[track]}</summary>
            <Button
              variant="outline"
              disabled={busy}
              onClick={() => {
                void loadHistory();
              }}
            >
              Load latest history
            </Button>
            {history?.track === track && (
              <>
                <p>
                  {history.history.length} loaded versions. Export contains only
                  these loaded records, not your full account history.
                </p>
                <Button
                  variant="outline"
                  onClick={() =>
                    download(
                      {
                        scope: page.context.catalogScope,
                        structureId: id,
                        track,
                        history: history.history,
                        olderVersionsBefore: history.nextBefore,
                      },
                      'body-review-loaded-history.json',
                    )
                  }
                >
                  Export loaded history
                </Button>
                {history.history.map((record) => (
                  <details key={record.version}>
                    <summary>
                      Version {record.version} · {record.status} ·{' '}
                      {record.savedAt}
                    </summary>
                    <p>
                      {record.reviewer} · {record.qualification}
                    </p>
                    <p>{record.scope}</p>
                    <p>{record.notes}</p>
                    <ul>
                      {record.issues.map((i) => (
                        <li key={i.id}>
                          {i.severity}: {i.title} —{' '}
                          {i.resolved ? i.resolution : 'Unresolved'}
                        </li>
                      ))}
                    </ul>
                    <details>
                      <summary>Full recorded snapshot</summary>
                      <pre>{JSON.stringify(record, null, 2)}</pre>
                    </details>
                  </details>
                ))}
                {history.nextBefore && (
                  <Button
                    variant="outline"
                    disabled={busy}
                    onClick={() => {
                      void loadHistory(history.nextBefore!);
                    }}
                  >
                    Load older versions
                  </Button>
                )}
              </>
            )}
          </details>
        </>
      )}
    </section>
  );
}

export function BodyDecisionFields({
  draft,
  checklist,
  disabled,
  change,
  savedIssueIds = [],
}: {
  draft: BodyReviewDraft;
  checklist: { id: string; label: string }[];
  disabled: boolean;
  change: (patch: Partial<BodyReviewDraft>) => void;
  savedIssueIds?: string[];
}) {
  return (
    <fieldset disabled={disabled} className="body-decision-fields">
      <legend>Review details</legend>
      <div className="body-decision-name-row">
        <label>
          Reviewer name
          <input
            value={draft.reviewer}
            maxLength={150}
            onChange={(e) => change({ reviewer: e.target.value })}
          />
        </label>
        <label>
          Professional role / qualification
          <input
            value={draft.qualification}
            maxLength={200}
            onChange={(e) => change({ qualification: e.target.value })}
          />
        </label>
      </div>
      <label>
        Exact scope of this review
        <textarea
          rows={2}
          value={draft.scope}
          maxLength={2000}
          onChange={(e) => change({ scope: e.target.value })}
        />
      </label>
      <label>
        Notes and limitations
        <textarea
          rows={3}
          value={draft.notes}
          maxLength={6000}
          onChange={(e) => change({ notes: e.target.value })}
        />
      </label>
      <details>
        <summary>
          Checklist · {checklist.filter((c) => draft.checks[c.id]).length}/
          {checklist.length}
        </summary>
        {checklist.map((c) => (
          <label className="body-decision-check" key={c.id}>
            <input
              type="checkbox"
              checked={draft.checks[c.id] ?? false}
              onChange={(e) =>
                change({
                  checks: { ...draft.checks, [c.id]: e.target.checked },
                })
              }
            />
            {c.label}
          </label>
        ))}
      </details>
      <details>
        <summary>Evidence · {draft.evidence.length}</summary>
        {draft.evidence.map((e, index) => (
          <fieldset key={index}>
            <legend>Evidence {index + 1}</legend>
            <label>
              Title
              <input
                maxLength={180}
                value={e.title}
                onChange={(event) =>
                  change({
                    evidence: draft.evidence.map((v, i) =>
                      i === index ? { ...v, title: event.target.value } : v,
                    ),
                  })
                }
              />
            </label>
            <label>
              HTTPS reference
              <input
                type="url"
                maxLength={2048}
                value={e.url}
                onChange={(event) =>
                  change({
                    evidence: draft.evidence.map((v, i) =>
                      i === index ? { ...v, url: event.target.value } : v,
                    ),
                  })
                }
              />
            </label>
            <label>
              Evidence note
              <textarea
                maxLength={1000}
                value={e.note}
                onChange={(event) =>
                  change({
                    evidence: draft.evidence.map((v, i) =>
                      i === index ? { ...v, note: event.target.value } : v,
                    ),
                  })
                }
              />
            </label>
            <Button
              variant="outline"
              onClick={() =>
                change({
                  evidence: draft.evidence.filter((_, i) => i !== index),
                })
              }
            >
              Remove evidence {index + 1}
            </Button>
          </fieldset>
        ))}
        <Button
          variant="outline"
          disabled={draft.evidence.length >= 12}
          onClick={() =>
            change({
              evidence: [...draft.evidence, { title: '', url: '', note: '' }],
            })
          }
        >
          Add evidence
        </Button>
      </details>
      <details>
        <summary>
          Corrections · {draft.issues.filter((i) => !i.resolved).length} open
        </summary>
        <p>
          Issues remain in the record. Resolve them with an explanation; do not
          delete saved issues.
        </p>
        {draft.issues.map((issue, index) => {
          const update = (patch: Partial<typeof issue>) =>
            change({
              issues: draft.issues.map((v, i) =>
                i === index ? { ...v, ...patch } : v,
              ),
            });
          return (
            <fieldset key={issue.id}>
              <legend>Issue {index + 1}</legend>
              <label>
                Correction needed
                <textarea
                  maxLength={500}
                  value={issue.title}
                  onChange={(e) => update({ title: e.target.value })}
                />
              </label>
              <label>
                Severity
                <select
                  value={issue.severity}
                  onChange={(e) =>
                    update({
                      severity: e.target.value as typeof issue.severity,
                    })
                  }
                >
                  <option value="blocker">Blocker</option>
                  <option value="major">Major</option>
                  <option value="minor">Minor</option>
                </select>
              </label>
              <label className="body-decision-check">
                <input
                  type="checkbox"
                  checked={issue.resolved}
                  onChange={(e) => update({ resolved: e.target.checked })}
                />
                Resolved
              </label>
              <label>
                Resolution and reason
                <textarea
                  maxLength={1500}
                  value={issue.resolution}
                  onChange={(e) => update({ resolution: e.target.value })}
                />
              </label>
              {!savedIssueIds.includes(issue.id) && (
                <Button
                  variant="outline"
                  onClick={() =>
                    change({
                      issues: draft.issues.filter((_, i) => i !== index),
                    })
                  }
                >
                  Remove unsaved issue {index + 1}
                </Button>
              )}
            </fieldset>
          );
        })}
        <Button
          variant="outline"
          disabled={draft.issues.length >= 20}
          onClick={() =>
            change({
              issues: [
                ...draft.issues,
                {
                  id: crypto.randomUUID(),
                  title: '',
                  severity: 'major',
                  resolved: false,
                  resolution: '',
                },
              ],
            })
          }
        >
          Add correction
        </Button>
      </details>
      <label className="body-decision-check">
        <input
          type="checkbox"
          checked={draft.attested}
          onChange={(e) => change({ attested: e.target.checked })}
        />
        I personally performed the stated review; this is a scoped educational
        review, not certification of clinical fitness.
      </label>
    </fieldset>
  );
}

'use client';
import { reviewModelHref } from '@/lib/clinical-review-links';
import { clinicalReviewFetch } from '@/lib/clinical-review-fetch';
import { useEffect, useMemo, useState } from 'react';
import Link from 'next/link';
import { ReviewSignInLink } from '@/atlas-review/components/review-sign-in-link';
import { Brand } from '../../brand';
import { Button } from '@/atlas-review/components/ui/button';
import { Input } from '@/atlas-review/components/ui/input';
import {
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem,
} from '@/atlas-review/components/ui/select';
import { bodySystems } from '../../body-types';
import {
  bodyReviewQueue,
  type BodyReviewSummary,
} from '@/atlas-review/lib/body-review-search';
import type { BodyReviewMaterial } from '@/atlas-review/lib/body-review-material';
import { parseBodyReviewResponse } from '@/atlas-review/lib/body-review-response';
import { BodyDecisionEditor } from './body-decision-editor';
import { ReviewModelPreview } from '../review-model-preview';

const labels = {
  anatomy: 'Anatomy',
  function: 'Function',
  ct: 'CT',
  mri: 'MRI',
  xray: 'X-ray',
  ultrasound: 'Ultrasound',
  pathology: 'Pathology',
  clinical: 'Clinical',
  quiz: 'Quiz notes',
};
const readiness = {
  draft: 'Draft',
  pending: 'Pending',
  'identity-only': 'Identity only',
  'generated-identification': 'Identification prompt only',
};
export function BodyReviewDashboard({
  rows,
  regions,
  initialId,
  initialRegion,
}: {
  rows: BodyReviewSummary[];
  regions: { id: string; name: string }[];
  initialId: string | null;
  initialRegion: string;
}) {
  const [region, setRegion] = useState(initialRegion),
    [system, setSystem] = useState('all'),
    [query, setQuery] = useState('');
  const [page, setPage] = useState(() => {
      const index = bodyReviewQueue(rows, initialRegion, 'all', '').findIndex(
        (s) => s.id === initialId,
      );
      return Math.floor(Math.max(0, index) / 20);
    }),
    [selected, setSelected] = useState(initialId);
  const [dirty, setDirty] = useState(false);
  useEffect(() => {
    if (!dirty) return;
    const guard = (event: BeforeUnloadEvent) => {
      event.preventDefault();
      event.returnValue = '';
    };
    window.addEventListener('beforeunload', guard);
    return () => window.removeEventListener('beforeunload', guard);
  }, [dirty]);
  function canLeave() {
    return (
      !dirty ||
      window.confirm(
        'Leave this structure and discard unsaved review edits? Export or save them first if needed.',
      )
    );
  }
  const [material, setMaterial] = useState<BodyReviewMaterial | null>(null),
    [error, setError] = useState(''),
    [loading, setLoading] = useState(false),
    [attempt, setAttempt] = useState(0);
  const matches = useMemo(
    () => bodyReviewQueue(rows, region, system, query),
    [rows, region, system, query],
  );
  const currentPage = Math.min(
    page,
    Math.max(0, Math.ceil(matches.length / 20) - 1),
  );
  const visible = matches.slice(currentPage * 20, currentPage * 20 + 20);
  const selectedIndex = matches.findIndex((s) => s.id === selected);
  const previousStructure = selectedIndex > 0 ? matches[selectedIndex - 1] : null;
  const nextStructure =
    selectedIndex >= 0 ? matches[selectedIndex + 1] ?? null : null;
  function selectStructure(id: string) {
    // Clicking the current row must retain its editor and unsaved draft.
    if (id === selected) return;
    const index = matches.findIndex((s) => s.id === id);
    if (index < 0 || !canLeave()) return;
    setDirty(false);
    setMaterial(null);
    setError('');
    setPage(Math.floor(index / 20));
    setSelected(id);
  }
  useEffect(() => {
    const controller = new AbortController();
    let current = true;
    setMaterial(null);
    setError('');
    if (!selected) {
      setLoading(false);
      return () => controller.abort();
    }
    setLoading(true);
    clinicalReviewFetch(`/api/atlas-review/body-review?structure=${encodeURIComponent(selected)}`, {
      signal: controller.signal,
      cache: 'no-store',
    })
      .then(async (response) => {
        const data = await response.json();
        if (!response.ok)
          throw new Error(
            data &&
              typeof data === 'object' &&
              'error' in data &&
              typeof data.error === 'string'
              ? data.error
              : 'Unable to load the worksheet.',
          );
        const parsed = await parseBodyReviewResponse(data, selected);
        if (!parsed) throw new Error('Unexpected worksheet. Please retry.');
        if (current) setMaterial(parsed);
      })
      .catch((e) => {
        if (current && !controller.signal.aborted)
          setError(
            e instanceof Error ? e.message : 'Unable to load the worksheet.',
          );
      })
      .finally(() => {
        if (current) setLoading(false);
      });
    return () => {
      current = false;
      controller.abort();
    };
  }, [selected, attempt]);
  function resetSelection() {
    setDirty(false);
    setPage(0);
    setSelected(null);
    setMaterial(null);
    setError('');
  }
  return (
    <div
      className="body-review-app"
      onClickCapture={(event) => {
        const anchor = (event.target as Element).closest('a');
        if (
          !anchor ||
          anchor.target === '_blank' ||
          anchor.hasAttribute('download') ||
          anchor.getAttribute('href')?.startsWith('/api/atlas-review/body-review')
        )
          return;
        if (!canLeave()) {
          event.preventDefault();
          event.stopPropagation();
        }
      }}
    >
      <header className="body-review-header">
        <Brand />
        <span>Body review workspace</span>
        <Link href="/workspace/atlas-review">Clinical review home</Link>
        <Link href="/atlas">Back to atlas</Link>
      </header>
      <main className="body-review-shell">
        <h1>Review the wider body</h1>
        <p>
          Source details and current teaching for {rows.length.toLocaleString()}{' '}
          body selections. Keep private, versioned corrections and review
          records without adding controls to the learner's atlas.
        </p>
        <div className="body-review-grid">
          <aside className="body-review-queue" aria-label="Body review queue">
            <label htmlFor="body-review-query">Find a structure</label>
            <Input
              id="body-review-query"
              value={query}
              maxLength={256}
              placeholder="Name or anatomical ID"
              onChange={(e) => {
                if (!canLeave()) return;
                setQuery(e.target.value);
                resetSelection();
              }}
            />
            <label id="body-review-region-label">Region</label>
            <Select
              value={region}
              onValueChange={(v) => {
                if (v && canLeave()) {
                  setRegion(v);
                  resetSelection();
                }
              }}
            >
              <SelectTrigger aria-labelledby="body-review-region-label">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All regions</SelectItem>
                {regions.map((r) => (
                  <SelectItem value={r.id} key={r.id}>
                    {r.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <label id="body-review-system-label">System</label>
            <Select
              value={system}
              onValueChange={(v) => {
                if (v && canLeave()) {
                  setSystem(v);
                  resetSelection();
                }
              }}
            >
              <SelectTrigger aria-labelledby="body-review-system-label">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All systems</SelectItem>
                {Object.entries(bodySystems).map(([id, s]) => (
                  <SelectItem value={id} key={id}>
                    {s.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <p role="status">{matches.length} matching selections</p>
            <ul>
              {visible.map((s) => (
                <li key={s.id}>
                  <Button
                    variant={selected === s.id ? 'secondary' : 'ghost'}
                    aria-pressed={selected === s.id}
                    onClick={() => selectStructure(s.id)}
                  >
                    {s.name}
                    <small>
                      {s.fmaId} · {s.laterality}
                    </small>
                  </Button>
                </li>
              ))}
            </ul>
            {!matches.length && <p>No matches. Try another region or name.</p>}
            <nav aria-label="Review queue pages">
              <Button
                variant="outline"
                disabled={currentPage === 0}
                onClick={() => setPage(currentPage - 1)}
              >
                Previous
              </Button>
              <span>
                {matches.length ? currentPage + 1 : 0} /{' '}
                {Math.ceil(matches.length / 20)}
              </span>
              <Button
                variant="outline"
                disabled={(currentPage + 1) * 20 >= matches.length}
                onClick={() => setPage(currentPage + 1)}
              >
                Next
              </Button>
            </nav>
          </aside>
          <section
            className="body-review-paper"
            aria-label="Selected review worksheet"
            aria-busy={loading}
          >
            <nav
              className="body-review-structure-navigation"
              aria-label="Structures in the filtered review queue"
            >
              <Button
                variant="outline"
                disabled={!previousStructure}
                onClick={() => {
                  if (previousStructure) selectStructure(previousStructure.id);
                }}
              >
                Previous structure
              </Button>
              <p role="status" aria-atomic="true">
                {selectedIndex >= 0
                  ? `Structure ${selectedIndex + 1} of ${matches.length} in the filtered queue`
                  : selected
                    ? 'Selected structure is outside the filtered queue'
                    : 'No structure selected'}
              </p>
              <Button
                variant="outline"
                disabled={!nextStructure}
                onClick={() => {
                  if (nextStructure) selectStructure(nextStructure.id);
                }}
              >
                Next structure
              </Button>
            </nav>
            {loading && (
              <p role="status">Loading the selected source and teaching…</p>
            )}
            {error && (
              <div role="alert">
                <p>{error}</p>
                <Button
                  variant="outline"
                  onClick={() => setAttempt((n) => n + 1)}
                >
                  Retry
                </Button>
                <p>
                  <ReviewSignInLink target={{ scope: 'body', structure: selected }}>
                    Sign in to the review workspace
                  </ReviewSignInLink>
                  . No review decision has been saved.
                </p>
              </div>
            )}
            {!selected && (
              <p>Choose a structure to inspect its source and teaching.</p>
            )}
            {material?.structureId === selected && (
              <div className="body-review-selected">
                <ReviewModelPreview
                  key={material.materialHash}
                  href={material.atlasLink}
                  name={material.source.structure.name}
                  revision={material.materialHash}
                />
                <div className="body-review-worksheet">
                <BodyReviewDetails material={material} />
                <BodyDecisionEditor
                  key={`${material.structureId}-${material.materialHash}`}
                  id={material.structureId}
                  materialHash={material.materialHash}
                  onDirty={setDirty}
                />
                </div>
              </div>
            )}
          </section>
        </div>
      </main>
    </div>
  );
}

export function BodyReviewDetails({
  material,
}: {
  material: BodyReviewMaterial;
}) {
  const s = material.source.structure;
  return (
    <>
      <h2>{s.name}</h2>
      <p>
        {s.fmaId} · {s.laterality} · {s.sources.length} source parts
      </p>
      <div className="body-review-actions">
        {material.atlasLink && (
          <a href={reviewModelHref(material.atlasLink)} target="_blank" rel="noopener noreferrer">
            Open this model in a separate tab
          </a>
        )}
        <a
          href={`/api/atlas-review/body-review?structure=${encodeURIComponent(s.id)}&download=1`}
        >
          Download review worksheet
        </a>
      </div>
      {s.coverageNote && (
        <p className="body-review-caution">{s.coverageNote}</p>
      )}
      <details>
        <summary>Source & scope</summary>
        <p>{material.source.credit}</p>
        <p>
          {material.source.licence} · source version{' '}
          {material.source.sourceVersion} · {s.sourceTree}
        </p>
        <code>{s.id}</code>
        <p>Canonical model checksum</p>
        <code>{material.source.bundle.sha256}</code>
        <p>Worksheet material fingerprint (not an approval or signature)</p>
        <code>{material.materialHash}</code>
        {s.presentationParts && <details>
          <summary>Source-file display parts · not separate FMA identities</summary>
          <p>Both sides uses the complete group. Unilateral views use only the corresponding original file. Verify this mapping and its displayed bounds before sign-off.</p>
          <ul>{s.presentationParts.map(p => <li key={p.nodeName}>
            {p.displaySide} display · {p.source.file} · node <code>{p.nodeName}</code>
            <code>{p.source.sha256}</code>
            <p>Scene bounds: {p.bounds.min.join(', ')} to {p.bounds.max.join(', ')}. Label anchor: {p.anchor.join(', ')}.</p>
          </li>)}</ul>
        </details>}
        <ul>
          {s.sources.map((p) => (
            <li key={p.file}>
              {p.file}
              <code>{p.sha256}</code>
            </li>
          ))}
        </ul>
        <ul>
          {material.limits.map((limit) => (
            <li key={limit}>{limit}</li>
          ))}
        </ul>
      </details>
      <h3>Current teaching</h3>
      <p>
        Readiness describes available copy, not clinical approval. Expand a
        topic to review it.
      </p>
      {material.topics.map((topic) => (
        <details key={topic.tab}>
          <summary>
            {labels[topic.tab]} <span>{readiness[topic.readiness]}</span>
          </summary>
          <h4>{topic.title}</h4>
          <p>{topic.body}</p>
          {topic.bullets && (
            <ul>
              {topic.bullets.map((b, i) => (
