    const url = URL.createObjectURL(blob),
      a = document.createElement('a');
    a.href = url;
    a.download = 'visible-medicine-shoulder-reviews.json';
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
