      setBusy(false);
    }
  }
  const problems = specimenApprovalProblems(draft, c, track);
  return (
    <div className="specimen-decision">
      <p aria-live="polite">
        {page
          ? specimenDecisionLabel(page.history[0], c)
          : "Private history not loaded"}
      </p>
      {page && <ReviewChangeNotice change={specimenReviewChanges(page.history[0], c, track)} />}
      {error && <p role="alert">{error}</p>}
      {!page && error && <p><ReviewSignInLink target={{ scope: 'specimens',
        specimen: c.specimenKey, structure: c.structureId }} /></p>}
      {message && <p role="status">{message}</p>}
      <div className="specimen-review-actions">
        <Button variant="outline" disabled={busy} onClick={refresh}>
          Refresh saved history
        </Button>
        <Button
          variant="outline"
          onClick={() =>
            download(
              {
                kind: "unsaved-specimen-review-draft",
                approval: false,
                context: c,
                track,
                draft,
              },
              "specimen-review-draft.json",
            )
          }
        >
          Export my edits
        </Button>
      </div>
      {reconcile && (
        <p>
          <Button
            variant="outline"
            disabled={busy || !page || needsRefresh}
            onClick={() => {
              if (
                window.confirm(
                  "Replace your unsaved edits with the latest loaded saved draft? Export first if needed.",
                )
              ) {
                setDraft(specimenDraftFromSaved(page?.history[0], c, track));
                setDirty(false);
                setReconcile(false);
                setMessage(
                  "Saved draft loaded. Review it before saving again.",
                );
              }
            }}
          >
            Load saved draft after comparing
          </Button>
        </p>
      )}
      <fieldset disabled={busy || !page}>
        <legend>{titles[track]} checklist</legend>
        {c.checklists[track].map((item) => (
          <label className="specimen-check" key={item.id}>
            <input
              type="checkbox"
              checked={draft.checks[item.id]}
              onChange={(e) =>
                edit({
                  checks: { ...draft.checks, [item.id]: e.target.checked },
                })
              }
            />
            {item.label}
          </label>
        ))}
        {(["reviewer", "qualification", "scope", "notes"] as const).map((k) => (
          <label className="specimen-field" key={k}>
            {
              {
                reviewer: "Your name",
                qualification: "Professional role / qualification",
                scope: "Exact scope reviewed",
                notes: "Notes (do not enter patient information)",
              }[k]
            }
            <textarea
              value={draft[k]}
              maxLength={
                { reviewer: 150, qualification: 200, scope: 2000, notes: 6000 }[
                  k
                ]
              }
              rows={k === "notes" ? 3 : 2}
              onChange={(e) => edit({ [k]: e.target.value })}
            />
          </label>
        ))}
        <h3>Supporting evidence</h3>
        {draft.evidence.map((e, index) => (
          <div key={index} className="specimen-evidence">
            {(["title", "url", "note"] as const).map((k) => (
              <label key={k}>
                {k === "url"
                  ? "HTTPS reference URL"
                  : k === "title"
                    ? "Reference title"
                    : "What this supports"}
                <Input
                  value={e[k]}
                  maxLength={{ title: 180, url: 2048, note: 1000 }[k]}
                  onChange={(event) =>
                    edit({
                      evidence: draft.evidence.map((v, n) =>
                        n === index ? { ...v, [k]: event.target.value } : v,
                      ),
                    })
                  }
                />
              </label>
            ))}
            <Button
              variant="outline"
              onClick={() =>
                edit({ evidence: draft.evidence.filter((_, n) => n !== index) })
              }
            >
              Remove reference
            </Button>
          </div>
        ))}
        <Button
          variant="outline"
          disabled={draft.evidence.length >= 12}
          onClick={() =>
            edit({
              evidence: [...draft.evidence, { title: "", url: "", note: "" }],
            })
          }
        >
          Add evidence
        </Button>
        <details>
          <summary>Corrections &amp; issues ({draft.issues.length})</summary>
          {draft.issues.map((issue, index) => {
            const update = (patch: Partial<typeof issue>) =>
              edit({
                issues: draft.issues.map((v, n) =>
                  n === index ? { ...v, ...patch } : v,
                ),
              });
            return (
              <div className="specimen-evidence" key={issue.id}>
                <label>
                  Correction
                  <Input
                    value={issue.title}
                    maxLength={500}
                    onChange={(e) => update({ title: e.target.value })}
                  />
                </label>
                <label>
                  Severity
                  <Select
                    value={issue.severity}
                    onValueChange={(v) =>
                      update({ severity: v as typeof issue.severity })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {["blocker", "major", "minor"].map((v) => (
                        <SelectItem key={v} value={v}>
                          {v}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </label>
                <label className="specimen-check">
                  <input
                    type="checkbox"
                    checked={issue.resolved}
                    onChange={(e) => update({ resolved: e.target.checked })}
                  />
                  Resolved
                </label>
                <label>
                  Resolution explanation
                  <Input
                    value={issue.resolution}
                    maxLength={1500}
                    onChange={(e) => update({ resolution: e.target.value })}
                  />
                </label>
              </div>
            );
          })}
          <Button
            variant="outline"
            disabled={draft.issues.length >= 20}
            onClick={() =>
              edit({
                issues: [
                  ...draft.issues,
                  {
                    id: crypto.randomUUID(),
                    title: "",
                    severity: "major",
                    resolved: false,
                    resolution: "",
                  },
                ],
              })
            }
          >
            Add correction
          </Button>
          <p>
            Saved issues are retained, not deleted; resolve them with an
            explanation.
          </p>
        </details>
        <label className="specimen-field">
          Decision
          <Select
            value={draft.status}
            onValueChange={(v) =>
              edit({ status: v as SpecimenReviewDraft["status"] })
            }
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="draft">In progress</SelectItem>
              <SelectItem value="changes-required">Changes required</SelectItem>
              <SelectItem
                value="approved"
                disabled={!!c.blockers[track].length || !c.revisions[track]}
              >
                Record approval
              </SelectItem>
            </SelectContent>
          </Select>
        </label>
        <label className="specimen-check">
          <input
            type="checkbox"
            checked={draft.attested}
            onChange={(e) => edit({ attested: e.target.checked })}
          />
          I personally reviewed this exact specimen and revision within the
          scope stated above.
        </label>
        {!!problems.length && (
          <details
            open={draft.status === "approved" || !!c.blockers[track].length}
          >
            <summary>Before approval ({problems.length})</summary>
            <ul>
              {problems.map((p, i) => (
                <li key={i}>{p}</li>
              ))}
            </ul>
          </details>
        )}
        <Button
          onClick={save}
          disabled={
            !dirty ||
            reconcile ||
            (draft.status === "approved" && !!problems.length)
          }
        >
          Save private review
        </Button>
      </fieldset>
      <details>
        <summary>Saved version history</summary>
        {history?.history.map((r) => (
          <details key={r.version}>
            <summary>
              Version {r.version} · {r.status} · {r.savedAt}
            </summary>
            <p>
              {r.reviewer} · {r.qualification}
            </p>
            <p>{r.scope}</p>
            <p>{r.notes}</p>
            <Button
              variant="outline"
              onClick={() => download(r, `specimen-review-v${r.version}.json`)}
            >
              Export this saved record
            </Button>
            <pre>
              {JSON.stringify(
                {
                  checks: r.checks,
                  evidence: r.evidence,
                  issues: r.issues,
                  revision: r.revisionHash,
                },
                null,
                2,
              )}
            </pre>
          </details>
        ))}
        {!!history?.nextBefore && (
          <Button
            variant="outline"
            disabled={busy}
            onClick={async () => {
              if (busy) return;
              const controller = beginRead();
              setBusy(true);
              try {
                const previous = await read(history.nextBefore!, controller.signal);
                if (!controller.signal.aborted) setHistory(previous);
              } catch (e) {
                if (!controller.signal.aborted) setError((e as Error).message);
              } finally {
                if (!controller.signal.aborted) setBusy(false);
              }
            }}
          >
            Older records
          </Button>
        )}
      </details>
      <p>
        <small>
          Records belong to the signed-in account. Entered qualifications are
          self-declared, not credential verification. This does not release or
          certify the entire atlas.
        </small>
      </p>
    </div>
  );
}

'use client';

import {
  createContext,
  useCallback,
  useContext,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
  type RefObject,
} from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { Html } from '@react-three/drei';
import { Group, Vector3 } from 'three';
import { createLabelDepthProbe, coveredLabelDescription } from '@/atlas-review/lib/label-depth';
import { navigateSceneLabels, returnHiddenLabelFocus } from '@/atlas-review/lib/scene-label-focus';
import { selectedLabelNeedsCompact } from '@/atlas-review/lib/scene-label-size';
import {
  layoutScreenLabels,
  projectLabelAnchor,
  screenLabelMaxWidth,
  type ScreenLabel,
} from '@/atlas-review/lib/screen-label-layout';
import './scene-label-layer.css';

type Entry = {
  id: string;
  name: string;
  selected: boolean;
  priority: number;
  anchor: RefObject<Group | null>;
  onSelect: (id: string) => void;
};
const LabelContext = createContext<((entry: Entry) => () => void) | null>(null);
const overlayOrigin = () => [0, 0];
// Html's origin is not an anatomical anchor. Visibility is handled individually
// using the real anchors, including when panning places world origin behind us.
const managedVisibility = () => {};

export function SceneLabel({
  id,
  name,
  selected,
  priority = 0,
  position,
  onSelect,
}: {
  id: string;
  name: string;
  selected: boolean;
  priority?: number;
  position: [number, number, number];
  onSelect: (id: string) => void;
}) {
  const register = useContext(LabelContext);
  const anchor = useRef<Group>(null);
  useLayoutEffect(
    () => register?.({ id, name, selected, priority, anchor, onSelect }),
    [register, id, name, selected, priority, onSelect],
  );
  // Parenting this empty group under the tissue's displaced group applies every
  // transform exactly once without moving source geometry or anatomical IDs.
  return <group ref={anchor} position={position} />;
}

export function SceneLabelLayer({ children }: { children: ReactNode }) {
  const [entries, setEntries] = useState<Entry[]>([]);
  const invalidate = useThree((state) => state.invalidate);
  const size = useThree((state) => state.size);
  const canvas = useThree((state) => state.gl.domElement);
  const buttons = useRef(new Map<string, HTMLButtonElement>());
  const lines = useRef(new Map<string, SVGPathElement>());
  const points = useRef(new Map<string, SVGCircleElement>());
  const resizeObserver = useRef<ResizeObserver | null>(null);
  const world = useMemo(() => new Vector3(), []);
  const probeDepth = useMemo(createLabelDepthProbe, []);
  const depthFrame = useRef({ last: -Infinity, timer: null as ReturnType<typeof setTimeout> | null });
  useLayoutEffect(() => () => {
    if (depthFrame.current.timer !== null) clearTimeout(depthFrame.current.timer);
  }, []);
  const register = useCallback((entry: Entry) => {
    setEntries((current) => [
      ...current.filter((item) => item.id !== entry.id),
      entry,
    ]);
    return () =>
      setEntries((current) => current.filter((item) => item !== entry));
  }, []);
  useLayoutEffect(() => {
    const observer = new ResizeObserver(() => invalidate());
    resizeObserver.current = observer;
    for (const button of buttons.current.values()) observer.observe(button);
    invalidate();
    return () => {
      observer.disconnect();
      resizeObserver.current = null;
    };
  }, [entries, size.width, size.height, invalidate]);

  useFrame(({ camera, scene }) => {
    camera.updateMatrixWorld();
    // At most ten selected-anchor probes per second, with one trailing demand
    // frame so the final orbit/opacity/cut state cannot retain an old result.
    const selected = entries.find(entry => entry.selected && entry.anchor.current?.parent);
    for (const entry of entries) if (entry !== selected) {
      const button = buttons.current.get(entry.id), line = lines.current.get(entry.id);
      if (line) line.dataset.depth = '';
      if (button) {
        button.dataset.depth = '';
        button.setAttribute('aria-description', '');
      }
    }
    const now = performance.now();
    if (selected && now - depthFrame.current.last >= 100) {
      depthFrame.current.last = now;
      if (depthFrame.current.timer !== null) clearTimeout(depthFrame.current.timer);
      depthFrame.current.timer = null;
      scene.updateMatrixWorld(true);
      const anchor = selected.anchor.current!;
      anchor.getWorldPosition(world);
      const depth = probeDepth(scene, camera, world, anchor.parent!);
      for (const entry of entries) {
        const button = buttons.current.get(entry.id), line = lines.current.get(entry.id);
        if (!button || !line) continue;
        const covered = entry === selected && depth === 'covered';
        button.dataset.depth = covered ? 'covered' : '';
        line.dataset.depth = covered ? 'covered' : '';
        button.setAttribute('aria-description', covered ? coveredLabelDescription : '');
      }
    } else if (selected && depthFrame.current.timer === null) {
      depthFrame.current.timer = setTimeout(() => {
        depthFrame.current.timer = null;
        invalidate();
      }, Math.max(1, 101 - (now - depthFrame.current.last)));
    }
    const projected: ScreenLabel[] = [];
    const projectedPoints = new Map<string, { x: number; y: number }>();
    for (const entry of entries) {
      const anchor = entry.anchor.current,
        button = buttons.current.get(entry.id);
      if (!anchor || !button) continue;
      anchor.getWorldPosition(world);
      const point = projectLabelAnchor(world, camera, size.width, size.height);
      if (point) {
        projectedPoints.set(entry.id, point);
        // Read the full name from an off-layout span. Compacting the displayed
        // text cannot change this measurement and cause ResizeObserver churn.
        button.dataset.compact = entry.selected &&
          selectedLabelNeedsCompact(button, size.height - 20)
          ? 'true' : 'false';
        projected.push({
          ...point,
          id: entry.id,
          selected: entry.selected,
          priority: entry.priority,
          width: button.offsetWidth,
          height: button.offsetHeight,
        });
      } else button.dataset.compact = 'false';
    }
    const placements = new Map(
      layoutScreenLabels(projected, size.width, size.height).map((label) => [
        label.id,
        label,
      ]),
    );
    for (const entry of entries) {
      const button = buttons.current.get(entry.id),
        line = lines.current.get(entry.id),
        point = points.current.get(entry.id);
      if (!button || !line || !point) continue;
      const label = placements.get(entry.id);
      // Set the tooltip after the current compact/depth decisions, not one
      // demand frame later. The accessible name always remains unshortened.
      button.title = button.dataset.depth === 'covered'
        ? `${entry.name} — ${coveredLabelDescription}`
        : button.dataset.compact === 'true' ? entry.name : '';
      const projectedPoint = projectedPoints.get(entry.id);
      if (projectedPoint) {
        point.setAttribute('cx', String(projectedPoint.x));
        point.setAttribute('cy', String(projectedPoint.y));
      }
      if (!label) returnHiddenLabelFocus(button, canvas);
      button.style.visibility =
        line.style.visibility =
        point.style.visibility =
          label ? 'visible' : 'hidden';
      button.disabled = !label;
      if (!label) continue;
      button.dataset.side = label.side;
      button.style.transform = `translate(${label.left}px, ${label.top}px)`;
      line.setAttribute(
        'd',
        label.leader.map((point, index) =>
          `${index ? 'L' : 'M'} ${point.x} ${point.y}`,
        ).join(' '),
      );
    }
  });

  return (
    <LabelContext.Provider value={register}>
      {children}
      <Html
        calculatePosition={overlayOrigin}
        onOcclude={managedVisibility}
        zIndexRange={[3, 1]}
        style={{
          width: size.width,
          height: size.height,
          pointerEvents: 'none',
        }}
      >
        <div
          className="scene-label-overlay"
          role="group"
          aria-label="Anatomical structure labels"
          aria-description="Use arrow keys to move between visible labels, Home or End within a side, and Enter or Space to select."
        >
          <svg
            width={size.width}
            height={size.height}
            aria-hidden="true"
            className="scene-label-leaders"
          >
            {entries.map((entry) => (
              <g
                key={entry.id}
                className={entry.selected ? 'selected' : undefined}
              >
                <path
                  ref={(node) => {
                    if (node) {
                      lines.current.set(entry.id, node);
                      invalidate();
                    } else lines.current.delete(entry.id);
                  }}
                />
                <circle
                  r="2.2"
                  ref={(node) => {
                    if (node) {
                      points.current.set(entry.id, node);
                      invalidate();
                    } else points.current.delete(entry.id);
                  }}
                />
              </g>
            ))}
          </svg>
          {entries.map((entry) => (
            <button
              key={entry.id}
              type="button"
              aria-current={entry.selected ? 'true' : undefined}
              aria-label={entry.name}
              aria-keyshortcuts="ArrowUp ArrowDown ArrowLeft ArrowRight Home End"
              ref={(node) => {
                const previous = buttons.current.get(entry.id);
                if (previous) resizeObserver.current?.unobserve(previous);
                if (node) {
                  buttons.current.set(entry.id, node);
                  resizeObserver.current?.observe(node);
                  invalidate();
                } else buttons.current.delete(entry.id);
              }}
              className={`scene-label${entry.selected ? ' selected' : ''}`}
              // Grow with the actual label font, not device width or a guessed
              // zoom setting. Measured layout still enforces screen-side bounds.
              style={{ maxWidth: `min(${screenLabelMaxWidth(size.width, 2)}px, max(${screenLabelMaxWidth(size.width)}px, 7em))` }}
              onPointerDown={(event) => event.stopPropagation()}
              onPointerUp={(event) => event.stopPropagation()}
              onDoubleClick={(event) => event.stopPropagation()}
              onKeyDown={(event) => {
                if (!event.nativeEvent.isComposing)
                  navigateSceneLabels(event, event.currentTarget, buttons.current.values());
              }}
              onClick={(event) => {
                event.stopPropagation();
                entry.onSelect(entry.id);
              }}
            >
              <span className="scene-label-name">{entry.name}</span>
              <span className="scene-label-measure-clip" aria-hidden="true">
                <span className="scene-label-measure">{entry.name}</span>
              </span>
              <span className="scene-label-depth" aria-hidden="true">Behind tissue</span>
            </button>
          ))}
        </div>
      </Html>
    </LabelContext.Provider>
  );
}

'use client';
/* oxlint-disable react/react-compiler -- A frame callback synchronizes a read-only DOM label with the imperative camera. */
import { useLayoutEffect, useMemo, useRef, type RefObject } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { Vector3 } from 'three';
import type { SourceCoordinates } from '@/atlas-review/lib/anatomy-coordinates';
import { cameraOrientation, orientationBasis, orientationText, type OrientationCode } from '@/atlas-review/lib/camera-orientation';

/** No extra animation loop, camera writes or React frame updates. The visual
 * label stays silent; the accessible direction changes only with the pose.
 * SceneRecovery hides this whole view when the renderer fails. */
export function SceneOrientation({ output, statusOutput, keyboardCameraFrom, coordinates, enabled }: {
  output: RefObject<HTMLSpanElement | null>;
  statusOutput?: RefObject<HTMLOutputElement | null>;
  keyboardCameraFrom?: RefObject<Vector3 | null>;
  coordinates: SourceCoordinates;
  enabled: boolean;
}) {
  const basis = useMemo(() => orientationBasis(coordinates), [coordinates]);
  const from = useMemo(() => new Vector3(), []);
  const previous = useRef<OrientationCode[]>([]);
  const invalidate = useThree((state) => state.invalidate);
  useLayoutEffect(() => {
    previous.current = [];
    if (output.current) output.current.textContent = 'unavailable';
    if (keyboardCameraFrom) keyboardCameraFrom.current = null;
    if (statusOutput?.current?.textContent)
      statusOutput.current.textContent = 'View from: unavailable.';
    invalidate();
  }, [basis, enabled, output, statusOutput, keyboardCameraFrom, invalidate]);
  useFrame(({ camera }) => {
    const node = output.current;
    if (!enabled || !node) return;
    camera.getWorldDirection(from).negate();
    const codes = cameraOrientation(from, basis, previous.current);
    previous.current = codes;
    const text = orientationText(codes);
    if (node.textContent !== text) node.textContent = text;
    const status = statusOutput?.current;
    if (!status) return;
    const keyboardFrom = keyboardCameraFrom?.current;
    if (keyboardFrom && from.distanceToSquared(keyboardFrom) <= 1e-8) return;
    if (keyboardCameraFrom) keyboardCameraFrom.current = null;
    // An orbit gesture or preset invalidates keyboard-only angle details. Keep
    // the accessible direction in step with the actual camera, without a DOM
    // write or live announcement on every rendered frame.
    const statusText = `View from: ${text}.`;
    if (status.textContent !== statusText) status.textContent = statusText;
  });
  return null;
}

'use client';
import {
  Component,
  Fragment,
  createRef,
  useLayoutEffect,
  type ReactNode,
  type RefObject,
} from 'react';
import { useThree } from '@react-three/fiber';
import { Button } from '@/atlas-review/components/ui/button';
import {
  copyRecoveryCamera,
  observeRenderer,
  guardRenderer,
  type RendererHealth,
} from '@/atlas-review/lib/renderer-health';
import type { StudyCamera } from '@/atlas-review/lib/study-views';
import './scene-recovery.css';

export function RendererMonitor({
  onHealth,
}: {
  onHealth: (health: RendererHealth) => void;
}) {
  const { gl, invalidate } = useThree();
  useLayoutEffect(() => {
    const current = observeRenderer(
      gl.domElement,
      () => gl.getContext().isContextLost(),
      onHealth,
      invalidate,
    );
    const guard = guardRenderer(gl, current.fail, current.frame);
    return () => {
      guard.dispose();
      current.dispose();
    };
  }, [gl, invalidate, onHealth]);
  return null;
}

export function SceneRecoveryNotice({
  health,
  onRetry,
}: {
  health: RendererHealth;
  onRetry: () => void;
}) {
  if (health === 'ready') return null;
  const title =
    health === 'starting'
      ? 'Starting the 3D view…'
      : health === 'restoring'
        ? 'Restoring the 3D view…'
        : health === 'lost'
          ? 'The 3D view was interrupted'
          : 'The 3D view could not continue';
  return (
    <output
      className="vm-scene-recovery-notice"
      aria-live="polite"
      aria-atomic="true"
    >
      <strong>{title}</strong>
      <span className="vm-scene-recovery-detail">
        Your dissection settings and answers are retained. Practice waits until
        the model is available.
      </span>
      <Button type="button" variant="outline" onClick={onRetry}>
        Restart 3D view
      </Button>
      <small>
        If it still cannot start, try a browser with 3D graphics enabled.
        Structure information remains available outside the view.
      </small>
    </output>
  );
}

type Props = {
  className: string;
  cameraKey: string;
  children: (
    onHealth: (health: RendererHealth) => void,
    autoRecoveryCamera: RefObject<StudyCamera | null>,
    cameraTransitionActive: RefObject<boolean>,
  ) => ReactNode;
  onHealth: (health: RendererHealth) => void;
  cameraCapture?: RefObject<StudyCamera | null>;
  cameraRestore?: RefObject<StudyCamera | null>;
};
type State = { health: RendererHealth; attempt: number };
/** DOM recovery UI survives a stopped canvas. Anatomy and study state stay above it. */
export class SceneRecovery extends Component<Props, State> {
  state: State = { health: 'starting', attempt: 0 };
  private alive = true;
  private generation = 0;
  private terminalFailure = false;
  private lastReadyCameraKey: string | null = null;
  private returnFocus = false;
  private container = createRef<HTMLElement>();
  private autoRecoveryCamera: RefObject<StudyCamera | null> = { current: null };
  private queuedRecoveryCamera: RefObject<StudyCamera | null> = { current: null };
  private cameraTransitionActive: RefObject<boolean> = { current: false };
  private clearAutoRecovery() {
    const queued = this.queuedRecoveryCamera.current;
    if (queued && this.props.cameraRestore?.current === queued)
      this.props.cameraRestore.current = null;
    this.autoRecoveryCamera.current = null;
    this.queuedRecoveryCamera.current = null;
  }
  static getDerivedStateFromError(): Partial<State> {
    return { health: 'failed' };
  }
  componentDidMount() {
    this.alive = true;
    this.props.onHealth(this.terminalFailure ? 'failed' : 'starting');
  }
  componentDidCatch() {
    this.terminalFailure = true;
    this.props.onHealth('failed');
  }
  componentWillUnmount() {
    this.clearAutoRecovery();
    this.alive = false;
  }
  componentDidUpdate(previousProps: Props, previous: State) {
    if (previousProps.cameraKey !== this.props.cameraKey)
      this.clearAutoRecovery();
    if (this.state.health === 'ready')
      this.lastReadyCameraKey = this.props.cameraKey;
    if (
      previous.health !== 'ready' &&
      this.state.health === 'ready' &&
      this.returnFocus
    ) {
      this.returnFocus = false;
      const element = this.container.current;
      if (
        element &&
        (document.activeElement === document.body ||
          element.contains(document.activeElement))
      )
        element.focus({ preventScroll: true });
    }
  }
  private updateHealth = (generation: number, health: RendererHealth) => {
    if (
      !this.alive ||
      this.terminalFailure ||
      generation !== this.generation ||
      this.state.health === 'failed'
    )
      return;
    if (health === 'failed') this.terminalFailure = true;
    this.props.onHealth(health);
    if (health === 'ready') this.lastReadyCameraKey = this.props.cameraKey;
    this.setState({ health });
  };
  report = (health: RendererHealth) => this.updateHealth(0, health);
  retry = () => {
    if (!this.alive || this.state.health === 'ready') return;
    if (this.lastReadyCameraKey !== this.props.cameraKey)
      this.clearAutoRecovery();
    else if (
      this.queuedRecoveryCamera.current &&
      this.props.cameraRestore?.current !== this.queuedRecoveryCamera.current
    ) {
      this.autoRecoveryCamera.current = null;
      this.queuedRecoveryCamera.current = null;
    }
    // An explicitly queued saved-view camera takes precedence over the last orbit.
    if (
      this.props.cameraRestore &&
      !this.props.cameraRestore.current &&
      this.lastReadyCameraKey !== null &&
      this.lastReadyCameraKey === this.props.cameraKey
    ) {
      const copied = copyRecoveryCamera(
        this.props.cameraCapture?.current ?? null,
      );
      this.props.cameraRestore.current = copied;
      this.queuedRecoveryCamera.current = copied;
      this.autoRecoveryCamera.current = this.cameraTransitionActive.current
        ? copied : null;
    }
    this.returnFocus = true;
    const generation = ++this.generation;
    this.terminalFailure = false;
    this.report = (health: RendererHealth) =>
      this.updateHealth(generation, health);
    this.props.onHealth('starting');
    this.setState({ health: 'starting', attempt: generation });
  };
  render() {
    const ready = this.state.health === 'ready';
    return (
      <section
        ref={this.container}
        className={this.props.className + ' vm-scene-recovery'}
        data-health={this.state.health}
        tabIndex={-1}
        aria-label="Interactive 3D anatomy"
      >
        <div
          className="vm-scene-recovery-viewport"
          inert={!ready}
          aria-hidden={!ready}
        >
          {this.state.health !== 'failed' && (
            <Fragment key={this.state.attempt}>
              {this.props.children(this.report, this.autoRecoveryCamera, this.cameraTransitionActive)}
            </Fragment>
          )}
        </div>
        <SceneRecoveryNotice health={this.state.health} onRetry={this.retry} />
      </section>
    );
  }
}

'use client';
import { Button } from '@/atlas-review/components/ui/button';
import type { SelectionVisibility } from '@/atlas-review/lib/selection-visibility';
import './selection-visibility.css';

export function SelectionVisibilityNotice({
  name,
  report,
  onRecover,
  onReapply,
}: {
  name: string;
  report: SelectionVisibility | null;
  onRecover: () => void;
  onReapply: () => void;
}) {
  if (!report || (!report.reasons.length && !report.uncut)) return null;
  return (
    <div className="vm-selection-visibility">
      <output aria-live="polite" aria-atomic="true">
        <strong>{name}</strong>
        <span>
          {report.reasons.length
            ? report.reasons.join(' · ')
            : 'Selected structure kept uncut; other structures still follow the cutaway.'}
        </span>
      </output>
      <Button
        size="sm"
        variant="outline"
        onClick={report.reasons.length ? onRecover : onReapply}
      >
        {report.reasons.length ? 'Reveal selection' : 'Reapply cutaway'}
      </Button>
    </div>
  );
}

