export default function ShoulderExplorer({
  initialSelectedId = structures[0].id,
  presentation = 'standalone',
  assetBase = '',
  connectedReviews = true,
}: {
  initialSelectedId?: string;
  presentation?: 'standalone' | 'panel';
  assetBase?: string;
  connectedReviews?: boolean;
}) {
  const Title = presentation === 'panel' ? 'h2' : 'h1';
  const [selectedId, setSelectedId] = useState(initialSelectedId);
  const [rendererHealth, setRendererHealth] =
    useState<RendererHealth>('starting');
  const [modelReady, setModelReady] = useState(false);
  const rendererHealthRef = useRef<RendererHealth>('starting');
  const modelReadyRef = useRef(false);
  const examReadyRef = useRef(false);
  const displayReady = rendererReady(rendererHealth) && modelReady;
  const [view, setView] = useState<CameraView>('posterior');
  const [layer, setLayer] = useState<AnatomyLayer>('surface');
  const [zoom, setZoom] = useState(1);
  const [zoomStep, setZoomStep] = useState(0);
  const [visibleSystems, setVisibleSystems] = useState<
    Record<SystemKey, boolean>
  >({ skeleton: true, muscles: true, 'soft-tissue': true });
  const [isolated, setIsolated] = useState(false);
  const [explode, setExplode] = useState(0);
  const [layout, setLayout] = useState<BodyLayout>('spatial');
  const [anchorSkeleton, setAnchorSkeleton] = useState(false);
  const [showOrigins, setShowOrigins] = useState(false);
  const [plate, setPlate] = useState(false);
  const [inspection, setInspection] = useState(initialInspection);
  const cameraCapture = useRef<StudyCamera | null>(null);
  const cameraRestore = useRef<StudyCamera | null>(null);
  const [showLabels, setShowLabels] = useState(true);
  const [syncPlane, setSyncPlane] = useState(false);
  const [resetNonce, setResetNonce] = useState(0);
  const [mode, setMode] = useState<Mode>('study');
  const beforeExam = useRef<{ view: StudyView; zoomStep: number } | null>(null);
  const [tourIndex, setTourIndex] = useState<number | null>(null);
  const [guidedLearning, setGuidedLearning] = useState(false);
  const [tourPlaying, setTourPlaying] = useState(false);
  const [tourContinuous, setTourContinuous] = useState(false);
  const [tourRate, setTourRate] = useState<GuidedPlaybackRate>(1);
  const [tourMotionPaused, setTourMotionPaused] = useState(false);
  const [reducedMotion, setReducedMotion] = useState(false);
  const beforeTour = useRef<{ view: StudyView; zoomStep: number } | null>(null);
  const tourActiveRef = useRef(false);
  const tourPlaybackEpoch = useRef(0);
  const tourControls = useRef<HTMLDivElement>(null);
  const tourHadFocus = useRef(false);
  const tourActive = tourIndex !== null;
  const workspace = useWorkspaceSession(
    () => ({ layer, visibleSystems, explode, layout, inspection, plate, anchorSkeleton,
      showOrigins, isolated, syncPlane, view, zoom, camera: cameraCapture.current }),
    state => {
      setLayer(state.layer); setVisibleSystems(state.visibleSystems); setExplode(state.explode);
      setLayout(state.layout); setInspection(state.inspection); setPlate(state.plate);
      setAnchorSkeleton(state.anchorSkeleton); setShowOrigins(state.showOrigins);
      setIsolated(state.isolated); setSyncPlane(state.syncPlane); setView(state.view);
      setZoom(state.zoom); cameraRestore.current = state.camera; setResetNonce(n => n + 1);
    },
    next => ({ layer: (next === 'dissect' ? 'cuff' : 'surface') as AnatomyLayer,
      visibleSystems: { skeleton: true, muscles: true, 'soft-tissue': true },
      explode: 0, layout: 'spatial' as BodyLayout, inspection: initialInspection, plate: false,
      anchorSkeleton: false, showOrigins: false, isolated: false, syncPlane: false,
      view, zoom, camera: cameraCapture.current }),
  );
  const [shoulderPractice, practiceDispatch] = useReducer(
    practiceReducer,
    initialPractice,
  );
  const practiceSerial = useRef(0);
  const questionIndex = shoulderPractice.index;
  const answerId = shoulderPractice.responses[questionIndex]?.chosen ?? null;
  const score = practiceScore(shoulderPractice);
  function beginShoulderPractice() {
    if (!displayReady) return;
    const session: PracticeSession = {
      id: ++practiceSerial.current,
      mode: 'find',
      status: 'active',
      index: 0,
      questions: quizQuestions.map((q) => ({
        target: q.answer,
        choices: q.options,
      })),
      renderedIds: structures.map((s) => s.id),
      responses: [],
    };
    practiceDispatch({ type: 'start', session });
  }
  const selected = structureById.get(selectedId) ?? structures[0];
  const currentQuestion = quizQuestions[questionIndex];
  const studyScope = {
    kind: 'shoulder' as const,
    region: 'shoulder-pilot',
    revision: manifest.sha256,
    structureIds: structures.map((s) => s.id),
  };
  function captureView(): StudyView {
    return {
      kind: 'shoulder',
      region: 'shoulder-pilot',
      revision: manifest.sha256,
      selectedId,
      view,
      side: 'right',
      layer,
      systems: visibleSystems,
      hiddenIds: [],
      explode,
      layout,
      zoom,
      isolated,
      focus: false,
      labels: showLabels,
      referencePlane: syncPlane,
      ghostRemoved: false,
      illustrated: true,
      anchorSkeleton,
      showOrigins,
      plate,
      inspection,
      camera: cameraCapture.current,
    };
  }
  function restoreView(state: StudyView) {
    if (tourActiveRef.current) return;
    workspace.chooseMode('dissect');
    setMode('study');
    practiceDispatch({ type: 'dismiss' });
    beforeExam.current = null;
    applyStudyView(state);
  }
  const applyStudyView = useCallback((state: StudyView) => {
    setSyncPlane(state.referencePlane ?? false);
    setSelectedId(state.selectedId ?? structures[0].id);
    setView(state.view as CameraView);
    setLayer(state.layer);
    setVisibleSystems(state.systems as Record<SystemKey, boolean>);
    setExplode(state.explode);
    setLayout(state.layout ?? 'spatial');
    setZoom(state.zoom);
    setIsolated(state.isolated);
    setShowLabels(state.labels);
    setAnchorSkeleton(state.anchorSkeleton);
    setShowOrigins(state.showOrigins);
    setPlate(state.plate);
    setInspection(state.inspection);
    cameraRestore.current = state.camera;
    setResetNonce((n) => n + 1);
  }, []);

  const applyTourStep = useCallback((index: number) => {
    const state = shoulderTourStepView(index);
    if (!state) return;
    setTourIndex(index);
    setTourMotionPaused(false);
    setZoomStep(0);
    applyStudyView(state);
  }, [applyStudyView]);
  const pauseTourPlayback = useCallback(() => {
    tourPlaybackEpoch.current++;
    setTourPlaying(false);
    setTourMotionPaused(true);
  }, []);
  const changeTourRate = useCallback((rate: GuidedPlaybackRate) => {
    if (!isGuidedPlaybackRate(rate) || rate === tourRate) return;
    tourPlaybackEpoch.current++;
    setTourRate(rate);
  }, [tourRate]);
  const reportRendererHealth = useCallback((health: RendererHealth) => {
    rendererHealthRef.current = health;
    examReadyRef.current = rendererReady(health) && modelReadyRef.current;
    if (!examReadyRef.current && tourActiveRef.current) pauseTourPlayback();
    setRendererHealth(health);
  }, [pauseTourPlayback]);
  const reportModelReady = useCallback((ready: boolean) => {
    modelReadyRef.current = ready;
    examReadyRef.current = rendererReady(rendererHealthRef.current) && ready;
    if (!examReadyRef.current && tourActiveRef.current) pauseTourPlayback();
    setModelReady(ready);
  }, [pauseTourPlayback]);
  const manualTourStep = useCallback((index: number) => {
    if (!tourActiveRef.current || tourIndex === null || !Number.isInteger(index) ||
        index < 0 || index >= shoulderTour.steps.length || index === tourIndex) return;
    tourPlaybackEpoch.current++;
    applyTourStep(index);
  }, [applyTourStep, tourIndex]);
  function startTour(continuous = false) {
    if (!guidedLearning || tourActiveRef.current || !displayReady || mode !== 'study' || workspace.mode === 'practice') return;
    beforeTour.current = { view: structuredClone(captureView()), zoomStep };
    tourActiveRef.current = true;
    tourPlaybackEpoch.current++;
    setTourContinuous(continuous);
    setTourPlaying(continuous && !document.hidden && !reducedMotion);
    applyTourStep(0);
    if (document.hidden || reducedMotion) setTourMotionPaused(true);
  }
  function exitTour() {
    tourPlaybackEpoch.current++;
    const saved = beforeTour.current;
    beforeTour.current = null;
    tourActiveRef.current = false;
    setTourIndex(null);
    setTourPlaying(false);
    setTourContinuous(false);
    setTourMotionPaused(false);
    if (saved) {
      applyStudyView(saved.view);
      setZoomStep(saved.zoomStep);
    }
  }
  useEffect(() => {
    if (tourActive || tourHadFocus.current)
      tourControls.current?.querySelector<HTMLButtonElement>('button:not(:disabled)')?.focus({ preventScroll: true });
    tourHadFocus.current = tourActive;
  }, [tourActive]);
  useEffect(() => {
    const preference = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => {
      if (preference.matches && tourActiveRef.current) pauseTourPlayback();
      setReducedMotion(preference.matches);
    };
    update();
    preference.addEventListener('change', update);
    return () => preference.removeEventListener('change', update);
  }, [pauseTourPlayback]);
  useEffect(() => {
    if (!tourActive) return;
    const visibility = () => { if (document.hidden) pauseTourPlayback(); };
    if (!displayReady) pauseTourPlayback();
    document.addEventListener('visibilitychange', visibility);
    window.addEventListener('pagehide', pauseTourPlayback);
    return () => { document.removeEventListener('visibilitychange', visibility); window.removeEventListener('pagehide', pauseTourPlayback); };
  }, [tourActive, displayReady, pauseTourPlayback]);
  useEffect(() => () => { tourPlaybackEpoch.current++; tourActiveRef.current = false; }, []);
  useEffect(() => {
    if (!tourPlaying || tourIndex === null || !displayReady || document.hidden) return;
    let active = true;
    const epoch = tourPlaybackEpoch.current;
    const timer = window.setTimeout(() => {
      if (!active || epoch !== tourPlaybackEpoch.current || !tourActiveRef.current || document.hidden) return;
      if (tourIndex + 1 < shoulderTour.steps.length) applyTourStep(tourIndex + 1);
      else setTourPlaying(false);
    }, tourContinuous ? guidedPlaybackDuration(shoulderTour.steps[tourIndex].caption, shoulderTour.steps[tourIndex].durationMs, tourRate) : Math.ceil(shoulderTour.steps[tourIndex].durationMs / tourRate));
    return () => { active = false; window.clearTimeout(timer); };
  }, [tourPlaying, tourIndex, tourContinuous, tourRate, displayReady, applyTourStep]);

  const searchOptions = useMemo<SearchOption[]>(
    () => shoulderSearchOptions(structures),
    [],
  );
  const selectedSearchOption =
    searchOptions.find((option) => option.value === selectedId) ?? null;

  const applySelection = useCallback((id: string) => {
    if (tourActiveRef.current) return false;
    const structure = structureById.get(id);
    if (!structure) return false;
    setSelectedId(id);
    const slug = id.split(':').at(-1);
    if (slug === 'subscapularis' || slug === 'biceps-long-head')
      setView('anterior');
    if (
      slug === 'infraspinatus' ||
      slug === 'supraspinatus' ||
      slug === 'teres-minor'
    )
      setView('posterior');
    setVisibleSystems((current) => ({
      ...current,
      [structure.system]: true,
    }));
    return true;
  }, []);

  const linkEntries = useMemo(
    () => shoulderLinkEntries(manifest, structures),
    [],
  );
  const imagingLink = useImagingLink({
    entries: linkEntries,
    allowedIds: structures.map((s) => s.id),
    disabled: mode === 'exam' || tourActive,
    onSelect: (id) => {
      applySelection(id);
      setInspection(initialInspection);
    },
  });
  const publishSelection = imagingLink.publish;
  const selectStructure = useCallback(
    (id: string) => {
      if (!applySelection(id)) return false;
      publishSelection(id);
      return true;
    },
    [applySelection, publishSelection],
  );

  const handleSceneSelect = (id: string) => {
    if (!displayReady || tourActiveRef.current) return;
    selectStructure(id);
    if (mode === 'exam')
      practiceDispatch({
        type: 'answer',
        sessionId: shoulderPractice.id,
        index: questionIndex,
        chosen: id,
      });
  };

  const answerExamOption = (id: string, sessionId: number, index: number) => {
    if (!examReadyRef.current || tourActiveRef.current || mode !== 'exam' ||
        !quizQuestions[index]?.options.includes(id)) return;
    practiceDispatch({ type: 'answer', sessionId, index, chosen: id });
  };

  const nextQuestion = () => {
    if (!displayReady) return;
    practiceDispatch({
      type: 'next',
      sessionId: shoulderPractice.id,
      index: questionIndex,
    });
    if (questionIndex === quizQuestions.length - 1) beginShoulderPractice();
    setIsolated(false);
  };

  const toggleMode = () => {
    if (tourActiveRef.current) return;
    if (mode === 'exam') {
      setMode('study');
      practiceDispatch({ type: 'dismiss' });
      const saved = beforeExam.current;
      beforeExam.current = null;
      if (saved) {
        applyStudyView(saved.view);
        setZoomStep(saved.zoomStep);
      }
      return;
    }
    if (mode === 'study' && !displayReady) return;
    beforeExam.current = { view: structuredClone(captureView()), zoomStep };
    setPlate(false);
    setLayout('spatial');
    setSyncPlane(false);
    setMode((current) => (current === 'study' ? 'exam' : 'study'));
    practiceDispatch({ type: 'dismiss' });
    if (mode === 'study') beginShoulderPractice();
    setIsolated(false);
    setLayer('cuff');
    setVisibleSystems({
      skeleton: true,
      muscles: true,
      'soft-tissue': true,
    });
    setExplode(0);
  };

  const toggleSync = () => {
    setSyncPlane((current) => !current);
  };

  function changeLayout(next: BodyLayout) {
    if (mode === 'exam' || next === layout) return;
    setLayout(next);
    setPlate(next === 'tray');
    setExplode(next === 'spatial' ? 0 : 100);
    setIsolated(false);
    setZoom(1);
    setResetNonce((n) => n + 1);
  }

  function changePlate(next: boolean) {
    if (!next && layout === 'tray') changeLayout('spatial');
    else setPlate(next);
  }

  useEffect(() => {
    const context = (document as Document & { modelContext?: ModelContextLike })
      .modelContext;
    if (!context?.registerTool) return;
    const lifecycle = new AbortController();
    const reportError = (error: unknown) =>
      console.warn('WebMCP registration failed', error);

    const register = async () => {
      await context.registerTool(
        {
          name: 'select_anatomy_structure',
          title: 'Select anatomy structure',
          description:
            'Select and reveal a shoulder structure in the Visible Medicine anatomy explorer.',
          inputSchema: {
            type: 'object',
            properties: {
              structureId: {
                type: 'string',
                enum: structures.map((item) => item.id),
              },
            },
            required: ['structureId'],
            additionalProperties: false,
          },
          annotations: { readOnlyHint: false, untrustedContentHint: false },
          execute(input) {
            const id = (input as { structureId?: unknown })?.structureId;
            if (typeof id !== 'string' || !selectStructure(id))
              throw new Error('Unknown structureId');
            return {
              selectedStructureId: id,
              selectedStructureName: structureById.get(id)?.name,
            };
          },
        },
        { signal: lifecycle.signal },
      );
      await context.registerTool(
        {
          name: 'configure_anatomy_view',
          title: 'Configure anatomy view',
          description:
            'Configure the spatial 3D shoulder view, dissection layer, separation and labels.',
          inputSchema: {
            type: 'object',
            properties: {
              view: {
                type: 'string',
                enum: ['posterior', 'anterior', 'lateral'],
              },
              layer: { type: 'string', enum: ['cuff', 'surface', 'bones'] },
              explode: { type: 'number', minimum: 0, maximum: 100 },
              labels: { type: 'boolean' },
              isolateSelected: { type: 'boolean' },
            },
            additionalProperties: false,
          },
          annotations: { readOnlyHint: false, untrustedContentHint: false },
          execute(input) {
            if (tourActiveRef.current) throw new Error('Exit the guided tour before changing the view');
            const config = input as {
              view?: unknown;
              layer?: unknown;
              explode?: unknown;
              labels?: unknown;
              isolateSelected?: unknown;
            };
            if (
              config.view !== undefined &&
              (typeof config.view !== 'string' ||
                !['anterior', 'posterior', 'lateral'].includes(config.view))
            )
              throw new Error('Unknown view');
            if (
              config.layer !== undefined &&
              (typeof config.layer !== 'string' ||
                !['cuff', 'surface', 'bones'].includes(config.layer))
            )
              throw new Error('Unknown layer');
            if (
              config.explode !== undefined &&
              (typeof config.explode !== 'number' ||
                config.explode < 0 ||
                config.explode > 100)
            )
              throw new Error('explode must be between 0 and 100');
            if (
              config.labels !== undefined &&
              typeof config.labels !== 'boolean'
            )
              throw new Error('labels must be boolean');
            if (
              config.isolateSelected !== undefined &&
              typeof config.isolateSelected !== 'boolean'
            )
              throw new Error('isolateSelected must be boolean');
            if (config.layer !== undefined)
              workspace.chooseMode('dissect');
            if (typeof config.view === 'string')
              setView(config.view as CameraView);
            if (typeof config.layer === 'string')
              setLayer(config.layer as AnatomyLayer);
            if (typeof config.explode === 'number') setExplode(config.explode);
            if (typeof config.labels === 'boolean')
              setShowLabels(config.labels);
            if (typeof config.isolateSelected === 'boolean')
              setIsolated(config.isolateSelected);
            return {
              view: config.view,
              layer: config.layer,
              explode: config.explode,
              labels: config.labels,
              isolateSelected: config.isolateSelected,
            };
          },
        },
        { signal: lifecycle.signal },
      );
    };
    void register().catch(reportError);
    return () => lifecycle.abort();
  }, [selectStructure, workspace]);

  const answerCorrect = answerId === currentQuestion.answer;
  const answerName = answerId ? structureById.get(answerId)?.name : '';
  const selectedVisibility =
    mode === 'study'
      ? selectionVisibility({
          system: selected.system,
          enabled: visibleSystems[selected.system],
          bounds: shoulderSelectionBounds.get(selected.id) ?? null,
          frame: shoulderSelectionFrame,
          inspection,
        })
      : null;
  function revealSelection() {
    if (mode !== 'study' || !selectedVisibility) return;
    if (selectedVisibility.systemOff)
      setVisibleSystems((current) => ({
        ...current,
        [selected.system]: true,
      }));
    setInspection((current) =>
      recoverSelectionInspection(current, selectedVisibility),
    );
  }

  return (
    <TooltipProvider>
