import type { SpecimenDepthLesson, SpecimenDepthNote } from '@/atlas-review/content/um-calf-depth';
import { specimenDepthReviewName } from '@/atlas-review/lib/specimen-depth-scope';

function Note({ title, note }: { title: string; note: SpecimenDepthNote }) {
  return <section><h4>{title}</h4><p>{note.body}</p>
    <ul aria-label={`${title} references`}>{note.references.map(reference => <li key={reference.url}>
      <a href={reference.url} target="_blank" rel="noreferrer">{reference.title}</a>
    </li>)}</ul>
  </section>;
}

/** Compact in the learner's existing tabs; fully visible in the review packet.
 * Reading links are references, never an entitlement or imaging registration. */
export function SpecimenDepthNotes({ depth, section }: {
  depth: SpecimenDepthLesson; section: 'anatomy' | 'clinical' | 'review';
}) {
  const regionName = specimenDepthReviewName(depth);
  if (!regionName) return <p>Additional depth is unavailable for this source/revision scope; no other region was substituted.</p>;
  const content = <>
    <p className="um-knee-scene-caption">Additional teaching draft · specialist review pending.</p>
    {section !== 'clinical' && <><Note title="Relationships" note={depth.relationships} />
      <Note title="Typical arterial supply" note={depth.arterialSupply} /></>}
    {section !== 'anatomy' && <Note title="Clinical pitfall" note={depth.clinicalPitfall} />}
    <p className="um-source-caution">Model limit: {depth.modelLimit}</p>
  </>;
  return section === 'review' ? <section aria-label={`${regionName} depth to review`}>
    <h3>{regionName} relationships, blood supply & clinical depth · Draft</h3>
    <p>Revision: <code>{depth.revision}</code>. Review the actual source surfaces; these notes do not establish absent tissue geometry or scan alignment.</p>
    {content}
  </section> : <details className="um-knee-details">
    <summary>{section === 'anatomy' ? 'Relationships & blood supply' : 'Clinical depth · pitfall'}</summary>
    {content}
  </details>;
}

'use client';
import { useId, useRef } from 'react';
import { Button } from '@/atlas-review/components/ui/button';
import { Input } from '@/atlas-review/components/ui/input';
import { Switch } from '@/atlas-review/components/ui/switch';
import { filterSpecimen, type SpecimenDefinition } from '@/atlas-review/lib/independent-specimen';

/** Filtering changes the list only; visibility and selection remain explicit actions. */
export function SpecimenStructureSearch({
  specimen, query, onQueryChange, selectedId, hidden, onSelect, onVisibility,
}: {
  specimen: SpecimenDefinition;
  query: string;
  onQueryChange: (query: string) => void;
  selectedId: string | null;
  hidden: string[];
  onSelect: (id: string) => void;
  onVisibility: (id: string, visible: boolean) => void;
}) {
  const statusId = useId();
  const input = useRef<HTMLInputElement>(null);
  const results = filterSpecimen(specimen, query);
  const hiddenMatches = results.filter((surface) => hidden.includes(surface.id)).length;
  return <>
    <Input ref={input} type="search"
      aria-label={`Search ${specimen.label.toLowerCase()} specimen structures`}
      aria-describedby={query ? statusId : undefined}
      placeholder="Name, side or anatomical ID…" value={query}
      onChange={(event) => onQueryChange(event.target.value)} />
    {query && <div className="um-specimen-search-status">
      <p id={statusId} role="status" aria-live="polite" aria-atomic="true">
        {results.length} of {specimen.surfaces.length} structures
        {hiddenMatches > 0 && ` · ${hiddenMatches} hidden`}
      </p>
      <Button size="sm" variant="ghost" onClick={() => {
        onQueryChange(''); input.current?.focus();
      }}>Clear search</Button>
    </div>}
    <ul className="eye-layer-list um-knee-list">{results.map((surface) => <li key={surface.id}>
      <Button size="sm" variant={selectedId === surface.id ? 'secondary' : 'ghost'}
        aria-pressed={selectedId === surface.id} onClick={() => onSelect(surface.id)}>
        {surface.name}
      </Button>
      <Switch checked={!hidden.includes(surface.id)} aria-label={`Show ${surface.name}`}
        onCheckedChange={(visible) => onVisibility(surface.id, visible)} />
    </li>)}</ul>
    {!results.length && <p>No matching tissue in this specimen. Try a name, side or an assigned anatomical ID.</p>}
  </>;
}

'use client';
import { useState } from 'react';
import { Button } from '@/atlas-review/components/ui/button';
import { Input } from '@/atlas-review/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/atlas-review/components/ui/select';
import { makeSpecimenLink } from '@/atlas-review/lib/um-limb-navigation';
import type { SpecimenDefinition } from '@/atlas-review/lib/independent-specimen';
import { specimenTopicLabels, type SpecimenTopic } from '@/atlas-review/lib/specimen-links';
import { availableSpecimenTopics } from '@/atlas-review/lib/um-limb-teaching';
import type { DissectionView } from './dissection-data';
import type {ContainedLimbStudyBase} from '@/atlas-review/lib/model-delivery';

export function SpecimenStudyLink({ definition, selectedId, studyId, view, basePath, reviewAvailable = true }: { definition: SpecimenDefinition; selectedId: string; studyId: string | null; view: DissectionView; basePath?: '/atlas-runtime/lower-limb/index.html'|ContainedLimbStudyBase; reviewAvailable?: boolean }) {
  const [topic, setTopic] = useState<SpecimenTopic | null>(null);
  const topics = availableSpecimenTopics(definition, selectedId);
  const canonical = makeSpecimenLink(definition, { selectedId, studyId, view, topic });
  const href = canonical && basePath ? basePath + (basePath.includes('?')?'&':'?') + canonical.slice(canonical.indexOf('?')+1) : canonical;
  return <details className="um-knee-details"><summary>Link to this study</summary>
    <Select value={topic ?? 'model'} items={[{value:'model',label:'3D model'},...topics.map(t=>({value:t,label:specimenTopicLabels[t]+' notes'}))]} onValueChange={v => setTopic(topics.includes(v as SpecimenTopic) ? v as SpecimenTopic : null)}>
      <SelectTrigger aria-label="Study link opens"><SelectValue /></SelectTrigger>
      <SelectContent><SelectItem value="model">3D model</SelectItem>{topics.map(t => <SelectItem key={t} value={t}>{specimenTopicLabels[t]} notes</SelectItem>)}</SelectContent>
    </Select>
    {!studyId && <p>Custom dissection: the link opens this structure with the region’s source context. Hidden tissues and separation are not saved.</p>}
    {href ? <CopySpecimenLink key={href} href={href} /> : <p>A link cannot be made for this source binding.</p>}
    {href && reviewAvailable && <p><a href={`/workspace/atlas-review/specimens?specimen=${encodeURIComponent(definition.key)}&structure=${encodeURIComponent(selectedId)}`} target="_blank" rel="noreferrer">Review this structure</a></p>}
    <p>Opens the selected source, study and camera direction at the model’s original positions. No access permissions, scan alignment or quiz answers are included.</p>
  </details>;
}
export function CopySpecimenLink({ href }: { href: string }) {
  const [status, setStatus] = useState(''), [fallback, setFallback] = useState('');
  async function copy() {
    const absolute = new URL(href, window.location.origin).href;
    try { await navigator.clipboard.writeText(absolute); setStatus('Study link copied. Access restrictions still apply.'); setFallback(''); }
    catch { setFallback(absolute); setStatus('Automatic copy is unavailable. Select and copy the link below.'); }
  }
  return <><div className="eye-layer-actions"><Button size="sm" variant="outline" onClick={copy}>Copy link</Button><a href={href}>Open linked view</a></div>
    {status && <p role="status">{status}</p>}{fallback && <Input aria-label="Study link to copy" readOnly value={fallback} onFocus={e => e.currentTarget.select()} />}</>;
}

'use client';
import { useId, useMemo, useState } from 'react';
import { Button } from '@/atlas-review/components/ui/button';
import { bodySystems, type BodyStructure, type BodySystem } from './body-types';
import type { DissectionProfile, DissectionState } from './dissection-data';
import {
  studyLibrary,
  filterStudyLibrary,
  studyRecipePreview,
  studyRecipeActive,
  studyLibraryAction,
  type StudyRecipe,
  type StudyLibrarySort,
} from '@/atlas-review/lib/study-library';

export function StudyLibrary({
  profile,
  state,
  structures,
  visibleIds,
  loaded,
  failed,
  disabled,
  onStage,
  onFocus,
}: {
  profile: DissectionProfile;
  state: DissectionState;
  structures: BodyStructure[];
  visibleIds: string[];
  loaded: string[];
  failed: string[];
  disabled: boolean;
  onStage: (id: string) => void;
  onFocus: (id: string) => void;
}) {
  const controlId = useId();
  const [query, setQuery] = useState('');
  const [system, setSystem] = useState<BodySystem | 'all'>('all');
  const [kind, setKind] = useState<StudyRecipe['kind'] | 'all'>('all');
  const [sort, setSort] = useState<StudyLibrarySort>('authored');
  const [expanded, setExpanded] = useState<string | null>(null);
  const cards = useMemo(
    () => studyLibrary(structures, profile),
    [structures, profile],
  );
  const matches = useMemo(
    () => filterStudyLibrary(cards, query, system, kind, sort),
    [cards, query, system, kind, sort],
  );
  const selected = matches.find((card) => card.key === expanded);
  const selectedPreview = selected
    ? studyRecipePreview(
        selected.recipes[0],
        structures,
        visibleIds,
        loaded,
        failed,
      )
    : null;
  function open(key: string) {
    const action = studyLibraryAction(structures, profile, key, disabled);
    if (!action) return;
    if (action.kind === 'focus') onFocus(action.id);
    else onStage(action.id);
  }
  if (disabled)
    return (
      <p className="study-library-notice">
        End practice to browse study views.
      </p>
    );
  return (
    <section className="study-library" aria-label="Study view library">
      <div className="study-library-filters">
        <label className="study-library-search" htmlFor={`${controlId}-search`}>
          Find a study view
          <input
            id={`${controlId}-search`}
            type="search"
            maxLength={256}
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="View name, included structure or FMA ID…"
          />
        </label>
        <label htmlFor={`${controlId}-system`}>
          Includes system
          <select
            id={`${controlId}-system`}
            value={system}
            onChange={(event) =>
              setSystem(event.target.value as BodySystem | 'all')
            }
          >
            <option value="all">All systems</option>
            {(Object.keys(bodySystems) as BodySystem[]).map((id) => (
              <option key={id} value={id}>
                {bodySystems[id].name}
              </option>
            ))}
          </select>
        </label>
        <label htmlFor={`${controlId}-kind`}>
          View type
          <select
            id={`${controlId}-kind`}
            value={kind}
            onChange={(event) =>
              setKind(event.target.value as StudyRecipe['kind'] | 'all')
            }
          >
            <option value="all">Windows & focuses</option>
            <option value="window">Study windows</option>
            <option value="focus">Compartment focuses</option>
          </select>
        </label>
        <label htmlFor={`${controlId}-sort`}>
          Order
          <select
            id={`${controlId}-sort`}
            value={sort}
            onChange={(event) =>
              setSort(event.target.value as StudyLibrarySort)
            }
          >
            <option value="authored">Authored order</option>
            <option value="small-first">Fewest structures first</option>
            <option value="large-first">Broadest views first</option>
            <option value="name">Name A–Z</option>
          </select>
        </label>
        <Button
          size="sm"
          variant="outline"
          onClick={() => {
            setQuery('');
            setSystem('all');
            setKind('all');
            setSort('authored');
          }}
        >
          Clear filters
        </Button>
      </div>
      <p className="study-library-help">
        Search includes retained context. Preview a view before opening it;
        these are independent study choices, not successive tissue depths.
      </p>
      <output
        className="study-library-status"
        aria-live="polite"
        aria-atomic="true"
      >
        {matches.length} of {cards.length} study groups match.
        {selectedPreview && selected
          ? ` Preview: ${selected.title}. ${selectedPreview.hide.length} to hide, ${selectedPreview.restore.length} to restore.`
          : ''}
      </output>
      <ul className="study-library-list" aria-label="Available study views">
        {matches.map((card) => {
          const first = card.recipes[0],
            show = expanded === card.key;
          const active = card.recipes.some((recipe) =>
            studyRecipeActive(recipe, state),
          );
          const focus = card.recipes.find((recipe) => recipe.kind === 'focus');
          const targets = new Set(focus?.targets?.map((item) => item.id));
          const preview = show
            ? studyRecipePreview(first, structures, visibleIds, loaded, failed)
            : null;
          const panelId = `${controlId}-${card.key}`;
          return (
            <li
              key={card.key}
              className={
                active ? 'study-library-card active' : 'study-library-card'
              }
            >
              <button
                type="button"
                className="study-library-summary"
                aria-expanded={show}
                aria-controls={panelId}
                onClick={() => setExpanded(show ? null : card.key)}
              >
                <span>
                  <strong>{card.title}</strong>
                  <small>
                    {card.recipes
                      .map((recipe) =>
                        recipe.kind === 'focus'
                          ? 'Compartment focus'
                          : 'Study window',
                      )
                      .join(' · ')}{' '}
                    · {first.visible.length} retained
                  </small>
                </span>
                <span className="study-library-tag">
                  {active
                    ? 'Active recipe'
                    : show
                      ? 'Close preview'
                      : 'Preview'}
                </span>
              </button>
              <div
                id={panelId}
                className="study-library-preview"
                hidden={!show}
              >
                {show && preview && (
                  <>
                    <p>{first.description}</p>
                    <p className="study-library-inspect">{first.inspect}</p>
                    <dl className="study-library-counts">
                      <div>
                        <dt>Hide</dt>
                        <dd>{preview.hide.length}</dd>
                      </div>
                      <div>
                        <dt>Restore</dt>
                        <dd>{preview.restore.length}</dd>
                      </div>
                      <div>
                        <dt>Keep</dt>
                        <dd>{preview.keep.length}</dd>
                      </div>
                    </dl>
                    <p className="study-library-help">
                      {preview.loaded.length}/{first.visible.length} retained
                      entries loaded · {preview.waiting.length} not loaded ·{' '}
                      {preview.failed.length} failed. Counts describe catalogue
                      entries, not screen occlusion.
                    </p>
                    {focus && (
                      <p className="study-library-help">
                        {focus.targets?.length} focus targets ·{' '}
                        {first.visible.length - targets.size} context entries.
                        Context may include automatic skeletal background;
                        grouping does not establish an anatomical connection.
                      </p>
                    )}
                    <details className="study-library-members">
                      <summary>
                        Retained structures ({first.visible.length})
                      </summary>
                      <ul>
                        {first.visible.map((item) => (
                          <li key={item.id}>
                            <span>{item.name}</span>
                            <small>
                              {item.fmaId}
                              {focus
                                ? targets.has(item.id)
                                  ? ' · Target'
                                  : ' · Context'
                                : ''}
                            </small>
                          </li>
                        ))}
                      </ul>
                    </details>
                    <p className="study-library-reset">
                      Opening a view clears manual removals, system filters,
                      selection, cutaway and separation, then frames its preset.
                      Browsing changes none of these.
                    </p>
                    <div className="study-library-actions">
                      {card.recipes.map((recipe) => (
                        <Button
                          key={recipe.key}
                          size="sm"
                          variant={
                            recipe.kind === 'focus' ? 'default' : 'outline'
                          }
                          disabled={!recipe.available}
                          onClick={() => open(recipe.key)}
                        >
                          {recipe.kind === 'focus'
                            ? 'Open compartment focus'
                            : 'Open study window'}
                        </Button>
                      ))}
                    </div>
                    {!card.recipes.some((recipe) => recipe.available) && (
                      <p className="study-library-notice">
                        No eligible targets in the current side/region. Change
                        the side filter to inspect the available source anatomy.
                      </p>
                    )}
                  </>
                )}
              </div>
            </li>
          );
        })}
      </ul>
      {!matches.length && (
        <p className="study-library-notice">
          No study views match. Clear the filters or try an included structure
          name.
        </p>
      )}
    </section>
  );
}

'use client';
import { useMemo, useState } from 'react';
import Link from 'next/link';
import { Button } from '@/atlas-review/components/ui/button';
import {
  makeStudyLink,
  studyDestinations,
  type StudySide,
} from '../lib/study-links';
import type { BodyCatalog, BodyStructure } from './body-types';
import { regionalStudyDeliveryUrl } from '../lib/model-delivery';

export function StudyLinks({
  catalog,
  selected,
  region,
  side,
  focusId,
  assetBase = '',
}: {
  catalog: BodyCatalog;
  selected: BodyStructure;
  region: string;
  side: StudySide;
  focusId: string | null;
  assetBase?: string;
}) {
  const [copyState, setCopyState] = useState<{
    href: string;
    copied: boolean;
  } | null>(null);
  const destinations = useMemo(
    () => studyDestinations(catalog, selected, region, side)
      .filter(destination => !assetBase || assetBase === '/atlas-runtime/head-neck' || destination.region === region)
      .map(destination => ({...destination,
        // The shared module's Link adapter updates the containing website too.
        // Older single-region containers must still stay in their own scope.
        href: assetBase === '/atlas-runtime/head-neck' ? destination.href
          : regionalStudyDeliveryUrl(destination.href, destination.region, assetBase),
        focuses: destination.focuses.map(view => ({...view,
          href: assetBase === '/atlas-runtime/head-neck' ? view.href
            : regionalStudyDeliveryUrl(view.href, destination.region, assetBase)})),
      })),
    [catalog, selected, region, side, assetBase],
  );
  const sourceLink =
    makeStudyLink(catalog, region, selected.id, side, focusId) ??
    makeStudyLink(catalog, region, selected.id, side);
  const current = sourceLink ? regionalStudyDeliveryUrl(sourceLink, region, assetBase) : null;
  async function copyLink() {
    if (!current) return;
    try {
      await navigator.clipboard.writeText(
        new URL(current, window.location.origin).href,
      );
      setCopyState({ href: current, copied: true });
    } catch {
      setCopyState({ href: current, copied: false });
    }
  }
  return (
    <details className="anatomy-study-links">
      <summary>Continue this dissection</summary>
      <p>
        Keep <strong>{selected.name}</strong> selected {assetBase && assetBase !== '/atlas-runtime/head-neck'
          ? 'in a linked regional study view.'
          : 'when moving between the whole body and its available regions.'}
      </p>
      {destinations.length > 0 && <ul className="anatomy-study-destinations">
        {destinations.map((destination) => (
          <li key={destination.region}>
            <Link href={destination.href} prefetch={false}>
              {destination.name} · keep selection
            </Link>
            {destination.focuses.length > 0 && (
              <details>
                <summary>
                  {destination.focuses.length} focused study{' '}
                  {destination.focuses.length === 1 ? 'view' : 'views'}
                </summary>
                <ul>
                  {destination.focuses.map((view) => (
                    <li key={view.focusId}>
                      <Link href={view.href} prefetch={false}>
                        {view.title}
                        <small>Selection is a study {view.role}</small>
                      </Link>
                    </li>
                  ))}
                </ul>
              </details>
            )}
          </li>
        ))}
      </ul>}
      <p className="anatomy-study-link-note">
        Links open assembled anatomy or a named focus. Use Saved study views to
        preserve custom removals, cutaways and camera positions. Links never
        contain practice results or review records. Access stays private.
      </p>
      {current && (
        <div className="anatomy-study-link-copy">
          <Button size="sm" variant="outline" onClick={copyLink}>
            Copy this study link
          </Button>
          <a href={current}>Open linked view</a>
          <output aria-live="polite">
            {copyState?.href === current
              ? copyState.copied
                ? 'Study link copied. It does not grant access.'
                : 'Copy is unavailable. Use Open linked view, then copy the address.'
              : ''}
          </output>
        </div>
      )}
    </details>
  );
}

'use client';
import { createContext, useContext, useEffect, useId, useRef, type ReactNode, type HTMLAttributes } from 'react';
import { Dialog as Modal, DialogContent as ModalContent, DialogTitle as ModalTitle, DialogDescription as ModalDescription } from '@/atlas-review/components/ui/dialog';
import { useAtlasWorkspace } from './atlas-workspace';
import './study-surface.css';

const Inline = createContext(false);
const ActiveStudy = createContext(true);
const Surface = createContext({ titleId: '', descriptionId: '', close: () => {} });

/** Change presentation only: specimens retain their own source coordinates and controls. */
export function InlineStudy({ children, active = true }: { children: ReactNode; active?: boolean }) {
  const { setPanelOpen } = useAtlasWorkspace();
  useEffect(() => {
    if (!active) return;
    setPanelOpen(false, false);
    setPanelOpen(true, false);
  }, [setPanelOpen, active]);
  return <Inline.Provider value={true}><ActiveStudy.Provider value={active}>{children}</ActiveStudy.Provider></Inline.Provider>;
}

// Compatible wrappers retain modal presentation for independent, non-Atlas callers.
export function Dialog({ open, onOpenChange, children }: {
  open: boolean; onOpenChange: (open: boolean) => void; children: ReactNode;
}) {
  const inline = useContext(Inline), id = useId();
  if (!inline) return <Modal open={open} onOpenChange={onOpenChange}>{children}</Modal>;
  return open ? <Surface.Provider value={{ titleId: `${id}-title`, descriptionId: `${id}-description`, close: () => onOpenChange(false) }}>{children}</Surface.Provider> : null;
}
export function DialogContent({ children, className = '', showCloseButton: _ }: {
  children: ReactNode; className?: string; showCloseButton?: boolean;
}) {
  const inline = useContext(Inline), surface = useContext(Surface);
  const active = useContext(ActiveStudy);
  const node = useRef<HTMLElement>(null);
  useEffect(() => {
    if (!inline || !active) return;
    const root = node.current?.closest('.body-app');
    node.current?.focus({ preventScroll: true });
    return () => {
      requestAnimationFrame(() => {
        // A mobile launcher may have lived in a now-closed drawer. Preserve a
        // valid explicit return target; otherwise land on the active mode.
        if (root?.isConnected && (document.activeElement === document.body || !document.activeElement?.getClientRects().length))
          root.querySelector<HTMLElement>('[role="radio"][aria-checked="true"]')?.focus({ preventScroll: true });
      });
    };
  }, [inline, active]);
  if (!inline) return <ModalContent className={className} showCloseButton={_}>{children}</ModalContent>;
  return <section ref={node} hidden={!active} tabIndex={-1} role="region" aria-labelledby={surface.titleId}
    aria-describedby={surface.descriptionId} data-slot="dialog-content" data-study-surface="inline"
    className={`atlas-inline-study ${className}`}
    onKeyDown={event => { if (event.key === 'Escape' && !event.defaultPrevented) { event.stopPropagation(); surface.close(); } }}>
    {children}
  </section>;
}
export function DialogTitle(props: HTMLAttributes<HTMLHeadingElement>) {
  const inline = useContext(Inline), surface = useContext(Surface);
  return inline ? <h2 {...props} id={surface.titleId} data-slot="dialog-title" /> : <ModalTitle {...props} />;
}
export function DialogDescription(props: HTMLAttributes<HTMLParagraphElement>) {
  const inline = useContext(Inline), surface = useContext(Surface);
  return inline ? <p {...props} id={surface.descriptionId} data-slot="dialog-description" /> : <ModalDescription {...props} />;
}

'use client';
import { useEffect, useId, useRef, useState } from 'react';
import Link from 'next/link';
import { BookmarkPlus, RotateCcw, Trash2 } from 'lucide-react';
import { Button } from '@/atlas-review/components/ui/button';
import { Input } from '@/atlas-review/components/ui/input';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/atlas-review/components/ui/dialog';
import {
  compatibleStudyView,
  decodeStudyBookmarks,
  editStudyBookmarks,
  persistStudyBookmarks,
  MAX_STUDY_VIEWS,
  STUDY_STORAGE_KEY,
  type StudyBookmark,
  type StudyScope,
  type StudyView,
} from '@/atlas-review/lib/study-views';
import './study-views.css';

export function StudyViews({
  scope,
  capture,
  restore,
  disabled = false,
}: {
  scope: StudyScope;
  capture: () => StudyView | null;
  restore: (state: StudyView) => void;
  disabled?: boolean;
}) {
  const [bookmarks, setBookmarks] = useState<StudyBookmark[]>([]);
  const [ready, setReady] = useState(false),
    [error, setError] = useState(''),
    [message, setMessage] = useState('');
  const [open, setOpen] = useState(false),
    [name, setName] = useState(''),
    [busy, setBusy] = useState(false);
  const [removing, setRemoving] = useState<StudyBookmark | null>(null);
  const nameId = useId();
  const summary = useRef<HTMLElement | null>(null);
  const saveOpener = useRef<HTMLButtonElement | null>(null);
  const removeOpener = useRef<HTMLButtonElement | null>(null);
  const savePopup = useRef<HTMLDivElement | null>(null);
  const removePopup = useRef<HTMLDivElement | null>(null);
  const returnDialogFocus = (opener: HTMLButtonElement | null, popup: HTMLDivElement | null) => {
    const active = summary.current?.ownerDocument.activeElement;
    // Preserve focus deliberately moved outside this dialog. A removed trigger
    // or the twentieth-save disabled trigger cannot receive keyboard focus.
    if (active && active !== summary.current?.ownerDocument.body &&
      active !== opener && !popup?.contains(active)) return false;
    if (opener?.isConnected && !opener.disabled && opener.getClientRects().length) return opener;
    return summary.current?.isConnected && summary.current.getClientRects().length ? summary.current : false;
  };
  useEffect(() => {
    const refresh = () => {
      try {
        setBookmarks(
          decodeStudyBookmarks(window.localStorage.getItem(STUDY_STORAGE_KEY)),
        );
        setError('');
        setReady(true);
      } catch (e) {
        setReady(false);
        setError(
          e instanceof Error
            ? e.message
            : 'Saved views are unavailable in this browser.',
        );
      }
    };
    const changed = (event: StorageEvent) => {
      if (event.key === STUDY_STORAGE_KEY || event.key === null) refresh();
    };
    refresh();
    window.addEventListener('storage', changed);
    return () => window.removeEventListener('storage', changed);
  }, []);
  async function change(action: Parameters<typeof editStudyBookmarks>[1]) {
    setBusy(true);
    setError('');
    const update = () => {
      // Persist first: a quota/security failure must not be reported as a successful save.
      const next = persistStudyBookmarks(window.localStorage, action);
      setBookmarks(next);
      setReady(true);
    };
    try {
      if (navigator.locks)
        await navigator.locks.request(STUDY_STORAGE_KEY, update);
      else update();
      setMessage(
        action.type === 'save'
          ? 'Study view saved on this browser.'
          : 'Study view removed from this browser.',
      );
      return true;
    } catch (e) {
      setError(
        e instanceof Error
          ? e.message
          : 'The change could not be saved. Your existing views are unchanged.',
      );
      return false;
    } finally {
      setBusy(false);
    }
  }
  async function save() {
    const state = capture();
    if (!state || !state.camera) {
      setError('Wait for the 3D view to finish preparing, then try again.');
      return;
    }
    if (!compatibleStudyView(state, scope)) {
      setError(
        'This view no longer matches the current anatomy. Please try again.',
      );
      return;
    }
    const bookmark: StudyBookmark = {
      id: crypto.randomUUID(),
      name: name.trim(),
      savedAt: new Date().toISOString(),
      state,
    };
    if (await change({ type: 'save', bookmark })) {
      setOpen(false);
      setName('');
    }
  }
  const current = bookmarks.filter(
    (b) => b.state.kind === scope.kind && b.state.region === scope.region,
  );
  const other = bookmarks.filter((b) => !current.includes(b));
  const removeButton = (b: StudyBookmark) => (
    <Button
      size="icon-sm"
      variant="ghost"
      disabled={busy || disabled}
      aria-label={`Remove saved view ${b.name}`}
      onClick={(event) => {
        removeOpener.current = event.currentTarget;
        setError('');
        setRemoving(b);
      }}
    >
      <Trash2 />
    </Button>
  );
  return (
    <details className="vm-study-views">
      <summary ref={summary}>
        Saved study views <span>{current.length} in this region</span>
      </summary>
      <div className="vm-study-content">
        <p>
          Save this dissection, cutaway and camera framing. Stored only in this
          browser; not synced to your account. Keep patient details out of view
          names.
        </p>
        <Button
          size="sm"
          variant="outline"
          disabled={
            !ready || busy || disabled || bookmarks.length >= MAX_STUDY_VIEWS
          }
          onClick={(event) => {
            saveOpener.current = event.currentTarget;
            setError('');
            setOpen(true);
          }}
        >
          <BookmarkPlus />
          Save current view
        </Button>
        <p className="vm-study-meta">
          {bookmarks.length}/{MAX_STUDY_VIEWS} saved across the atlas
          {disabled ? ' · Unavailable during practice or loading' : ''}
        </p>
        {!current.length && <p>No saved views for this region yet.</p>}
        <ul>
          {current.map((b) => {
            const compatible = compatibleStudyView(b.state, scope);
            return (
              <li key={b.id}>
                <div>
                  <strong>{b.name}</strong>
                  <small>
                    {new Date(b.savedAt).toLocaleDateString()} ·{' '}
                    {b.state.plate ? 'Illustration' : '3D'}
                    {b.state.inspection.plane !== 'off'
                      ? ` · ${b.state.inspection.plane} cutaway`
                      : ''}
                  </small>
                  {!compatible && (
                    <small className="vm-study-warning">
                      Anatomy changed. This saved view cannot be restored.
                    </small>
                  )}
                </div>
                <Button
                  size="sm"
                  variant="outline"
                  disabled={disabled || busy || !compatible}
                  onClick={() => {
                    restore(b.state);
                    setMessage(`Restored ${b.name}.`);
                  }}
                  aria-label={`Restore saved view ${b.name}`}
                >
                  <RotateCcw />
                  Restore
                </Button>
                {removeButton(b)}
              </li>
            );
          })}
        </ul>
        {other.length > 0 && (
          <details className="vm-study-other">
            <summary>Other regions · {other.length}</summary>
            <ul>
              {other.map((b) => (
                <li key={b.id}>
                  <div>
                    <strong>{b.name}</strong>
                    <Link
                      href={
                        b.state.kind === 'shoulder'
                          ? '/shoulder'
                          : b.state.region === 'whole-body'
                            ? '/'
                            : `/regions/${b.state.region}`
                      }
                    >
                      Open {b.state.region.replaceAll('-', ' ')}
                    </Link>
                  </div>
                  {removeButton(b)}
                </li>
              ))}
            </ul>
          </details>
        )}
        <output aria-live="polite">{message}</output>
        {error && (
          <p role="alert" className="vm-study-warning">
            {error}
          </p>
        )}
      </div>
      <Dialog open={open} onOpenChange={(v) => !busy && setOpen(v)}>
        <DialogContent className="vm-study-dialog" ref={savePopup} finalFocus={() => returnDialogFocus(saveOpener.current, savePopup.current)}>
          <DialogHeader>
            <DialogTitle>Save study view</DialogTitle>
            <DialogDescription>
              Name this view for your own study. This saves display settings
              only, not a scan or clinical review.
            </DialogDescription>
          </DialogHeader>
          <form
            onSubmit={(event) => {
              event.preventDefault();
              void save();
            }}
          >
            <label htmlFor={nameId}>View name</label>
            <Input
              id={nameId}
              value={name}
              onChange={(event) => setName(event.target.value)}
              maxLength={64}
              required
              placeholder="e.g. Posterior cuff — deep view"
              disabled={busy}
            />
            {error && (
              <p role="alert" className="vm-study-warning">
                {error}
              </p>
            )}
            <DialogFooter>
              <Button
                type="button"
                variant="outline"
                disabled={busy}
                onClick={() => setOpen(false)}
              >
                Cancel
              </Button>
              <Button type="submit" disabled={busy || disabled || !name.trim()}>
                {busy ? 'Saving…' : 'Save view'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
      <Dialog
        open={!!removing}
        onOpenChange={(v) => !v && !busy && setRemoving(null)}
      >
        <DialogContent className="vm-study-dialog" ref={removePopup} finalFocus={() => returnDialogFocus(removeOpener.current, removePopup.current)}>
          <DialogHeader>
            <DialogTitle>Remove saved view?</DialogTitle>
            <DialogDescription>
              Remove “{removing?.name}” from this browser? This does not change
              the anatomy or clinical review records.
            </DialogDescription>
          </DialogHeader>
          {error && (
            <p role="alert" className="vm-study-warning">
              {error}
            </p>
          )}
          <DialogFooter>
            <Button
              variant="outline"
              disabled={busy}
              onClick={() => setRemoving(null)}
            >
              Cancel
            </Button>
            <Button
              disabled={busy || disabled}
              onClick={async () => {
                if (
                  removing &&
                  (await change({ type: 'remove', id: removing.id }))
                )
                  setRemoving(null);
              }}
            >
              Remove view
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </details>
  );
}

