}

'use client';
import type {ContentLesson} from '@/atlas-review/lib/content-types';
import {StructureQuickCheck} from './structure-quick-check';
import {SupplementalQuizChecks} from './supplemental-quiz-checks';
import './tour-imaging-notes.css';

/** Only existing explicitly keyed source-bound lessons; never infer an answer. */
export function TourQuickCheck({lesson,onOpen,onChange}:{lesson:ContentLesson;onOpen:()=>void;onChange?:(open:boolean)=>void}) {
  const choices=lesson.bullets??[];
  if(lesson.readiness!=='draft'||!lesson.correctAnswer||
    choices.filter(choice=>choice===lesson.correctAnswer).length!==1||
    choices.some(choice=>!choice.trim())||new Set(choices.map(choice=>choice.trim())).size!==choices.length)return null;
  return <details className="tour-imaging-notes tour-quick-check" onToggle={event=>{const open=event.currentTarget.open;if(open)onOpen();onChange?.(open);}}>
    <summary>Quick check</summary>
    <div className="tour-imaging-reader" role="region" aria-label="Tour quick check" tabIndex={0}>
      <p>Opening this check pauses the tour. Use Play when you are ready to continue.</p>
      {onChange&&<p>Imaging linking stays paused while this check is open.</p>}
      <StructureQuickCheck question={lesson.body} choices={choices}
        correctAnswer={lesson.correctAnswer} explanation={lesson.explanation}/>
      {lesson.additionalChecks&&<SupplementalQuizChecks checks={lesson.additionalChecks}/>}
      <details><summary>References & limits</summary>
        {lesson.note&&<p>{lesson.note}</p>}
        {lesson.citations?.filter(url=>/^https?:\/\//i.test(url)).map((url,index)=><a key={url} href={url} target="_blank" rel="noreferrer">Reference {index+1} ↗</a>)}
      </details>
    </div>
  </details>;
}

import {GUIDED_PLAYBACK_RATES,isGuidedPlaybackRate,type GuidedPlaybackRate} from '@/atlas-review/lib/guided-playback';
import './tour-speed-control.css';

/** Shared by every 3D tour; changing speed never starts or advances playback. */
export function TourSpeedControl({rate,onRateChange,disabled=false}:{rate:GuidedPlaybackRate;onRateChange:(rate:GuidedPlaybackRate)=>void;disabled?:boolean}){
  return <label className="tour-speed-control"><span>Tour speed</span><select aria-label="Tour speed" value={rate} disabled={disabled} onChange={event=>{
    const next=Number(event.currentTarget.value);
    if(!disabled&&isGuidedPlaybackRate(next)&&next!==rate)onRateChange(next);
  }}>{GUIDED_PLAYBACK_RATES.map(value=><option key={value} value={value}>{value}×{value===1?' · Normal':value===0.5?' · Slower':value===3?' · Fastest':''}</option>)}</select></label>;
}

'use client';
import {Select,SelectContent,SelectItem,SelectTrigger,SelectValue} from '@/atlas-review/components/ui/select';
import './tour-step-picker.css';

type Props={steps:readonly {id:string;title:string}[];index:number;ready:boolean;onPause:()=>void;onStep:(index:number)=>void};

/** Navigation only: it never marks an unvisited stop as learned or approved. */
export function TourStepPicker({steps,index,ready,onPause,onStep}:Props){
  const selected=steps[index];
  if(!selected)return null;
  return <Select key={ready?'ready':'unavailable'} value={selected.id} disabled={!ready}
    onOpenChange={open=>{if(open&&ready)onPause();}}
    onValueChange={value=>{
      if(!ready||typeof value!=='string')return;
      const next=steps.findIndex(step=>step.id===value);
      if(next<0||next===index)return;
      onPause();onStep(next);
    }}>
    <SelectTrigger className="tour-step-trigger" aria-label="Go to tour step">
      <SelectValue>Step {index+1} of {steps.length}</SelectValue>
    </SelectTrigger>
    <SelectContent className="tour-step-options" align="end" alignItemWithTrigger={false}>
      {steps.map((step,i)=><SelectItem key={step.id} value={step.id}>{i+1}. {step.title}</SelectItem>)}
    </SelectContent>
  </Select>;
}

