        <span aria-live="polite">{visible.length}/{kneeStructures.length} visible</span>
      </div>
      {!supplement && <SpecimenMotorExplorer definition={specimen} selectedId={selectedId} disabled={!!guidance} onSelect={select} onExplore={nerve => {
