export default function LimbSpecimenDialog({ initialRegion, initialLink = noSpecimenLink, onClose,assetBase='' }: { initialRegion: string; initialLink?: ParsedSpecimenLink; onClose: () => void;assetBase?:string }) {
  const resolved = resolveSpecimenLink(initialLink);
  const [ignoreLink, setIgnoreLink] = useState(false);
  const [scope, setScope] = useState<LimbScope>(initialLink.status === 'requested' && Object.hasOwn(limbDefinitions, initialLink.request.scope) ? initialLink.request.scope : initialRegion === 'foot' ? 'foot' : ['pelvis', 'thigh'].includes(initialRegion) ? 'hip-thigh' : 'knee');
  const specimen = limbDefinitions[scope];
  const options=Object.entries(limbDefinitions).map(([value,definition])=>({value,label:definition.label+(value==='whole'?' · larger download':'')}));
  const blocked = !ignoreLink && resolved.status === 'rejected';
  return <Dialog open onOpenChange={(open) => { if (!open) onClose(); }}>
    <DialogContent className="eye-layers-dialog um-knee-dialog" showCloseButton={false}>
      <div className="eye-layer-heading brain-study-heading">
        <div><DialogTitle>Lower limb · independent specimen</DialogTitle>
          <DialogDescription>Right-limb source · Clinical validation pending · Separate from the body atlas</DialogDescription></div>
        <Select value={scope} items={options} onValueChange={(next) => { if (next && Object.hasOwn(limbDefinitions, next)) { setIgnoreLink(true); setScope(next as LimbScope); } }}>
          <SelectTrigger aria-label="Independent specimen region"><SelectValue /></SelectTrigger>
          <SelectContent>{Object.entries(limbDefinitions).map(([key, value]) => <SelectItem key={key} value={key}>{value.label}{key === 'whole' ? ' · larger download' : ''}</SelectItem>)}</SelectContent>
        </Select>
        <Button size="sm" variant="outline" onClick={onClose}><ArrowLeft />Back to atlas</Button>
      </div>
      {blocked ? <section className="um-specimen-link-warning" role="alert">
        <h2>This specimen link cannot be opened</h2>
        <p>{resolved.reason === 'source-changed' || resolved.reason === 'revision-changed' ? 'Its source model or study revision differs from the current specimen.' : resolved.reason === 'topic-unavailable' ? 'The requested teaching topic is not available for this exact source structure.' : 'It is incomplete or does not match the specified structure and study.'} No alternative structure has been selected.</p>
        <p>Choose another region above, or explicitly open the current source view to make a new link.</p>
        <Button variant="outline" onClick={() => setIgnoreLink(true)}>Open current source view</Button>
      </section> : <KneeSpecimenView key={scope} assetBase={assetBase} specimen={specimen} initialNavigation={!ignoreLink && resolved.status === 'ready' ? resolved : undefined}
        studyLink={assetBase?(definition,selectedId,studyId,view)=><SpecimenStudyLink definition={definition} selectedId={selectedId} studyId={studyId} view={view} basePath={containedLimbStudyBase(initialRegion)} reviewAvailable={false}/>:undefined} />}
    </DialogContent>
  </Dialog>;
}

'use client';
import { useMemo, useState } from 'react';
import { Button } from '@/atlas-review/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/atlas-review/components/ui/select';
import { limbMotorGroups } from '@/atlas-review/lib/limb-motor';
import type { BodyCatalog } from './body-types';

export function UpperLimbMotorExplorer({
  catalog,
  region,
  side,
  selectedId,
  disabled,
  onSelect,
  onExplore,
}: {
  catalog: BodyCatalog;
  region: string;
  side: string;
  selectedId: string | null;
  disabled: boolean;
  onSelect: (id: string) => void;
  onExplore: (key: string) => void;
}) {
  const groups = useMemo(
    () => limbMotorGroups(catalog, region, side),
    [catalog, region, side],
  );
  const [choice, setChoice] = useState('');
  const group = groups.find((g) => g.key === choice);
  if (!groups.length || disabled) return null;
  return (
    <details className="body-study-tools body-motor-explorer">
      <summary>Muscles by nerve</summary>
      <p>Typical motor supply · nerves are not modelled.</p>
      {region === 'pelvis' && (
        <p>
          Pelvic-floor and compound perineal records are outside this limb-motor
          scope.
        </p>
      )}
      <Select
        value={group?.key ?? ''}
        onValueChange={(v) => {
          if (groups.some((g) => g.key === v)) setChoice(v!);
        }}
      >
        <SelectTrigger aria-label="Motor nerve group">
          <SelectValue placeholder="Choose a nerve…" />
        </SelectTrigger>
        <SelectContent>
          {groups.map((g) => (
            <SelectItem key={g.key} value={g.key}>
              {g.label} · {g.targets.length}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      {group && (
        <UpperLimbMotorDetails
          group={group}
          selectedId={selectedId}
          onSelect={onSelect}
          onExplore={onExplore}
        />
      )}
    </details>
  );
}

export function UpperLimbMotorDetails({
  group,
  selectedId,
  onSelect,
  onExplore,
}: {
  group: ReturnType<typeof limbMotorGroups>[number];
  selectedId: string | null;
  onSelect: (id: string) => void;
  onExplore: (key: string) => void;
}) {
  return (
    <>
      <p>{group.note}</p>
      <Button size="sm" variant="outline" onClick={() => onExplore(group.key)}>
        Show muscles & bones
      </Button>
      <p>
        {group.targets.length} source selections in this region and side filter;
        not a complete nerve territory.
