                Cartilage is a navigation landmark, not a muscle tissue parent.
                Attachments, tissue intersections and functional movement need
                specialist review. No phonation, airway, thyroid gland or
                operative plane is simulated.
              </p>
            </>
          ) : isPancreatic ? (
            <>
              <p>
                The pancreatic duct and singleton IS-A duct-tree component are
                shown once each. In the source PART-OF index, the duct-tree
                group includes both components. No accessory duct has been
                inferred from these labels.
              </p>
              <p>
                The optional envelope uses one existing surface. A
                near-coincident parenchymal alternative is withheld; it is not
                presented as a separable tissue layer.
              </p>
              <p>
                Colour and separation distinguish source surfaces, not flow, an
                open lumen, an established junction or a papillary opening. CT,
                MRI and ultrasound matching remain unvalidated.
              </p>
            </>
          ) : isVisual ? (
            <>
              <p>
                Three source surfaces: one optic chiasm and two optic tracts.
                The chiasm retains two closed halves under one label; its seam
                does not show crossing axons.
              </p>
              <p>
                Optic nerves, optic radiations, fibre pathways and functional
                visual-field maps are not supplied by this study. Source tracts
                sit close to both lateral and medial geniculate surfaces; no
                termination or connection is validated.
              </p>
              <p>
                Optional landmarks are orientation only and disappear during
                separation. Colours identify surfaces, not visual fields or MRI
                signal.
              </p>
            </>
          ) : isRenal ? (
            <>
              <p>
                Four right-sided or three left-sided vessel groups preserve the
                supplied source geometry. Arterial red and venous blue
                distinguish vessel types, not flow, oxygenation or scan signal.
              </p>
              <p>
                Kidney cortex, medulla, calyces and pelvis are not individually
                represented. The left inferior suprarenal artery and overlapping
                alternative renal trunks are excluded. Source group components
                are not certified connected lumens or surgical planes.
              </p>
            </>
          ) : isHepatic ? (
            <>
              <p>
                Seven branch groups reuse 48 existing source files. The optional
                tissue context retains the other nine liver files unchanged,
                including source defects and internal remnants.
              </p>
              <p>
                Source segment VI and VII surfaces have nearly identical extents
                with substantial sampled near-contact; segment VIII contains two
                region surfaces. Individual segment labels are withheld. No
                segment has been relabelled, reconstructed or merged into a
                clinical territory.
              </p>
              <p>
                Arterial red, portal blue, biliary green and tributary purple
                distinguish source groups, not oxygenation or flow. The single
                middle-hepatic tributary is not complete venous outflow.
              </p>
            </>
          ) : isPulmonary ? (
            <>
              <p>
                Each selectable item combines the existing airway and vessel
                files assigned to one lobe in the source table. Colours
                distinguish groups, not oxygenation or tissue types.
              </p>
              <p>
                No lung tissue envelope, fissure surface, alveoli or complete
                bronchopulmonary segment is demonstrated. The left upper group
                retains one duplicate source face. Both source geometry and
                anatomical membership need specialist review.
              </p>
              <p>
                Optional airway landmarks reuse the trachea and the main
                bronchus on this side. Original bronchial remnants and duplicate
                faces remain; these are not measured lumen boundaries or proof
                of uninterrupted airway continuity.
              </p>
            </>
          ) : isCardiac ? (
            <>
              <p>
                Four source cavity shapes, not solid heart chambers, measured
                blood volumes or a registered cardiac scan. Colours distinguish
                spaces, not oxygenation or scan signal.
              </p>
              <p>
                Only the two atrial walls are available as faint context. Source
                mappings for ventricular walls, papillary muscles and the mitral
                valve contain overlapping identities and are excluded from this
                study pending adjudication. Valves, chordae and conduction
                pathways are not demonstrated.
              </p>
            </>
          ) : isCerebral ? (
            <>
              <p>
                These are supplied cortical regions, not a complete cortex.
                Eight original lobe representations and two insulae are
                supplemented by four separately labelled superior temporal
                subdivisions from the same source version.
              </p>
              <p>
                The added parts were absent from the original brain. Reference
                surfaces agree in source coordinates, but this is not clinical
                registration. Small detached frontal components remain
                unchanged. Limbic lobes, full white matter and functional
                territories are not independently delineated.
              </p>
            </>
          ) : isBrainstem ? (
            <>
              <p>
                Four source-table compounds and two supplied inferior collicular
                brachia, not proof of complete anatomy. Original source surfaces
                are retained. Colours distinguish structures, not MRI signal or
                functional territories.
              </p>
              <p>
                Individual fibres, internal nuclei and cerebellar lobules are
                not independently segmented. Superior brachia are withheld
                because their source side labels conflict with their
                coordinates. The pons source retains tiny disconnected remnants
                and duplicate faces; it has not been repaired or clinically
                validated.
              </p>
            </>
          ) : (
            <>
              <p>
                Ventricles contain cerebrospinal fluid; coloured shapes
                represent spaces, not solid tissue. Aqueduct, foramina,
                subdivisions and flow are not independently modelled.
              </p>
            </>
          )}
          <p>
            No CT/MRI correspondence, diagnostic measurement or clinical
            approval is provided.{' '}
            {isCoronaryVenous ? (
              'The main heart aggregate is excluded from this study at every visibility state.'
            ) : isCricothyroid ? (
              'Cartilage landmarks are optional orientation surfaces. Separation is a teaching layout, not muscle action.'
            ) : isRenal ? (
              'The kidney surface is optional orientation context; it does not define the vascular lumen or tissue territories.'
            ) : (
              <>
                The main{' '}
                {isPancreatic
                  ? 'pancreas aggregate'
                  : isHepatic
                    ? 'liver aggregate'
                    : isPulmonary
                      ? 'lung'
                      : isCardiac
                        ? 'heart'
                        : 'brain'}{' '}
                is not rendered over these components.
              </>
            )}
          </p>
          {(isCoronaryVenous
            ? coronaryVenousReferences
            : isCricothyroid
            ? cricothyroidReferences
            : isPancreatic
              ? pancreaticReferences
              : isVisual
                ? visualPathwayReferences
                : isRenal
                  ? renalReferences
                  : isHepatic
                    ? [hepaticReference]
                    : isPulmonary
                      ? pulmonaryReferences
                      : isCardiac
                        ? [cardiacReference]
                        : isCerebral
                          ? cerebralReferences
                          : isBrainstem
                            ? brainstemReferences
                            : [ventricleReference]
          ).map((href, i) => (
            <p key={href}>
              <a href={href} target="_blank" rel="noreferrer">
                {isCoronaryVenous
                  ? 'Cardiac venous anatomy'
                  : isCricothyroid
                  ? 'Laryngeal anatomy'
                  : isPancreatic
                    ? 'NCI pancreatic anatomy'
                    : isRenal
                      ? 'Renal anatomy'
                      : isHepatic
                        ? 'NCI digestive anatomy'
                        : isPulmonary
                          ? 'NCI lung anatomy'
                          : `University ${isCardiac ? 'cardiac anatomy' : 'neuroanatomy'}`}{' '}
                reference {i + 1}
              </a>
            </p>
          ))}
          <p>{ventricleCatalog.credit}</p>
          <p>
            {isCricothyroid
              ? 'The display derivative omits 12 specifically audited faces from six detached, reversed duplicate-face islands. All retained coordinates, triangles and winding are unchanged; raw originals are preserved. Display normals and colours are adapted. This cleanup is not anatomical validation.'
              : 'Source components separated, transformed, normal-smoothed and recoloured; no triangles intentionally removed or coordinates reconstructed. Context reuses existing source surfaces.'}
          </p>
          <a
            href="https://creativecommons.org/licenses/by/4.0/"
            target="_blank"
            rel="noreferrer"
          >
            CC BY 4.0 licence
          </a>
        </details>
      </aside>
    </div>
  );
}

function LegacyVentricles({
  parent,
  educationCatalog,
  onClose,
  initialStudy,
  initialSelectedId,
  initialTeachingTopic,
  initialGuidedLearningExpanded = false,
  assetBase = '',
}: {
  parent: BodyStructure;
  educationCatalog?: BodyCatalog;
  onClose: () => void;
  initialStudy?: ComponentStudy;
  initialSelectedId?: string;
  initialTeachingTopic?: NestedImagingTopic;
  initialGuidedLearningExpanded?: boolean;
  assetBase?: string;
}) {
  const isCardiac = cardiacFor(parent).length > 0;
  const isCoronaryVenous = coronaryVenousFor(parent).length === 2;
  const isPulmonary = pulmonaryFor(parent).length > 0;
  const isHepatic = hepaticFor(parent).length > 0;
  const isRenal = renalFor(parent).length > 0;
  const isPancreatic = pancreaticFor(parent).length > 0;
  const isCricothyroid = cricothyroidFor(parent).length > 0;
  const startingStudy =
    isCoronaryVenous && initialStudy === 'coronary-venous'
      ? 'coronary-venous'
      : isCricothyroid || initialStudy === 'cricothyroid'
      ? 'cricothyroid'
      : isPancreatic || initialStudy === 'pancreatic'
        ? 'pancreatic'
        : isRenal
          ? 'renal'
          : isHepatic
            ? 'hepatic'
            : isPulmonary
              ? 'pulmonary'
              : isCardiac
                ? 'cardiac'
                : initialStudy === 'cardiac' ||
                    initialStudy === 'coronary-venous' ||
                    initialStudy === 'pulmonary' ||
                    initialStudy === 'hepatic' ||
                    initialStudy === 'renal'
                  ? 'brainstem'
                  : (initialStudy ?? 'brainstem');
  const [study, setStudy] = useState<ComponentStudy>(startingStudy);
  return (
    <Dialog
      open
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
    >
      <DialogContent className="eye-layers-dialog" showCloseButton={false}>
        <header className="eye-layer-heading brain-study-heading">
          <div>
            <DialogTitle>
              {isCricothyroid || study === 'cricothyroid'
                ? 'Larynx · cricothyroid muscle parts'
                : isPancreatic || study === 'pancreatic'
                  ? 'Pancreas · duct dissection'
                  : isRenal
                    ? `${parent.name} · vascular relationships`
                    : isHepatic
                      ? 'Liver · internal branch dissection'
                      : isPulmonary
                        ? `${parent.name} · branch dissection`
                      : isCardiac
                          ? study === 'coronary-venous'
                            ? 'Heart · coronary venous parts'
                            : 'Heart · chamber spaces'
                          : 'Brain · source dissection'}
            </DialogTitle>
            <DialogDescription>
              Source-based anatomy studies. Clinical validation pending.
            </DialogDescription>
          </div>
          {isCardiac && isCoronaryVenous && (
            <Select value={study} onValueChange={(value) => {
              if (value === 'cardiac' || value === 'coronary-venous') setStudy(value);
            }}>
              <SelectTrigger aria-label="Heart dissection study">
                <SelectValue>{study === 'coronary-venous' ? 'Coronary venous parts' : 'Chamber spaces'}</SelectValue>
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="cardiac">Chamber spaces</SelectItem>
                <SelectItem value="coronary-venous">Coronary venous parts</SelectItem>
              </SelectContent>
            </Select>
          )}
          {!isCardiac &&
            !isPulmonary &&
            !isHepatic &&
            !isRenal &&
            !isCricothyroid &&
            study !== 'cricothyroid' &&
            study !== 'pancreatic' && (
              <Select
                value={study}
                onValueChange={(v) => {
                  if (
                    v === 'brainstem' ||
                    v === 'ventricles' ||
                    v === 'cerebral' ||
                    v === 'visual-pathway'
                  )
                    setStudy(v);
                }}
              >
                <SelectTrigger aria-label="Brain dissection study">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="brainstem">
                    Brainstem and cerebellum
                  </SelectItem>
                  <SelectItem value="ventricles">Ventricular spaces</SelectItem>
                  <SelectItem value="cerebral">Cerebral regions</SelectItem>
                  <SelectItem value="visual-pathway">
                    Optic chiasm and tracts
                  </SelectItem>
                </SelectContent>
              </Select>
            )}
          <Button variant="outline" onClick={onClose}>
            <ArrowLeft /> Back to atlas
          </Button>
        </header>
        <VentricularView
          assetBase={assetBase}
          educationCatalog={educationCatalog}
          key={`${parent.id}:${study}`}
          parent={parent}
          study={study}
          initialGuidedLearningExpanded={study === startingStudy ? initialGuidedLearningExpanded : false}
          initialSelectedId={
            study === startingStudy ? initialSelectedId : undefined
          }
          initialTeachingTopic={
            study === startingStudy ? initialTeachingTopic : undefined
          }
        />
      </DialogContent>
    </Dialog>
  );
}

export default function Ventricles(props: {
  parent: BodyStructure;
  educationCatalog?: BodyCatalog;
  onClose: () => void;
  initialStudy?:
    | ComponentStudy
    | 'femoral-components'
    | 'cranial-artery-components';
  initialSelectedId?: string;
  initialTeachingTopic?: NestedImagingTopic;
  initialGuidedLearningExpanded?: boolean;
  assetBase?: string;
}) {
  const { initialStudy, educationCatalog, initialGuidedLearningExpanded, ...rest } = props;
  if (
    initialStudy === 'cranial-artery-components' ||
    (!initialStudy && cranialArteryComponentsFor(props.parent).length)
  )
    return <FemoralComponents {...rest} educationCatalog={educationCatalog} study="cranial-artery-components" />;
  if (
    initialStudy === 'femoral-components' ||
    (!initialStudy && femoralComponentsFor(props.parent).length)
  )
    return <FemoralComponents {...rest} educationCatalog={educationCatalog} />;
  return <LegacyVentricles {...rest} educationCatalog={educationCatalog} initialStudy={initialStudy}
    initialGuidedLearningExpanded={initialGuidedLearningExpanded} />;
}

'use client';
import { useState } from 'react';
import { WorkspaceOnly } from './atlas-workspace';
import { ChevronRight, Network } from 'lucide-react';
import { Button } from '@/atlas-review/components/ui/button';
import { Checkbox } from '@/atlas-review/components/ui/checkbox';
import { Switch } from '@/atlas-review/components/ui/switch';
import { bodySystems, type BodyStructure } from './body-types';
import { vesselVisibilityGroups } from '@/atlas-review/lib/vessel-visibility';
import type { VesselKind } from '@/atlas-review/lib/anatomy-vessels';

type VesselControlsProps = {
  structures: BodyStructure[]; visibleIds: string[]; enabled: boolean; disabled: boolean;
  onEnabled: (value: boolean) => void;
  onVisibility: (kind: VesselKind, show: boolean) => void;
  canUndo: boolean; canRedo: boolean; onUndo: () => void; onRedo: () => void;
};
export function VesselVisibilityOptions({ structures, visibleIds, enabled, disabled, onVisibility, canUndo, canRedo, onUndo, onRedo }: VesselControlsProps) {
  const groups = vesselVisibilityGroups(structures, visibleIds);
  return <fieldset className="vessel-system-options" aria-label="Vessel visibility">
    {groups.map(group => <label key={group.kind} className="vessel-system-option">
      <Checkbox checked={group.shown === group.total} indeterminate={group.shown > 0 && group.shown < group.total}
        disabled={disabled || !enabled} aria-label={`Show ${group.label.toLowerCase()}`}
        onCheckedChange={value => { if (!disabled && enabled) onVisibility(group.kind, value); }} />
      <span>{group.label}</span><small>{group.shown}/{group.total}</small>
    </label>)}
    <WorkspaceOnly modes={['dissect']}><div className="vessel-system-history">
      <Button type="button" size="sm" variant="outline" disabled={disabled || !canUndo}
        onClick={() => { if (!disabled && canUndo) onUndo(); }}>Undo</Button>
      <Button type="button" size="sm" variant="outline" disabled={disabled || !canRedo}
        onClick={() => { if (!disabled && canRedo) onRedo(); }}>Redo</Button>
    </div></WorkspaceOnly>
    <p>{enabled ? 'Show or hide this vessel type in the current region and side.' : 'Turn on Vessels to change these groups.'}</p>
  </fieldset>;
}
export function VesselSystemControl(props: VesselControlsProps) {
  const { structures, visibleIds, enabled, disabled, onEnabled } = props;
  const [open, setOpen] = useState(false);
  const groups = vesselVisibilityGroups(structures, visibleIds);
  const total = groups.reduce((n, group) => n + group.total, 0);
  return <div className={`body-vessel-system ${enabled ? 'active' : ''}`}>
    <Network style={{ color: bodySystems.vessels.color }} />
    <Button type="button" variant="ghost" className="vessel-system-expand"
      aria-label="Vessels: artery and vein controls" aria-expanded={open}
      disabled={disabled || total === 0} onClick={() => { if (!disabled) setOpen(value => !value); }}>
      <span>Vessels <small>{total}</small></span>
      <ChevronRight aria-hidden="true" className={open ? 'expanded' : ''} />
    </Button>
    <Switch checked={enabled} disabled={disabled || total === 0}
      onCheckedChange={value => { if (!disabled) onEnabled(value); }} aria-label="Show Vessels" />
    {open && <VesselVisibilityOptions {...props} />}
  </div>;
}

'use client';
import {Component,useId,useState,type ReactNode} from 'react';
import dynamic from 'next/dynamic';
import {regionalTours} from '@/atlas-review/lib/regional-tours';
import {nestedGuidedStudyOptions} from '@/atlas-review/lib/nested-guided-learning';
import type {BodyCatalog} from './body-types';
import type {PausedTourImaging} from '@/atlas-review/lib/paused-tour-imaging';
import {RegionalGuidedLearning} from './regional-guided-learning';
import './whole-body-guided-learning.css';

// Selecting a nested tour must not eagerly load its 3D/teaching workbench
// for every region. Use the same deferred boundary as manual eye exploration.
const nestedLoadFailure='This tour could not load. Choose another tour or Exit tour.';
class NestedTourLoadBoundary extends Component<{children:ReactNode},{failed:boolean}> {
  state={failed:false};
  static getDerivedStateFromError(){return {failed:true};}
  render(){return this.state.failed?<p role="alert">{nestedLoadFailure}</p>:this.props.children;}
}
const EyeLayerView=dynamic(()=>import('./eye-layers').then(module=>module.EyeLayerView),{ssr:false,
  loading:({error})=>error?<p role="alert">{nestedLoadFailure}</p>:<p role="status">Loading eye layers…</p>});
const VentricularView=dynamic(()=>import('./ventricles').then(module=>module.VentricularView),{ssr:false,
  loading:({error})=>error?<p role="alert">{nestedLoadFailure}</p>:<p role="status">Loading anatomy spaces…</p>});

// Whole-body tours explicitly declare their same-catalog regional union.
// Regional membership is never rewritten, nor independent specimens combined.
const order=['whole-body','head-neck','spine','thorax','abdomen','pelvis','shoulder-arm','forearm','hand','thigh','leg','foot'];
const regionTitle=(region:string)=>region==='whole-body'?'Whole body':region.split('-').map(word=>word[0].toUpperCase()+word.slice(1)).join(' ');
export const wholeBodyTourOptions=order.flatMap(region=>regionalTours.filter(t=>t.region===region));

export function WholeBodyGuidedLearning({catalog,assetBase,onExit,region='whole-body',pausedImaging}:{catalog:BodyCatalog;assetBase?:string;onExit:()=>void;region?:string;pausedImaging?:PausedTourImaging}) {
  const labelId=useId();
  const [query,setQuery]=useState('');
  const [regionFilter,setRegionFilter]=useState('all');
  const [pauseRequest,setPauseRequest]=useState(0);
  const pauseForLibrary=()=>setPauseRequest(request=>request+1);
  const regional=region==='whole-body'?wholeBodyTourOptions:wholeBodyTourOptions.filter(t=>t.region===region);
  const nested=nestedGuidedStudyOptions(catalog,region);
  const options=order.flatMap(r=>[
    ...regional.filter(t=>t.region===r).map(t=>({id:t.id,title:t.title,region:t.region,tour:t,eye:null})),
    ...nested.filter(t=>t.region===r).map(t=>({id:t.id,title:t.title,region:t.region,tour:null,eye:t})),
  ]);
  const [tourId,setTourId]=useState(options[0]?.id??'');
  const tour=options.find(t=>t.id===tourId)??options[0];
  if(!tour)return <section aria-label="Guided tour library"><p role="status">No guided tours are available for this region.</p><button type="button" onClick={onExit}>Exit tour</button></section>;
  const discover=region==='whole-body';
  const search=query.trim().toLocaleLowerCase();
  const visible=discover?options.filter(option=>
    (regionFilter==='all'||option.region===regionFilter)&&
    (!search||[option.title,regionTitle(option.region),
      ...(option.tour?.steps.map(step=>step.title)??option.eye?.guide.steps.map(step=>step.title)??[])]
      .some(value=>value.toLocaleLowerCase().includes(search)))):options;
  const filtersActive=!!query||regionFilter!=='all';
  const currentVisible=visible.some(option=>option.id===tour.id);
  return <section className="whole-body-guided-learning" aria-label="Guided tour library">
    <div className="whole-body-tour-picker" onFocusCapture={pauseForLibrary} onPointerDownCapture={pauseForLibrary}>
      <div className="whole-body-tour-choice">
        <label htmlFor={`${labelId}-tour`}>Choose a tour</label>
        <select id={`${labelId}-tour`} aria-label="Choose a tour" value={tour.id} disabled={!visible.length} onChange={event=>{
          const id=event.target.value;
          if(visible.some(option=>option.id===id)&&id!==tour.id){pausedImaging?.suspend();setTourId(id);}
        }}>
          {!currentVisible&&<option value={tour.id} disabled>Current tour: {tour.title} (outside filters)</option>}
          {visible.map(option=><option key={option.id} value={option.id}>{option.title}</option>)}
        </select>
      </div>
      {discover&&<details className="whole-body-tour-discovery" onToggle={event=>{if(event.currentTarget.open)pauseForLibrary();}}>
        <summary>Find a tour{filtersActive?' · filtered':''}</summary>
        <div className="whole-body-tour-filters">
          <label htmlFor={`${labelId}-search`}>Search tours</label>
          <input id={`${labelId}-search`} type="search" value={query} onChange={event=>setQuery(event.target.value)} placeholder="Title, region or step"/>
          <label htmlFor={`${labelId}-region`}>Region</label>
          <select id={`${labelId}-region`} value={regionFilter} onChange={event=>setRegionFilter(event.target.value)}>
            <option value="all">All regions</option>
            {order.filter(r=>options.some(option=>option.region===r)).map(r=><option key={r} value={r}>{regionTitle(r)}</option>)}
          </select>
          {filtersActive&&<button type="button" onClick={()=>{setQuery('');setRegionFilter('all');}}>Clear filters</button>}
        </div>
        <p className="whole-body-tour-results" role="status">{visible.length?`${visible.length} ${visible.length===1?'tour':'tours'} available`:'No tours match. Clear filters to see all tours.'}</p>
      </details>}
    </div>
    {/* A new key discards old timers, step, readiness, reading and camera state.
        The next tour waits for its own sources and an explicit Start action. */}
    {tour.tour ? <RegionalGuidedLearning key={`${tour.id}:${tour.tour.revision}`} catalog={catalog} tour={tour.tour} assetBase={assetBase} pausedImaging={pausedImaging} pauseRequest={pauseRequest} onExit={onExit}/>
      : tour.eye ? <div className="whole-body-nested-guidance" key={`${tour.id}:${tour.eye.parentHash}:${tour.eye.sourceHash}:${JSON.stringify(tour.eye.guide)}`}>
        <header><h2>{tour.title}</h2><button type="button" onClick={onExit}>Exit tour</button></header>
        <NestedTourLoadBoundary>
          {tour.eye.kind==='eye'?<EyeLayerView parent={tour.eye.parent} educationCatalog={catalog} assetBase={assetBase} initialGuidedLearningExpanded/>
            :<VentricularView parent={tour.eye.parent} study={tour.eye.kind} educationCatalog={catalog} assetBase={assetBase} initialGuidedLearningExpanded/>}
        </NestedTourLoadBoundary>
      </div> : null}
  </section>;
}

'use client';
import { useCallback, useMemo, useRef, useState } from 'react';
import type { WorkspaceMode } from '@/atlas-review/lib/atlas-navigation';

/** Local display snapshots only. Selection, teaching, entitlements and scans are not copied. */
export function useWorkspaceSession<T>(capture: () => T, restore: (state: T) => void, initial: (mode: WorkspaceMode) => T) {
  const [mode, setMode] = useState<WorkspaceMode>('explore');
  const saved = useRef<Partial<Record<WorkspaceMode, T>>>({});
  const current = useRef({ mode, capture, restore, initial });
  current.current = { mode, capture, restore, initial };
  const chooseMode = useCallback((next: WorkspaceMode) => {
    const active = current.current;
    if (next === active.mode) return;
    // Practice is a temporary working view; never overwrite the saved learning modes.
    if (active.mode !== 'practice') saved.current[active.mode] = structuredClone(active.capture());
    if (next !== 'practice') active.restore(structuredClone(saved.current[next] ?? active.initial(next)));
    current.current.mode = next;
    setMode(next);
  }, []);
  return useMemo(() => ({ mode, chooseMode }), [mode, chooseMode]);
}

/* oxlint-disable next/no-html-link-for-pages -- Sites dispatch owns sign-in; use top-level, non-prefetched navigation. */
export type ReviewSignInTarget =
  | { scope: 'shoulder' | 'body'; structure: string | null }
  | { scope: 'nested'; parent: string; study: string; structure: string; source: string }
  | { scope: 'specimens'; specimen: string; structure: string };

/** Fixed local routes only. No return URL, user identity, draft or approval is
 * accepted from the caller; the destination revalidates its source selection. */
export function reviewSignInHref(target: ReviewSignInTarget): string {
  let path: string;
  const params = new URLSearchParams();
  switch (target.scope) {
    case 'shoulder': path = '/workspace/atlas-review/shoulder'; break;
    case 'body': path = '/workspace/atlas-review/body'; break;
    case 'nested':
      path = '/workspace/atlas-review/nested';
      params.set('parent', target.parent);
      params.set('study', target.study);
      params.set('source', target.source);
      break;
    case 'specimens':
      path = '/workspace/atlas-review/specimens';
      params.set('specimen', target.specimen);
      break;
    default: throw new Error('Unknown review scope');
  }
  if (target.structure) params.set('structure', target.structure);
  const query = params.toString();
  return '/signin-with-chatgpt?' + new URLSearchParams({ return_to: path + (query ? '?' + query : '') });
}

export function ReviewSignInLink({ target, children = 'Sign in to save reviews' }: {
  target: ReviewSignInTarget; children?: React.ReactNode;
}) {
  return <a href={reviewSignInHref(target)} target="_top">{children}</a>;
}

