import {
  parseSavedBodyReview,
  type SavedBodyReview,
  type BodyReviewTrack,
} from './body-review-decisions';

type EventRow = {
  payload: string;
  version: number;
  structure_id: string;
  track: string;
};
function parseRow(row: EventRow, id: string, track?: BodyReviewTrack) {
  const parsed = parseSavedBodyReview(JSON.parse(row.payload));
  if (
    row.structure_id !== id ||
    parsed.structureId !== id ||
    row.track !== parsed.track ||
    (track && parsed.track !== track) ||
    row.version !== parsed.version
  )
    throw new Error('Body review row does not match its storage key');
  return parsed;
}
export async function latestBodyReviews(
  db: D1Database,
  user: string,
  id: string,
) {
  const rows = await db
    .prepare(`SELECT payload,version,structure_id,track FROM atlas_personal_body_review_events
    WHERE user_id=?1 AND structure_id=?2 AND (track,version) IN
      (SELECT track,MAX(version) FROM atlas_personal_body_review_events WHERE user_id=?1 AND structure_id=?2 GROUP BY track)`)
    .bind(user, id)
    .all<EventRow>();
  return rows.results.map((row) => parseRow(row, id));
}
export async function bodyReviewHistory(
  db: D1Database,
  user: string,
  id: string,
  track: BodyReviewTrack,
  before = 2147483648,
) {
  const rows = await db
    .prepare(
      'SELECT payload,version,structure_id,track FROM atlas_personal_body_review_events WHERE user_id=?1 AND structure_id=?2 AND track=?3 AND version<?4 ORDER BY version DESC LIMIT 20',
    )
    .bind(user, id, track, before)
    .all<EventRow>();
  return rows.results.map((row) => parseRow(row, id, track));
}
export async function appendBodyReview(
  db: D1Database,
  user: string,
  review: SavedBodyReview,
  expected: number,
) {
  // One atomic statement: stale clients cannot overwrite or create parallel versions.
  if (review.version !== expected + 1)
    throw new Error('Invalid append version');
  const record = parseSavedBodyReview(review);
  const result = await db
    .prepare(`INSERT INTO atlas_personal_body_review_events(user_id,structure_id,track,version,payload,saved_at)
    SELECT ?1,?2,?3,?4,?5,?6 WHERE COALESCE((SELECT MAX(version) FROM atlas_personal_body_review_events
    WHERE user_id=?1 AND structure_id=?2 AND track=?3),0)=?7`)
    .bind(
      user,
      record.structureId,
      record.track,
      record.version,
      JSON.stringify(record),
      record.savedAt,
      expected,
    )
    .run();
  return result.meta.changes === 1;
}

import { structures } from '../app/anatomy-data';
import { bodyReviewSummaries, bodyReviewSearchAliases } from './body-review-material';
import { normalizeAnatomySearch, anatomySearchWordMatches } from './anatomy-search';
import { nestedReviewRows } from './nested-review-material';
import { specimenReviewRows } from './specimen-review-material';
import bindings from '../content/nested-review-bindings.json';
import { resolveReviewPilot } from './clinical-review-pilot';

export type ClinicalReviewScope = 'shoulder' | 'body' | 'nested' | 'specimens';
export const clinicalReviewScopes = [
  { id: 'shoulder', label: 'Dedicated shoulder', description: 'Dedicated right-shoulder source worksheets.', href: '/workspace/atlas-review/shoulder' },
  { id: 'body', label: 'Whole body', description: 'Whole-body source structure worksheets.', href: '/workspace/atlas-review/body' },
  { id: 'nested', label: 'Internal anatomy', description: 'Structures within organs, with their exact source context.', href: '/workspace/atlas-review/nested' },
  { id: 'specimens', label: 'Independent specimens', description: 'Separate source specimen and surface worksheets.', href: '/workspace/atlas-review/specimens' },
] as const;
export type ClinicalReviewEntry = {
  key: string; scope: ClinicalReviewScope; name: string; context: string;
  id: string; laterality: string; href: string;
};
const link = (path: string, params: Record<string, string>) => path + '?' + new URLSearchParams(params).toString();
const scopeOrder = (scope: ClinicalReviewScope) => clinicalReviewScopes.findIndex(s => s.id === scope);
const compare = (a: string, b: string) => a < b ? -1 : a > b ? 1 : 0;
const nestedEntries: ClinicalReviewEntry[] = nestedReviewRows.flatMap(row => {
  const groups = bindings.groups.filter(g => g.key === row.key && g.parent.id === row.parentId && g.study === row.study);
  if (groups.length !== 1) throw Error('Nested review binding does not match public row');
  const group = groups[0];
  if (group.selections.length !== row.surfaces.length) throw Error('Nested review selections do not match public row');
  return row.surfaces.map(surface => {
    const selections = group.selections.filter(s => s.id === surface.id);
    if (selections.length !== 1 || !/^[a-f0-9]{64}$/.test(selections[0].sourceToken)) throw Error('Missing exact nested review source token');
    return { key: 'nested:' + JSON.stringify([row.key, surface.id]), scope: 'nested', name: surface.name,
      context: row.name + ' · ' + row.study, id: surface.id, laterality: surface.laterality,
      href: link('/workspace/atlas-review/nested', { parent: row.parentId, study: row.study, structure: surface.id, source: selections[0].sourceToken }) };
  });
});
if (bindings.groups.length !== nestedReviewRows.length) throw Error('Nested review groups do not match public rows');
/** Public source metadata only: no private records, status counts or approvals. */
export const clinicalReviewEntries: readonly ClinicalReviewEntry[] = [
  ...structures.map(s => ({ key: 'shoulder:' + s.id, scope: 'shoulder' as const, name: s.name,
    context: 'Dedicated shoulder · ' + s.region + ' · ' + s.system + ' · ' + (s.sourceFmaIds ?? []).join(' '),
    id: s.id, laterality: s.laterality, href: link('/workspace/atlas-review/shoulder', { structure: s.id }) })),
  ...bodyReviewSummaries.map(s => ({ key: 'body:' + s.id, scope: 'body' as const, name: s.name,
    context: 'Whole body · ' + s.regions.join(' · ') + ' · ' + s.system + ' · ' + s.fmaId,
    id: s.id, laterality: s.laterality, href: link('/workspace/atlas-review/body', { structure: s.id }) })),
  ...nestedEntries,
  ...specimenReviewRows.flatMap(row => row.surfaces.map(s => ({ key: 'specimens:' + JSON.stringify([row.key, s.id]), scope: 'specimens' as const,
    name: s.name, context: row.name + ' · ' + row.key, id: s.id, laterality: s.laterality,
    href: link('/workspace/atlas-review/specimens', { specimen: row.key, structure: s.id }) }))),
].sort((a, b) => scopeOrder(a.scope) - scopeOrder(b.scope) || compare(a.name.toLowerCase(), b.name.toLowerCase()) || compare(a.key, b.key));
if (new Set(clinicalReviewEntries.map(e => e.key)).size !== clinicalReviewEntries.length) throw Error('Duplicate clinical review search key');
const pilotEntries = resolveReviewPilot(clinicalReviewEntries);
const searchableText = new Map(clinicalReviewEntries.map(e => [e.key,
  normalizeAnatomySearch([e.name, e.id, e.context, e.laterality,
    ...(e.scope === 'body' ? bodyReviewSearchAliases(e.id)
      : e.scope === 'shoulder' ? structures.find(s => s.id === e.id)?.synonyms ?? [] : []),
  ].join(' ')),
]));

export type ClinicalReviewSearch = {
  q: string; scope: 'all' | 'pilot' | ClinicalReviewScope; page: number; pageCount: number;
  total: number; entries: ClinicalReviewEntry[]; pageSize: 12;
};
export type ClinicalReviewSearchInput = { q?: unknown; scope?: unknown; page?: unknown };
function query(value: unknown) { return typeof value === 'string' ? value.trim().slice(0, 160) : ''; }
function scope(value: unknown): ClinicalReviewSearch['scope'] {
  if (value === 'pilot') return 'pilot';
  return typeof value === 'string' && clinicalReviewScopes.some(s => s.id === value) ? value as ClinicalReviewScope : 'all';
}
function page(value: unknown) {
  const number = typeof value === 'number' ? value : typeof value === 'string' && /^[1-9]\d*$/.test(value) ? Number(value) : 1;
  return Number.isSafeInteger(number) && number > 0 ? number : 1;
}
export function findClinicalReviewEntries(input: ClinicalReviewSearchInput = {}): ClinicalReviewSearch {
  const q = query(input.q), selectedScope = scope(input.scope), tokens = normalizeAnatomySearch(q).split(/\s+/).filter(Boolean);
  const candidates = selectedScope === 'pilot' ? pilotEntries : clinicalReviewEntries;
  const found = candidates.filter(e => (selectedScope === 'all' || selectedScope === 'pilot' || e.scope === selectedScope)
    && tokens.every(token => anatomySearchWordMatches(searchableText.get(e.key)!, token)));
  const pageCount = Math.max(1, Math.ceil(found.length / 12)), current = Math.min(page(input.page), pageCount);
  return { q, scope: selectedScope, page: current, pageCount, total: found.length,
    entries: found.slice((current - 1) * 12, current * 12).map(e => ({ ...e })), pageSize: 12 };
}
export function clinicalReviewHref(input: ClinicalReviewSearchInput = {}): string {
  const result = findClinicalReviewEntries(input), params = new URLSearchParams();
  if (result.q) params.set('q', result.q);
  if (result.scope !== 'all') params.set('scope', result.scope);
  if (result.page > 1) params.set('page', String(result.page));
  const suffix = params.toString();
  return '/workspace/atlas-review' + (suffix ? '?' + suffix : '');
}

import type { DissectionState } from '@/atlas-review/app/dissection-data';

/** Describe only the removal that the existing history's next Undo reverses. */
export function lastSingleRemoval<T extends { id: string; name: string }>(
  state: DissectionState,
  structures: T[],
): T | null {
  const previous = state.history.at(-1);
  if (
    !previous ||
    previous.stageId !== state.stageId ||
    previous.focusId !== state.focusId
  ) return null;
  const sameIds = (a: string[], b: string[]) =>
    a.length === b.length &&
    new Set(a).size === a.length &&
    new Set(b).size === b.length &&
    a.every((id) => b.includes(id));
  const added = state.removed.filter((id) => !previous.removed.includes(id));
  if (added.length !== 1) return null;
  const id = added[0];
  if (
    !sameIds(state.removed, [...previous.removed, id]) ||
    !sameIds(state.restored, previous.restored.filter((item) => item !== id))
  ) return null;
  const matches = structures.filter((item) => item.id === id);
  return matches.length === 1 ? matches[0] : null;
}

import { nestedBundleHash, nestedPartsFor, type NestedStudy } from './nested-anatomy';
import { sourceCanonical } from './body-source-additions';
import type { BodyStructure } from '../app/body-types';
import bindings from '../content/nested-review-bindings.json';
/** Frozen source token binds parent/child records, both bundles, frame and study.
 * Current server material must match it before opening a selected worksheet. */
export function nestedReviewHref(parent:BodyStructure,study:NestedStudy,child:BodyStructure) {
  const canonical=nestedPartsFor(parent,study).find(s=>s.id===child.id);
  const source=nestedBundleHash(study,child.bundle);
  if(!canonical||!source||sourceCanonical(canonical)!==sourceCanonical(child))return null;
  const group=bindings.groups.find(g=>g.study===study&&g.parent.id===parent.id&&sourceCanonical(g.parent)===sourceCanonical(parent));
  const pin=group?.selections.find(s=>s.id===child.id&&s.childBundleHash===source);
  return pin?'/workspace/atlas-review/nested?'+new URLSearchParams({parent:parent.id,study,structure:child.id,source:pin.sourceToken}).toString():null;
}

import bindings from '../content/nested-review-bindings.json';
import type { nestedReviewRows } from './nested-review-material';

/** Search is a navigation preference, never a review identity or permission. */
export function nestedReviewQuery(value: unknown): string {
  return typeof value === 'string'
    ? value.replace(/[\u0000-\u001f\u007f]/g, '').trim().slice(0, 160)
    : '';
}
export function nestedReviewNavigationTrack(value: unknown): 'geometry' | 'teaching' {
  return value === 'teaching' ? 'teaching' : 'geometry';
}

export function nestedReviewQueue(
  rows: typeof nestedReviewRows,
  key: string,
  query: unknown,
  selected: { nestedKey: string; structureId: string } | null,
  track: unknown = 'geometry',
) {
  const group = rows.find(row => row.key === key);
  const pin = bindings.groups.find(row => row.key === key);
  const q = nestedReviewQuery(query);
  // Unknown/mismatched scopes cannot acquire a neighbour link.
  if (!group || !pin || pin.parent.id !== group.parentId || pin.study !== group.study)
    return { entries: [], index: -1, previous: null, next: null, query: q };
  const entries = group.surfaces.filter(surface =>
    `${surface.name} ${surface.id} ${surface.laterality}`.toLowerCase().includes(q.toLowerCase()),
  ).flatMap(surface => {
    const binding = pin.selections.find(item => item.id === surface.id);
    if (!binding || !/^[a-f0-9]{64}$/.test(binding.sourceToken)) return [];
    let href = `/workspace/atlas-review/nested?parent=${encodeURIComponent(group.parentId)}&study=${encodeURIComponent(group.study)}&structure=${encodeURIComponent(surface.id)}&source=${binding.sourceToken}`;
    if (q) href += '&q=' + encodeURIComponent(q);
    if (nestedReviewNavigationTrack(track) === 'teaching') href += '&t=teaching';
    return [{ ...surface, href }];
  });
  const index = selected?.nestedKey === key
    ? entries.findIndex(entry => entry.id === selected.structureId) : -1;
  return { entries, index, query: q,
    previous: index > 0 ? entries[index - 1] : null,
    next: index >= 0 && index < entries.length - 1 ? entries[index + 1] : null };
}

