import type { BodyStructure, Vec3 } from '@/atlas-review/app/body-types';
import type { BodyLayout } from './body-arrangement';
import { systemOpacity, type InspectionState } from './inspection-state';

export type OriginGuide = {
  id: string;
  start: Vec3;
  end: Vec3;
  bounds: BodyStructure['bounds'];
};

/** A display annotation, never a tissue connection or an anatomical route. */
export function selectedOriginGuide({
  enabled,
  exam,
  layout,
  explode,
  selectedId,
  structures,
  hiddenIds,
  contextIds = [],
  inspection,
  offsets,
  appearance,
}: {
  enabled: boolean;
  exam: boolean;
  layout: BodyLayout;
  explode: number;
  selectedId: string | null;
  structures: BodyStructure[];
  hiddenIds: string[];
  contextIds?: string[];
  inspection: InspectionState;
  offsets: Map<string, { x: number; y: number; z: number }>;
  appearance?: Record<string, { opacity: number }>;
}): OriginGuide | null {
  if (
    !enabled ||
    exam ||
    layout === 'tray' ||
    !Number.isFinite(explode) ||
    explode <= 0 ||
    inspection.plane !== 'off' ||
    !selectedId ||
    hiddenIds.includes(selectedId) ||
    contextIds.includes(selectedId)
  )
    return null;
  const structure = structures.find((s) => s.id === selectedId);
  const offset = offsets.get(selectedId);
  if (!structure || !offset) return null;
  const displacement = [offset.x, offset.y, offset.z];
  const opacity =
    systemOpacity(inspection, structure.system, true) *
    (appearance?.[selectedId]?.opacity ?? 1);
  if (
    !displacement.every(Number.isFinite) ||
    !structure.anchor.every(Number.isFinite) ||
    displacement.every((n) => n === 0) ||
    !Number.isFinite(opacity) ||
    opacity < 0.2
  )
    return null;
  return {
    id: selectedId,
    start: [...structure.anchor],
    end: structure.anchor.map((n, i) => n + displacement[i]) as Vec3,
    bounds: structure.bounds,
  };
}

import type { SavedReview, ReviewTrack } from './review-workspace';

type EventRow = { payload: string };
export async function latestReviews(
  db: D1Database,
  userId: string,
): Promise<SavedReview[]> {
  const result = await db
    .prepare(`SELECT e.payload FROM atlas_personal_review_events e
    JOIN (SELECT structure_id,track,MAX(version) AS version FROM atlas_personal_review_events WHERE user_id=?1 GROUP BY structure_id,track) latest
    ON e.structure_id=latest.structure_id AND e.track=latest.track AND e.version=latest.version
    WHERE e.user_id=?1`)
    .bind(userId)
    .all<EventRow>();
  return result.results.map((r) => JSON.parse(r.payload));
}
export async function reviewHistory(
  db: D1Database,
  userId: string,
  id: string,
  track: ReviewTrack,
  before = 2147483647,
) {
  const rows = await db
    .prepare(
      'SELECT payload FROM atlas_personal_review_events WHERE user_id=?1 AND structure_id=?2 AND track=?3 AND version<?4 ORDER BY version DESC LIMIT 20',
    )
    .bind(userId, id, track, before)
    .all<EventRow>();
  return rows.results.map((r) => JSON.parse(r.payload) as SavedReview);
}
export async function appendReview(
  db: D1Database,
  userId: string,
  review: SavedReview,
  expected: number,
) {
  // Atomic optimistic concurrency: no overwrite and no lost edits from another tab.
  const result = await db
    .prepare(`INSERT INTO atlas_personal_review_events(user_id,structure_id,track,version,payload,saved_at)
    SELECT ?1,?2,?3,?4,?5,?6
    WHERE COALESCE((SELECT MAX(version) FROM atlas_personal_review_events WHERE user_id=?1 AND structure_id=?2 AND track=?3),0)=?7`)
    .bind(
      userId,
      review.structureId,
      review.track,
      review.version,
      JSON.stringify(review),
      review.savedAt,
      expected,
    )
    .run();
  return result.meta.changes === 1;
}

import {
  parseSavedSpecimenReview,
  type SavedSpecimenReview,
  type SpecimenReviewTrack,
} from "./specimen-review";
type Row = {
  payload: string;
  specimen_key: string;
  structure_id: string;
  track: string;
  version: number;
};
export async function specimenReviewHistory(
  db: D1Database,
  user: string,
  key: string,
  id: string,
  track: SpecimenReviewTrack,
  before = 2147483648,
) {
  const rows = await db
    .prepare(
      `SELECT payload,specimen_key,structure_id,track,version FROM atlas_personal_specimen_review_events
    WHERE user_id=?1 AND specimen_key=?2 AND structure_id=?3 AND track=?4 AND version<?5 ORDER BY version DESC LIMIT 20`,
    )
    .bind(user, key, id, track, before)
    .all<Row>();
  return rows.results.map((row) => {
    const r = parseSavedSpecimenReview(JSON.parse(row.payload));
    if (
      row.specimen_key !== key ||
      row.structure_id !== id ||
      row.track !== track ||
      r.specimenKey !== key ||
      r.structureId !== id ||
      r.track !== track ||
      r.version !== row.version
    )
      throw Error("Stored review scope mismatch.");
    return r;
  });
}
export async function appendSpecimenReview(
  db: D1Database,
  user: string,
  review: SavedSpecimenReview,
  expected: number,
) {
  const r = parseSavedSpecimenReview(review);
  if (r.version !== expected + 1) throw Error("Invalid append version.");
  const result = await db
    .prepare(
      `INSERT INTO atlas_personal_specimen_review_events(user_id,specimen_key,structure_id,track,version,payload,saved_at)
    SELECT ?1,?2,?3,?4,?5,?6,?7 WHERE COALESCE((SELECT MAX(version) FROM atlas_personal_specimen_review_events
    WHERE user_id=?1 AND specimen_key=?2 AND structure_id=?3 AND track=?4),0)=?8`,
    )
    .bind(
      user,
      r.specimenKey,
      r.structureId,
      r.track,
      r.version,
      JSON.stringify(r),
      r.savedAt,
      expected,
    )
    .run();
  return result.meta.changes === 1;
}

