  const [message,setMessage]=useState(`Loading your private ${context.kind} history…`),[error,setError]=useState(false),[downloadMessage,setDownloadMessage]=useState('');
  const active=useRef(true),inFlight=useRef(false),hasLoaded=useRef(false),generation=useRef(0),confirmedHistory=useRef(false),dirtyRef=useRef(false),baseline=useRef(blankFacialDecision(context));
