'use client';

import {useEffect,useRef,useState} from 'react';
import {clinicalReviewFetch} from '../lib/clinical-review-fetch';
import {blankHeadTeachingDraft,headTeachingDraftStale,validateHeadTeachingDraft,type HeadTeachingDraft,type HeadTeachingDraftContext,type SavedHeadTeachingDraft} from '../lib/head-teaching-review-contract';
import {confirmHeadTeachingSave,parseHeadTeachingHistory,HeadTeachingSourceChangedError} from '../lib/head-teaching-review-client';
import {headTeachingWorkingCopy,downloadHeadWorkingCopy} from '../lib/head-review-working-copy';
import './head-teaching-review-notes.css';

async function checkedResponse(response:Response){
  const value:unknown=await response.json();
  if(!response.ok)throw Error(value&&typeof value==='object'&&'error'in value&&typeof value.error==='string'?value.error:'Request failed. Keep your edits.');
  return value;
}
/** Private corrections only. Checklist completion never confers approval. */
export function HeadTeachingReviewNotes({context}:{context:HeadTeachingDraftContext}){
  const clinical=context.packetId==='head-brainstem-clinical',ventricular=context.packetId==='head-ventricular-clinical',cerebellar=context.packetId==='head-cerebellar-clinical',deepGrey=context.packetId==='head-deep-grey-clinical',lobar=context.packetId==='head-lobar-clinical',hippocampal=context.packetId==='head-hippocampal-clinical';
  const mriClinical=context.packetId==='head-mri-only-clinical',mriQuestions=context.packetId==='head-mri-anatomy-checks';
  const endpoint=clinical?'/api/atlas-review/head-brainstem-clinical':ventricular?'/api/atlas-review/head-ventricular-clinical':cerebellar?'/api/atlas-review/head-cerebellar-clinical':deepGrey?'/api/atlas-review/head-deep-grey-clinical':lobar?'/api/atlas-review/head-lobar-clinical':hippocampal?'/api/atlas-review/head-hippocampal-clinical':mriClinical?'/api/atlas-review/head-mri-only-clinical':mriQuestions?'/api/atlas-review/head-mri-anatomy-checks':'/api/atlas-review/head-learning';
  const headingId=clinical?'brainstem-clinical-notes-title':ventricular?'ventricular-clinical-notes-title':cerebellar?'cerebellar-clinical-notes-title':deepGrey?'deep-grey-clinical-notes-title':lobar?'lobar-clinical-notes-title':hippocampal?'hippocampal-clinical-notes-title':mriClinical?'mri-only-clinical-notes-title':mriQuestions?'mri-anatomy-checks-notes-title':'head-review-notes-title';
  const [draft,setDraft]=useState(()=>blankHeadTeachingDraft(context));
  const [history,setHistory]=useState<SavedHeadTeachingDraft[]>([]);
  const [nextBefore,setNextBefore]=useState<number|null>(null);
  const [version,setVersion]=useState(0),[latest,setLatest]=useState(0);
  const [loaded,setLoaded]=useState(false),[busy,setBusy]=useState(false),[dirty,setDirty]=useState(false),[uncertain,setUncertain]=useState(false);
  const [reloadRequired,setReloadRequired]=useState(false);
  const [message,setMessage]=useState('Loading your private saved history…'),[error,setError]=useState(false);
  const [discard,setDiscard]=useState(false);
  const [downloadMessage,setDownloadMessage]=useState('');
  const active=useRef(true),inFlight=useRef(false),hasLoaded=useRef(false);
  const baseline=useRef(blankHeadTeachingDraft(context)),dirtyRef=useRef(false);
  useEffect(()=>{
    active.current=true;
    return()=>{active.current=false;};
  },[]);
  useEffect(()=>{
    if(!dirty)return;
    const warn=(event:BeforeUnloadEvent)=>{event.preventDefault();event.returnValue='';};
    window.addEventListener('beforeunload',warn);
    return()=>window.removeEventListener('beforeunload',warn);
  },[dirty]);
  const status=(text:string,failed=false)=>{setMessage(text);setError(failed);};
  function downloadWorkingCopy(){
    try{
      downloadHeadWorkingCopy(headTeachingWorkingCopy(context,draft,{baseVersion:loaded?version:null,unsavedChanges:dirty,saveUncertain:uncertain||busy,reloadRequired}));
      setDownloadMessage('Working-copy download requested. Confirm the file was saved and keep it private. Your edits and server-save status are unchanged.');
    }catch{setDownloadMessage('Download could not be started. Keep this page open and copy your notes before leaving.');}
  }
  async function load(before?:number){
    if(inFlight.current)return;
    inFlight.current=true;setBusy(true);
    try{
      const response=await clinicalReviewFetch(endpoint+(before?'?before='+before:''),{cache:'no-store'});
      if([401,403,409].includes(response.status)&&active.current)setReloadRequired(true);
      const value=parseHeadTeachingHistory(await checkedResponse(response),context,before);
      if(!active.current)return;
      setHistory(previous=>before?[...previous,...value.history]:value.history);setNextBefore(value.nextBefore);
      if(!before){
        const newest=value.history[0]?.version??0;
        setLatest(newest);setLoaded(true);
        // Reloading history must not silently rebase or discard an open draft.
        if(!hasLoaded.current){setVersion(newest);setUncertain(false);hasLoaded.current=true;}
        status(dirtyRef.current?'History refreshed; your unsaved edits are unchanged. Compare the latest entry before discarding or starting again.':newest?'History loaded. Load a current saved draft below, or start a fresh draft.':'No saved notes yet. Your first save will create version 1.');
      }
    }catch(caught){if(active.current){setUncertain(true);if(caught instanceof HeadTeachingSourceChangedError)setReloadRequired(true);status(caught instanceof Error?caught.message:'History unavailable. Keep your edits.',true);}}
    finally{inFlight.current=false;if(active.current)setBusy(false);}
  }
  useEffect(()=>{void load();},[]); // Initial account-bound GET; never retries a write.
  function edit(change:Partial<HeadTeachingDraft>){
    setDraft(previous=>({...previous,...change}));dirtyRef.current=true;setDirty(true);setDiscard(false);
  }
  function replace(record?:SavedHeadTeachingDraft){
    if(dirtyRef.current||busy||!loaded||reloadRequired||record&&headTeachingDraftStale(record,context))return;
    const next=record?validateHeadTeachingDraft(record.draft,context):blankHeadTeachingDraft(context);
    setDraft(next);baseline.current=next;setVersion(latest);setUncertain(false);
    status(record?`Loaded version ${record.version} for editing against latest version ${latest}. Saving creates a new entry.`:'Started a fresh draft for the current packet. Previous history is preserved.');
  }
  async function save(){
    if(inFlight.current||!loaded||uncertain||reloadRequired||version!==latest)return;
    let validated:HeadTeachingDraft;
    try{validated=validateHeadTeachingDraft(draft,context);}catch(caught){status(caught instanceof Error?caught.message:'Check your draft.',true);return;}
    inFlight.current=true;setBusy(true);
    try{
      const response=await clinicalReviewFetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({catalogScope:context.catalogScope,packetId:context.packetId,packetRevision:context.packetRevision,headRevision:context.headRevision,checklistVersion:context.checklistVersion,expectedVersion:version,draft:validated})});
      if([401,403].includes(response.status)&&active.current)setReloadRequired(true);
      const saved=confirmHeadTeachingSave(await checkedResponse(response),context,version,validated);
      if(!active.current)return;
      setHistory(previous=>[saved,...previous]);setVersion(saved.version);setLatest(saved.version);setDraft(saved.draft);baseline.current=saved.draft;
      dirtyRef.current=false;setDirty(false);setDiscard(false);setUncertain(false);status(`Saved private version ${saved.version}. This is not clinical sign-off or publication.`);
    }catch(caught){if(active.current){setUncertain(true);status(caught instanceof Error?caught.message:'Save could not be confirmed. Keep your edits and compare history.',true);}}
    finally{inFlight.current=false;if(active.current)setBusy(false);}
  }
  return <section className="head-review-notes" aria-labelledby={headingId}>
    <h2 id={headingId}>{clinical?'Private brainstem clinical notes & corrections':ventricular?'Private ventricular clinical notes & corrections':cerebellar?'Private cerebellar clinical notes & corrections':deepGrey?'Private deep-grey clinical notes & corrections':lobar?'Private cerebral-lobe clinical notes & corrections':hippocampal?'Private hippocampal clinical notes & corrections':mriClinical?'Private MRI-only clinical notes & corrections':mriQuestions?'Private MRI-only anatomy check corrections':'Private review notes & corrections'}</h2>
    {clinical&&<p>Separate clinical packet · midbrain, pons and medulla. These corrections are not part of the original anatomy-notes history.</p>}
    {ventricular&&<p>Clinical packet · lateral, third and fourth ventricles. Corrections are saved with the ventricular packet revision.</p>}
    {cerebellar&&<p>Clinical packet · left/right cerebellar hemispheres and vermis. MRI vermis coverage is partial; no exact matching 3D part or patient-space registration is claimed. Corrections are saved with this independent clinical revision.</p>}
    {deepGrey&&<p>Clinical packet · paired caudate, putamen, globus pallidus and thalamus. Corrections use this independent clinical revision, not the original anatomy or other clinical histories. CT/MRI and reference 3D comparison is semantic, not patient-space registration.</p>}
    {lobar&&<p>Independent clinical packet · paired frontal, parietal, temporal and occipital lobes. Corrections stay with this clinical revision and its eight concepts, separate from anatomy and other clinical histories. CT/MRI and reference 3D comparison is semantic, not patient-space registration.</p>}
    {hippocampal&&<p>Independent clinical packet · left and right hippocampus. Corrections stay with this clinical revision and its two concepts, separate from original anatomy teaching and other clinical histories. CT/MRI and the existing 3D Atlas are separate, unregistered subjects; the saved masks cannot establish sclerosis, epileptogenicity, memory performance, subfield boundaries or volumetry.</p>}
    {mriClinical&&<p>Independent clinical packet · pituitary and corpus callosum. These corrections stay with this clinical revision, separate from MRI teaching, anatomy questions and other clinical histories. No exact CT counterpart is mapped; MRI and the existing 3D Atlas are separate, unregistered subjects.</p>}
    {mriQuestions&&<p>Independent question packet · paired amygdalae, corpus callosum and pituitary. Corrections bind the questions and their complete MRI teaching source, separate from teaching and clinical histories. This is not an exam response or score. No exact CT counterpart or patient-space registration is claimed.</p>}
    <p>Saved only for your signed-in account and institution. These notes do not approve, publish or modify the teaching packet or masks. Name and qualification are self-reported, not verified credentials. Do not enter patient data.</p>
    <p className="head-review-message" role={error?'alert':'status'} aria-live="polite">{message}</p>
    <form onSubmit={event=>{event.preventDefault();void save();}}>
      <fieldset disabled={busy||!loaded}>
        <legend>Current packet · {context.conceptIds.length} linked concepts</legend>
        <div className="head-review-fields">
          <label>Reviewer name (self-reported)<input value={draft.reviewer} maxLength={160} onChange={event=>edit({reviewer:event.target.value})}/></label>
          <label>Qualification (self-reported)<input value={draft.qualification} maxLength={160} onChange={event=>edit({qualification:event.target.value})}/></label>
          <label>Status<select value={draft.status} onChange={event=>edit({status:event.target.value as HeadTeachingDraft['status']})}><option value="draft">Draft notes</option><option value="changes-required">Corrections requested</option></select></label>
          <label>Review scope<textarea value={draft.scope} rows={2} maxLength={1000} placeholder={mriClinical||mriQuestions?'Concept IDs and the MRI/existing 3D aspects inspected':cerebellar?'Concept IDs and the CT/MRI teaching inspected':'Concept IDs and the CT/MRI/3D aspects inspected'} onChange={event=>edit({scope:event.target.value})}/></label>
        </div>
        <details><summary>Checks considered · not an approval checklist</summary><div className="head-review-checks">{context.checklist.map(check=><label key={check.id}><input type="checkbox" checked={draft.checks[check.id]} onChange={event=>edit({checks:{...draft.checks,[check.id]:event.target.checked}})}/><span>{check.label}</span></label>)}</div></details>
        <label className="head-review-notes-field">Notes / requested corrections<textarea value={draft.notes} rows={5} maxLength={8000} placeholder="Describe the structure, source and exact correction. Corrections requested need at least 10 characters." onChange={event=>edit({notes:event.target.value})}/></label>
        <div className="head-review-actions"><button type="submit" disabled={uncertain||reloadRequired||version!==latest}>Save private {draft.status==='changes-required'?'correction request':'draft'}</button><span>{dirty?'Unsaved edits':`Editing from version ${version}`} · packet {context.packetRevision.slice(0,12)}</span></div>
      </fieldset>
    </form>
    {downloadMessage&&<p role="status" aria-live="polite">{downloadMessage}</p>}
    <div className="head-review-actions">
      <button type="button" onClick={downloadWorkingCopy}>Download working copy</button>
      <button type="button" disabled={busy} onClick={()=>void load()}>Refresh saved history</button>
      <button type="button" disabled={busy||!loaded||dirty||reloadRequired} onClick={()=>replace()}>Start fresh draft</button>
      {dirty&&<button type="button" disabled={busy} onClick={()=>setDiscard(true)}>Discard unsaved edits…</button>}
    </div>
    {discard&&<div className="head-review-discard"><p>Discard only the unsaved form edits? Saved history will not be deleted. Copy any text you want to keep first.</p><button type="button" disabled={busy} onClick={()=>{setDraft(baseline.current);dirtyRef.current=false;setDirty(false);setDiscard(false);status('Unsaved edits discarded. Refresh history, then explicitly load a saved draft or start fresh.');}}>Confirm discard</button> <button type="button" onClick={()=>setDiscard(false)}>Keep editing</button></div>}
    {uncertain&&<p>Saving is locked until you compare saved history and explicitly load a current entry or start fresh. If the account, institution or packet changed, copy your notes and reload this page.</p>}
    {reloadRequired&&<p role="alert">The source or authorized session changed. Copy any unsaved notes, then reload this page. Loading old history cannot unlock saving.</p>}
    <details className="head-review-history"><summary>Saved history · {history.length} loaded {dirty?'· preserve unsaved edits before loading':''}</summary>
      {history.length===0?<p>No history loaded.</p>:<ol>{history.map(record=>{
        const stale=headTeachingDraftStale(record,context);
        return <li key={record.version}><div className="head-review-actions"><strong>Version {record.version} · {record.draft.status==='changes-required'?'Corrections requested':'Draft'}</strong><time dateTime={record.savedAt}>{record.savedAt}</time><span>{stale?'Historical source — cannot resume':'Current packet'}</span>{!stale&&<button type="button" disabled={busy||dirty||reloadRequired} onClick={()=>replace(record)}>Load version {record.version}</button>}</div><p>{record.draft.reviewer||'No self-reported name'} · {record.draft.qualification||'No qualification supplied'}</p><p className="head-review-preserve">{record.draft.scope}</p><p className="head-review-preserve">{record.draft.notes||'No notes supplied.'}</p><details><summary>Exact saved revision &amp; checklist</summary><pre>{JSON.stringify(record,null,2)}</pre></details></li>;
      })}</ol>}
      {nextBefore!==null&&<button type="button" disabled={busy} onClick={()=>void load(nextBefore)}>Load older history</button>}
    </details>
  </section>;
}

'use client';

import {useEffect, useLayoutEffect, useRef, useState} from 'react';
import {createHeadTourPlaybackController, type HeadTourPlaybackContext, type HeadTourPlaybackState} from '../lib/head-tour-playback';
import './head-tour-playback.css';

export function HeadTourPlayback({context, blockedReason, onPlayingChange}: {context: HeadTourPlaybackContext; blockedReason?: string; onPlayingChange?: (playing: boolean) => void}) {
  const controls = useRef<HTMLDivElement>(null), committed = useRef<object | null>(null), token = {};
  const playingChange = useRef(onPlayingChange);
  const [state, setState] = useState<HeadTourPlaybackState>({playing: false, finished: false, speed: 1});
  const controllerRef = useRef<ReturnType<typeof createHeadTourPlaybackController> | null>(null);
  const visible = () => !!committed.current && !document.hidden && !!controls.current &&
    !controls.current.closest('[hidden], [inert]') && (!controls.current.closest('details') || controls.current.closest('details')!.open);
  if (!controllerRef.current) controllerRef.current = createHeadTourPlaybackController({
    schedule: (callback, delay) => window.setTimeout(callback, delay),
    cancel: handle => window.clearTimeout(handle as number),
    canAdvance: visible,
    onState: next => {if (committed.current) {setState(next); playingChange.current?.(next.playing);}},
  });
  const controller = controllerRef.current;
  useLayoutEffect(() => {
    committed.current = token;
    playingChange.current = onPlayingChange;
    controller.update(context);
    return () => {if (committed.current === token) committed.current = null;};
  });
  useEffect(() => {
    const root = controls.current?.closest('.imaging-workspace-page, .head-guided-module-page');
    const pause = () => controller.pause();
    const manual = (event: Event) => {if (!controls.current?.contains(event.target as Node)) pause();};
    const hidden = () => {if (document.hidden) pause();};
    root?.addEventListener('pointerdown', manual, true);
    root?.addEventListener('wheel', manual, true);
    root?.addEventListener('keydown', manual, true);
    document.addEventListener('visibilitychange', hidden);
    window.addEventListener('blur', pause); window.addEventListener('pagehide', pause); window.addEventListener('popstate', pause);
    return () => {
      controller.pause();
      playingChange.current?.(false);
      root?.removeEventListener('pointerdown', manual, true);
      root?.removeEventListener('wheel', manual, true);
      root?.removeEventListener('keydown', manual, true);
      document.removeEventListener('visibilitychange', hidden);
      window.removeEventListener('blur', pause); window.removeEventListener('pagehide', pause); window.removeEventListener('popstate', pause);
    };
  }, [controller]);
  const canControl = () => committed.current === token && visible();
  return <div ref={controls} className="head-tour-playback" role="group" aria-label="Guided tour playback" onKeyDown={event => {
    if (event.key === 'Escape' && canControl()) controller.pause();
  }}>
    <button type="button" disabled={!state.playing && (context.blocked || !context.stepId)} onClick={() => {
      if (!canControl()) return;
      if (controller.state().playing) controller.pause(); else {
        // The inline comparison folds learning by default. Explicit playback
        // reveals the notes, rather than advancing captions behind a closed panel.
        const notes=controls.current?.closest('.imaging-workspace-page, .head-guided-module-page')?.querySelector<HTMLDetailsElement>('.imaging-comparison-learning');
        if(notes)notes.open=true;
        controller.play();
      }
    }}>{state.playing ? 'Pause tour' : state.finished ? 'Replay this step' : 'Play tour'}</button>
    <label>Speed <select aria-label="Guided tour speed" value={state.speed} onChange={event => {
      if (canControl()) controller.setSpeed(Number(event.target.value));
    }}><option value={0.5}>0.5× · slow</option><option value={1}>1×</option><option value={1.5}>1.5×</option><option value={2}>2× · fast</option></select></label>
    <span role="status">{blockedReason || (state.finished ? 'Tour ended · final notes remain open.' : state.playing ? context.ready ? 'Playing · notes advance with each structure.' : 'Waiting for this structure to be confirmed…' : 'Manual navigation pauses playback.')}</span>
  </div>;
}

'use client';
import {useEffect,useLayoutEffect,useRef,useState,type ReactNode} from 'react';
import Link from 'next/link';
import {AtlasWorkspaceNavigation} from './AtlasWorkspaceNavigation';
import {ImagingPaneNavigation} from './ImagingPaneNavigation';
import {type AtlasModalityId} from '../lib/atlas-navigation';
import {type HeadImageNavigationContext} from '../lib/head-atlas-navigation';
import {type ImagingPane} from '../lib/imaging-pane-focus';
import './imaging-atlas-shell.css';

export type ImagingAtlasShellProps = {
  title: string;
  modality: Exclude<AtlasModalityId,'3d'>;
  regionId: string;
  subtitle?: string;
  notice: ReactNode;
  actions?: ReactNode;
  sidebar: ReactNode;
  toolbar?: ReactNode;
  children: ReactNode;
  info: ReactNode;
  infoLabel?: string;
  headNavigation?: HeadImageNavigationContext;
  comparison?: ReactNode;
  canFocusImages?: boolean;
  imageFocusContext?: object|null;
};

export function ImagingAtlasShell({title,modality,regionId,subtitle,notice,actions,sidebar,toolbar,children,info,infoLabel='Structure information',headNavigation,comparison,canFocusImages=false,imageFocusContext=null}:ImagingAtlasShellProps){
  const workspace=useRef<HTMLElement>(null),[fullscreen,setFullscreen]=useState(false),[fullscreenError,setFullscreenError]=useState('');
  const [focusedContext,setFocusedContext]=useState<object|null>(null);
  const pendingPane=useRef<{origin:HTMLElement;focus:()=>void;context:object;token:number}|null>(null);
  const paneToken=useRef(0);
  const committedRender=useRef<object|null>(null);
  const renderIdentity={};
  const focusAvailable=canFocusImages&&imageFocusContext!==null&&!comparison;
  const imagesFocused=focusAvailable&&focusedContext===imageFocusContext;
  useLayoutEffect(()=>{committedRender.current=renderIdentity;});
  useLayoutEffect(()=>()=>{
    committedRender.current=null;
    pendingPane.current=null;
    paneToken.current++;
  },[]);
  useLayoutEffect(()=>{
    if(focusedContext!==null&&(!focusAvailable||focusedContext!==imageFocusContext))setFocusedContext(null);
    if(pendingPane.current&&(!focusAvailable||pendingPane.current.context!==imageFocusContext))pendingPane.current=null;
  },[focusAvailable,focusedContext,imageFocusContext]);
  useLayoutEffect(()=>{
    const request=pendingPane.current;
    if(!request||imagesFocused||!focusAvailable||request.context!==imageFocusContext)return;
    pendingPane.current=null;
    if(request.token===paneToken.current&&request.origin.isConnected)request.focus();
  },[imagesFocused,focusAvailable,imageFocusContext,focusedContext]);
  function navigatePane(origin:HTMLElement,pane:ImagingPane,focus:()=>void){
    if(committedRender.current!==renderIdentity)return;
    paneToken.current++;
    pendingPane.current=null;
    if(pane!=='image'&&imagesFocused&&imageFocusContext){
      pendingPane.current={origin,focus,context:imageFocusContext,token:paneToken.current};
      setFocusedContext(null);
      return;
    }
    focus();
  }
  function toggleImageFocus(){
    if(committedRender.current!==renderIdentity||!focusAvailable)return;
    paneToken.current++;
    pendingPane.current=null;
    setFocusedContext(imagesFocused?null:imageFocusContext);
  }
  useEffect(()=>{const update=()=>setFullscreen(document.fullscreenElement===workspace.current);document.addEventListener('fullscreenchange',update);return()=>document.removeEventListener('fullscreenchange',update);},[]);
  async function expandWorkspace(){try{setFullscreenError('');if(document.fullscreenElement===workspace.current)await document.exitFullscreen();else if(workspace.current?.requestFullscreen)await workspace.current.requestFullscreen();else setFullscreenError('Full-screen mode is unavailable in this browser.');}catch{setFullscreenError('Full-screen mode could not open. The comparison remains available here.');}}
  return <main ref={workspace} className="imaging-workspace-page">
    <ImagingPaneNavigation infoLabel={infoLabel} onPaneRequest={navigatePane}/>
    <header className="imaging-workspace-titlebar">
      <div className="imaging-workspace-heading">
        <nav aria-label="Breadcrumb"><Link href="/atlas">Atlas</Link><span aria-hidden="true">/</span><span>{title}</span></nav>
        <h1>{title}</h1>
        {subtitle&&<p>{subtitle}</p>}
      </div>
      {(actions||focusAvailable)&&<div className="imaging-workspace-actions">{actions}{focusAvailable&&<button type="button" className="imaging-image-focus-toggle" aria-pressed={imagesFocused} onClick={toggleImageFocus}>{imagesFocused?'Restore panels':'Focus images'}</button>}</div>}
    </header>
    <AtlasWorkspaceNavigation modality={modality} regionId={regionId} headNavigation={headNavigation}/>
    <div className="imaging-workspace-notice"><span className="imaging-workspace-use">Education only · no diagnostic use · review pending</span><div>{notice}</div><details className="imaging-workspace-disclosure"><summary>Navigation &amp; limitations</summary><p>Browsing another modality or 3D region does not carry image focus or spatial registration. Only a verified, revision-bound CT/MRI head link can retain learning context. Atlas, cases and lectures have separate access.</p></details></div>
    <div className={`imaging-workspace-grid${comparison?' has-reference-comparison':''}${imagesFocused?' is-image-focused':''}`}>
      <aside className="imaging-workspace-sidebar" aria-label="Anatomy index" data-imaging-pane="index" tabIndex={-1} hidden={imagesFocused}>{sidebar}</aside>
      <section className="imaging-workspace-viewer" aria-label="Image viewer" data-imaging-pane="image" tabIndex={-1}>
        {(comparison||fullscreen)&&<div className="imaging-comparison-expand"><button type="button" onClick={()=>void expandWorkspace()}>{fullscreen?'Exit full screen':'Expand workspace'}</button>{fullscreen&&<span>Esc to exit</span>}{fullscreenError&&<span role="status">{fullscreenError}</span>}</div>}
        {toolbar&&<div className="imaging-workspace-toolbar">{toolbar}</div>}
        <div className="imaging-workspace-stage">{children}</div>
      </section>
      <aside className="imaging-workspace-info" aria-label={infoLabel} data-imaging-pane="learning" tabIndex={-1} hidden={imagesFocused}>{comparison?<>{comparison}<details className="imaging-comparison-learning"><summary>Structure &amp; learning</summary>{info}</details></>:info}</aside>
    </div>
  </main>;
}

'use client';

import {focusImagingPane, type ImagingPane} from '../lib/imaging-pane-focus';

/** Keyboard-only disclosure avoids adding another permanent viewer toolbar. */
export function ImagingPaneNavigation({infoLabel,onPaneRequest}: {infoLabel: string;onPaneRequest?: (origin: HTMLElement,pane: ImagingPane,focus:()=>void) => void}) {
  const destinations: Array<{pane: ImagingPane; label: string}> = [
    {pane: 'image', label: 'Skip to image viewer'},
    {pane: 'learning', label: `Skip to ${infoLabel.toLowerCase()}`},
    {pane: 'index', label: 'Skip to anatomy index'},
  ];
  return <nav className="imaging-pane-navigation" aria-label="Imaging workspace shortcuts">
    {destinations.map(({pane, label}) => <button key={pane} type="button" onClick={event => {
      const origin=event.currentTarget;
      const focus=()=>{focusImagingPane(origin,pane);};
      if(onPaneRequest)onPaneRequest(origin,pane,focus);else focus();
    }}>{label}</button>)}
  </nav>;
}

