'use client';

// Per-document identity continuity, never an authorization grant. The server
// independently authenticates and checks institution membership on every call.
let context: string | null = null;
export async function clinicalReviewFetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
  const headers = new Headers(init?.headers);
  if (context) headers.set('X-Clinical-Review-Context', context);
  const response = await fetch(input, { ...init, headers });
  const received = response.headers.get('X-Clinical-Review-Context');
  if (response.ok && received) {
    if (context && received !== context) return Response.json({ error: 'Your account or institution changed. Keep or export your edits, then reload Clinical Review before saving.' }, { status: 409 });
    context = received;
  }
  return response;
}

/** Translate only known source routes. Exact source query identities survive;
 * external links and arbitrary return URLs are never accepted as model targets. */
export function reviewModelHref(href: string | null): string {
  if (!href || !href.startsWith('/') || href.startsWith('//')) return '/workspace/atlas-review';
  const url = new URL(href, 'https://review.invalid');
  let kind = 'body', region = 'whole-body';
  if (url.pathname === '/shoulder') kind = 'shoulder';
  else if (url.pathname === '/') { /* whole body */ }
  else if (/^\/regions\/[a-z]+(?:-[a-z]+)*$/.test(url.pathname)) region = url.pathname.slice('/regions/'.length);
  else if (['kidneys', 'female-pelvis', 'back-layers', 'abdominal-wall', 'lower-limb'].some(k => url.pathname === '/specimens/' + k)) {
    kind = url.pathname.slice('/specimens/'.length);
    region = kind === 'lower-limb' ? ({ knee: 'leg', calf: 'leg', foot: 'foot', 'hip-thigh': 'thigh', whole: 'pelvis' }[url.searchParams.get('specimenScope') ?? 'whole'] ?? 'pelvis')
      : kind === 'female-pelvis' ? 'pelvis' : kind === 'back-layers' ? 'spine' : 'abdomen';
  }
  else return '/workspace/atlas-review';
  url.searchParams.delete('kind'); url.searchParams.delete('region');
  url.searchParams.set('kind', kind); url.searchParams.set('region', region);
  return '/workspace/atlas-review/model?' + url.searchParams.toString();
}

/** Presentation-only link. Missing/unsupported material must not fall back to
 * the review home or another anatomy selection inside the worksheet. */
export function reviewModelPreviewHref(href: string | null): string | null {
  if (!href || !href.startsWith('/') || href.startsWith('//') || /[\\\u0000-\u0020]/.test(href)) return null;
  const original = new URL(href, 'https://review.invalid');
  const mapped = original.pathname === '/workspace/atlas-review/model' ? href : reviewModelHref(href);
  const url = new URL(mapped, 'https://review.invalid');
  if (url.pathname !== '/workspace/atlas-review/model') return null;
  return '/workspace/atlas-review/model/embedded' + url.search;
}

import {clinicalReviewEntries, type ClinicalReviewEntry} from '../atlas-review/lib/clinical-review-index';
import {bodyReviewMaterial} from '../atlas-review/lib/body-review-material';
import {nestedReviewMaterial} from '../atlas-review/lib/nested-review-material';
import {specimenReviewMaterial} from '../atlas-review/lib/specimen-review-material';
import {reviewModelHref} from './clinical-review-links';

const home = {href:'/workspace/atlas-review', name:null};
type Params = Record<string, string | string[] | undefined>;
/** Compare the complete source-bound model link, not just a familiar structure ID.
 * Public material only: no private review records, authorization or approvals. */
function signature(params: Params): string | null {
  const pairs: Array<[string,string]> = [];
  for (const [key,value] of Object.entries(params)) {
    if (value === undefined) continue;
    if (typeof value !== 'string' || value.length > 256) return null;
    pairs.push([key,value]);
  }
  if (!pairs.some(([key])=>key==='kind')) pairs.push(['kind','body']);
  if (!pairs.some(([key])=>key==='region')) pairs.push(['region','whole-body']);
  return JSON.stringify(pairs.sort(([a],[b])=>a.localeCompare(b)));
}
async function entryModelHref(entry: ClinicalReviewEntry): Promise<string> {
  const query = new URL(entry.href,'https://review.invalid').searchParams;
  if (entry.scope === 'shoulder') return reviewModelHref('/shoulder?'+new URLSearchParams({structure:entry.id}));
  if (entry.scope === 'body') return reviewModelHref((await bodyReviewMaterial(entry.id))?.atlasLink ?? null);
  if (entry.scope === 'nested') return reviewModelHref((await nestedReviewMaterial(JSON.stringify([query.get('parent'),query.get('study')]),entry.id))?.atlasLink ?? null);
  return reviewModelHref((await specimenReviewMaterial(query.get('specimen')!,entry.id))?.atlasLink ?? null);
}
export async function clinicalReviewReturn(params: Params): Promise<{href:string;name:string|null}> {
  const requested = signature(params);
  if (!requested) return {...home};
  const kind = params.kind ?? 'body';
  const scope = kind === 'shoulder' ? 'shoulder' : kind === 'body'
    ? params.study === '2' ? 'nested' : 'body' : 'specimens';
  const id = scope === 'nested' ? params.part : scope === 'specimens'
    ? kind === 'lower-limb' ? params.specimenPart : params.refStructure : params.structure;
  if (typeof id !== 'string') return {...home};
  const matches: ClinicalReviewEntry[] = [];
  for (const entry of clinicalReviewEntries.filter(e=>e.scope===scope && e.id===id)) {
    const url = new URL(await entryModelHref(entry),'https://review.invalid');
    if (url.pathname === '/workspace/atlas-review/model'
      && signature(Object.fromEntries(url.searchParams)) === requested) matches.push(entry);
  }
  return matches.length === 1 ? {href:matches[0].href,name:matches[0].name} : {...home};
}

