/** Public anatomy identities only. No pixels, mask derivatives or scan metadata. */
export function headCtFacialComparisonPacket(){
  return {schema:'vm-head-ct-facial-comparison-review-1',packetId:'head-ct-facial-comparisons',status:'draft',
    headRevision:HEAD_LINK_REVISION,patientRegistration:false,clinicalApproval:false,publicationApproval:false,
    scope:'Three CT-only semantic comparisons: limited-region zygomatic masks and the saved mandible mask with existing generic 3D bones. Representation names do not establish complete coverage. Subjects and extents differ; there is no patient-space registration, diagnostic or fracture assessment, MRI counterpart, clinical approval or publication approval. These bindings have an independent review revision; earlier skull-bone, teaching or tour decisions do not approve them.',
    reviewChecks:[
      'Verify native ID, exact raw label, laterality and representation against the pinned head manifest.',
      'Inspect the actual saved CT extent with overlays hidden and shown. Limited regions and a mask-type label are not evidence of a complete whole bone.',
      'Inspect the generic bone independently, including source bundle, side, boundaries and missing anatomy; these generic surfaces remain unvalidated.',
      'Assess educational semantic usefulness only. Do not infer matching subjects, coordinates, distances, normality, fracture detection or MRI equivalence.',
      'Record an explicit decision against this independent comparison packet, not inherited geometry, teaching, tour or publication approval.',
    ],
    items:identities.map(([conceptId,id,label,laterality,representation,suffix])=>({conceptId,
      ct:{id,label,laterality,representation},
      atlas:{structureId:'vm:anatomy:body:head-neck:'+suffix,sourceHash,study:'1',side:laterality==='midline_or_unpaired'?'both':laterality},
      binding:headConceptById(conceptId)}))};
}
export type HeadCtFacialComparisonPacket=ReturnType<typeof headCtFacialComparisonPacket>;

export async function verifiedHeadCtFacialComparisonPacket(manifestRevision:string):Promise<HeadCtFacialComparisonPacket|null>{
  if(manifestRevision!==HEAD_LINK_REVISION)return null;
  const packet=headCtFacialComparisonPacket();
  for(const item of packet.items){
    const {binding,atlas}=item;
    if(!binding||binding.ctHref!==`/atlas/ct-head?concept=${item.conceptId}`||Object.hasOwn(binding,'mriHref'))return null;
    if(JSON.stringify(headAtlasConcept(item.ct,'CT'))!==JSON.stringify(binding))return null;
    const query=new URLSearchParams({study:atlas.study,structure:atlas.structureId,side:atlas.side,source:atlas.sourceHash,concept:item.conceptId});
    if(binding.atlasHref!==`/atlas/head-neck-3d?${query}`)return null;
  }
  const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(packet)));
  return Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('')===HEAD_CT_FACIAL_COMPARISON_REVISION?packet:null;
}

import {authenticatedReviewer,reviewBody,reviewJson,ReviewHttpError} from '../atlas-review/lib/review-http.ts';
import {facialDecisionKind,facialDecisionConcept,facialDecisionContext,parseFacialDecisionContext,parseSavedFacialDecision,validateFacialDecision,type FacialDecisionKind} from './head-ct-facial-decision-contract.ts';
import {facialDecisionHistory,appendFacialDecision} from './head-ct-facial-decision-store.ts';

// Internal handlers: the website route MUST run runClinicalReview first.
// Only its server-derived account/institution identity is accepted at that boundary.
const privateUser=(request:Request,kind:FacialDecisionKind)=>JSON.stringify(['vm-head-ct-facial-personal-decisions-1',kind,authenticatedReviewer(request.headers)]);
const database=(db:Pick<D1Database,'prepare'>|undefined)=>{if(!db)throw new ReviewHttpError(503,'Facial review storage is unavailable.');return db;};
function failure(error:unknown){
  if(error instanceof ReviewHttpError)return reviewJson({error:error.message},error.status);
  console.error(JSON.stringify({event:'head-ct-facial-decision-unconfirmed'}));
  return reviewJson({error:'Save or history could not be confirmed. Keep your edits and compare saved history before retrying.'},503);
}
export async function getFacialDecisions(request:Request,binding:Pick<D1Database,'prepare'>|undefined,manifestRevision:string){
  try{
    authenticatedReviewer(request.headers);
    const params=new URL(request.url).searchParams;
    for(const key of params.keys())if(!['concept','kind','before'].includes(key)||params.getAll(key).length!==1)throw new ReviewHttpError(400,'Unexpected or duplicate history parameter.');
    const concept=params.get('concept'),kind=params.get('kind');
    if(!facialDecisionConcept(concept)||!facialDecisionKind(kind))throw new ReviewHttpError(400,'Unknown facial concept or decision kind.');
    const raw=params.get('before'),before=raw===null?2147483648:Number(raw);
    if((raw!==null&&!/^[1-9]\d{0,9}$/.test(raw))||!Number.isSafeInteger(before)||before<1||before>2147483648)throw new ReviewHttpError(400,'Invalid history cursor.');
    const user=privateUser(request,kind),context=await facialDecisionContext(manifestRevision,concept,kind);
    const history=await facialDecisionHistory(database(binding),user,concept,kind,before);
    return reviewJson({context,history,nextBefore:history.length===20?history.at(-1)!.version:null,scope:'private-to-signed-in-account-and-institution'});
  }catch(error){return failure(error);}
}
export async function postFacialDecision(request:Request,binding:Pick<D1Database,'prepare'>|undefined,manifestRevision:string){
  try{
    authenticatedReviewer(request.headers);
    if(new URL(request.url).searchParams.size)throw new ReviewHttpError(400,'Unexpected decision query parameter.');
    const raw=await reviewBody(request);
    if(!raw||typeof raw!=='object'||Array.isArray(raw)||Object.keys(raw).length!==3||!['context','expectedVersion','decision'].every(k=>Object.hasOwn(raw,k)))throw new ReviewHttpError(400,'Unexpected decision field.');
    const input=raw as Record<string,unknown>;
    let submitted;try{submitted=parseFacialDecisionContext(input.context);}catch{throw new ReviewHttpError(400,'Invalid facial identity or context.');}
    const user=privateUser(request,submitted.kind),context=await facialDecisionContext(manifestRevision,submitted.conceptId,submitted.kind);
    if(JSON.stringify(submitted)!==JSON.stringify(context))throw new ReviewHttpError(409,'The facial source, packet or review wording changed. Keep edits and reload before reviewing again.');
    const expected=input.expectedVersion;
    if(typeof expected!=='number'||!Number.isSafeInteger(expected)||expected<0||expected>2147483646)throw new ReviewHttpError(400,'Invalid decision version.');
    let decision;try{decision=validateFacialDecision(input.decision,context);}catch(error){throw new ReviewHttpError(422,error instanceof Error?error.message:'Invalid decision.');}
    const db=database(binding),previous=(await facialDecisionHistory(db,user,context.conceptId,context.kind))[0];
    if((previous?.version??0)!==expected)throw new ReviewHttpError(409,'Another save changed this facial decision. Refresh history and compare your edits.');
    const saved=parseSavedFacialDecision({eventSchema:'vm-ct-facial-decision-event-1',context,version:expected+1,savedAt:new Date().toISOString(),decision});
    if(!await appendFacialDecision(db,user,saved,expected))throw new ReviewHttpError(409,'Another save won the version check. Refresh history and compare your edits.');
    return reviewJson({review:saved},201);
  }catch(error){return failure(error);}
}

import {facialDecisionStale,parseFacialDecisionContext,parseSavedFacialDecision,validateFacialDecision,type FacialDecision,type FacialDecisionContext} from './head-ct-facial-decision-contract.ts';
const exact=(v:unknown,keys:string[]):v is Record<string,unknown>=>!!v&&typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).length===keys.length&&keys.every(k=>Object.hasOwn(v,k));
export class FacialSourceChangedError extends Error{}
const nextVersion=(expected:number)=>{if(!Number.isSafeInteger(expected)||expected<0||expected>2147483646)throw Error('Invalid facial decision version. Keep your edits.');return expected+1;};
export function parseFacialHistory(input:unknown,expected:FacialDecisionContext,before=2147483648){
  if(!Number.isSafeInteger(before)||before<1||before>2147483648||!exact(input,['context','history','nextBefore','scope'])||input.scope!=='private-to-signed-in-account-and-institution'||!Array.isArray(input.history)||input.history.length>20)throw Error('Invalid saved history. Keep your edits.');
  const context=parseFacialDecisionContext(input.context);
  if(JSON.stringify(context)!==JSON.stringify(parseFacialDecisionContext(expected)))throw new FacialSourceChangedError('The facial source or checklist changed. Keep your edits and reload.');
  const history=input.history.map(parseSavedFacialDecision);
  if(history.some((r,i)=>r.context.conceptId!==context.conceptId||r.context.kind!==context.kind||r.version>=before||(i>0&&r.version!==history[i-1].version-1))||before!==2147483648&&history.length>0&&history[0].version!==before-1)throw Error('Invalid saved facial history order or family. Keep your edits.');
  const nextBefore=history.length===20?history.at(-1)!.version:null;
  if(nextBefore!==input.nextBefore)throw Error('Invalid history cursor. Keep your edits.');
  return {context,history,nextBefore};
}
export function facialSavePayload(context:FacialDecisionContext,expected:number,decision:FacialDecision){
  nextVersion(expected);const checked=parseFacialDecisionContext(context);
  return {context:checked,expectedVersion:expected,decision:validateFacialDecision(decision,checked)};
}
const comparable=(d:FacialDecision,c:FacialDecisionContext)=>{const checked=validateFacialDecision(d,c);return JSON.stringify({...checked,checks:c.checklist.map(item=>[item.id,checked.checks[item.id]])});};
export function confirmFacialSave(input:unknown,context:FacialDecisionContext,expected:number,decision:FacialDecision){
  const version=nextVersion(expected);if(!exact(input,['review']))throw Error('Save could not be confirmed. Preserve edits and compare history.');
  const saved=parseSavedFacialDecision(input.review);
  if(facialDecisionStale(saved,context)||saved.version!==version||comparable(saved.decision,context)!==comparable(decision,context))throw Error('Save did not match this decision and revision. Preserve edits and compare history.');
  return saved;
}

import {HEAD_CT_FACIAL_COMPARISON_REVISION,CT_FACIAL_COMPARISON_CONCEPTS,verifiedHeadCtFacialComparisonPacket} from './head-ct-facial-comparison-review.ts';
