/** Draft concept navigation between CT and MRI images of separate, unregistered subjects.
 * These three concepts have no exact matching 3D part or spatial correspondence.
 */
import {
  HEAD_LINK_REVISION,
  headAtlasConcept,
  headConceptById,
  resolveHeadConcept,
  type HeadConceptLink,
  type HeadEntry,
  type HeadModality,
} from './head-atlas-links.ts';

export type HeadImageConceptLink = Omit<HeadConceptLink, 'atlasHref'> & {atlasHref?: string};

type ImageOnlyConcept = {
  conceptId: string;
  label: string;
  suffix: string;
  side: 'left' | 'right' | 'midline_or_unpaired';
  nativeName: string;
  mriRepresentation: 'mask' | 'partial-mask';
};

const imageOnlyConcepts: readonly ImageOnlyConcept[] = [
  {conceptId: 'cerebellum-left-hemisphere', label: 'Left cerebellar hemisphere', suffix: 'Left cerebellar hemisphere', side: 'left', nativeName: 'cerebellar_hemisphere.left', mriRepresentation: 'mask'},
  {conceptId: 'cerebellum-right-hemisphere', label: 'Right cerebellar hemisphere', suffix: 'Right cerebellar hemisphere', side: 'right', nativeName: 'cerebellar_hemisphere.right', mriRepresentation: 'mask'},
  {conceptId: 'cerebellum-vermis', label: 'Cerebellar vermis', suffix: 'Cerebellar vermis', side: 'midline_or_unpaired', nativeName: 'cerebellar_vermis', mriRepresentation: 'partial-mask'},
];

function nativeId(concept: ImageOnlyConcept, modality: HeadModality): string {
  return `${modality === 'CT' ? 'cth' : 'mrb'}.cer.${concept.nativeName}`;
}

function matches(entry: HeadEntry, concept: ImageOnlyConcept, modality: HeadModality): boolean {
  return !!entry && entry.id === nativeId(concept, modality) &&
    entry.label === `${concept.suffix} — regional mask` &&
    entry.laterality === concept.side &&
    entry.representation === (modality === 'MRI' ? concept.mriRepresentation : 'mask');
}

function imageOnlyLink(concept: ImageOnlyConcept): HeadImageConceptLink {
  return {
    conceptId: concept.conceptId,
    label: concept.label,
    ctHref: `/atlas/ct-head?concept=${concept.conceptId}`,
    mriHref: `/atlas/mri-head?concept=${concept.conceptId}`,
    scopeNote: concept.mriRepresentation === 'partial-mask'
      ? 'Draft image-only anatomy concept link. The MRI vermis mask has partial coverage; CT and MRI are separate, unregistered subjects. No exact matching 3D part, spatial correspondence or clinical approval.'
      : 'Draft image-only anatomy concept link. CT and MRI are separate, unregistered subjects. No exact matching 3D part, spatial correspondence or clinical approval.',
    headRevision: HEAD_LINK_REVISION,
  };
}

/** Existing 3D links retain their complete source-pinned contract. */
export function headImageConceptById(id: string): HeadImageConceptLink | null {
  const existing = headConceptById(id);
  if (existing) return existing;
  const concept = imageOnlyConcepts.find(item => item.conceptId === id);
  return concept ? imageOnlyLink(concept) : null;
}

export function headImageConcept(entry: HeadEntry, modality: HeadModality): HeadImageConceptLink | null {
  const existing = headAtlasConcept(entry, modality);
  if (existing) return existing;
  if (modality !== 'CT' && modality !== 'MRI') return null;
  const concept = imageOnlyConcepts.find(item => matches(entry, item, modality));
  return concept ? imageOnlyLink(concept) : null;
}

/** Resolve an image-only identity only when exactly one current entry matches. */
export function resolveHeadImageConcept(entries: readonly HeadEntry[], id: string, modality: HeadModality): HeadEntry | null {
  const existing = resolveHeadConcept(entries, id, modality);
  if (existing) return existing;
  if (!Array.isArray(entries) || (modality !== 'CT' && modality !== 'MRI')) return null;
  const concept = imageOnlyConcepts.find(item => item.conceptId === id);
  if (!concept) return null;
  const matchesInStudy = entries.filter(entry => matches(entry, concept, modality));
  return matchesInStudy.length === 1 ? matchesInStudy[0] : null;
}

/** Metadata for a future, independent clinical review; no review is implied. */
export function headImageOnlyComparisonPacket() {
  return {
    schema: 'vm-head-image-only-comparison-1',
    headRevision: HEAD_LINK_REVISION,
    status: 'draft' as const,
    clinicalApproval: false as const,
    patientRegistration: false as const,
    bindings: imageOnlyConcepts.map(concept => ({
      conceptId: concept.conceptId,
      ct: {id: nativeId(concept, 'CT'), label: `${concept.suffix} — regional mask`, laterality: concept.side, representation: 'mask' as const},
      mri: {id: nativeId(concept, 'MRI'), label: `${concept.suffix} — regional mask`, laterality: concept.side, representation: concept.mriRepresentation},
    })),
  };
}

import {atlasStudySuffix} from './atlas-study-transport.ts';
import {HEAD_LINK_REVISION,headConceptById,type HeadModality} from './head-atlas-links.ts';
import {headLinksCurrent} from './head-link-availability.ts';
import {headImageHref} from './head-atlas-navigation.ts';
import type {LiveHeadSelection} from './head-live-selection.ts';
import type {HeadGuidedDestination} from './head-guided-focus.ts';
import regionalManifest from '../public/atlas-runtime/head-neck/manifest.json' with {type:'json'};

export type InlineHeadDestination={conceptId:string;label:string;atlasHref:string;src:string;sourceRevision:string;headRevision:string;scope:string;target:HeadGuidedDestination['target']};

/** The embedded model is built only from the reviewed concept and imported runtime. */
export function headInlineDestination(conceptId:string,revision:string,modality:HeadModality):InlineHeadDestination|null{
  if(!headLinksCurrent()||revision!==HEAD_LINK_REVISION||
    regionalManifest.sourceCommit.length!==40||!/^[a-f0-9]{40}$/.test(regionalManifest.sourceCommit)||
    (modality!=='CT'&&modality!=='MRI'))return null;
  const concept=headConceptById(conceptId);
  if(!concept||concept.headRevision!==revision||!(modality==='CT'?concept.ctHref:concept.mriHref))return null;
  const href=new URL(concept.atlasHref,'https://atlas.invalid');
  if(href.origin!=='https://atlas.invalid'||href.pathname!=='/atlas/head-neck-3d'||href.hash||
    href.searchParams.get('concept')!==conceptId)return null;
  const suffix=atlasStudySuffix(Object.fromEntries(href.searchParams));
  if(!suffix)return null;
  const query=new URLSearchParams(suffix.slice(1)),nested=query.get('study')==='2';
  const id=query.get(nested?'part':'structure'),source=query.get(nested?'partSource':'source');
  if(!id||!source)return null;
  const identity={id,source,laterality:id.split(':')[4]};
  const target:HeadGuidedDestination['target']=nested
    ?{kind:'nested',...identity,parentId:query.get('structure')!,parentSource:query.get('source')!,study:query.get('detail')!}
    :{kind:'root',...identity};
  // Keep model/camera only within the same source, side and anatomical study.
  // Exact selected-piece identity still travels in every acknowledged command.
  const scopeQuery=new URLSearchParams(query);
  // Different sources need their own authored initial model URL and session.
  // Only the selected piece may vary within a reusable source/study frame.
  scopeQuery.delete(nested?'part':'structure');
  const scope=JSON.stringify([regionalManifest.sourceCommit,revision,modality,'head-neck',scopeQuery.toString()]);
  return {conceptId,label:concept.label,atlasHref:concept.atlasHref,src:'/atlas-runtime/head-neck/index.html?region=head-neck'+suffix+'&presentation=compare',sourceRevision:regionalManifest.sourceCommit,headRevision:revision,scope,target};
}

export function headInlineMatches(selection:LiveHeadSelection|null,conceptId:string):boolean{
  return selection?.status==='selected'&&selection.concept?.conceptId===conceptId;
}

/** Reverse navigation requires a fresh, exact model identity and an authored scan target. */
export function headInlineReverseConcept(selection:LiveHeadSelection|null,expectedConceptId:string,modality:HeadModality,revision:string):string|null{
  if(!headLinksCurrent()||revision!==HEAD_LINK_REVISION||!selection||selection.status!=='selected')return null;
  const concept=selection.concept;
  if(!concept||concept.conceptId===expectedConceptId||!headImageHref(modality,concept.conceptId,null,revision))return null;
  return concept.conceptId;
}

import {HEAD_MANIFEST_SHA256} from './head-atlas-import.ts';
import {HEAD_LINK_REVISION} from './head-atlas-links.ts';

/** Display eligibility only; never grants access or patient-space registration. */
export function headLinksCurrent(): boolean {
  return typeof HEAD_LINK_REVISION === 'string' && /^[a-f0-9]{64}$/.test(HEAD_LINK_REVISION) && HEAD_LINK_REVISION === HEAD_MANIFEST_SHA256;
}

export const HEAD_LINK_REVISION_NOTICE = 'CT/MRI comparisons and linked tours are temporarily unavailable because the imaging revision has changed. The source mappings must be checked before these links can be used. You can still explore the 3D Atlas.';

/** Numeric, transient load status only: no paths, labels, identifiers or scan bytes. */
export type HeadReadProgress={readonly loadedBytes:number;readonly totalBytes:number};
export type HeadReadObserver=(progress:HeadReadProgress)=>void;
export type HeadStudyProgress=HeadReadProgress&{readonly phase:'reading'|'verifying'};
export type HeadStudyObserver=(progress:HeadStudyProgress)=>void;

/** A display observer must never change whether image integrity checks succeed. */
export function notifyHeadProgress<T>(observer:((progress:T)=>void)|undefined,progress:T):void{
  try{observer?.(progress);}catch{/* Progress display failure must not disclose or replace a source error. */}
}

export function headStudyLoadingMessage(modality:'CT'|'MRI',progress:HeadStudyProgress):string{
  const {loadedBytes,totalBytes}=progress;
  if(!Number.isSafeInteger(loadedBytes)||!Number.isSafeInteger(totalBytes)||totalBytes<1||loadedBytes<0||loadedBytes>totalBytes)return `Opening ${modality} native image…`;
  if(progress.phase==='verifying')return `Verifying ${modality} image checksum…`;
  // Announce coarse real byte progress, not estimated time or every network chunk.
  const percent=Math.floor(loadedBytes/totalBytes*10)*10;
  return `Reading ${modality} native image… ${percent}%`;
}

export const HEAD_CLIENT_TRACE_PREFIX='VM_HEAD_CLIENT ';
export const HEAD_CLIENT_TRACE_LIMIT=128;

export type HeadClientPhase='study-start'|'reading'|'verifying'|'study-data-ready'|'failed'|'cancelled';
export type HeadClientTraceEvent={
  readonly schema:1;
  readonly attempt:number;
  readonly phase:HeadClientPhase;
  readonly elapsedMs:number;
  readonly loadedBytes?:number;
  readonly totalBytes?:number;
};
export type HeadClientTrace=(phase:HeadClientPhase,progress?:HeadReadProgress)=>void;

/** The URL must be the exact origin, and the fragment opt-in must occur once. */
export function headClientDiagnosticsAllowed(buildEnabled:boolean,origin:string,fragment:string):boolean{
  if(buildEnabled!==true||typeof origin!=='string'||typeof fragment!=='string')return false;
  try{
    const url=new URL(origin);
    if(url.protocol!=='http:'||url.origin!==origin||!['localhost','127.0.0.1','[::1]'].includes(url.hostname))return false;
    if(!fragment.startsWith('#'))return false;
    const values=new URLSearchParams(fragment.slice(1)).getAll('headDiagnostics');
    return values.length===1&&values[0]==='1';
  }catch{return false;}
}

const headClientPhases:ReadonlySet<string>=new Set(['study-start','reading','verifying','study-data-ready','failed','cancelled']);
const headClientTerminalPhases:ReadonlySet<string>=new Set(['study-data-ready','failed','cancelled']);
const HEAD_CLIENT_MAX_BYTES=536870912;
const HEAD_CLIENT_MAX_MS=86400000;

function snapshotHeadClientProgress(value:unknown):HeadReadProgress|null{
  if(!value||typeof value!=='object')return null;
  try{
    const {loadedBytes,totalBytes}=value as HeadReadProgress;
    if(Number.isSafeInteger(loadedBytes)&&Number.isSafeInteger(totalBytes)&&
      loadedBytes>=0&&loadedBytes<=HEAD_CLIENT_MAX_BYTES&&totalBytes>=1&&
      totalBytes<=HEAD_CLIENT_MAX_BYTES&&loadedBytes<=totalBytes)return {loadedBytes,totalBytes};
  }catch{/* Untrusted progress getters are diagnostic only. */}
  return null;
}

/** A deliberately injectable, inert-by-default seam for private local diagnostics. */
export function createHeadClientDiagnostics(options:{enabled?:boolean;write?:(line:string)=>void;now?:()=>number}={}){
  let emitted=0;
  let attempts=0;
  const enabled=options.enabled===true&&typeof options.write==='function';
  return function begin():HeadClientTrace|null{
    if(!enabled||emitted>=HEAD_CLIENT_TRACE_LIMIT)return null;
    const attempt=++attempts;
    let started=0;
    try{const value=options.now?.()??Date.now();if(Number.isFinite(value))started=value;}catch{/* Clock failure is diagnostic only. */}
    let lastElapsed=0;
    let lastReadingBucket=-1;
    let lastReadingTotal=0;
    let retired=false;
    const trace:HeadClientTrace=(phase,progress)=>{
      if(retired||emitted>=HEAD_CLIENT_TRACE_LIMIT||!headClientPhases.has(phase)||phase==='study-start')return;
      let bytes:HeadReadProgress|undefined;
      if(progress!==undefined){
        const snapshot=snapshotHeadClientProgress(progress);
        if(!snapshot)return;
        bytes=snapshot;
      }
      if(phase==='reading'&&!bytes)return;
      if(phase==='reading'&&bytes){
        const bucket=Math.floor(bytes.loadedBytes/bytes.totalBytes*10);
        if(bucket<=lastReadingBucket&&bytes.totalBytes===lastReadingTotal)return;
        if(lastReadingBucket>=0&&(bucket<lastReadingBucket||bytes.totalBytes!==lastReadingTotal))return;
        lastReadingBucket=bucket;
        lastReadingTotal=bytes.totalBytes;
        bytes={loadedBytes:bucket===10?bytes.totalBytes:Math.floor(bytes.totalBytes*bucket/10),totalBytes:bytes.totalBytes};
      }
      emit(phase,bytes);
      if(headClientTerminalPhases.has(phase))retired=true;
    };
    function emit(phase:HeadClientPhase,bytes?:HeadReadProgress){
      let current=started;
      try{const value=options.now?.()??Date.now();if(Number.isFinite(value))current=value;}catch{/* Keep previous elapsed time. */}
      lastElapsed=Math.max(lastElapsed,Math.min(HEAD_CLIENT_MAX_MS,Math.max(0,Math.trunc(current-started))));
      const event:HeadClientTraceEvent=bytes?
        {schema:1,attempt,phase,elapsedMs:lastElapsed,loadedBytes:bytes.loadedBytes,totalBytes:bytes.totalBytes}:
        {schema:1,attempt,phase,elapsedMs:lastElapsed};
      emitted++;
      try{options.write?.(HEAD_CLIENT_TRACE_PREFIX+JSON.stringify(event));}catch{/* Observer failure cannot affect a study. */}
    }
    emit('study-start');
    return trace;
  };
}

declare const __VM_LOCAL_HEAD_DIAGNOSTICS__:boolean;
let pageHeadDiagnosticsFactory:ReturnType<typeof createHeadClientDiagnostics>|undefined;

/** Local build and URL gates are checked on every call; no persisted setting. */
export function beginHeadStudyDiagnostics():HeadClientTrace|null{
  try{
    if(typeof __VM_LOCAL_HEAD_DIAGNOSTICS__==='undefined'||typeof window==='undefined'||
      !headClientDiagnosticsAllowed(__VM_LOCAL_HEAD_DIAGNOSTICS__,window.location.origin,window.location.hash))return null;
    if(!pageHeadDiagnosticsFactory){
      if(typeof window.console?.info!=='function')return null;
      pageHeadDiagnosticsFactory=createHeadClientDiagnostics({enabled:true,write:line=>window.console.info(line)});
    }
    return pageHeadDiagnosticsFactory();
  }catch{return null;}
}

