export async function headTeachingDraftHistory(db:Pick<D1Database,'prepare'>,user:string,before=2147483648,kind:HeadTeachingDraftKind='anatomy'):Promise<SavedHeadTeachingDraft[]>{
  if(!Number.isSafeInteger(before)||before<1||before>2147483648)throw Error('Invalid history cursor.');
  const tuple=storage(kind);
  const rows=await db.prepare(`SELECT user_id,nested_key,structure_id,track,version,payload,saved_at
    FROM atlas_personal_nested_review_events WHERE user_id=?1 AND nested_key=?2 AND structure_id=?3
    AND track=?4 AND version<?5 ORDER BY version DESC LIMIT 20`)
    .bind(user,tuple.key,tuple.structure,tuple.track,before).all<Row>();
  return rows.results.map(row=>{
    const saved=parseSavedHeadTeachingDraft(JSON.parse(row.payload));
    if(row.user_id!==user||row.nested_key!==tuple.key||row.structure_id!==tuple.structure||row.track!==tuple.track||
      saved.context.catalogScope!==expectedScope(kind)||saved.context.packetId!==tuple.structure||
      row.version!==saved.version||row.saved_at!==saved.savedAt)throw Error('Stored head teaching envelope mismatch.');
    return saved;
  });
}

export async function appendHeadTeachingDraft(db:Pick<D1Database,'prepare'>,user:string,saved:SavedHeadTeachingDraft,expected:number,kind:HeadTeachingDraftKind='anatomy'){
  const record=parseSavedHeadTeachingDraft(saved);
  const tuple=storage(kind);
  if(record.context.catalogScope!==expectedScope(kind)||record.context.packetId!==tuple.structure)throw Error('Wrong teaching packet identity.');
  if(!Number.isSafeInteger(expected)||expected<0||expected>2147483646||record.version!==expected+1)throw Error('Invalid append version.');
  const result=await db.prepare(`INSERT INTO atlas_personal_nested_review_events
    (user_id,nested_key,structure_id,track,version,payload,saved_at)
    SELECT ?1,?2,?3,?4,?5,?6,?7 WHERE COALESCE((SELECT MAX(version)
      FROM atlas_personal_nested_review_events WHERE user_id=?1 AND nested_key=?2 AND structure_id=?3 AND track=?4),0)=?8`)
    .bind(user,tuple.key,tuple.structure,tuple.track,record.version,JSON.stringify(record),record.savedAt,expected).run();
  return result.meta.changes===1;
}

export type HeadTourSpeed = 0.5 | 1 | 1.5 | 2;
export type HeadTourPlaybackContext = {
  identity: unknown;
  revision: string;
  sequenceId: string;
  stepId: string | null;
  index: number;
  total: number;
  nextId: string | null;
  ready: boolean;
  blocked: boolean;
  onAdvance: (conceptId: string) => void;
};
export type HeadTourPlaybackState = {playing: boolean; finished: boolean; speed: HeadTourSpeed};
export const HEAD_TOUR_READING_MS = 12000;

/** Reading time begins only after exact source/selection confirmation. No scans,
 * scores, progress, registration or approvals are stored by this transport. */
export function createHeadTourPlaybackController(options: {
  schedule: (callback: () => void, milliseconds: number) => unknown;
  cancel: (handle: unknown) => void;
  canAdvance: () => boolean;
  onState: (state: HeadTourPlaybackState) => void;
}) {
  let context: HeadTourPlaybackContext | null = null;
  let state: HeadTourPlaybackState = {playing: false, finished: false, speed: 1};
  let timer: unknown;
  let generation = 0;
  let expectedNext: string | null = null;
  const valid = (value: HeadTourPlaybackContext | null): value is HeadTourPlaybackContext =>
    !!value && !!value.identity && /^[a-f0-9]{64}$/.test(value.revision) && !!value.sequenceId && !!value.stepId &&
    Number.isInteger(value.index) && Number.isInteger(value.total) && value.total > 0 &&
    value.index >= 0 && value.index < value.total &&
    (value.index === value.total - 1 ? value.nextId === null : !!value.nextId && value.nextId !== value.stepId);
  function invalidate() {
    generation++;
    if (timer !== undefined) options.cancel(timer);
    timer = undefined;
  }
  function publish(next: Partial<HeadTourPlaybackState>) {
    const value = {...state, ...next};
    if (value.playing === state.playing && value.finished === state.finished && value.speed === state.speed) return;
    state = value;
    options.onState({...state});
  }
  function pause() { invalidate(); expectedNext = null; publish({playing: false}); }
  function schedule() {
    if (!state.playing || timer !== undefined || expectedNext || !valid(context) || !context.ready || context.blocked) return;
    const epoch = generation;
    timer = options.schedule(() => {
      if (epoch !== generation || !state.playing) return;
      timer = undefined;
      if (!valid(context) || !context.ready || context.blocked || !options.canAdvance()) { pause(); return; }
      if (context.nextId === null) { invalidate(); publish({playing: false, finished: true}); return; }
      // Reserve the sole next canonical slot before a callback can reenter.
      expectedNext = context.nextId;
      generation++;
      context.onAdvance(expectedNext);
      // Wait for the next committed target, then its annotation/model readiness.
      // There is no speculative follow-up timer or skip across missing steps.
    }, HEAD_TOUR_READING_MS / state.speed);
  }
  return {
    update(next: HeadTourPlaybackContext) {
      const previous = context;
      const replaced = !previous || previous.identity !== next.identity || previous.revision !== next.revision ||
        previous.sequenceId !== next.sequenceId || previous.total !== next.total;
      const moved = !previous || previous.stepId !== next.stepId || previous.index !== next.index;
      const automatic = !replaced && moved && expectedNext === next.stepId && next.index === previous.index + 1;
      context = next;
      if (replaced || moved && !automatic || !valid(next) || next.blocked) {
        pause(); publish({finished: false}); return;
      }
      if (moved) { invalidate(); expectedNext = null; publish({finished: false}); }
      if (!next.ready) invalidate();
      schedule();
    },
    play() {
      if (!valid(context) || context.blocked || !options.canAdvance()) return false;
      if (state.playing) return true;
      invalidate(); expectedNext = null;
      const epoch = generation;
      publish({playing: true, finished: false});
      if (epoch !== generation || !state.playing) return false;
      schedule(); return true;
    },
    pause,
    setSpeed(speed: number) {
      if (speed !== 0.5 && speed !== 1 && speed !== 1.5 && speed !== 2 || speed === state.speed) return;
      invalidate();
      const epoch = generation;
      publish({speed});
      if (epoch === generation) schedule();
    },
    state: () => ({...state}),
  };
}

import type {LoadedStudy,LocalHeadPackage,Modality} from './head-atlas-import';
import type {Plane,Vec3} from './head-atlas-geometry.mjs';

/** Only this opaque key enters browser history. Native positions stay in tab memory. */
export const HEAD_VIEW_ENTRY_KEY='__visibleMedicineHeadViewEntry';
export const HEAD_VIEW_EXTERNAL_HISTORY_KEY='__vinext_externalHistoryState';
export type HeadHistoryView={cursor:Vec3;layout:Plane|'multiplanar';windowing:[number,number]};
export type HeadHistoryScope={pkg:LocalHeadPackage;study:LoadedStudy;modality:Modality;revision:string};
type SourceStamp={packageId:number;studyId:number;configured:boolean;modality:Modality;revision:string;shape:[number,number,number];imageSha256:string;imageFile:string;imageDtype:string};
type Receipt={href:string;source:SourceStamp|null;view:HeadHistoryView|null};
const layouts=new Set<HeadHistoryView['layout']>(['axial','coronal','sagittal','multiplanar']);
const record=(value:unknown):value is Record<string,unknown>=>!!value&&typeof value==='object'&&!Array.isArray(value);
const shapeFor=(scope:HeadHistoryScope):[number,number,number]|null=>{
  const definition=scope.pkg?.manifest?.studies?.[scope.modality];
  const saved=scope.study?.definition?.image?.shape_kji;
  const loaded=scope.study?.geometry?.shapeKJI;
  if((scope.modality!=='CT'&&scope.modality!=='MRI')||!scope.revision||definition!==scope.study.definition||
    !Array.isArray(saved)||!Array.isArray(loaded)||saved.length!==3||loaded.length!==3||
    !saved.every((n,index)=>Number.isSafeInteger(n)&&n>0&&n<=4096&&n===loaded[index]))return null;
  return [saved[0],saved[1],saved[2]];
};
const validView=(view:unknown,shape:readonly number[]):view is HeadHistoryView=>{
  if(!record(view)||Object.keys(view).length!==3||!['cursor','layout','windowing'].every(key=>Object.hasOwn(view,key))||
    !layouts.has(view.layout as HeadHistoryView['layout']))return false;
  const cursor=view.cursor,windowing=view.windowing;
  return Array.isArray(cursor)&&cursor.length===3&&cursor.every((n,index)=>Number.isSafeInteger(n)&&n>=0&&n<shape[2-index])&&
    Array.isArray(windowing)&&windowing.length===2&&windowing.every(n=>typeof n==='number'&&Number.isFinite(n)&&Math.abs(n)<=1_000_000)&&windowing[1]>=1;
};
const copy=(view:HeadHistoryView):HeadHistoryView=>({cursor:[...view.cursor],layout:view.layout,windowing:[...view.windowing]});
const tokenFrom=(state:unknown)=>record(state)&&typeof state[HEAD_VIEW_ENTRY_KEY]==='string'&&
  state[HEAD_VIEW_ENTRY_KEY].length>=8&&state[HEAD_VIEW_ENTRY_KEY].length<=128?state[HEAD_VIEW_ENTRY_KEY] as string:null;

/** Bounded, process-local receipts. A reload or evicted entry falls back to canonical focus. */
export function createHeadViewHistory(limit=64,newToken=()=>globalThis.crypto?.randomUUID?.()??null){
  const entries=new Map<string,Receipt>();
  const ids=new WeakMap<object,number>();let nextId=0;
  const identity=(value:object)=>{let id=ids.get(value);if(!id){id=++nextId;ids.set(value,id);}return id;};
  function stamp(scope:HeadHistoryScope):SourceStamp|null{
    const shape=shapeFor(scope);if(!shape)return null;
    const image=scope.study.definition.image;
    return {packageId:identity(scope.pkg),studyId:identity(scope.study.definition),
      configured:scope.pkg.source==='configured-local',modality:scope.modality,revision:scope.revision,shape,
      imageSha256:image.sha256,imageFile:image.file,imageDtype:image.dtype};
  }
  const matches=(older:SourceStamp,current:SourceStamp)=>older.modality===current.modality&&
    older.revision===current.revision&&older.shape.every((n,index)=>n===current.shape[index])&&
    older.imageSha256===current.imageSha256&&older.imageFile===current.imageFile&&older.imageDtype===current.imageDtype&&
    (older.packageId===current.packageId&&older.studyId===current.studyId||
      // Configured SSD packages are reverified on each route mount. Bind a
      // fresh object to the exact admitted image and manifest revision only.
      older.configured&&current.configured&&/^[0-9a-f]{64}$/i.test(older.imageSha256));
  function touch(token:string,receipt:Receipt){
    entries.delete(token);entries.set(token,receipt);
    while(entries.size>limit)entries.delete(entries.keys().next().value!);
  }
  return {
    /** Preserve every framework field; a token copied to another URL is not an entry. */
    ensure(state:unknown,href:string):{state:Record<string,unknown>;token:string;changed:boolean}|null{
      if(!record(state)||typeof href!=='string'||href.length>2048||limit<1)return null;
      const old=tokenFrom(state),known=old?entries.get(old):undefined;
      if(old&&known?.href===href)return {state,token:old,changed:false};
      const token=newToken();
      if(typeof token!=='string'||token.length<8||token.length>128||entries.has(token))return null;
      touch(token,{href,source:null,view:null});
      return {state:{...state,[HEAD_VIEW_ENTRY_KEY]:token},token,changed:true};
    },
    freshExternalState(state:unknown):unknown{
      if(!record(state))return state;
      // Vinext treats copied indexed app state as traversal. Mark this
      // app-initiated push as external so its controller allocates a new index.
      const next={...state};delete next[HEAD_VIEW_ENTRY_KEY];
      next[HEAD_VIEW_EXTERNAL_HISTORY_KEY]=true;
      return next;
    },
    save(state:unknown,href:string,scope:HeadHistoryScope,view:unknown):boolean{
      const token=tokenFrom(state),old=token&&entries.get(token),source=stamp(scope);
      if(!token||!old||old.href!==href||!source||!validView(view,source.shape))return false;
      touch(token,{href,source,view:copy(view)});return true;
    },
    read(state:unknown,href:string,scope:HeadHistoryScope):HeadHistoryView|null{
      const token=tokenFrom(state),entry=token&&entries.get(token),source=stamp(scope);
      if(!entry||entry.href!==href||!entry.view||!entry.source||!source||
        !matches(entry.source,source)||!validView(entry.view,source.shape))return null;
      touch(token,entry);return copy(entry.view);
    },
    clearPackage(pkg:LocalHeadPackage){const id=ids.get(pkg);for(const [token,entry] of entries)if(entry.source&&(
      entry.source.packageId===id||pkg.source==='configured-local'&&entry.source.configured))entries.delete(token);},
    clear(){entries.clear();},
    size(){return entries.size;},
  };
}

export const headViewHistory=createHeadViewHistory();

export type ImagingPane = 'index' | 'image' | 'learning';

/** Move keyboard focus only: never select anatomy, change a route or place a quiz answer. */
export function focusImagingPane(origin: HTMLElement, pane: ImagingPane): boolean {
  if (!['index', 'image', 'learning'].includes(pane)) return false;
  const workspace = origin.closest('.imaging-workspace-page');
  const target = workspace?.querySelector<HTMLElement>(`[data-imaging-pane="${pane}"]`);
  if (!target) return false;
  target.focus({preventScroll: true});
  // Desktop panes are already visible. On a stacked layout, reveal an off-screen
  // pane deliberately, without resetting its independently scrolled contents.
  const viewport = target.ownerDocument.defaultView;
  const box = target.getBoundingClientRect();
  if (viewport && (box.bottom <= 0 || box.top >= viewport.innerHeight || box.right <= 0 || box.left >= viewport.innerWidth)) {
    target.scrollIntoView({block: 'nearest', inline: 'nearest', behavior: 'instant'});
  }
  return true;
}

import {headAtlasConceptOptions,headConceptById} from './head-atlas-links.ts';
import {headImageConceptById,headImageOnlyComparisonPacket,type HeadImageConceptLink} from './head-image-only-links.ts';
import {HEAD_IMAGE_ONLY_COMPARISON_REVISION} from './head-image-only-comparison-review.ts';
import {headImageHref} from './head-atlas-navigation.ts';
import {headLinksCurrent} from './head-link-availability.ts';

/** A publication snapshot of a concept link, never an authority to navigate. */
export type LectureAnatomyReference = {
  kind: 'head-concept-v1';
  conceptId: string;
  headRevision: string;
  atlasTarget: string;
} | {
  kind: 'head-image-concept-v1';
  conceptId: string;
  headRevision: string;
  ctTarget: string;
  mriTarget: string;
  comparisonRevision: string;
};

const atlasFields = ['kind', 'conceptId', 'headRevision', 'atlasTarget'] as const;
const imageFields = ['kind', 'conceptId', 'headRevision', 'ctTarget', 'mriTarget', 'comparisonRevision'] as const;
const conceptIdPattern = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const revisionPattern = /^[a-f0-9]{64}$/;
const targetPrefix = '/atlas/head-neck-3d?';
const controlChars = /[\u0000-\u001f\u007f-\u009f]/;

function validConceptId(value: unknown): value is string {
  return typeof value === 'string' && value.length > 0 && value.length <= 128 && conceptIdPattern.test(value);
}

function validAtlasTarget(value: unknown): value is string {
  return typeof value === 'string' && value.length > targetPrefix.length && value.length <= 2048 &&
    value.startsWith(targetPrefix) && !controlChars.test(value) &&
    !/[\\#\s]/.test(value);
}

function validImageTarget(value: unknown, modality:'ct'|'mri'): value is string {
  const prefix=`/atlas/${modality}-head?`;
  return typeof value==='string'&&value.length>prefix.length&&value.length<=2048&&
    value.startsWith(prefix)&&!controlChars.test(value)&&!/[\\#\s]/.test(value);
}

/** Validate the saved shape without requiring today's link revision or concept list. */
export function validateLectureAnatomyReference(value: unknown): LectureAnatomyReference {
  if (value === null || typeof value !== 'object' || Array.isArray(value) ||
      (Object.getPrototypeOf(value) !== Object.prototype && Object.getPrototypeOf(value) !== null)) {
    throw new Error('Invalid lecture anatomy reference');
  }
  const keys = Reflect.ownKeys(value);
  const descriptors = Object.getOwnPropertyDescriptors(value);
  const kind = descriptors.kind?.value;
  const fields = kind==='head-concept-v1'?atlasFields:kind==='head-image-concept-v1'?imageFields:null;
  if (!fields || keys.length !== fields.length || keys.some(key => !fields.includes(key as never))) {
    throw new Error('Invalid lecture anatomy reference fields');
  }
  if (fields.some(key => !descriptors[key] || !Object.hasOwn(descriptors[key], 'value'))) {
    throw new Error('Invalid lecture anatomy reference fields');
  }
  const conceptId = descriptors.conceptId.value;
  const headRevision = descriptors.headRevision.value;
  if (!validConceptId(conceptId) || typeof headRevision !== 'string' || !revisionPattern.test(headRevision)) {
    throw new Error('Invalid lecture anatomy reference value');
  }
  if(kind==='head-concept-v1'){
    const atlasTarget=descriptors.atlasTarget.value;
    if(!validAtlasTarget(atlasTarget))throw new Error('Invalid lecture anatomy reference value');
    return {kind, conceptId, headRevision, atlasTarget};
  }
  const ctTarget=descriptors.ctTarget.value,mriTarget=descriptors.mriTarget.value;
  const comparisonRevision=descriptors.comparisonRevision.value;
  if(!validImageTarget(ctTarget,'ct')||!validImageTarget(mriTarget,'mri')||
    typeof comparisonRevision!=='string'||!revisionPattern.test(comparisonRevision)){
    throw new Error('Invalid lecture anatomy reference value');
  }
  return {kind,conceptId,headRevision,ctTarget,mriTarget,comparisonRevision};
}

/** Available 3D options plus the source-bound draft image-only identities. */
export function lectureAnatomyOptions():Array<{conceptId:string;label:string}>{
  if(!headLinksCurrent())return [];
  return [...headAtlasConceptOptions(),...headImageOnlyComparisonPacket().bindings.flatMap(item=>{
    const link=headImageConceptById(item.conceptId);
    return link&&!link.atlasHref&&link.ctHref&&link.mriHref?[{conceptId:link.conceptId,label:link.label}]:[];
  })].filter(option=>createLectureAnatomyReference(option.conceptId)!==null);
}

/** Create a pin from the current allowlisted head concept. */
export function createLectureAnatomyReference(conceptId: string): LectureAnatomyReference | null {
  if (!validConceptId(conceptId) || !headLinksCurrent()) return null;
  const link = headConceptById(conceptId);
  if(link){
    if(!validAtlasTarget(link.atlasHref))return null;
    return {kind: 'head-concept-v1', conceptId: link.conceptId,
      headRevision: link.headRevision, atlasTarget: link.atlasHref};
  }
  if(!headImageOnlyComparisonPacket().bindings.some(item=>item.conceptId===conceptId))return null;
  const image=headImageConceptById(conceptId);
  if(!image||image.atlasHref||!image.ctHref||!image.mriHref)return null;
  const ctTarget=headImageHref('CT',conceptId,null,image.headRevision);
  const mriTarget=headImageHref('MRI',conceptId,null,image.headRevision);
  if(!validImageTarget(ctTarget,'ct')||!validImageTarget(mriTarget,'mri'))return null;
  return {kind:'head-image-concept-v1',conceptId:image.conceptId,
    headRevision:image.headRevision,ctTarget,mriTarget,
    comparisonRevision:HEAD_IMAGE_ONLY_COMPARISON_REVISION};
}

/** Resolve only to a fresh, canonical link from the current source mapping. */
export function resolveLectureAnatomyReference(value: unknown): HeadImageConceptLink | null {
  let reference: LectureAnatomyReference;
  try {
    reference = validateLectureAnatomyReference(value);
  } catch {
    return null;
  }
  if (!headLinksCurrent()) return null;
  if(reference.kind==='head-concept-v1'){
    const link=headConceptById(reference.conceptId);
    return link&&reference.headRevision===link.headRevision&&reference.atlasTarget===link.atlasHref?link:null;
  }
  if(reference.comparisonRevision!==HEAD_IMAGE_ONLY_COMPARISON_REVISION||
    !headImageOnlyComparisonPacket().bindings.some(item=>item.conceptId===reference.conceptId))return null;
  const link=headImageConceptById(reference.conceptId);
  if(!link||link.atlasHref||!link.ctHref||!link.mriHref||reference.headRevision!==link.headRevision)return null;
  return reference.ctTarget===headImageHref('CT',link.conceptId,null,link.headRevision)&&
    reference.mriTarget===headImageHref('MRI',link.conceptId,null,link.headRevision)?link:null;
}

import {createLectureAnatomyReference,resolveLectureAnatomyReference} from './lecture-anatomy-reference.ts';
import type {LectureSearchParams} from './lecture-slide-navigation.ts';
import {appendLectureTourContext,parseLectureTourContext,lectureTourReturn,type LectureTourContext} from './lecture-tour-context.ts';

export const RELATED_LECTURE_PAGE_SIZE=16;
export type RelatedLectureRequest={conceptId:string;headRevision:string;offset:number;tourContext?:LectureTourContext};

/** Only explicit, current anatomy pins can enter lecture discovery. */
export function relatedLectureHref(conceptId:string,headRevision:string,offset=0,tourContext?:LectureTourContext):string|null{
  if(!Number.isSafeInteger(offset)||offset<0||offset>1_000_000||offset%RELATED_LECTURE_PAGE_SIZE!==0)return null;
  const reference=createLectureAnatomyReference(conceptId);
  if(!reference||reference.headRevision!==headRevision||!resolveLectureAnatomyReference(reference))return null;
  if(tourContext&&tourContext.kind!=='none'&&(tourContext.kind!=='ready'||tourContext.conceptId!==conceptId||tourContext.headRevision!==headRevision||!lectureTourReturn(tourContext)))return null;
  const query=new URLSearchParams({concept:conceptId,headRevision});
  if(offset)query.set('offset',String(offset));
  return appendLectureTourContext(`/learn/related-anatomy?${query}`,tourContext);
}

export function parseRelatedLectureRequest(params:LectureSearchParams):RelatedLectureRequest|null{
  const conceptId=params.concept,headRevision=params.headRevision,rawOffset=params.offset;
  if(typeof conceptId!=='string'||typeof headRevision!=='string'||
    (rawOffset!==undefined&&(typeof rawOffset!=='string'||!/^(0|[1-9][0-9]{0,6})$/.test(rawOffset))))return null;
  const offset=rawOffset===undefined?0:Number(rawOffset);
  const tourContext=parseLectureTourContext(params);
  if(tourContext.kind==='invalid')return null;
  return relatedLectureHref(conceptId,headRevision,offset,tourContext)?{conceptId,headRevision,offset,...(tourContext.kind==='ready'?{tourContext}:{})}:null;
}

export function relatedLectureConcept(request:RelatedLectureRequest){
  if(!relatedLectureHref(request.conceptId,request.headRevision,request.offset,request.tourContext))return null;
  return resolveLectureAnatomyReference(createLectureAnatomyReference(request.conceptId));
}

import {HEAD_LINK_REVISION} from './head-atlas-links.ts';
import {headLinksCurrent} from './head-link-availability.ts';
import {headLearningLinks,headLearningSequencesForModality,type HeadLearningPosition} from './head-atlas-learning.ts';

export type LectureTourContext = {kind:'none'} | {kind:'invalid'} | {
  kind:'ready';sequenceId:string;conceptId:string;headRevision:string;view:'CT'|'MRI'|'3D';
};
type Params=URLSearchParams|Record<string,string|string[]|undefined>;
const keys=['returnTour','returnStep','returnConcept','returnRevision','returnView'] as const;
const invalid:LectureTourContext={kind:'invalid'};
function record(value:unknown,names:string[]):value is Record<string,unknown>{
  if(!value||typeof value!=='object'||Array.isArray(value)||![Object.prototype,null].includes(Object.getPrototypeOf(value)))return false;
  const fields=Reflect.ownKeys(value);
  return fields.length===names.length&&fields.every(key=>typeof key==='string'&&names.includes(key)&&Object.hasOwn(Object.getOwnPropertyDescriptor(value,key)??{},'value'));
}
function destination(context:unknown){
  if(!record(context,['kind','sequenceId','conceptId','headRevision','view'])||context.kind!=='ready'||
    !headLinksCurrent()||context.headRevision!==HEAD_LINK_REVISION||typeof context.sequenceId!=='string'||
    typeof context.conceptId!=='string'||typeof context.view!=='string'||!['CT','MRI','3D'].includes(context.view))return null;
  const sequence=headLearningSequencesForModality().find(item=>item.id===context.sequenceId);
  const index=sequence?.concepts.indexOf(context.conceptId)??-1;
  if(!sequence||index<0)return null;
  const links=headLearningLinks({sequenceId:sequence.id,conceptId:context.conceptId});
  const href=context.view==='CT'?links?.ctHref:context.view==='MRI'?links?.mriHref:links?.atlasHref;
  return href?{href,label:sequence.label,step:index+1,total:sequence.concepts.length,view:context.view as 'CT'|'MRI'|'3D'}:null;
}
/** A canonical authored step, never a live model-selection or access receipt. */
export function createLectureTourContext(position:HeadLearningPosition,view:'CT'|'MRI'|'3D',revision:string):LectureTourContext{
  const context={kind:'ready' as const,sequenceId:position?.sequenceId,conceptId:position?.conceptId,headRevision:revision,view};
  return destination(context)?context as LectureTourContext:invalid;
}
export function parseLectureTourContext(params:Params):LectureTourContext{
  if(!params||typeof params!=='object'||(!(params instanceof URLSearchParams)&&
    (Array.isArray(params)||![Object.prototype,null].includes(Object.getPrototypeOf(params)))))return invalid;
  if(!(params instanceof URLSearchParams)&&keys.some(key=>Object.hasOwn(params,key)&&!Object.hasOwn(Object.getOwnPropertyDescriptor(params,key)??{},'value')))return invalid;
  const has=(key:string)=>params instanceof URLSearchParams?params.has(key):Object.hasOwn(params,key);
  if(!keys.some(has))return {kind:'none'};
  const read=(key:string)=>{const values=params instanceof URLSearchParams?params.getAll(key):params[key];
    return params instanceof URLSearchParams?Array.isArray(values)&&values.length===1?values[0]:null:typeof values==='string'?values:null;};
