const home = '/workspace/atlas-review';
const queryKeys: Record<string,readonly string[]> = {
  [home]: [],
  [home+'/body']: ['structure'],
  [home+'/shoulder']: ['structure'],
  [home+'/nested']: ['parent','study','structure','source'],
  [home+'/specimens']: ['specimen','structure'],
